# --- Apply_EQ (MATLAB lines 905–976) ---

# ============================================================
# MATLAB→Python translation notes for Apply_EQ
# MATLAB lines: 905–976
# ============================================================
# Inlines TD_CTLE (4593–4609) and FFE (2026–2048).
# MATLAB 1-based index fom_result.ctle → Python [ctle-1].
# sample_start: MATLAB mod(t_s-1, M)+1 with t_s 1-BASED. Python's fom_result.t_s
#   is BEST.cursor_i, already 0-based, so t_s_m = t_s_py + 1 and the 0-based
#   start is mod(t_s_m - 1, M) = t_s_py % M. Same identity get_PSDs uses
#   (cursor_i % M for MATLAB's mod(cursor_i-1,M)+1). An earlier version wrote
#   (t_s - 1) % M, converting the RESULT to 0-based but not the INPUT, and so
#   sampled the ADC-clip pulse one sample early.
# OP.RxFFE branch calls the real force() to apply the Rx-FFE taps to the pulse.
# chdata extended with zeros if shorter than fom_result.sbr.
# ============================================================



def Apply_EQ(param, fom_result, chdata, OP):
    FB = param.fb
    ctle_idx = int(fom_result.ctle) - 1  # MATLAB 1-based → 0-based
    FZ = np.asarray(param.CTLE_fz, dtype=float)[ctle_idx]
    FP1 = np.asarray(param.CTLE_fp1, dtype=float)[ctle_idx]
    FP2 = np.asarray(param.CTLE_fp2, dtype=float)[ctle_idx]
    GDC = np.asarray(param.ctle_gdc_values, dtype=float)[ctle_idx]

    hp_idx = int(fom_result.best_G_high_pass) - 1  # MATLAB 1-based → 0-based
    f_HP = getattr(param, 'f_HP', None)
    g_DC_HP_values = getattr(param, 'g_DC_HP_values', None)
    f_HP_Z = getattr(param, 'f_HP_Z', None)
    f_HP_P = getattr(param, 'f_HP_P', None)

    FHP = float(np.asarray(f_HP, dtype=float)[hp_idx]) if (f_HP is not None and len(f_HP) > 0) else None
    GDCHP = float(np.asarray(g_DC_HP_values, dtype=float)[hp_idx]) if (g_DC_HP_values is not None and len(g_DC_HP_values) > 0) else None
    FHPZ = float(np.asarray(f_HP_Z, dtype=float)[ctle_idx]) if (f_HP_Z is not None and len(f_HP_Z) > 0) else None
    FHPP = float(np.asarray(f_HP_P, dtype=float)[ctle_idx]) if (f_HP_P is not None and len(f_HP_P) > 0) else None

    # Extend chdata[0] if needed
    SBR_Len = len(fom_result.sbr)
    if len(np.asarray(chdata[0].uneq_imp_response)) < SBR_Len:
        n_add = SBR_Len - len(chdata[0].uneq_imp_response)
        t_end = float(np.asarray(chdata[0].t)[-1])
        # MATLAB L927: (1:samples_added)/param.fb/param.samples_per_ui + t(end)
        # -- TWO successive divisions, not one multiply by a pre-formed dt.
        # (k/fb)/M and k*(1/(fb*M)) are not the same double: 2 of 7 and 3 of 13
        # sample offsets differ at fb=25e9, M=8.  COM Octave, 7 added samples,
        # t(end)=1.95e-10: last t is 2.3000000000000001e-10, where the
        # pre-formed-dt version gave 2.2999999999999998e-10.
        new_t = np.arange(1, n_add + 1) / param.fb / param.samples_per_ui + t_end
        chdata[0].uneq_imp_response = np.concatenate([np.asarray(chdata[0].uneq_imp_response), np.zeros(n_add)])
        chdata[0].uneq_pulse_response = np.concatenate([np.asarray(chdata[0].uneq_pulse_response), np.zeros(n_add)])
        chdata[0].t = np.concatenate([np.asarray(chdata[0].t), new_t])

    M = param.samples_per_ui
    for i in range(param.number_of_s4p_files):
        uneq_ir = np.asarray(chdata[i].uneq_imp_response, dtype=float)
        if OP.INCLUDE_CTLE == 1:
            ctle_type = param.CTLE_type
            if ctle_type == 'CL93':
                eq_ir, _, _, _ = _TD_CTLE(uneq_ir, FB, FZ, FP1, FP2, GDC, M)
            elif ctle_type == 'CL120d':
                eq_ir, _, _, _ = _TD_CTLE(uneq_ir, FB, FZ, FP1, FP2, GDC, M)
                eq_ir, _, _, _ = _TD_CTLE(eq_ir, FB, FHP, FHP, 100e100, GDCHP, M)
            elif ctle_type == 'CL120e':
                eq_ir, _, _, _ = _TD_CTLE(uneq_ir, FB, FZ, FP1, FP2, GDC, M)
                eq_ir, _, _, _ = _TD_CTLE(eq_ir, FB, FHPZ, FHPP, 1e99, 0, M)
            else:
                # MATLAB's switch (L933-942) has no `otherwise`, so an
                # unrecognised CTLE_type leaves eq_ir undefined and the next
                # line errors.  Falling through to the uneq response answered
                # an un-equalised channel as though it were equalised.
                # COM Octave, param.CTLE_type='NOSUCH', OP.INCLUDE_CTLE=1:
                #   "error: 'eq_ir' undefined near line 46, column 31"
                raise ValueError("Apply_EQ: unsupported param.CTLE_type %r "
                                 "(MATLAB leaves eq_ir undefined)" % (ctle_type,))
        else:
            eq_ir = uneq_ir

        chdata[i].eq_imp_response = eq_ir
        eq_pulse = lfilter(np.ones(M), [1.0], eq_ir)

        if chdata[i].type in ('FEXT', 'THRU'):
            eq_pulse = _FFE(fom_result.txffe, fom_result.cur - 1, M, eq_pulse)

        chdata[i].pulse_response_w_CFT_TXFFE_noRxFFE = eq_pulse
        chdata[i].ctle_pulse = eq_pulse
        sample_start = int(fom_result.t_s) % M  # 0-based; see header note
        chdata[i].pulse_sampled_w_tx_ffe_ctle = eq_pulse[sample_start::M]
        chdata[i].t_sampled_w_tx_ffe_ctle = np.asarray(chdata[i].t)[sample_start::M]

        if OP.RxFFE:
            if OP.FFE_OPT_METHOD.upper() == 'MMSE':
                chdata[i].ctle_imp_response = _FFE(fom_result.RxFFE, fom_result.cur - 1, M, eq_ir)
            # MATLAB L973: [eq_pulse, C] = force(eq_pulse, param, OP, t_s, fom_result.RxFFE)
            # C provided -> force applies the precomputed RxFFE taps (top-level fn).
            eq_pulse, _, _ = force(eq_pulse, param, OP, fom_result.t_s, fom_result.RxFFE)
        chdata[i].eq_pulse_response = eq_pulse

    return chdata



# --- Bathtub_Contribution_Wrapper (MATLAB lines 977–1027) ---

# ============================================================
# MATLAB→Python translation notes for Bathtub_Contribution_Wrapper
# MATLAB lines: 977–1028
# ============================================================
# MATLAB figure/subplot GUI → matplotlib.  msgbox/movegui omitted.
# OP.COM_CONTRIBUTION_CURVES=False → plot_bathtub_curves; True → plot_pie_com (top-level,
#   resolved in the assembled module), MATLAB L1003-1021.
# MATLAB case_number is 1-based; matplotlib add_subplot uses 1-based too.
# ============================================================





# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.


def _Bathtub_Contribution_Wrapper__plot_bathtub_curves(hax, max_signal, sci_pdf, cci_pdf, isi_and_xtalk_pdf,
                         noise_pdf, jitt_pdf, combined_interference_and_noise_pdf, bin_size):
    cursors = _d_cpdf(bin_size, max_signal * np.array([-1.0, 1.0]), np.array([0.5, 0.5]))
    signal_and_isi_pdf = _conv_fct(cursors, sci_pdf)
    signal_and_xtalk_pdf = _conv_fct(cursors, cci_pdf)
    signal_and_channel_noise_pdf = _conv_fct(cursors, isi_and_xtalk_pdf)
    signal_and_system_noise_pdf = _conv_fct(cursors, noise_pdf)
    signal_and_system_jitt_pdf = _conv_fct(cursors, jitt_pdf)

    cursors_l = copy.copy(cursors)
    cursors_l.y = cursors_l.y.copy()
    cursors_l.y[cursors_l.x > 0] = 0
    cursors_r = copy.copy(cursors)
    cursors_r.y = cursors_r.y.copy()
    cursors_r.y[cursors_r.x < 0] = 0

    signal_and_total_noise_pdf_l = _conv_fct(cursors_l, combined_interference_and_noise_pdf)
    signal_and_total_noise_pdf_r = _conv_fct(cursors_r, combined_interference_and_noise_pdf)

    hax.semilogy(signal_and_isi_pdf.x, np.abs(np.cumsum(signal_and_isi_pdf.y) - 0.5),
                 'r', label='ISI')
    hax.semilogy(signal_and_xtalk_pdf.x, np.abs(np.cumsum(signal_and_xtalk_pdf.y) - 0.5),
                 'b', label='Xtalk')
    hax.semilogy(signal_and_channel_noise_pdf.x,
                 np.abs(np.cumsum(signal_and_channel_noise_pdf.y) - 0.5),
                 'c', label='ISI+Xtalk')
    hax.semilogy(signal_and_system_noise_pdf.x,
                 np.abs(np.cumsum(signal_and_system_noise_pdf.y) - 0.5),
                 'm', label='Jitter, SNR_TX,RL_M, eta_0 noise')
    hax.semilogy(signal_and_system_jitt_pdf.x,
                 np.abs(np.cumsum(signal_and_system_jitt_pdf.y) - 0.5),
                 'g', label='Jitter noise')

    vbt_l = np.abs(0.5 - np.cumsum(signal_and_total_noise_pdf_l.y))
    vbt_r = np.flipud(0.5 - np.cumsum(np.flipud(signal_and_total_noise_pdf_r.y)))
    hax.semilogy(signal_and_total_noise_pdf_l.x, vbt_l, 'k', label='total noise PDF left')
    hax.semilogy(signal_and_total_noise_pdf_r.x, vbt_r, 'k', label='total noise PDF right')

    hax.plot(max_signal * np.array([-1.0, -1.0, 1.0, 1.0]), [0.5, 1e-20, 1e-20, 0.5], '--ok')
    hax.set_ylabel('Probability')
    hax.set_xlabel('volts')
    hax.legend()


def Bathtub_Contribution_Wrapper(COM_SNR_Struct, Noise_Struct, param, chdata, OP):
    case_number = int(param.package_testcase_i)  # 1-based
    if not OP.COM_CONTRIBUTION_CURVES:
        try:
            import matplotlib.pyplot as plt
        except ImportError:
            return
        fig_name = 'Voltage bathtub curves'
        existing = [plt.figure(n) for n in plt.get_fignums()
                    if plt.figure(n).get_label() == fig_name]
        fig = existing[0] if existing else plt.figure(num=fig_name)
        n_cases = len(OP.pkg_len_select)
        hax = fig.add_subplot(n_cases, 1, case_number)
        _Bathtub_Contribution_Wrapper__plot_bathtub_curves(
            hax,
            COM_SNR_Struct.A_s,
            Noise_Struct.sci_pdf,
            Noise_Struct.cci_pdf,
            Noise_Struct.isi_and_xtalk_pdf,
            Noise_Struct.noise_pdf,
            Noise_Struct.jitt_pdf,
            COM_SNR_Struct.combined_interference_and_noise_pdf,
            param.delta_y,
        )
        hax.set_ylim([param.specBER / 10, 1])
        xlims = hax.get_xlim()
        hax.plot(list(xlims), [param.specBER, param.specBER], 'r:')
        # MATLAB appends the space BEFORE regexprep and the format adds another,
        # so the title ends in TWO spaces.  COM Octave:
        #   sprintf('case %d VBC: %s ',1,regexprep(['Case_1_port_A',' '],'_',' '))
        #   -> 'case 1 VBC: Case 1 port A  '  (27 chars)
        base_str = (chdata[0].base + ' ').replace('_', ' ')
        hax.set_title(f'case {case_number} VBC: {base_str} ')
    else:
        # MATLAB L1003-1021: COM contribution (rough allocation) branch.
        try:
            import matplotlib.pyplot as plt
        except ImportError:
            return
        fig_name = 'COM Contributions (Rough Allocations)'
        existing = [plt.figure(n) for n in plt.get_fignums()
                    if plt.figure(n).get_label() == fig_name]
        fig = existing[0] if existing else plt.figure(num=fig_name)
        n_cases = len(OP.pkg_len_select)
        hax = fig.add_subplot(n_cases, 1, case_number)
        # top-level plot_pie_com (resolved in the assembled module); note: no jitt_pdf,
        # and it takes param (MATLAB L1011-1018).
        plot_pie_com(
            hax,
            COM_SNR_Struct.A_s,
            Noise_Struct.sci_pdf,
            Noise_Struct.cci_pdf,
            Noise_Struct.isi_and_xtalk_pdf,
            Noise_Struct.noise_pdf,
            COM_SNR_Struct.combined_interference_and_noise_pdf,
            param.delta_y,
            param,
        )
        base_str = (chdata[0].base + ' ').replace('_', ' ')   # see VBC branch
        hax.set_title(f'case {case_number} rough COM impact: {base_str} ')



# --- Bessel_Thomson_Filter (MATLAB lines 1028–1037) ---

# ============================================================
# MATLAB→Python translation notes for Bessel_Thomson_Filter
# MATLAB lines: 1028–1037
# ============================================================
# bessel(n): called from sibling module — inlined as _bessel (protocol:
#   no cross-module imports from py_impl.py siblings).
# a(1) in MATLAB (1-based) = a[0] in Python = constant term (largest value)
# fliplr(a) reverses [a0,...,an] → [an,...,a0], highest-degree first for polyval
# np.polyval matches MATLAB polyval: highest-degree coefficient first ✓
# use_BT=False: all-pass (unity response)
# ============================================================



def _Bessel_Thomson_Filter__length(x):
    """MATLAB length(): the longest dimension, 0 when empty, 1 for a scalar."""
    if x.size == 0:
        return 0
    return max(x.shape) if x.ndim else 1


def Bessel_Thomson_Filter(param, f, use_BT):
    f = np.asarray(f, dtype=float)
    # Same shape as Butterworth_Filter, and the same two traps. MATLAB `if
    # use_BT` is true only for a non-empty value whose elements are ALL
    # non-zero, and `length()` is the LONGEST dimension, not the first.
    # COM Octave (param.BTorder=4, fb=106.25e9, fb_BT_cutoff=0.75):
    #   use_BT=[]    -> ones branch        use_BT=[1 0] -> ones branch
    #   use_BT=[1 1] -> filter branch      f 2x3, use_BT=0 -> ones(1,3)
    #   f scalar, use_BT=0 -> 1            (len(f) raised TypeError)
    use = np.asarray(use_BT)
    if not (use.size and np.all(use)):
        return np.ones(_Bessel_Thomson_Filter__length(f))
    a = _bessel(param.BTorder)       # [a0,...,an]; a[0] is constant term
    acoef = a[::-1]                  # fliplr → highest-degree first
    s = 1j * f / (param.fb_BT_cutoff * param.fb)
    return a[0] / np.polyval(acoef, s)   # a(1) in MATLAB = a[0]



# --- Bread_Crumb_Chdata_Reduction (MATLAB lines 1038–1082) ---

def Bread_Crumb_Chdata_Reduction(chdata, fields_file):
    """Remove or keep selected fields in chdata list (MATLAB lines 1038-1082).

    fields_file: text file with first line '#reduce' or '#include',
    remaining lines are field names.
    Returns modified chdata list.
    """
    with open(fields_file, 'r') as fid:
        lines = fid.read().splitlines()

    # Remove blank lines
    lines = [ln for ln in lines if ln.strip()]
    if not lines:
        return chdata

    mode = lines[0].strip().lower()
    field_names = [ln.strip() for ln in lines[1:] if ln.strip()]

    if mode == '#reduce':
        remove_fields = field_names
    elif mode == '#include':
        all_fields = set()
        for cd in chdata:
            all_fields |= set(vars(cd).keys())
        remove_fields = list(all_fields - set(field_names))
    else:
        raise ValueError(f'Bad first line. Must be "#reduce" or "#include"')

    for cd in chdata:
        for field in remove_fields:
            if hasattr(cd, field):
                delattr(cd, field)

    return chdata



# --- Burst_Probability_Calc (MATLAB lines 1083–1132) ---

def _Burst_Probability_Calc__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _Burst_Probability_Calc__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _Burst_Probability_Calc__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)




# --- inline from conv_fct (MATLAB 5371-5388) ---

# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.


# --- inline from get_pdf_from_sampled_signal (MATLAB 7473-7518) ---


def _Burst_Probability_Calc__get_pdf_from_sampled_signal(input_vector, L, BinSize):
    if not np.isscalar(input_vector):
        iv = np.asarray(input_vector, dtype=float).ravel()
    else:
        iv = np.array([float(input_vector)])
    # MATLAB max([]) is [], and `if []` is false, so an empty input falls
    # straight through to the delta pdf.  np.max raises
    # "zero-size array to reduction operation maximum" instead.
    if iv.size and _Burst_Probability_Calc__mmax(np.abs(iv)) > BinSize:
        iv = iv[np.abs(iv) > BinSize]
    else:
        return _d_cpdf(BinSize, 0, 1)
    iv[np.abs(iv) < BinSize] = 0.0
    b = np.sign(iv)
    sort_idx = np.argsort(np.abs(iv), kind='stable')[::-1]
    iv = np.abs(iv[sort_idx]) * b[sort_idx]
    # MATLAB ones(1,L) takes a double L happily -- every Octave number is a
    # double, so the reference has only ever been run this way -- while
    # np.ones(4.0) raises "expected a sequence of integers or a single
    # integer".  param.levels arrives as a float from the config workbook, so
    # this crashed for every run with OP.nburst > 0.
    nlev = int(L)
    values = 2.0 * np.arange(nlev) / (L - 1) - 1.0
    prob = np.ones(nlev) / L
    pdf = _d_cpdf(BinSize, 0, 1)
    empty_pdf = pdf
    for v in iv:
        pdfn = _Init_PDF_Fast(empty_pdf, np.abs(v) * values, prob)
        pdf = _conv_fct(pdf, pdfn)
    return pdf


def Burst_Probability_Calc(COM_SNR_Struct, DFE_taps, param, OP):
    """Compute burst error probability (MATLAB lines 1083-1132).

    Returns (p_burst, p_error_propagation).
    """
    A_s = float(COM_SNR_Struct.A_s)
    error_propagation_noise_pdf = [COM_SNR_Struct.combined_interference_and_noise_pdf]
    error_threshold = A_s / (10 ** ((float(param.pass_threshold) - float(OP.COM_EP_margin)) / 20.0))

    pdf0 = error_propagation_noise_pdf[0]
    idx = np.where(pdf0.x >= error_threshold)[0]
    p_ep_0 = 1e-20 if len(idx) == 0 else float(np.sum(pdf0.y[idx[0]:]))
    p_error_propagation = [p_ep_0]

    sorted_abs_taps = np.sort(np.abs(np.asarray(DFE_taps).ravel()))[::-1]
    nburst = int(OP.nburst)
    ndfe = int(param.ndfe)
    for k in range(1, min(ndfe, nburst)):
        if OP.use_simple_EP_model:
            # An empty DFE_taps is legal here: MATLAB max([]) is [], 2*A_s*[]
            # stays empty, and get_pdf_from_sampled_signal([]) returns the
            # delta pdf, so every burst probability repeats the uncorrelated
            # one.  COM Octave 4p16p0, DFE_taps=[] with ndfe=nburst=3:
            # p_error_propagation = 1.386500771629333e-45 three times.
            # float(_Burst_Probability_Calc__mmax([])) raised instead.
            tap_val = (sorted_abs_taps if sorted_abs_taps.size == 0
                       else 2.0 * A_s * float(_Burst_Probability_Calc__mmax(sorted_abs_taps)))
            post_pdf = _Burst_Probability_Calc__get_pdf_from_sampled_signal(tap_val, param.levels, param.delta_y)
            new_pdf = _conv_fct(error_propagation_noise_pdf[0], post_pdf)
        else:
            tap_val = 2.0 * A_s * float(sorted_abs_taps[k - 1])
            post_pdf = _Burst_Probability_Calc__get_pdf_from_sampled_signal(tap_val, param.levels, param.delta_y)
            new_pdf = _conv_fct(error_propagation_noise_pdf[k - 1], post_pdf)
        error_propagation_noise_pdf.append(new_pdf)
        idx = np.where(new_pdf.x >= error_threshold)[0]
        p_ep_k = 1e-20 if len(idx) == 0 else float(np.sum(new_pdf.y[idx[0]:]))
        p_error_propagation.append(p_ep_k)

    p_burst = np.cumprod(p_error_propagation)
    return p_burst, p_error_propagation



# --- Butterworth_Filter (MATLAB lines 1133–1138) ---

# ============================================================
# MATLAB→Python translation notes for Butterworth_Filter
# MATLAB lines: 1133–1138
# ============================================================
# polyval([1 2.613126 3.414214 2.613126 1], s):
#   MATLAB highest-degree-first → np.polyval same convention ✓
# 1i*f./(cutoff*fb): s = j*f/f_c, element-wise → same with numpy arrays
# ones(1,length(f)): row vector → np.ones(_Butterworth_Filter__length(f)) 1-D array, where
#   _Butterworth_Filter__length() is MATLAB's length(): the longest dimension, 1 for a scalar
# use_BW=False: all-pass (unity response)
# ============================================================


_BW_POLY = [1, 2.613126, 3.414214, 2.613126, 1]


def _Butterworth_Filter__length(x):
    """MATLAB length(): the longest dimension, 0 when empty, 1 for a scalar."""
    if x.size == 0:
        return 0
    return max(x.shape) if x.ndim else 1


def Butterworth_Filter(param, f, use_BW):
    f = np.asarray(f, dtype=float)
    # MATLAB `if use_BW` is true only for a non-empty value whose elements are
    # ALL non-zero.  COM Octave: use_BW=[] -> ones branch, [1 0] -> ones branch,
    # [1 1] -> filter branch.  `not use_BW` raised on any numpy array of more
    # than one element, and took the filter branch for the list [1, 0].
    use = np.asarray(use_BW)
    if not (use.size and np.all(use)):
        # ones(1,length(f)): length() is the LONGEST dimension, not the first.
        # COM Octave: f 2x3 -> ones(1,3), three elements not six; f scalar -> 1
        # (len(f) raised TypeError on a scalar).
        return np.ones(_Butterworth_Filter__length(f))
    s = 1j * f / (param.fb_BW_cutoff * param.fb)
    return 1.0 / np.polyval(_BW_POLY, s)



# --- CDF_ev (MATLAB lines 1139–1141) ---

# ============================================================
# MATLAB→Python translation notes for CDF_ev
# MATLAB lines: 1139–1141
# ============================================================
# find(PDF.x >= -val, 1, 'first'): 1-based index of first element ≥ -val.
#   np.argmax(PDF.x >= -val): 0-based index of first True.
#   Both directly index CDF/PDF.x → equivalent result ✓
#   BUT np.argmax returns 0 when *nothing* matches, where find() returns [].
#   See the no-match guard below.
# CDF_ev = CDF(index): scalar probability at the voltage crossing.
#
# Note on the Octave compat build (octave/com_ieee8023_4p16p0_octave_compat.m):
# it replaces the find() with `index = lookup(PDF.x,-val) + 1`. lookup() returns
# the last i with x(i) <= v, so the +1 form answers one bin HIGH exactly when
# -val is bit-identical to a grid element, and runs off the end when -val is
# above the whole axis. Measured under Octave 11.3 on x = -0.3:0.1:0.3 over 13
# probe values: 4 disagree (-val = -0.3, 0.2, 0.3, and the above-range 0.5).
# The other exact-looking hits agree only because 0.1 steps are not exactly
# representable, so which values tie is a floating-point accident rather than
# something a caller can reason about. This port follows the MATLAB reference.
# ============================================================



def CDF_ev(val, PDF, CDF):
    x = np.asarray(PDF.x, dtype=float)
    CDF = np.asarray(CDF, dtype=float)
    hit = x >= -val
    if not hit.any():
        # find() is empty, so MATLAB's CDF(index) is an empty 1x0 — there is
        # no value to return.  np.argmax on an all-False mask answers 0, which
        # would hand back CDF(1) as though it were the crossing.
        # COM Octave 4p16p0: CDF_ev(-0.5,PDF,CDF) with PDF.x=[-0.3:0.1:0.3]
        # errors "CDF(8): out of bound 7 (dimensions are 1x7)"; the MATLAB
        # find() form returns empty.  Either way there is no answer here.
        raise IndexError('CDF_ev: no PDF.x >= -val')
    index = int(np.argmax(hit))         # first index where PDF.x >= -val
    return float(CDF[index])



# --- CDF_inv_ev (MATLAB lines 1142–1148) ---

# ============================================================
# MATLAB→Python translation notes for CDF_inv_ev
# MATLAB lines: 1142–1148
# ============================================================
# find(CDF >= val, 1, 'first'): 1-based index of first CDF ≥ val.
#   Python: np.where(CDF >= val)[0] → 0-based array of matching indices.
# isempty(index): no match → return PDF.x(end) = PDF.x[-1].
# else: return PDF.x(index) at 1-based index → PDF.x[index] at 0-based ✓
# ============================================================



def CDF_inv_ev(val, PDF, CDF):
    x = np.asarray(PDF.x, dtype=float)
    CDF = np.asarray(CDF, dtype=float)
    indices = np.where(CDF >= val)[0]       # 0-based indices of CDF >= val
    if len(indices) == 0:
        return float(x[-1])                 # isempty(index) → PDF.x(end)
    return float(x[indices[0]])             # first match



# --- COM_CommandLine_Parse (MATLAB lines 1149–1200) ---

# ============================================================
# MATLAB→Python translation notes for COM_CommandLine_Parse
# MATLAB lines: 1149–1200
# ============================================================
# varargin in MATLAB → *args tuple in Python.
# keywords = {'Legacy','TD','Config2Mat'}: the *match* is strcmpi, so it is
# case-insensitive, but my_keyword keeps the caller's spelling and the two
# switch statements that follow are case-SENSITIVE. So 'td' is consumed as a
# keyword yet selects no case: nothing further is parsed. See the oracle
# evidence beside the switch below.
# varargin_extractor inlined as _COM_CommandLine_Parse__pop: pops first element, or MATLAB [] → None.
# str2num(s) is eval(['[' s ']']); isempty(str2num(s)) is approximated by
# _COM_CommandLine_Parse__str2num_nonempty, see its comment.
# After keyword consumed, args is passed by reference in MATLAB → use list for
# mutation.
# Returns: config_file, num_fext, num_next, Remember_keyword, OP, remaining_varargin.
# ============================================================



_KEYWORDS = ('Legacy', 'TD', 'Config2Mat')

# Bare words MATLAB's str2num resolves to a numeric (or logical) value, so
# str2num returns non-empty for them.
_NUMERIC_WORDS = frozenset(('pi', 'e', 'i', 'j', 'eps', 'inf', 'nan',
                            'true', 'false'))


def _COM_CommandLine_Parse__try_float(s):
    try:
        float(s)
        return True
    except (ValueError, TypeError):
        return False


def _COM_CommandLine_Parse__str2num_nonempty(s):
    """~isempty(str2num(s)), for the numeric-array forms str2num accepts.

    str2num is eval(['[' s ']']), so anything that evaluates to a numeric
    array is non-empty: a bare number, a numeric constant such as pi or eps,
    a logical, a bracketed or separated list, a colon range. Arithmetic
    expressions ('2+3') are not covered here; they would need an expression
    evaluator and are not a command line COM is given.
    """
    t = s.strip()
    if t.startswith('[') and t.endswith(']'):
        t = t[1:-1]
    tokens = [k for k in re.split(r'[\s,;]+', t) if k]
    if not tokens:
        return False                      # str2num('') and str2num('[]') are []
    for k in tokens:
        parts = k.split(':') if ':' in k else [k]
        for p in parts:
            if not (_COM_CommandLine_Parse__try_float(p) or p.lower().lstrip('+-') in _NUMERIC_WORDS):
                return False
    return True


def _COM_CommandLine_Parse__pop(args):
    """varargin_extractor: the first argument, or MATLAB [] when there is none."""
    return args.pop(0) if args else None


def COM_CommandLine_Parse(OP, *varargin):
    """Parse COM command-line arguments (MATLAB lines 1149-1200).

    Returns (config_file, num_fext, num_next, Remember_keyword, OP, remaining_varargin).
    """
    Remember_keyword = 'Legacy'
    OP = SimpleNamespace(**vars(OP)) if not isinstance(OP, dict) else SimpleNamespace(**OP)
    OP.TDMODE = False
    OP.GET_FD = True
    OP.CONFIG2MAT_ONLY = False
    config_file = ''
    num_fext = None
    num_next = None

    args = list(varargin)

    if args:
        if not isinstance(args[0], str):
            raise TypeError('First input must be a string')
        if args[0].lower() in [k.lower() for k in _KEYWORDS]:
            # Keyword Mode: strcmpi matched, so the keyword is consumed
            # whatever its case, and Remember_keyword keeps that spelling.
            my_keyword = args[0]
            Remember_keyword = my_keyword
            args.pop(0)
        else:
            my_keyword = Remember_keyword

        # first keyword check: set special OP values.
        # COM Octave: switch my_keyword is case-sensitive, so ('td','cfg.csv',0,0)
        # leaves TDMODE=0, GET_FD=1, config_file=[], num_fext=[], num_next=[],
        # and ('config2mat','cfg.xlsx') leaves CONFIG2MAT_ONLY=0 and
        # config_file=[]. Only the exact spellings below do anything.
        if my_keyword == 'TD':
            OP.TDMODE = True
            OP.GET_FD = False

        # main keyword check: pull varargin
        if my_keyword in ('Legacy', 'TD'):
            config_file = _COM_CommandLine_Parse__pop(args)
            new_argument = args[0] if args else None
            if isinstance(new_argument, str) and not _COM_CommandLine_Parse__str2num_nonempty(new_argument):
                # special input: allow num_fext and num_next to be omitted
                # when they are 0
                num_fext = 0
                num_next = 0
            else:
                # normal input: num_fext and num_next are given
                num_fext = _COM_CommandLine_Parse__pop(args)
                num_next = _COM_CommandLine_Parse__pop(args)
        elif my_keyword == 'Config2Mat':
            OP.CONFIG2MAT_ONLY = True
            config_file = _COM_CommandLine_Parse__pop(args)

    return config_file, num_fext, num_next, Remember_keyword, OP, args



# --- COM_FD_to_TD (MATLAB lines 1201–1361) ---

# ============================================================
# MATLAB→Python translation notes for COM_FD_to_TD
# MATLAB lines: 1201–1361
# ============================================================
# Indexing: MATLAB 1-based → 0-based. find(x==max,1,'first') → np.argmax
#   mod(ipeak-1, M)+1 (1-based) → ipeak % M (0-based, same phase)
#   istart:M:iend (1-based slice) → Python slice [istart::M][:nsteps]
# filter(ones(1,M), 1, x): MATLAB FIR running-sum → scipy.signal.lfilter(ones(M), 1, x)
# norm(x): np.linalg.norm(x)
# Anonymous functions: Sinc and W defined inline (W not called in this function)
# Callee stubs for: s21_to_impulse_DC, Bessel_Thomson_Filter,
#   Butterworth_Filter, get_cm_noise (all are verified functions; stubbed here
#   per protocol — no cross-py_impl imports)
# Output shape: chdata is modified list of SimpleNamespace objects, returned
# Known discrepancy from sicopr.py: sicopr.py missing raw/filtered variants and SCMR
# ============================================================



# ---------------------------------------------------------------------------
# Callee stubs (minimal correct implementations)
# ---------------------------------------------------------------------------

def _COM_FD_to_TD__Bessel_Thomson_Filter(param, faxis, enable):
    """Stub: returns unit response (no filter) when not enabled, else BT shape."""
    if not enable:
        return np.ones(len(faxis))
    # Minimal BT: 4th-order Bessel-Thomson magnitude at faxis
    # using the bessel polynomial coefficients (verified fn)
    f0 = param.fb_BT_cutoff * param.fb  # 3 dB cutoff
    s = 1j * faxis / (f0 + 1e-300)
    # 4th-order Bessel poly coefficients [highest to lowest]
    b = [105, 105, 45, 10, 1]  # bessel(4)
    H0 = b[0]
    p = np.polyval(b, s)
    return np.abs(H0 / p)


def _COM_FD_to_TD__Butterworth_Filter(param, faxis, enable):
    """Stub: returns unit response when not enabled, else BW shape."""
    if not enable:
        return np.ones(len(faxis))
    f0 = param.fb / 2.0
    order = 4
    return 1.0 / np.sqrt(1.0 + (faxis / (f0 + 1e-300)) ** (2 * order))


def _COM_FD_to_TD__s21_to_impulse_DC(sdd21, faxis, sample_dt, OP, param):
    """Stub: minimal s21→impulse via ifft (matches s21_to_impulse_DC intent)."""
    N = len(sdd21)
    # Mirror spectrum and compute IFFT
    S = np.zeros(2 * N - 2, dtype=complex)
    S[:N] = sdd21
    S[N:] = np.conj(sdd21[-2:0:-1])
    ir = np.real(np.fft.ifft(S))
    dt = sample_dt
    t = np.arange(len(ir)) * dt
    return ir, t, 0.0, 0.0


def _COM_FD_to_TD__get_cm_noise(M, pulse_resp, levels, P_peak, OP):
    """Stub: returns a struct with CMn = RMS of pulse_resp."""
    rms_val = np.sqrt(np.mean(pulse_resp ** 2)) + 1e-30
    result = SimpleNamespace(CMn=rms_val, CMn_peak=rms_val)
    return result


# ---------------------------------------------------------------------------
# Main function
# ---------------------------------------------------------------------------

def COM_FD_to_TD(chdata, param, OP,
                 _s21_to_impulse_DC_fn=None,
                 _Bessel_Thomson_Filter_fn=None,
                 _Butterworth_Filter_fn=None,
                 _get_cm_noise_fn=None):
    """Convert frequency-domain S-parameters to time-domain pulse responses.

    MATLAB lines 1201–1361.

    chdata: list of SimpleNamespace objects, each with fields:
        faxis, sdd21, sdd21_raw, sdd21_orig, scd21_orig, sdc21_orig, A, type, base
    param: SimpleNamespace with fb, samples_per_ui, sample_dt, number_of_s4p_files,
        package_testcase_i, sigma_X, ndfe, f2, f1, levels, P_peak, etc.
    OP: SimpleNamespace with flags (Bessel_Thomson, Butterworth, transmitter_transition_time,
        RX_CALIBRATION, PSDRXCAL, DEBUG, DISPLAY_WINDOW, ENFORCE_CAUSALITY)

    Dependency injection via optional *_fn parameters for testing.
    Returns chdata (modified in place).
    """
    # Inject dependencies or use stubs
    s21_fn = _s21_to_impulse_DC_fn if _s21_to_impulse_DC_fn is not None else _COM_FD_to_TD__s21_to_impulse_DC
    bt_fn = _Bessel_Thomson_Filter_fn if _Bessel_Thomson_Filter_fn is not None else _COM_FD_to_TD__Bessel_Thomson_Filter
    bw_fn = _Butterworth_Filter_fn if _Butterworth_Filter_fn is not None else _COM_FD_to_TD__Butterworth_Filter
    cm_fn = _get_cm_noise_fn if _get_cm_noise_fn is not None else _COM_FD_to_TD__get_cm_noise

    # MATLAB release being emulated; set by read_ParamConfigFile. Defaults to the
    # 4p15p0 baseline when absent so a hand-built param still behaves as before.
    _v416 = str(getattr(param, 'matlab_version', '4p15p0')) == '4p16p0'

    M = int(param.samples_per_ui)

    # ---- Sinc helper (MATLAB sinc = sin(pi*x)/(pi*x)) ----
    def _sinc(x):
        px = np.pi * x + np.finfo(float).tiny  # eps(0) ≈ 5e-324; tiny is close enough
        return np.sin(px) / px

    # ---- Build Rx and Tx filters ----
    faxis = chdata[0].faxis
    H_bt = bt_fn(param, faxis, OP.Bessel_Thomson)
    H_bw = bw_fn(param, faxis, OP.Butterworth)
    H_r = H_bw * H_bt
    # Gaussian transmitter filter (eq uses transition time in ns; faxis in Hz)
    ttr = OP.transmitter_transition_time  # in ns (9e-3 typical)
    H_t = np.exp(-(np.pi * faxis / 1e9 * ttr / 1.6832) ** 2)
    H_filters = H_r * H_t

    for i in range(int(param.number_of_s4p_files)):
        ch = chdata[i]

        # ---- Impulse responses ----
        ch.uneq_imp_response, ch.t, ch.causality_correction_dB, ch.truncation_dB = \
            s21_fn(ch.sdd21, ch.faxis, param.sample_dt, OP, param)

        ch.uneq_pulse_response = lfilter(np.ones(M), 1, ch.uneq_imp_response)
        if _v416:
            # ML 4p16p0 L1236. cumsum of the pulse response decimated at the
            # symbol rate: MATLAB (1:samples_per_ui:end) is 1-based and starts
            # at the first sample, so the Python slice is [::M], not [M-1::M].
            ch.uneq_step_response = np.cumsum(ch.uneq_pulse_response[::M])

        ch.uneq_imp_response_raw, ch.t_raw, ch.causality_correction_dB, ch.truncation_dB = \
            s21_fn(ch.sdd21_raw, ch.faxis, param.sample_dt, OP, param)

        ch.uneq_pulse_response_raw = lfilter(np.ones(M), 1, ch.uneq_imp_response_raw)
        if _v416:
            ch.uneq_step_response_raw = np.cumsum(ch.uneq_pulse_response_raw[::M])

        ch.uneq_imp_response_raw_filtered, ch.t_raw_fltr, ch.causality_correction_dB, ch.truncation_dB = \
            s21_fn(ch.sdd21_raw * H_filters, ch.faxis, param.sample_dt, OP, param)
        if _v416:
            # ML 4p16p0 L1249-1250. Both fields are new: 4p15p0 computed the
            # filtered raw IMPULSE response but never a pulse or step from it.
            ch.uneq_pulse_response_raw_filtered = \
                lfilter(np.ones(M), 1, ch.uneq_imp_response_raw_filtered)
            ch.uneq_step_response_raw_filtered = \
                np.cumsum(ch.uneq_pulse_response_raw_filtered[::M])

        ch.uneq_imp_response_orig, ch.t_orig, ch.causality_correction_dB, ch.truncation_dB = \
            s21_fn(ch.sdd21_orig, ch.faxis, param.sample_dt, OP, param)

        ch.uneq_pulse_response_orig = lfilter(np.ones(M), 1, ch.uneq_imp_response_orig)
        if _v416:
            ch.uneq_step_response_orig = np.cumsum(ch.uneq_pulse_response_orig[::M])
        # Note: MATLAB recomputes this after the next filtered version
        ch.uneq_pulse_response_orig_filtered = lfilter(np.ones(M), 1, ch.uneq_pulse_response_orig)

        ch.uneq_imp_response_orig_filtered, ch.t_orig_fltr, ch.causality_correction_dB, ch.truncation_dB = \
            s21_fn(ch.sdd21_orig * H_filters, ch.faxis, param.sample_dt, OP, param)

        ch.uneq_pulse_response_orig_filtered = lfilter(np.ones(M), 1, ch.uneq_imp_response_orig_filtered)
        if _v416:
            # ML 4p16p0 L1265 -- after the SECOND assignment of
            # uneq_pulse_response_orig_filtered, so it uses the filtered-impulse
            # version, not the double-filtered one computed above.
            ch.uneq_step_response_orig_filtered = \
                np.cumsum(ch.uneq_pulse_response_orig_filtered[::M])

        # ---- Amplitude scaling ----
        USE_channel_amplitude = True
        if OP.RX_CALIBRATION and i > 0:
            USE_channel_amplitude = False
        if OP.PSDRXCAL and i == len(chdata) - 1:
            USE_channel_amplitude = False
        if USE_channel_amplitude:
            ch.uneq_imp_response = ch.uneq_imp_response * ch.A
            if _v416:
                # ML 4p16p0 L1277-1278. In 4p15p0 only the IMPULSE response was
                # scaled; the pulse response was built earlier from the unscaled
                # impulse and never corrected, so the two were inconsistent by a
                # factor of A. This is the one change in 4p16p0 that moves
                # already-reported numbers (peak_uneq_pulse_mV,
                # steady_state_voltage_mV), which is why it is version-gated.
                ch.uneq_pulse_response = ch.uneq_pulse_response * ch.A
                ch.uneq_step_response = ch.uneq_step_response * ch.A

        # ---- CD/DC common-mode impulse responses ----
        # 4p16p0 L1280/L1295 guard both conversions: "some test fixtures have
        # almost zero CM and will cause TD conversion to fail". 4p15p0 called
        # them unconditionally.
        if (not _v416) or float(np.mean(np.abs(ch.scd21_orig))) > 1e-6:
            (ch.uneq_CD_imp_response_filtered, ch.t_CD_fltr,
             ch.causality_correction_CD_dB, _trunc_cd) = \
                s21_fn(ch.scd21_orig * H_filters, ch.faxis, param.sample_dt, OP, param)
            ch.uneq_pulse_CD_response_filtered = \
                lfilter(np.ones(M), 1, ch.uneq_CD_imp_response_filtered)
        else:
            ch.t_CD_fltr = ch.t_raw
            ch.uneq_pulse_CD_response_filtered = np.zeros(len(ch.t_raw))
            _trunc_cd = 0.0
        # 4p16p0 L1284 fixed the field-name typo truncation__CD_dB ->
        # truncation_CD_dB. Both names are set so neither spelling breaks a
        # reader, whichever version is selected.
        ch.truncation_CD_dB = _trunc_cd
        ch.truncation__CD_dB = _trunc_cd

        if (not _v416) or float(np.mean(np.abs(ch.sdc21_orig))) > 1e-6:
            (ch.uneq_DC_imp_response_filtered, ch.t_DC_fltr,
             ch.causality_correction_DC_dB, _trunc_dc) = \
                s21_fn(ch.sdc21_orig * H_filters, ch.faxis, param.sample_dt, OP, param)
            ch.uneq_pulse_DC_response_filtered = \
                lfilter(np.ones(M), 1, ch.uneq_DC_imp_response_filtered)
        else:
            ch.t_DC_fltr = ch.t_raw
            ch.uneq_pulse_DC_response_filtered = np.zeros(len(ch.t_raw))
            _trunc_dc = 0.0
        ch.truncation_DC_dB = _trunc_dc
        ch.truncation__DC_dB = _trunc_dc

        # ---- Frequency band indices ----
        fax = ch.faxis
        a_idx = np.searchsorted(fax, param.f2, side='left')
        index_f2 = len(fax) - 1 if a_idx >= len(fax) else a_idx
        b_idx = np.searchsorted(fax, param.f1, side='right') - 1
        index_f1 = 0 if b_idx < 0 else b_idx

        # ---- Common-mode RMS (CD, DC) ----
        rss = -np.inf
        for im in range(M):
            rss = max(rss, np.linalg.norm(ch.uneq_pulse_CD_response_filtered[im::M]))
        ch.CD_CM_RMS = rss * np.sqrt(param.sigma_X)

        ch.VCM_CD_HF_struct = cm_fn(M, ch.uneq_pulse_CD_response_filtered, param.levels, param.P_peak, OP)
        ch.VCM_DC_HF_struct = cm_fn(M, ch.uneq_pulse_DC_response_filtered, param.levels, param.P_peak, OP)

        # ---- SCMR metrics (peak and RMS-based) ----
        # Use the first channel's filtered orig PR for signal power (i==0 only, but applied to all)
        PR_ORIG_fltr = chdata[0].uneq_pulse_response_orig_filtered
        ipeak = int(np.argmax(PR_ORIG_fltr))
        V_peak = PR_ORIG_fltr[ipeak]
        istart = ipeak % M  # 0-based phase offset
        nsteps = len(PR_ORIG_fltr) // M
        iend = istart + nsteps * M
        PR_sampled = PR_ORIG_fltr[istart:iend:M]
        P_signal = float(np.linalg.norm(PR_sampled) ** 2)
        ch.P_signal = P_signal

        CMn_cd = ch.VCM_CD_HF_struct.CMn
        CMn_dc = ch.VCM_DC_HF_struct.CMn
        # ML 1342-1345: 10*log10(V_peak^2/CMn^2) with NO 1e-300 floor on the
        # denominator. On a perfectly balanced channel CMn is exactly 0, where
        # the reference gives +Inf and the floored form gives a finite ~2993 dB
        # that reads like a measurement. Same defect FD_Processing carried on
        # its SCMR_FD_CD_ch_dB, and its test fixture used scd21_orig = zeros,
        # so that one was live. errstate only silences numpy; MATLAB divides by
        # zero quietly.
        # np.float64, not Python float: a Python scalar divided by zero RAISES
        # ZeroDivisionError, where MATLAB and numpy both give Inf. errstate
        # governs numpy's warning only, so the operands have to be numpy types
        # for the reference's own answer to come out at all.
        _cd = np.float64(CMn_cd) ** 2
        _dc = np.float64(CMn_dc) ** 2
        _vp = np.float64(V_peak) ** 2
        _ps = np.float64(P_signal)
        with np.errstate(divide='ignore', invalid='ignore'):
            ch.SCMR_CD_ch_pk = 10.0 * np.log10(_vp / _cd)
            ch.SCMR_CD_ch = 10.0 * np.log10(_ps / _cd)
            ch.SCMR_DC_ch_pk = 10.0 * np.log10(_vp / _dc)
            ch.SCMR_DC_ch = 10.0 * np.log10(_ps / _dc)

        # ---- Console output (matches MATLAB fprintf) ----
        if not OP.DISPLAY_WINDOW and i == 0:
            print('processing COM PDF ', end='')
        print(f'{ch.base}\tCausality correction = {ch.causality_correction_dB:.1f} dB', end='')
        if OP.ENFORCE_CAUSALITY:
            print()
        else:
            print(' (not applied)')
        print(f'{ch.base}\tTruncation ratio = {ch.truncation_dB:.1f} dB')

    return chdata



# --- COM_eye_width (MATLAB lines 1362–1551) ---

# ============================================================
# MATLAB→Python translation notes for COM_eye_width
# MATLAB lines: 1362–1551
# ============================================================
# Indexing: MATLAB 1-based → 0-based Python
#   half_UI: MATLAB ceil(samp_UI/2) [1-based] → samp_UI//2 [0-based]
#   pdf_range: MATLAB 1:samp_UI → Python range(samp_UI)
#   start_sample/end_sample: MATLAB 1-based → subtract 1 for Python
#   h_j_full(:,j): MATLAB col j [1-based] → h_j_full[:, j] [0-based]
#   A_s_vec(j): MATLAB 1-based → A_s_vec[j] [0-based]
#   pdf_full{n}(j): MATLAB 1-based both → pdf_full[n][j] [0-based]
#   eye_contour{n}(half_UI, :): MATLAB 1-based row → eye_contour[n][half_UI, :]
#
# Levels vector: MATLAB Levels=2*(0:L-1)/(L-1)-1 → [-1,...,+1] (L values)
# A_s_vec scaling: A_s_vec *= (levels-1)   [MATLAB: A_s_vec*(param.levels-1)]
#
# eye_contour output: samp_UI × 2*(levels-1) matrix
#   col (n-1)*2+1 (1-based) = A_ni_top{n+1} → col (n)*2 (0-based) = A_ni_top[n+1]
#   col (n-1)*2+2 (1-based) = A_ni_bottom{n} → col (n)*2+1 (0-based) = A_ni_bottom[n]
#
# out_VT/out_VB: only computed when param.T_O != 0 (windowed histogram)
# Histogram window types: gaussian, triangle, rectangle, dual_rayleigh
# ============================================================


def _COM_eye_width__histogram_window(T_O, QL, hw_type):
    """ML 1502-1524: the VEC histogram window, one vector of 2*T_O+1 weights.

    Lifted out of COM_eye_width so it can be driven on its own. The whole
    behaviour of OP.Histogram_Window_Weight lives here, and inline it was
    unreachable by any test: COM_eye_width needs the full get_pdf_full chain to
    run at all, so the three non-default window types sat in
    test_option_coverage.py's KNOWN_UNCOVERED with nothing exercising them.

    Verified against the reference by lifting ML 1502-1524 verbatim into an
    Octave function and running both on the same (T_O, QL). All four window
    types agree at T_O = 3, 5, 7, 8 and QL = 1.5, 2.5, 4.0: exact for
    gaussian, dual_rayleigh and rectangle, and within 3.4e-16 for triangle,
    whose MATLAB colon expression accumulates differently from arange.
    """
    T_O = int(T_O)
    if hw_type in ('gaussian', 'norm', 'normal', 'guassian'):
        QL_sigma = T_O / (QL + 1e-300)
        idx_arr = np.arange(-T_O, T_O + 1)
        return np.exp(-0.5 * (idx_arr / (QL_sigma + 1e-300)) ** 2)
    if hw_type == 'triangle':
        t_slope = 1.0 / T_O
        weights = np.concatenate([
            np.arange(0, 1 + t_slope, t_slope),
            np.arange(1 - t_slope, -t_slope, -t_slope)])
        return weights[:2 * T_O + 1]
    if hw_type == 'dual_rayleigh':
        QL_sigma = T_O / (QL + 1e-300)
        X = np.arange(-T_O, T_O + 1, dtype=float)
        weights = ((X + T_O) / QL_sigma ** 2 *
                   np.exp(-0.5 * ((X + T_O) / QL_sigma) ** 2) -
                   (X - T_O) / QL_sigma ** 2 *
                   np.exp(-0.5 * ((X - T_O) / QL_sigma) ** 2))
        return weights / (_COM_eye_width__mmax(weights) + 1e-300)
    if hw_type == 'rectangle':
        return np.ones(2 * T_O + 1)
    # ML 1523: otherwise -> error('%s not recognized for
    # Histogram_Window_Weight'). The port used to fall through to rectangle,
    # answering where the reference stops on a misspelled option.
    raise ValueError('%s not recognized for Histogram_Window_Weight' % hw_type)


def _COM_eye_width__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _COM_eye_width__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _COM_eye_width__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)


def _COM_eye_width__mmin(a):
    """MATLAB min(): the mirror of _COM_eye_width__mmax."""
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _COM_eye_width__mextreme_complex(a, 0)
    if a.dtype.kind != 'f':
        return np.min(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.min(a)
    return np.nanmin(a)



# ---------------------------------------------------------------------------
# Callee stubs
# ---------------------------------------------------------------------------


def _COM_eye_width__conv1d(a, b):
    """Direct convolution, as conv2 is. (This stub's FFT dispatch went with
    conv_fct's in 8ec85b0: an FFT loses the far tail of a PDF.)"""
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    return np.convolve(a, b)


def _COM_eye_width__get_pdf_full(chdata_0, delta_y, t_s, param, OP, pdf_range):
    """Stub: returns list of trivial PDFs, zero ISI, unit signal."""
    samp_UI = int(param.samples_for_C2M)
    n_bins = max(32, int(2.0 / delta_y))
    x0 = np.linspace(-1.0, 1.0, n_bins)
    dx = x0[1] - x0[0]
    y0 = np.ones(n_bins) / n_bins
    pdf_list = [SimpleNamespace(x=x0.copy(), y=y0.copy(), BinSize=dx, Min=-n_bins//2)
                for _ in range(samp_UI)]
    # h_j_full: ISI matrix shape (1, samp_UI) — minimal
    h_j_full = np.zeros((1, samp_UI))
    A_s_vec = np.ones(samp_UI) * 0.5  # representative signal amplitude
    return pdf_list, h_j_full, A_s_vec


def _COM_eye_width__normal_dist(sigma, n_sigma, delta_y):
    """Stub: Gaussian PDF."""
    n = max(32, int(n_sigma * sigma / (delta_y + 1e-300) * 2))
    x = np.linspace(-n_sigma * sigma, n_sigma * sigma, n)
    dx = x[1] - x[0] if n > 1 else 1.0
    y = np.exp(-0.5 * (x / (sigma + 1e-300))**2) / ((sigma + 1e-300) * np.sqrt(2 * np.pi)) * dx
    y /= y.sum() + 1e-300
    return SimpleNamespace(x=x, y=y, BinSize=dx, Min=int(x[0] / (dx + 1e-300)))


def _COM_eye_width__conv_fct(pdf_a, pdf_b):
    """Stub: convolve two PDFs (same x axis assumption)."""
    y_c = _COM_eye_width__conv1d(pdf_a.y, pdf_b.y)
    dx = float(getattr(pdf_a, 'BinSize', 1e-3))
    x_c = np.arange(len(y_c)) * dx + float(pdf_a.x[0]) + float(pdf_b.x[0])
    total = y_c.sum()
    y_c = y_c / (total + 1e-300)
    return SimpleNamespace(x=x_c, y=y_c, BinSize=dx, Min=int(x_c[0] / (dx + 1e-300)))


def _COM_eye_width__conv_fct_MeanNotZero(pdf_a, pdf_b):
    return _COM_eye_width__conv_fct(pdf_a, pdf_b)


def _COM_eye_width__get_pdf_from_sampled_signal(samples, levels, delta_y):
    """Stub: Gaussian from samples."""
    rms = float(np.sqrt(np.mean(np.asarray(samples, dtype=float)**2))) + 1e-30
    n = max(32, int(4 * rms / (delta_y + 1e-300)))
    x = np.linspace(-4 * rms, 4 * rms, n)
    dx = x[1] - x[0] if n > 1 else delta_y
    y = np.exp(-0.5 * (x / rms)**2) / (rms * np.sqrt(2 * np.pi)) * dx
    y /= y.sum() + 1e-300
    return SimpleNamespace(x=x, y=y, BinSize=dx, Min=int(x[0] / (dx + 1e-300)))


def _COM_eye_width__pdf_to_cdf(pdf):
    cdf_y = np.cumsum(pdf.y)
    return SimpleNamespace(x=pdf.x.copy(), y=cdf_y, BinSize=pdf.BinSize, Min=pdf.Min)


def _COM_eye_width__cdf_to_ber_contour(cdf, specBER):
    """Find top (V where CDF(V) >= 1-specBER) and bottom (V where CDF(V) >= specBER) voltages."""
    idx_top = int(np.searchsorted(cdf.y, 1.0 - specBER))
    idx_bot = int(np.searchsorted(cdf.y, specBER))
    x = cdf.x
    top = float(x[min(idx_top, len(x) - 1)])
    bot = float(x[min(idx_bot, len(x) - 1)])
    return top, bot


def _COM_eye_width__find_eye_width(eye_contour_n, half_UI, samp_UI, vref):
    """Stub: return half of samp_UI as symmetric eye width."""
    half = samp_UI // 4
    return float(half), float(half)


def _COM_eye_width__combine_pdf_same_voltage_axis(pdf_a, pdf_b):
    """Stub: add y values (assumes same x axis)."""
    if len(pdf_a.y) == len(pdf_b.y):
        y_combined = pdf_a.y + pdf_b.y
    else:
        y_combined = pdf_a.y.copy()
    return SimpleNamespace(x=pdf_a.x.copy(), y=y_combined, BinSize=pdf_a.BinSize, Min=pdf_a.Min)


# ---------------------------------------------------------------------------
# Main function
# ---------------------------------------------------------------------------

def COM_eye_width(chdata, delta_y, fom_result, param, OP, Struct_Noise, pdf_range_flag,
                  _get_center_of_UI_fn=None,
                  _get_pdf_full_fn=None,
                  _normal_dist_fn=None,
                  _conv_fct_fn=None,
                  _conv_fct_MNZ_fn=None,
                  _get_pdf_ss_fn=None,
                  _pdf_to_cdf_fn=None,
                  _cdf_to_ber_fn=None,
                  _find_eye_width_fn=None,
                  _combine_pdf_fn=None):
    """Compute eye width and contours for the COM figure of merit.

    MATLAB lines 1362–1551.

    chdata: list of SimpleNamespace (chdata[0] is the primary channel)
    delta_y: voltage bin size for PDFs
    fom_result: SimpleNamespace with t_s field (cursor sample index, 0-based)
    param: SimpleNamespace with samples_for_C2M, T_O, levels, specBER, sigma_RJ,
           sigma_X, A_DD, QL
    OP: SimpleNamespace with Histogram_Window_Weight, ber_q
    Struct_Noise: SimpleNamespace with sigma_N, sigma_TX, ne_noise_pdf, cci_pdf, ber_q
    pdf_range_flag: bool — if True, limit PDF computation to T_O window around center

    Returns (Left_EW, Right_EW, eye_contour, out_VT, out_VB)
        Left_EW, Right_EW: arrays of length (levels-1), time in samples
        eye_contour: (samp_UI, 2*(levels-1)) array
        out_VT, out_VB: scalars or [] (only set when T_O != 0)
    """
    gcu_fn = _get_center_of_UI_fn or _get_center_of_UI
    gpf_fn = _get_pdf_full_fn or _COM_eye_width__get_pdf_full
    nd_fn = _normal_dist_fn or _COM_eye_width__normal_dist
    cf_fn = _conv_fct_fn or _COM_eye_width__conv_fct
    cfmz_fn = _conv_fct_MNZ_fn or _COM_eye_width__conv_fct_MeanNotZero
    gpss_fn = _get_pdf_ss_fn or _COM_eye_width__get_pdf_from_sampled_signal
    ptc_fn = _pdf_to_cdf_fn or _COM_eye_width__pdf_to_cdf
    ber_fn = _cdf_to_ber_fn or _COM_eye_width__cdf_to_ber_contour
    few_fn = _find_eye_width_fn or _COM_eye_width__find_eye_width
    cpdf_fn = _combine_pdf_fn or _COM_eye_width__combine_pdf_same_voltage_axis

    samp_UI = int(param.samples_for_C2M)
    levels = int(param.levels)
    specBER = float(param.specBER)
    sigma_RJ = float(param.sigma_RJ)
    sigma_X = float(param.sigma_X)
    A_DD = float(param.A_DD)
    ber_q = float(getattr(Struct_Noise, 'ber_q', getattr(OP, 'ber_q', 7.0)))

    # 0-based center index
    half_UI = gcu_fn(samp_UI)  # 0-based

    T_O = int(np.floor((param.T_O / 1000.0) * samp_UI))
    start_sample = half_UI - T_O
    end_sample = half_UI + T_O

    # pdf_range: get_pdf_full expects 1-based MATLAB indices (matching MATLAB COM_eye_width)
    if pdf_range_flag:
        pdf_range_pass = [start_sample + 1, end_sample + 1]
    else:
        pdf_range_pass = []

    pdf_full_1, h_j_full, A_s_vec = gpf_fn(
        chdata[0], delta_y, fom_result.t_s, param, OP, pdf_range_pass)

    # Resolve pdf_range to full list of 0-based indices
    if not pdf_range_flag or not pdf_range_pass:
        pdf_range = list(range(samp_UI))
    else:
        pdf_range = list(range(min(start_sample, end_sample),
                               max(start_sample, end_sample) + 1))

    # Normalized signal amplitude levels: -1, ..., +1
    Levels = 2.0 * np.arange(levels) / (levels - 1) - 1.0  # shape (levels,)
    A_s_vec = np.asarray(A_s_vec) * (levels - 1)  # scale

    # ---- Build per-level shifted PDFs ----
    # pdf_full[n][j]: copy of pdf_full_1[j] with x shifted by A_s_vec[j] * Levels[n]
    pdf_full = []
    for n in range(levels):
        pdf_n = [copy.deepcopy(pdf_full_1[j]) for j in range(samp_UI)]
        for j in pdf_range:
            shift = float(A_s_vec[j]) * float(Levels[n])
            pdf_n[j].x = pdf_n[j].x + shift
            dx = float(pdf_n[j].BinSize)
            pdf_n[j].Min = int(pdf_n[j].x[0] / (dx + 1e-300))
        pdf_full.append(pdf_n)

    # ---- Build noise + ISI combined PDFs ----
    sigma_G_full = np.zeros(samp_UI)
    combined_pdf = [[None] * samp_UI for _ in range(levels)]
    combined_cdf = [[None] * samp_UI for _ in range(levels)]

    sigma_N = float(Struct_Noise.sigma_N)
    sigma_TX = float(Struct_Noise.sigma_TX)

    for n in range(levels):
        for j in pdf_range:
            h_col = h_j_full[:, j].ravel()
            sigma_G_full[j] = float(np.linalg.norm([
                sigma_RJ * sigma_X * float(np.linalg.norm(h_col)),
                sigma_N,
                sigma_TX,
            ]))
            g_pdf = nd_fn(sigma_G_full[j], ber_q, delta_y)
            g_pdf = cf_fn(g_pdf, Struct_Noise.ne_noise_pdf)
            dd_pdf = gpss_fn(A_DD * h_col, levels, delta_y)
            noise_pdf = cf_fn(g_pdf, dd_pdf)
            isi_xtalk_pdf = cfmz_fn(pdf_full[n][j], Struct_Noise.cci_pdf)
            comb_pdf = cfmz_fn(isi_xtalk_pdf, noise_pdf)
            combined_pdf[n][j] = comb_pdf
            combined_cdf[n][j] = ptc_fn(comb_pdf)

    # ---- BER contour: top and bottom voltages ----
    A_ni_top = [np.zeros(samp_UI) for _ in range(levels)]
    A_ni_bot = [np.zeros(samp_UI) for _ in range(levels)]
    for n in range(levels):
        for j in pdf_range:
            top, bot = ber_fn(combined_cdf[n][j], specBER)
            A_ni_top[n][j] = top
            A_ni_bot[n][j] = bot

    # ---- Eye contour: (levels-1) eyes ----
    # MATLAB: eye_contour{n}(:,1)=A_ni_top{n+1};  eye_contour{n}(:,2)=A_ni_bottom{n};
    n_eyes = levels - 1
    eye_contour_list = []
    for n in range(n_eyes):
        ec_n = np.column_stack([A_ni_top[n + 1], A_ni_bot[n]])  # shape (samp_UI, 2)
        eye_contour_list.append(ec_n)

    # ---- Eye width ----
    Left_EW = np.zeros(n_eyes)
    Right_EW = np.zeros(n_eyes)
    for n in range(n_eyes):
        EH_top = float(eye_contour_list[n][half_UI, 0])
        EH_bot = float(eye_contour_list[n][half_UI, 1])
        vref = EH_top / 2.0 + EH_bot / 2.0
        lew, rew = few_fn(eye_contour_list[n], half_UI, samp_UI, vref)
        Left_EW[n] = lew
        Right_EW[n] = rew

    # ---- Convert eye_contour cell to matrix ----
    eye_contour = np.zeros((samp_UI, 2 * n_eyes))
    for n in range(n_eyes):
        eye_contour[:, n * 2: n * 2 + 2] = eye_contour_list[n]

    # ---- Timing-bathtub data for plotting (final full-eye call only) ----
    # BER vs sample phase at each eye's center threshold (the horizontal scan).
    # Stored on chdata[0] as a side-channel so the return signature (and MATLAB
    # fidelity) is unchanged; consumed by com_plots when OP.SAVE_FIGURES.
    if not pdf_range_flag:
        # pdf_to_cdf returns THREE curves and picking the wrong one silently
        # produces a flat 0.5:
        #     yB = cumsum(pdf)        = P(V <= v)   (bottom-eye tail)
        #     yT = reverse cumsum     = P(V >= v)   (top-eye tail)
        #     y  = min(yB, yT)        -- necessarily ~0.5 mid-distribution
        # A threshold crossing is an error only in one direction per level: the
        # UPPER level errs by falling below the threshold (yB), the LOWER level
        # by rising above it (yT). An earlier version of this block used `y` and
        # `1 - y`, which reads the minimum of two half-probabilities and pinned
        # every bathtub at BER ~ 0.5 regardless of how open the eye was.
        def _tail(cdf_obj, which):
            """P(V<=v) for 'B' or P(V>=v) for 'T', with a safe fallback."""
            arr = getattr(cdf_obj, 'yB' if which == 'B' else 'yT', None)
            if arr is None:                      # minimal stub without yB/yT
                y = np.asarray(cdf_obj.y, dtype=float)
                arr = np.cumsum(y) if which == 'B' else np.flip(np.cumsum(np.flip(y)))
            return np.asarray(arr, dtype=float).ravel()

        def _eye_ber(up, lo, j, vth):
            """Symbol-error probability at threshold vth for the eye up/lo."""
            cuj, clj = combined_cdf[up][j], combined_cdf[lo][j]
            if cuj is None or clj is None:
                return np.nan
            ber_up = float(np.interp(vth, np.asarray(cuj.x, dtype=float),
                                     _tail(cuj, 'B')))
            ber_lo = float(np.interp(vth, np.asarray(clj.x, dtype=float),
                                     _tail(clj, 'T')))
            return 0.5 * (ber_up + ber_lo)

        phase_UI = (np.arange(samp_UI) - half_UI) / float(samp_UI)

        # --- timing bathtub: sweep sample phase at each eye's own threshold ---
        ber_eyes = np.full((n_eyes, samp_UI), np.nan)
        vth_eyes = np.zeros(n_eyes)
        for n in range(n_eyes):
            up, lo = n + 1, n
            vth = 0.5 * (A_ni_bot[lo][half_UI] + A_ni_top[up][half_UI])
            vth_eyes[n] = vth
            for j in range(samp_UI):
                ber_eyes[n, j] = _eye_ber(up, lo, j, vth)

        # --- voltage bathtub: sweep the threshold at the centre phase ---------
        # One curve per eye, each spanning its own eye and therefore centred on
        # that eye's level rather than on a single +/-A_s pair.
        # The axis must run well BEYOND the outer thresholds, not just span the
        # eye edges: each outer eye's bathtub keeps rising past its own level,
        # and an axis that stops at the outermost threshold clips those two
        # curves mid-slope. Extend by a full eye spacing on each side so every
        # curve reaches its ~0.5 shoulders.
        v_lo = min(float(A_ni_top[n + 1][half_UI]) for n in range(n_eyes))
        v_hi = max(float(A_ni_bot[n][half_UI]) for n in range(n_eyes))
        vth_min, vth_max = float(_COM_eye_width__mmin(vth_eyes)), float(_COM_eye_width__mmax(vth_eyes))
        if n_eyes > 1:
            pad = (vth_max - vth_min) / (n_eyes - 1)      # one eye spacing
        else:
            pad = max(v_hi - v_lo, 1e-6)
        lo = min(v_lo, vth_min - pad)
        hi = max(v_hi, vth_max + pad)
        v_axis = np.linspace(lo, hi, 601)
        ber_v = np.full((n_eyes, v_axis.size), np.nan)
        for n in range(n_eyes):
            up, lo = n + 1, n
            for k, vth in enumerate(v_axis):
                ber_v[n, k] = _eye_ber(up, lo, half_UI, float(vth))

        chdata[0].timing_bathtub = {"phase_UI": phase_UI, "ber_eyes": ber_eyes,
                                    "eye_contour": eye_contour,
                                    "eye_threshold_V": vth_eyes,
                                    "vbt_threshold_V": v_axis,
                                    "vbt_ber": ber_v}

    # ---- Windowed VEC (out_VT, out_VB) when T_O != 0 ----
    out_VT = []
    out_VB = []
    if int(param.T_O) != 0:
        T_O_nonzero = T_O if T_O > 0 else 1
        hw_type = str(getattr(OP, 'Histogram_Window_Weight', 'rectangle')).lower()
        weights = _COM_eye_width__histogram_window(T_O_nonzero, float(param.QL), hw_type)

        # Build weighted combined PDF for each level
        out_pdf_levels = [None] * levels
        for n in range(levels):
            out_pdf_n = None
            for j_idx, j in enumerate(range(start_sample, end_sample + 1)):
                if j < 0 or j >= samp_UI:
                    continue
                if combined_pdf[n][j] is None:
                    continue
                target = copy.deepcopy(combined_pdf[n][j])
                w = float(weights[j_idx])
                target.y = target.y * w
                if out_pdf_n is None:
                    out_pdf_n = target
                else:
                    out_pdf_n = cpdf_fn(out_pdf_n, target)
            if out_pdf_n is not None:
                s = out_pdf_n.y.sum()
                out_pdf_n.y = out_pdf_n.y / (s + 1e-300)
            out_pdf_levels[n] = out_pdf_n

        out_cdf_levels = [ptc_fn(p) if p is not None else None for p in out_pdf_levels]

        A_ni_top_O = np.zeros(levels)
        A_ni_bot_O = np.zeros(levels)
        for n in range(levels):
            if out_cdf_levels[n] is not None:
                top, bot = ber_fn(out_cdf_levels[n], specBER)
            else:
                top, bot = 0.0, 0.0
            A_ni_top_O[n] = top
            A_ni_bot_O[n] = bot

        OUT_VT_L = np.zeros((n_eyes, 2))
        for n in range(n_eyes):
            OUT_VT_L[n, 0] = A_ni_top_O[n + 1]
            OUT_VT_L[n, 1] = A_ni_bot_O[n]

        EH_VT = OUT_VT_L[:, 0] - OUT_VT_L[:, 1]
        min_idx = int(np.argmin(EH_VT))
        out_VT = float(OUT_VT_L[min_idx, 0])
        out_VB = float(OUT_VT_L[min_idx, 1])

    return Left_EW, Right_EW, eye_contour, out_VT, out_VB



# --- Create_Noise_PDF (MATLAB lines 1552–1680) ---

# ============================================================
# MATLAB→Python translation notes for Create_Noise_PDF
# MATLAB lines: 1552–1680
# ============================================================
# Inputs: A_s, param, fom_result, chdata, OP, sigma_bn, PSD_results.
# RX_CALIBRATION==1: compute sigma_ne via get_sigma_noise (inlined).
# CTLE_type 'CL120e' under RX_CALIBRATION raises: MATLAB L1592 reads bare
#   f_HP_P/f_HP_Z, undefined in this scope, so the reference errors there too.
# NS.sigma_N = fom_result.sigma_N.
# Non-MMSE path: sigma_TX uses SNR_TX param; sigma_G = norm([sigma_RJ*sigma_X*norm(h_J), sigma_N, sigma_TX]).
# MMSE path: sigma_TX/sigma_G/sigma_rjit/sigma_N from PSD_results.
# NS.ber_q: erfcinv-based from specBER, or Noise_Crest_Factor if nonzero.
# normal_dist inlined as _normal_dist.
# conv_fct inlined as _conv_fct.
# d_cpdf inlined as _d_cpdf.
# NS.p_DD = get_pdf_from_sampled_signal(A_DD*h_J, levels, delta_y) [inlined].
# NS.sci_pdf = chdata[0].pdfr.
# sci_mxi, sci_msi: find(cumsum(sci_pdf.y) >= specBER, 1, 'first') 1-based → argmax on cumsum.
# CCI loop: k=2..number_of_s4p_files (1-based) → Python k=1..N-1 (0-based).
# combined_interference_and_noise_pdf = conv(isi_and_xtalk_pdf, noise_pdf).
# N_qb != 0 path (Eq 93A-37, MATLAB L1674-1675): calls the top-level
#   adjust_Rx_noise_for_quantization. That fn references fom_result.RxFFE, so the
#   quantization path is only valid together with RxFFE (true in MATLAB too).
# ============================================================


def _Create_Noise_PDF__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _Create_Noise_PDF__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _Create_Noise_PDF__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)





# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.


def _Create_Noise_PDF__get_pdf_from_sampled_signal(input_vector, L, BinSize):
    iv = np.asarray(input_vector, dtype=float).ravel()
    if len(iv) == 0:
        return _d_cpdf(BinSize, 0, 1)
    if _Create_Noise_PDF__mmax(np.abs(iv)) > BinSize:
        iv = iv[np.abs(iv) > BinSize]
    else:
        return _d_cpdf(BinSize, 0, 1)
    iv[np.abs(iv) < BinSize] = 0.0
    b = np.sign(iv)
    sort_idx = np.argsort(np.abs(iv), kind='stable')[::-1]
    iv = np.abs(iv[sort_idx]) * b[sort_idx]
    values = 2.0 * np.arange(L) / (L - 1) - 1.0
    prob = np.ones(L) / L
    pdf = _d_cpdf(BinSize, 0, 1)
    empty_pdf = pdf
    for v in iv:
        pdfn = _Init_PDF_Fast(empty_pdf, np.abs(v) * values, prob)
        pdf = _conv_fct(pdf, pdfn)
    return pdf


def _Create_Noise_PDF__get_sigma_noise(H_ctf, param, chdata, sigma_bn):
    """Inlined get_sigma_noise for RX_CALIBRATION path."""
    H_ctf = np.asarray(H_ctf, dtype=complex)
    faxis = np.asarray(chdata[1].faxis, dtype=float).ravel()
    H_r = 1.0 / np.polyval(
        [1, 2.613126, 3.414214, 2.613126, 1],
        1j * faxis / (float(param.f_r) * float(param.fb))
    )
    idx0 = int(np.argmax(faxis >= float(param.fb) / 2))
    idxfbby2 = idx0 + 1

    if len(chdata) >= 2:
        Hnoise_channel = np.asarray(chdata[1].sdd21, dtype=complex).ravel()
    else:
        Hnoise_channel = np.ones(len(faxis), dtype=complex)

    f = faxis
    f_hp = float(param.f_hp)
    if f_hp != 0:
        H_hp = (-1j * f / f_hp) / (1 + 1j * f / f_hp)
    else:
        H_hp = np.ones(len(f), dtype=complex)

    H_np = Hnoise_channel * H_ctf * H_r * H_hp
    sigma_NE = float(sigma_bn) * np.sqrt(np.mean(np.abs(H_np[:idxfbby2]) ** 2))
    sigma_HP = float(sigma_bn) * np.mean(np.abs(H_hp[:idxfbby2]) ** 2)
    return sigma_NE, sigma_HP


def Create_Noise_PDF(A_s, param, fom_result, chdata, OP, sigma_bn, PSD_results=None):
    """Compute combined interference and noise PDF/CDF (MATLAB lines 1552-1680).

    Returns (PDF, CDF, NS) where NS is a SimpleNamespace of noise parameters.
    """
    NS = SimpleNamespace()
    delta_y = float(param.delta_y)

    if OP.RX_CALIBRATION:
        ctle_i = int(fom_result.ctle) - 1  # 0-based
        faxis2 = np.asarray(chdata[1].faxis, dtype=float).ravel()
        ctle_gain2 = ((10.0 ** (float(param.ctle_gdc_values[ctle_i]) / 20.0)
                       + 1j * faxis2 / float(param.CTLE_fz[ctle_i]))
                      / ((1 + 1j * faxis2 / float(param.CTLE_fp1[ctle_i]))
                         * (1 + 1j * faxis2 / float(param.CTLE_fp2[ctle_i]))))
        ctype = str(param.CTLE_type)
        if ctype == 'CL93':
            H_low2 = 1.0
        elif ctype == 'CL120d':
            ghp_i = int(fom_result.best_G_high_pass) - 1
            H_low2 = ((10.0 ** (float(param.g_DC_HP_values[ghp_i]) / 20.0)
                       + 1j * faxis2 / float(param.f_HP[ghp_i]))
                      / (1 + 1j * faxis2 / float(param.f_HP[ghp_i])))
        elif ctype == 'CL120e':
            # UPSTREAM DEFECT (MATLAB L1592): this one line reads bare
            # f_HP_P(...) and f_HP_Z(...) where the six other sites in the
            # reference write param.f_HP_P(...) / param.f_HP_Z(...). Neither
            # bare name exists in Create_Noise_PDF's scope, so the reference
            # cannot execute this branch at all.
            #   COM Octave, CTLE_type='CL120e', OP.RX_CALIBRATION=1:
            #     error: 'f_HP_P' undefined near line 16, column 45
            #         Create_Noise_PDF at line 16 column 13
            # MATLAB raises the same "Undefined function or variable".
            # The port read param.f_HP_P/param.f_HP_Z, i.e. it answered where
            # the reference stops. Copying the reference's bug is the ruling;
            # knowing it occurred is the point, so it raises with the reason
            # named. Also recorded in com_functions/verification/builtins.md.
            raise ValueError(
                "Create_Noise_PDF: CTLE_type='CL120e' with OP.RX_CALIBRATION "
                'cannot run. MATLAB line 1592 reads bare f_HP_P/f_HP_Z '
                'instead of param.f_HP_P/param.f_HP_Z, which are undefined in '
                'this function. COM Octave: "error: \'f_HP_P\' undefined near '
                'line 16, column 45, Create_Noise_PDF at line 16 column 13". '
                'Upstream defect, for the COM ad hoc -- not a port failure.')
        else:
            H_low2 = 1.0
        H_ctf2 = H_low2 * ctle_gain2
        sigma_ne, NS.sigma_hp = _Create_Noise_PDF__get_sigma_noise(H_ctf2, param, chdata, sigma_bn)
    else:
        sigma_ne = 0.0

    NS.sigma_N = float(fom_result.sigma_N)

    use_mmse = (str(OP.FFE_OPT_METHOD).upper() == 'MMSE' and OP.RxFFE)
    if not use_mmse:
        if not OP.SNR_TXwC0:
            NS.sigma_TX = float((param.levels - 1) * A_s / param.R_LM
                                * 10.0 ** (-param.SNR_TX / 20.0))
        else:
            cur = int(fom_result.cur) - 1  # 0-based
            NS.sigma_TX = float((param.levels - 1) * A_s
                                / float(fom_result.txffe[cur])
                                / param.R_LM
                                * 10.0 ** (-param.SNR_TX / 20.0))
        h_J = np.asarray(fom_result.h_J, dtype=float).ravel()
        NS.sigma_rjit = float(param.sigma_RJ * param.sigma_X * np.linalg.norm(h_J))
        NS.sigma_G = float(np.linalg.norm([NS.sigma_rjit, NS.sigma_N, NS.sigma_TX]))
    else:
        if OP.PSDRXCAL:
            NS.sigma_hp = float(sigma_bn)
        NS.sigma_TX = float(PSD_results.S_tn_rms)
        NS.sigma_G = float(PSD_results.S_G_rms)
        NS.sigma_rjit = float(PSD_results.S_rj_rms)
        NS.sigma_N = float(PSD_results.S_rn_rms)

    if param.Noise_Crest_Factor == 0:
        NS.ber_q = float(np.sqrt(2) * erfcinv(2 * param.specBER))
    else:
        NS.ber_q = float(param.Noise_Crest_Factor)

    NS.gaussian_noise_pdf = _normal_dist(NS.sigma_G, NS.ber_q, delta_y)

    if OP.force_BBN_Q_factor:
        NS.ne_noise_pdf = _normal_dist(sigma_ne, OP.BBN_Q_factor, delta_y)
    else:
        NS.ne_noise_pdf = _normal_dist(sigma_ne, NS.ber_q, delta_y)
    NS.gaussian_noise_pdf = _conv_fct(NS.gaussian_noise_pdf, NS.ne_noise_pdf)

    h_J = np.asarray(fom_result.h_J, dtype=float).ravel()
    NS.p_DD = _Create_Noise_PDF__get_pdf_from_sampled_signal(param.A_DD * h_J, int(param.levels), delta_y)

    NS.noise_pdf = _conv_fct(NS.gaussian_noise_pdf, NS.p_DD)
    gaussian_rjitt_pdf = _normal_dist(NS.sigma_rjit, NS.ber_q, delta_y)
    NS.jitt_pdf = _conv_fct(gaussian_rjitt_pdf, NS.p_DD)

    NS.sci_pdf = chdata[0].pdfr

    def _first_ber_idx(pdf_obj):
        cdf_y = np.cumsum(np.asarray(pdf_obj.y, dtype=float))
        idxs = np.where(cdf_y >= float(param.specBER))[0]
        return int(idxs[0]) if len(idxs) > 0 else len(cdf_y) - 1

    sci_mxi = _first_ber_idx(NS.sci_pdf)
    NS.thru_peak_interference_at_BER = float(abs(NS.sci_pdf.x[sci_mxi]))
    NS.sci_sigma = float(abs(NS.sci_pdf.x[sci_mxi]
                             / (erfcinv(2 * param.specBER) * np.sqrt(2))))

    if not OP.RX_CALIBRATION:
        MDNEXT_cci_pdf = _d_cpdf(delta_y, 0, 1)
        MDFEXT_cci_pdf = _d_cpdf(delta_y, 0, 1)
        # MATLAB k=2..number_of_s4p_files (1-based) → Python k=1..len(chdata)-1 (0-based)
        n_files = getattr(param, 'number_of_s4p_files', len(chdata))
        for k in range(1, n_files):
            if k >= len(chdata):
                break
            if chdata[k].type == 'NEXT':
                MDNEXT_cci_pdf = _conv_fct(MDNEXT_cci_pdf, chdata[k].pdfr)
            elif chdata[k].type == 'FEXT':
                MDFEXT_cci_pdf = _conv_fct(MDFEXT_cci_pdf, chdata[k].pdfr)
            else:
                raise ValueError(f'Crosstalk PDF unexpected channel type: {chdata[k].type!r}')

        mdnxi = _first_ber_idx(MDNEXT_cci_pdf)
        NS.MDNEXT_peak_interference = float(abs(MDNEXT_cci_pdf.x[mdnxi]))
        mdfxi = _first_ber_idx(MDFEXT_cci_pdf)
        NS.MDFEXT_peak_interference = float(abs(MDFEXT_cci_pdf.x[mdfxi]))

        NS.cci_pdf = _conv_fct(MDFEXT_cci_pdf, MDNEXT_cci_pdf)
        cci_mxi = _first_ber_idx(NS.cci_pdf)
        NS.crosstalk_peak_interference_at_BER = float(abs(NS.cci_pdf.x[cci_mxi]))
        NS.cci_sigma = float(abs(NS.cci_pdf.x[cci_mxi]
                                 / (erfcinv(2 * param.specBER) * np.sqrt(2))))
        NS.isi_and_xtalk_pdf = _conv_fct(NS.sci_pdf, NS.cci_pdf)
    else:
        NS.isi_and_xtalk_pdf = NS.sci_pdf

    mxi = _first_ber_idx(NS.isi_and_xtalk_pdf)
    NS.peak_interference_at_BER = float(abs(NS.isi_and_xtalk_pdf.x[mxi]))

    combined_interference_and_noise_pdf = _conv_fct(NS.isi_and_xtalk_pdf, NS.noise_pdf)

    if int(param.N_qb) != 0:
        # Equation 93A-37 (MATLAB L1674-1675): apply Rx ADC quantization noise.
        # adjust_Rx_noise_for_quantization is a top-level fn in the assembled module.
        chdata, NS, combined_interference_and_noise_pdf = adjust_Rx_noise_for_quantization(
            combined_interference_and_noise_pdf, NS, chdata, fom_result, param, OP)

    CDF = np.cumsum(np.asarray(combined_interference_and_noise_pdf.y, dtype=float))
    return combined_interference_and_noise_pdf, CDF, NS



# --- FD_CTLE (MATLAB lines 1681–1683) ---

# ============================================================
# MATLAB→Python translation notes for FD_CTLE
# MATLAB lines: 1681–1683
# ============================================================
# 10.^(kacdc_dB/20): scalar → float; 10**(kacdc_dB/20)
# ./ and .* are element-wise → standard numpy ops on arrays
# kacdc_dB ≤ 0 typical: DC gain < 1, peaking at high frequency
# At freq=0: H = 10^(kacdc_dB/20) (real DC value)
# ============================================================



def FD_CTLE(freq, f_z, f_p1, f_p2, kacdc_dB):
    freq = np.asarray(freq, dtype=float)
    num = 10 ** (kacdc_dB / 20) + 1j * freq / f_z
    den = (1 + 1j * freq / f_p1) * (1 + 1j * freq / f_p2)
    return num / den



# --- FD_Processing (MATLAB lines 1684–2025) ---

"""
FD_Processing: Frequency-domain metrics — IL fit, FOM_ILD, ICN, FEXT/NEXT noise.
MATLAB lines 1684–2025.
"""



_EPS0 = np.nextafter(0.0, 1.0)   # MATLAB eps(0) = 4.9406564584124654e-324


def _FD_Processing__W(f, ft, fr, fb):
    """Power weighting function, eq 93A-57: sinc^2 * 4th-order * 8th-order rolloff.

    Transcribed operation for operation from the reference, which is
        Sinc = @(x) sin(pi*x+eps(0))./(pi*x+eps(0));
        W = @(f,ft,fr,fb) 1/fb * Sinc(f/fb).^2 .* (1./(1+(f/ft).^4)) .* (1./(1+(f/fr).^8));
    The order matters: `1/fb * A` rounds the reciprocal first and is not the
    same double as `A / fb`, and the earlier `+1e-300` guards on fb/ft/fr were
    an invented floor.  The previous spelling differed from the reference in
    15 of 32 samples at the last bit; this one is bit-identical.
    """
    x = f / fb
    sinc = np.sin(np.pi * x + _EPS0) / (np.pi * x + _EPS0)
    return (1.0 / fb * sinc**2
            * (1.0 / (1.0 + (f / ft)**4))
            * (1.0 / (1.0 + (f / fr)**8)))


def _FD_Processing__neg20log10(x):
    """MATLAB -20*log10(abs(x)).

    No epsilon floor: at |x| = 0 the reference returns +Inf, and every metric
    built on it (a ratio in dB, an interp1 through the bin) inherits that Inf.
    `-20*log10(|x| + 1e-300)` returns ~6000 dB instead, which is finite and
    plausible and therefore worse than the Inf.
    """
    with np.errstate(divide='ignore'):
        return -20.0 * np.log10(np.abs(x))


def _FD_Processing__db10_ratio(num, den):
    """MATLAB 10*log10(num/den) -- +Inf at den == 0, with no epsilon floor."""
    with np.errstate(divide='ignore', invalid='ignore'):
        return float(10.0 * np.log10(np.float64(num) / np.float64(den)))


def _FD_Processing__interp1(x, v, xq):
    """MATLAB interp1(x, v, xq) at one point: linear, NaN outside the data.

    Two things np.interp does differently, both of which showed up against the
    reference:

    * np.interp CLAMPS outside [x[0], x[-1]] and returns the end value, where
      interp1 with no extrapolation argument returns NaN.  A channel whose
      frequency axis starts above Nyquist came back with the first bin's loss
      instead of NaN.
    * np.interp carries a NaN-avoidance retry: when `slope*(xq-x[i]) + v[i]`
      is NaN it recomputes from the right-hand end.  interp1 has no such
      fallback, so where v[i] is +Inf (a zero S-parameter bin) it returns NaN
      and np.interp returned +Inf.
      COM Octave: interp1([0 1 2 3],[1 Inf 3 4],[0 0.5 1 1.5 2]) ->
        [NaN Inf NaN NaN 3];  np.interp gave [1 Inf Inf Inf 3].

    So spell out interp1's own `s*dy(k) + v(k)` on the bracket `lookup` picks.
    """
    xa = np.asarray(x, dtype=float).ravel()
    va = np.asarray(v, dtype=float).ravel()
    if xq < xa[0] or xq > xa[-1]:
        return float('nan')
    k = int(np.searchsorted(xa, xq, side='right')) - 1
    k = min(max(k, 0), len(xa) - 2)
    s = (xq - xa[k]) / (xa[k + 1] - xa[k])
    with np.errstate(invalid='ignore'):      # Inf-Inf is a result, not a warning
        return float(s * (va[k + 1] - va[k]) + va[k])


def _FD_Processing__find_idx_ge(faxis, f):
    """0-based index of first element >= f; clamps to len-1 if none found."""
    idx = int(np.searchsorted(faxis, f, side='left'))
    return min(idx, len(faxis) - 1)


def _FD_Processing__find_idx_le(faxis, f):
    """0-based index of last element <= f; clamps to 0 if none found."""
    idx = int(np.searchsorted(faxis, f, side='right')) - 1
    return max(idx, 0)


def FD_Processing(chdata, output_args, param, OP, SDDp2p=None, DO_ONCE=True,
                  _get_ILN_fn=None, _get_ILN_cmp_td_fn=None,
                  _capture_RIL_RILN_fn=None,
                  _Bessel_Thomson_Filter_fn=None, _Butterworth_Filter_fn=None,
                  _Raised_Cosine_Filter_fn=None, _Tx_FFE_Filter_fn=None):

    # ── Amplitude assignment ────────────────────────────────────────────────
    ptc_i = int(param.package_testcase_i)  # 1-based
    if getattr(OP, 'WC_PORTZ', False):
        tx_sel = int(param.Tx_rd_sel) - 1  # convert to 0-based
        A_thru = float(np.asarray(param.a_thru).ravel()[tx_sel])
        A_fext = float(np.asarray(param.a_fext).ravel()[tx_sel])
        A_next = float(np.asarray(param.a_next).ravel()[tx_sel])
    else:
        pkg_tc = int(np.asarray(OP.pkg_len_select).ravel()[ptc_i - 1]) - 1  # 0-based index
        A_thru = float(np.asarray(param.a_thru).ravel()[pkg_tc])
        A_fext = float(np.asarray(param.a_fext).ravel()[pkg_tc])
        A_next = float(np.asarray(param.a_next).ravel()[pkg_tc])

    # MATLAB loops `for i=1:param.number_of_s4p_files`, not over every element of
    # chdata: with PSDRXCAL the noise path sits past that count and the reference
    # never touches it.  Iterating the whole list gave it an A, a PWF and -- for a
    # crosstalk type -- a place in the ICN power sum (ICN_mV 4.2335 vs 3.1327 on a
    # 3-channel/count-2 case).
    n_files = int(param.number_of_s4p_files)
    chdata_in_scope = chdata[:n_files]

    for ch in chdata_in_scope:
        if ch.type == 'THRU':
            ch.A = A_thru
            ch.Aicn = A_thru
        elif ch.type == 'FEXT':
            ch.A = A_fext
            ch.Aicn = float(param.a_icn_fext)
        elif ch.type == 'NEXT':
            ch.A = A_next
            ch.Aicn = float(param.a_icn_next)
        else:  # NOISE
            ch.A = 1.0
            ch.Aicn = 1.0

    if getattr(OP, 'TDMODE', False):
        for ch in chdata_in_scope:
            # MATLAB indices 11,10 (1-based) → Python 10,9 (0-based)
            ch.delta_f = float(np.asarray(ch.faxis).ravel()[10] - np.asarray(ch.faxis).ravel()[9])

    if not DO_ONCE:
        return chdata, output_args

    # ── Initialize output fields ────────────────────────────────────────────
    for field in ('fitted_IL_dB_at_Fnq', 'cable__assembley_loss', 'loss_with_PCB',
                  'VIP_to_VMP_IL_dB_at_Fnq', 'IL_dB_channel_only_at_Fnq',
                  'VTF_loss_dB_at_Fnq', 'IL_db_die_to_die_at_Fnq',
                  'FOM_TDILN', 'TD_ILN', 'FOM_RILN', 'FOM_ILD'):
        setattr(output_args, field, [])

    if not getattr(OP, 'GET_FD', True):
        return chdata, output_args

    # ── Apply receiver filter (INCLUDE_FILTER path) ─────────────────────────
    if getattr(OP, 'INCLUDE_FILTER', False):
        for ch in chdata_in_scope:
            f = np.asarray(ch.faxis).ravel()
            H_bt = _Bessel_Thomson_Filter_fn(param, f, OP.Bessel_Thomson)
            H_bw = _Butterworth_Filter_fn(param, f, OP.Butterworth)
            H_rc = _Raised_Cosine_Filter_fn(param, f, OP.Raised_Cosine)
            H_tx = _Tx_FFE_Filter_fn(param, f, param.Pkg_TXFFE_preset)
            ch.sdd21 = np.asarray(ch.sdd21).ravel() * H_bw * H_bt * H_rc * H_tx

    # ── Main FD loop ────────────────────────────────────────────────────────
    f2 = float(param.f2)
    f2_ild = float(param.f2_ild)
    f1 = float(param.f1)
    fr = float(param.f_r) * float(param.fb)
    fb = float(param.fb)

    MDFEXT_ICN = 0.0
    MDNEXT_ICN = 0.0
    P_signal = 0.0
    ILD_magft = np.array([])

    nf = len(np.asarray(chdata[0].sdd21f).ravel())
    PSXT = np.zeros(nf)
    MDFEXT = np.zeros(nf)
    MDNEXT = np.zeros(nf)

    for ch in chdata_in_scope:
        faxis = np.asarray(ch.faxis).ravel()

        # Frequency boundary indices (0-based)
        idx_f2 = _FD_Processing__find_idx_ge(faxis, f2)
        idx_f1 = _FD_Processing__find_idx_le(faxis, f1)
        idx_f2_ild = _FD_Processing__find_idx_ge(faxis, f2_ild)

        # Power weighting function (eq 93A-57)
        temp_angle = float(param.samples_per_ui) * float(param.sample_dt) * np.pi * faxis
        if faxis[0] == 0.0:
            temp_angle[0] = 1e-20
        SINC = np.sin(temp_angle) / temp_angle
        PWF = SINC**2 / (1.0 + (faxis / float(ch.ftr))**4) / (1.0 + (faxis / fr)**8)

        delta_f = float(faxis[10] - faxis[9])
        ch.delta_f = delta_f

        if ch.type == 'THRU':
            sdd21f = np.asarray(ch.sdd21f).ravel()
            Il_dB = _FD_Processing__neg20log10(sdd21f)
            fslice = faxis[idx_f1:idx_f2 + 1]

            P_signal = 2.0 * delta_f * np.sum(
                _FD_Processing__W(fslice, float(ch.ftr), fr, fb) * 10.0**(-Il_dB[idx_f1:idx_f2 + 1] / 10.0)
            )
            output_args.P_signal_sigma_FD = float(np.sqrt(max(P_signal, 0.0)))
            output_args.P_signal_FD = float(P_signal)

            # SCMR_FD (common-mode rejection metrics)
            Q_inv = lambda x: erfcinv(2.0 * x) * np.sqrt(2.0)
            sigma_X = float(param.sigma_X)
            qv2 = Q_inv(float(param.P_peak))**2
            scd21_o = np.asarray(ch.scd21_orig).ravel()[idx_f1:idx_f2 + 1]
            sdc21_o = np.asarray(ch.sdc21_orig).ravel()[idx_f1:idx_f2 + 1]
            W_slice = _FD_Processing__W(fslice, float(ch.ftr), fr, fb)
            EC_CD = 2.0 * delta_f * np.sum(W_slice * np.abs(scd21_o)**2 * sigma_X**2 * qv2)
            EC_DC = 2.0 * delta_f * np.sum(W_slice * np.abs(sdc21_o)**2 * sigma_X**2 * qv2)
            # A perfectly balanced channel has scd21_orig/sdc21_orig identically
            # zero, so EC_CD/EC_DC are 0 and the reference reports Inf dB of
            # common-mode rejection.  `/(EC + 1e-300)` reported ~2993 dB.
            output_args.SCMR_FD_CD_ch_dB = _FD_Processing__db10_ratio(P_signal, EC_CD)
            output_args.SCMR_FD_DC_ch_dB = _FD_Processing__db10_ratio(P_signal, EC_DC)

            # ILD fit over [f1, f2_ild]
            ILD_magft, ch.fit_f2_ild = _get_ILN_fn(
                sdd21f[idx_f1:idx_f2_ild + 1], faxis[idx_f1:idx_f2_ild + 1])
            _, ch.fit_orig = _get_ILN_fn(sdd21f, faxis)

            fnq = 1.0 / (float(param.ui) * 2.0)
            if faxis[idx_f2] >= fnq:
                ch.fit_ILatNq = _FD_Processing__interp1(faxis, -np.asarray(ch.fit_orig).ravel(), fnq)
                output_args.fitted_IL_dB_at_Fnq = ch.fit_ILatNq
            else:
                ch.fit_ILatNq = []
                output_args.fitted_IL_dB_at_Fnq = []

            fit_f2_ild_arr = np.asarray(ch.fit_f2_ild).ravel()
            output_args.fitted_IL_dB_at_F2_ild = float(-fit_f2_ild_arr[-1])

            if faxis[-1] >= fnq:
                ch.ILatNq = _FD_Processing__interp1(faxis, _FD_Processing__neg20log10(sdd21f), fnq)
            else:
                ch.ILatNq = []
            output_args.IL_dB_channel_only_at_Fnq = ch.ILatNq if isinstance(ch.ILatNq, list) else float(ch.ILatNq)

            if getattr(OP, 'include_pcb', False):
                output_args.cable__assembley_loss = _FD_Processing__interp1(
                    faxis, _FD_Processing__neg20log10(np.asarray(ch.sdd21_orig).ravel()), fnq)
                output_args.loss_with_PCB = _FD_Processing__interp1(
                    faxis, _FD_Processing__neg20log10(np.asarray(ch.sdd21_raw).ravel()), fnq)

            # TD/RILN metrics
            if getattr(OP, 'COMPUTE_TDILN', False) or getattr(OP, 'COMPUTE_RILN', False):
                ILD_td, ch.fit, TD_ILN = _get_ILN_cmp_td_fn(
                    sdd21f[idx_f1:idx_f2 + 1], faxis[idx_f1:idx_f2 + 1], OP, param, ch.A)
                FOM_TDILN = float(TD_ILN.SNR_ISI_FOM_PDF)

            if getattr(OP, 'COMPUTE_TDILN', False):
                output_args.FOM_TDILN = FOM_TDILN
                output_args.TD_ILN = TD_ILN

            if getattr(OP, 'COMPUTE_RILN', False):
                RIL_struct = _capture_RIL_RILN_fn(chdata)
                RILN_dB = np.asarray(RIL_struct.RILN_dB).ravel()
                f_span = float(param.f2) - float(param.f1)
                FOM_RILN = float(np.sqrt(delta_f / f_span *
                                          np.sum(PWF[idx_f1:idx_f2] * RILN_dB[idx_f1:idx_f2]**2)))
                output_args.FOM_RILN = FOM_RILN

            # eq 93A-56: FOM_ILD
            FOM_ILD = float(np.sqrt(delta_f / fb *
                                     np.sum(PWF[idx_f1:idx_f2_ild + 1] * np.asarray(ILD_magft)**2)))
            output_args.FOM_ILD = FOM_ILD

        elif ch.type in ('FEXT', 'NEXT'):
            sdd21f = np.asarray(ch.sdd21f).ravel()

            if ch.type == 'FEXT':
                MDFEXT = np.sqrt(np.abs(sdd21f)**2 + MDFEXT**2)
                MDFEXT_dBloss = _FD_Processing__neg20log10(MDFEXT)
                MDFEXT_ICN = float(np.sqrt(
                    2.0 * delta_f / fb *
                    np.sum(ch.Aicn**2 * PWF[idx_f1:idx_f2 + 1] *
                           np.abs(MDFEXT[idx_f1:idx_f2 + 1])**2)))
                output_args.MDFEXT_ICN_92_47_mV = MDFEXT_ICN * 1000.0

                PS_MDFEXT = _FD_Processing__W(faxis, float(ch.ftr), fr, fb) * 10.0**(-MDFEXT_dBloss / 10.0)
                sqrd_mdfext = 2.0 * delta_f * np.sum(PS_MDFEXT[idx_f1:idx_f2 + 1]) * float(param.sigma_X)**2
                # No FEXT coupling at all makes sqrd_mdfext 0, where the
                # reference reports Inf dB SNR; `+1e-300` reported ~2993 dB.
                output_args.SNR_MDFEXT = _FD_Processing__db10_ratio(P_signal, sqrd_mdfext)

            else:  # NEXT
                MDNEXT = np.sqrt(np.abs(sdd21f)**2 + MDNEXT**2)
                MDNEXT_ICN = float(np.sqrt(
                    2.0 * delta_f / fb *
                    np.sum(ch.Aicn**2 * PWF[idx_f1:idx_f2 + 1] *
                           np.abs(MDNEXT[idx_f1:idx_f2 + 1])**2)))
                output_args.MDNEXT_ICN_92_46_mV = MDNEXT_ICN * 1000.0

            PSXT = np.sqrt((np.abs(sdd21f) * ch.Aicn)**2 + PSXT**2)
            ICN = float(np.sqrt(
                2.0 * delta_f / fb *
                np.sum(PWF[idx_f1:idx_f2 + 1] * np.abs(PSXT[idx_f1:idx_f2 + 1])**2)))
            output_args.ICN_mV = ICN * 1000.0

        # else NOISE → skip (no PSXT update, as in MATLAB `continue`)

    # ── Final Nyquist loss interpolation ────────────────────────────────────
    # MATLAB reads chdata(i).faxis, where i is whatever the loop above left
    # behind -- the LAST channel it visited, which is number_of_s4p_files, not
    # the last element of chdata.
    fax_last = np.asarray(chdata_in_scope[-1].faxis).ravel()
    fnq = 1.0 / (float(param.ui) * 2.0)
    ch0 = chdata[0]

    def _il_at_fnq(sig):
        # interp1 returns NaN outside the data range, which the reference leaves
        # unguarded here; _FD_Processing__interp1 reproduces that rather than clamping.
        return _FD_Processing__interp1(fax_last, _FD_Processing__neg20log10(np.asarray(sig).ravel()), fnq)

    output_args.VTF_loss_dB_at_Fnq = _il_at_fnq(ch0.sdd21)
    output_args.IL_db_die_to_die_at_Fnq = _il_at_fnq(ch0.sdd21p_nodie)
    output_args.VIP_to_VMP_IL_dB_at_Fnq = _il_at_fnq(ch0.sdd21p)

    return chdata, output_args



# --- FFE (MATLAB lines 2026–2048) ---

# ============================================================
# MATLAB→Python translation notes for FFE
# MATLAB lines: 2026–2048
# ============================================================
# iscolumn(V): True when V is (N,1) → transpose to row: V=V.'
#   Python: if V.ndim==2 and V.shape[1]==1, ravel to 1-D ✓
# ishift = (i-1-cmx)*spui (MATLAB, 1-based i)
#         = (i-cmx)*spui   (Python, 0-based i)
#   because i_MATLAB = i_Python + 1, so (i_M-1-cmx) = (i_P-cmx) ✓
# circshift(V',[ishift,0]): shift V TRANSPOSED by ishift rows.
#   Positive ishift → move elements DOWN (index increases), wraps at end.
#   np.roll(V.T, ishift, axis=0): for a 1-D V this is exactly np.roll(V,ishift);
#   for a 2-D V it is the transpose MATLAB actually shifts. See below.
# ishift must be a whole number or MATLAB's circshift errors. See below.
# V0 accumulates as array after first non-zero tap (0+array→array).
# ============================================================



def FFE(C, cmx, spui, V):
    C = np.asarray(C, dtype=float)
    V = np.asarray(V, dtype=float)
    if V.ndim == 2 and V.shape[1] == 1:
        V = V.ravel()                   # iscolumn(V) → V=V.' equivalent

    V0 = 0.0
    for i, c in enumerate(C):          # 0-based i
        if c != 0:
            ishift = (i - cmx) * spui   # MATLAB: (i-1-cmx)*spui with 1-based i
            # MATLAB circshift refuses a fractional shift, so Python must too:
            # a non-integer spui made np.roll truncate 1.5 to 1 and answer.
            # COM Octave: FFE([1 1],0,1.5,[1 2 3 4]) ->
            #   "circshift: all values of N must be integers"
            # (Python returned [5 3 5 7].)
            if ishift != int(ishift):
                raise ValueError('circshift: all values of N must be integers')
