# MATLAB lines 4843-4857, with SL (4368-4401), R_series2 (4354-4360), r_parrelell2 (9390-9395)




def _add_pkg_with_die__R_series2(zref, nfreq, R):
    """MATLAB R_series2: series resistance 2-port S-params."""
    s11 = np.full(nfreq, R / (R + 2.0 * zref), dtype=complex)
    s21 = np.full(nfreq, 2.0 * zref / (R + 2.0 * zref), dtype=complex)
    return s11, s21, s21, s11  # s11, s12, s21, s22


def _add_pkg_with_die__r_parrelell2(zref, nfreq, rpad):
    """MATLAB r_parrelell2: parallel resistance 2-port S-params."""
    s11 = np.full(nfreq, -zref / (rpad * (zref / rpad + 2.0)), dtype=complex)
    s21 = np.full(nfreq, 2.0 / (zref / rpad + 2.0), dtype=complex)
    return s11, s21, s21, s11  # s11, s12, s21, s22


def _add_pkg_with_die__SL(S, R, zref):
    """MATLAB SL: cascade a series/parallel R element before S."""
    SLD = copy.deepcopy(S)
    if R == zref:
        return SLD

    nfreq = S.Parameters.shape[0]
    s11c = S.Parameters[:, 0, 0]
    s12c = S.Parameters[:, 0, 1]
    s21c = S.Parameters[:, 1, 0]
    s22c = S.Parameters[:, 1, 1]

    if R > zref:
        spr11, spr12, spr21, spr22 = _add_pkg_with_die__R_series2(zref, nfreq, R - zref)
    else:
        rpad = -R * zref / (R - zref)
        spr11, spr12, spr21, spr22 = _add_pkg_with_die__r_parrelell2(zref, nfreq, rpad)

    o11, o12, o21, o22 = _combines4p(spr11, spr12, spr21, spr22,
                                      s11c, s12c, s21c, s22c)
    SLD.Parameters[:, 0, 0] = o11
    SLD.Parameters[:, 0, 1] = o12
    SLD.Parameters[:, 1, 0] = o21
    SLD.Parameters[:, 1, 1] = o22
    return SLD


def add_pkg_with_die(S, mode, param, OP):
    """Add TX package with die resistance to channel S-params.

    MATLAB lines 4843-4857.

    S: SimpleNamespace with .Parameters (nfreq,2,2), .Frequencies, .Impedance, .NumPorts
    Returns (Smx, TX_RL).
    """
    # Step 1: Build TX package S-params
    s11in, s12in, s21in, s22in = make_full_pkg(
        'TX', S.Frequencies, param, 'THRU', mode)

    # Step 2: Cascade package → channel
    s11c = S.Parameters[:, 0, 0]
    s12c = S.Parameters[:, 0, 1]
    s21c = S.Parameters[:, 1, 0]
    s22c = S.Parameters[:, 1, 1]

    o11, o12, o21, o22 = _combines4p(s11in, s12in, s21in, s22in,
                                      s11c, s12c, s21c, s22c)

    Smx = copy.deepcopy(S)
    Smx.Parameters[:, 0, 0] = o11
    Smx.Parameters[:, 0, 1] = o12
    Smx.Parameters[:, 1, 0] = o21
    Smx.Parameters[:, 1, 1] = o22

    # Step 3: Apply die-pad series resistance (SL)
    R_diepad = float(np.asarray(param.R_diepad).ravel()[0])
    Z0 = float(param.Z0)
    if mode.lower() in ('dd', 'cd'):
        Rd, zref = R_diepad * 2.0, Z0 * 2.0
    else:
        Rd, zref = R_diepad / 2.0, Z0 * 2.0

    Smx = _add_pkg_with_die__SL(Smx, Rd, zref)

    # Step 4: TX_RL = S22 of combined (MATLAB Smx.Parameters(2,2,:))
    TX_RL = Smx.Parameters[:, 1, 1].copy()

    # Step 5: Restore S11 (TX-side reflection = original channel, not including pkg)
    Smx.Parameters[:, 0, 0] = S.Parameters[:, 0, 0]

    return Smx, TX_RL



# --- adjust_Rx_noise_for_quantization (MATLAB lines 4858–4896) ---

def _adjust_Rx_noise_for_quantization__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _adjust_Rx_noise_for_quantization__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _adjust_Rx_noise_for_quantization__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)




# --- inline from conv_fct (MATLAB 5371-5388) ---

# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.


# --- inline from CDF_inv_ev (MATLAB 1142-1148) ---


# --- inline from scalePDF (MATLAB 11268-11275) ---


# --- inline from get_pdf_from_sampled_signal (MATLAB 7473-7518) ---


def _adjust_Rx_noise_for_quantization__get_pdf_from_sampled_signal(input_vector, L, BinSize):
    input_vector = np.asarray(input_vector, dtype=float).ravel()
    # MATLAB max([]) is [], and `if []` is false, so an empty sampled pulse
    # falls straight through to the delta pdf.  COM Octave,
    # adjust_Rx_noise_for_quantization with
    # chdata(1).pulse_sampled_w_tx_ffe_ctle = []: NS.peak_clip = 0.2, the same
    # answer a wholly sub-bin pulse gives.  np.max raised "zero-size array to
    # reduction operation maximum".  (The canonical
    # com_functions/fn/get_pdf_from_sampled_signal/py_impl.py already carries
    # this guard; this copy had not tracked it.)
    if input_vector.size and _adjust_Rx_noise_for_quantization__mmax(np.abs(input_vector)) > BinSize:
        input_vector = input_vector[np.abs(input_vector) > BinSize]
    else:
        return _d_cpdf(BinSize, 0, 1)
    input_vector[np.abs(input_vector) < BinSize] = 0.0
    b = np.sign(input_vector)
    sort_idx = np.argsort(np.abs(input_vector), kind='stable')[::-1]
    input_vector = np.abs(input_vector[sort_idx]) * b[sort_idx]
    values = 2.0 * np.arange(L) / (L - 1) - 1.0
    prob = np.ones(L) / L
    pdf = _d_cpdf(BinSize, 0, 1)
    empty_pdf = pdf
    for v in input_vector:
        pdfn = _Init_PDF_Fast(empty_pdf, np.abs(v) * values, prob)
        pdf = _conv_fct(pdf, pdfn)
    return pdf


def adjust_Rx_noise_for_quantization(combined_interference_and_noise_pdf, NS, chdata,
                                      fom_result, param, OP):
    """Adjust combined PDF to include quantization noise (MATLAB lines 4858-4896).

    Returns (chdata, NS, combined_interference_and_noise_pdf).
    """
    sig_after_ctle_pdf = _adjust_Rx_noise_for_quantization__get_pdf_from_sampled_signal(
        chdata[0].pulse_sampled_w_tx_ffe_ctle, param.levels, param.delta_y)
    sig_after_ctle_pdf = _conv_fct(sig_after_ctle_pdf, combined_interference_and_noise_pdf)
    sig_after_ctle_cdf = np.cumsum(sig_after_ctle_pdf.y)
    adc_clip = -float(_CDF_inv_ev(param.P_qc, sig_after_ctle_pdf, sig_after_ctle_cdf))
    ctle_signal_sigma = float(np.sqrt(np.sum((sig_after_ctle_pdf.x ** 2) * sig_after_ctle_pdf.y)))
    adc_lsb = 2.0 * adc_clip / (2 ** param.N_qb - 1)
    NS.sigma_Q = adc_lsb / np.sqrt(12.0)
    NS.sigma_before_clip = ctle_signal_sigma
    NS.peak_clip = adc_clip
    NS.p2ptosigma_clip = 2.0 * adc_clip / ctle_signal_sigma

    quantization_noise_in_pdf = copy.copy(combined_interference_and_noise_pdf)
    quantization_noise_in_pdf.y = np.zeros_like(quantization_noise_in_pdf.x, dtype=float)
    adc_ind_right = int(np.argmin(np.abs(quantization_noise_in_pdf.x - adc_lsb / 2)))
    adc_ind_left = int(np.argmin(np.abs(quantization_noise_in_pdf.x + adc_lsb / 2)))
    n_bins = adc_ind_right - adc_ind_left + 1
    quantization_noise_in_pdf.y[adc_ind_left:adc_ind_right + 1] = 1.0 / n_bins

    quantization_noise_pdf = copy.copy(combined_interference_and_noise_pdf)
    ind_center = int(np.argmin(np.abs(quantization_noise_pdf.x)))
    quantization_noise_pdf.y = np.zeros_like(quantization_noise_pdf.x, dtype=float)
    quantization_noise_pdf.y[ind_center] = 1.0

    rxffe = np.asarray(fom_result.RxFFE).ravel()
    h_rxffe = rxffe[rxffe != 0]
    cursor_tap = int(param.ffe_pre_tap_len) + 1  # r4p15p0: 1-based cursor tap position
    for irxffe_0, val in enumerate(h_rxffe):
        if (irxffe_0 + 1) != cursor_tap:
            scaled = _scalePDF(quantization_noise_in_pdf, float(np.abs(val)))
            quantization_noise_pdf = _conv_fct(quantization_noise_pdf, scaled)

    combined_interference_and_noise_pdf = _conv_fct(
        combined_interference_and_noise_pdf, quantization_noise_pdf)
    NS.quantization_noise_pdf = quantization_noise_pdf
    return chdata, NS, combined_interference_and_noise_pdf



# --- applyDFEbk (MATLAB lines 4897–4925) ---

def applyDFEbk(hisi, hisi_ref, idx, tap_bk, curval, bmaxg, dfe_delta):
    """Apply a contiguous bank of DFE taps at 0-based position idx.

    idx is the 0-based start index (MATLAB used 1-based; callers must subtract 1).
    Returns (hisi_modified, tap_coef, hisi_ref_modified).

    dfe_delta has no default. The MATLAB guards it with `if nargin<6`, but
    dfe_delta is the SEVENTH argument, so a 6-argument call skips the guard and
    then reads an unset variable.
    COM Octave: applyDFEbk(hisi,href,2,3,4,0.5)   -> "'dfe_delta' undefined"
                applyDFEbk(hisi,href,2,3,4)       -> "'bmaxg' undefined"
    Seven arguments is the only arity the reference accepts, so Python must not
    answer a 6-argument call either (it used to, with dfe_delta=0).
    """
    hisi = np.asarray(hisi, dtype=float).copy()
    hisi_ref = np.asarray(hisi_ref, dtype=float).copy()

    # rng=idx:idx+tap_bk-1 is a READ of hisi, so MATLAB errors when it runs off
    # either end; a Python slice silently shortens and answers on the wrong bank.
    # COM Octave: hisi=[1 2 3 4 5 6], idx=5, tap_bk=4 ->
    #   "hisi(8): out of bound 6"      (Python returned a 2-tap answer)
    #             idx=0                -> "hisi(0): subscripts must be ...
    #                                      integers 1 to (2^63)-1"
    # An empty bank (tap_bk<=0) makes rng empty, which MATLAB accepts whatever
    # idx is, so only a non-empty bank is range-checked.
    if tap_bk > 0:
        if idx < 0:
            raise IndexError('hisi(%d): subscripts must be either integers '
                             '1 to (2^63)-1 or logicals' % (idx + 1))
        if idx + tap_bk > hisi.size:
            raise IndexError('hisi(%d): out of bound %d'
                             % (idx + tap_bk, hisi.size))

    sl = slice(idx, idx + tap_bk)
    flt_curval = hisi[sl].copy()

    if dfe_delta != 0:
        flt_curval_q = (
            np.floor(np.abs(flt_curval / curval) / dfe_delta)
            * dfe_delta * np.sign(flt_curval) * curval
        )
    else:
        flt_curval_q = flt_curval

    # MATLAB min() drops a NaN and returns the other operand; np.minimum
    # propagates it, so a NaN bmaxg poisoned every tap instead of disabling
    # the clip.
    # COM Octave: hisi=[1 2 3 4 5 6], idx=2, tap_bk=3, curval=4, bmaxg=NaN ->
    #   tap_coef = [0.5 0.75 1]        (Python returned [nan nan nan])
    tap_coef = np.fmin(np.abs(flt_curval_q / curval), bmaxg) * np.sign(flt_curval_q)
    hisi[sl] = hisi[sl] - curval * tap_coef

    # hisi_ref(rng)=0 is an ASSIGNMENT, which grows the array in MATLAB rather
    # than erroring; the Python slice assignment wrote nothing past the end.
    # COM Octave: hisi_ref=[9 9 9], idx=4, tap_bk=3 -> [9 9 9 0 0 0]
    #   (Python returned [9 9 9]).   hisi_ref=[] -> [0 0 0 0]
    if tap_bk > 0 and idx + tap_bk > hisi_ref.size:
        grown = np.zeros(idx + tap_bk)
        grown[:hisi_ref.size] = hisi_ref
        hisi_ref = grown
    hisi_ref[sl] = 0.0
    return hisi, tap_coef, hisi_ref



