# --- cdf_to_ber_contour (MATLAB lines 5246–5257) ---

# ============================================================
# MATLAB→Python translation notes for cdf_to_ber_contour
# MATLAB lines: 5246–5257
# ============================================================
# 1-based vs 0-based indexing: MATLAB find() returns 1-based indices.
#   np.argmax on a boolean mask returns the 0-based index of the first True.
#   Index conversion for the top crossing:
#     MATLAB: nidx_true = length(y) - nidx_flipped + 1  (1-based)
#     Python:  nidx_true = len(y) - 1 - nidx_flipped     (0-based)
#   where nidx_flipped is 0-based in the flipped array.
# fliplr(cdf.y(:)'): flatten to row then flip — np.flip(y.ravel()).
# find(..., 1, 'first'): np.argmax on boolean mask — but argmax answers 0
#   where MATLAB's find() returns [], so the no-match case is guarded below.
# Output shape: two scalars (float).
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def cdf_to_ber_contour(cdf, specBER):
    """Find the bottom and top voltage crossings of specBER in the CDF.

    noise_bottom: leftmost x where cdf.y first exceeds specBER
    noise_top:    rightmost x where cdf.y last exceeds specBER
    """
    y = np.asarray(cdf.y, dtype=float).ravel()
    x = np.asarray(cdf.x, dtype=float).ravel()

    hit = y > specBER
    if not hit.any():
        # Both find() calls are empty, so MATLAB's cdf.x(nidx) is an empty
        # 1x0 for noise_bottom *and* noise_top — there is no contour.
        # np.argmax on an all-False mask answers 0, which handed back
        # (cdf.x(1), cdf.x(end)) — the full axis — as though it were the eye.
        # COM Octave 4p16p0: cdf.y=[0.1 0.3 0.7 0.3 0.1], x=[-2:2],
        # specBER=0.9 returns noise_bottom=[] and noise_top=[]; same for
        # specBER=NaN, where nothing compares greater.
        raise IndexError('cdf_to_ber_contour: no cdf.y > specBER')

    # Bottom eye: first index where cdf.y > specBER (MATLAB lines 5251-5252)
    nidx = int(np.argmax(hit))                   # 0-based
    noise_bottom = x[nidx]

    # Top eye: search flipped CDF for first crossing, then un-flip (lines 5254-5257)
    nidx_flipped = int(np.argmax(np.flip(y) > specBER))  # 0-based in flipped
    nidx = len(y) - 1 - nidx_flipped                      # 0-based in original
    noise_top = x[nidx]

    return float(noise_bottom), float(noise_top)



# --- comb_fct (MATLAB lines 5258–5285) ---

# ============================================================
# MATLAB→Python translation notes for comb_fct
# MATLAB lines: 5258–5285
# ============================================================
# PDF struct format: p.BinSize (bin width), p.Min (negative integer bin index),
#   p.y (probability array), p.x (voltage axis).
# p.x = (p.Min:-p.Min)*p.BinSize → symmetric voltage axis:
#   MATLAB range p.Min:-p.Min → np.arange(p.Min, -p.Min+1), e.g., -5:5 → [-5..5]
#   len(x) = -2*p.Min + 1 = 2*|p.Min| + 1
# difsz = abs(p1.Min - p2.Min) → integer shift in bins
# p1.Min == p.Min: p1 extends further left; zero-pad p2 on both sides
# p2.Min == p.Min: p2 extends further left; zero-pad p1 on both sides
# Equal Min: neither branch runs; p1.y and p2.y added directly (same length)
# MATLAB in-place array extension translated as constructing new zero array
#   and slicing in the original values: new_y[difsz:lp+difsz] = original_y
# p=p1 copies all fields → SimpleNamespace(**vars(p1)) then override Min/y/x
# ============================================================



def comb_fct(p1, p2):
    if p1.BinSize != p2.BinSize:
        raise ValueError('bin size must be equal')

    p = SimpleNamespace(**vars(p1))       # copy all fields (MATLAB p=p1)
    p.BinSize = p1.BinSize
    p.Min = min(p1.Min, p2.Min)
    difsz = int(abs(p1.Min - p2.Min))
    lp1 = len(p1.y)
    lp2 = len(p2.y)
    p1_y = np.asarray(p1.y, dtype=float).copy()
    p2_y = np.asarray(p2.y, dtype=float).copy()

    if p1.Min == p.Min:           # p1 has the smaller (more negative) Min
        new_p2 = np.zeros(lp1)
        new_p2[difsz:lp2 + difsz] = p2_y
        p2_y = new_p2
    elif p2.Min == p.Min:         # p2 has the smaller Min
        new_p1 = np.zeros(lp2)
        new_p1[difsz:lp1 + difsz] = p1_y
        p1_y = new_p1

    p.y = p1_y + p2_y
    p.x = np.arange(p.Min, -p.Min + 1) * p.BinSize   # (p.Min:-p.Min)*BinSize
    return p



# --- combine_pdf_same_voltage_axis (MATLAB lines 5286–5326) ---

# ============================================================
# MATLAB→Python translation notes for combine_pdf_same_voltage_axis
# MATLAB lines: 5286–5326
# ============================================================
# Unlike comb_fct, this function works with explicit voltage x arrays
#   rather than integer bin indices (Min).
# min1/min2: first element of x arrays (leftmost voltage).
# shift_amount = round(|min1-min2| / BinSize) → integer number of bins.
# Left-alignment: prepend x/y from the further-left pdf to the other:
#   MATLAB pdf1.x(1:shift_amount) → Python x1[:shift_amount]
#   (1-based [1:n] → 0-based [:n])
# Right-alignment: zero-pad the shorter of the two after left-alignment.
# Output has same BinSize, combined voltage axis, and summed probabilities.
# No renormalization — caller is responsible (per MATLAB comment).
# When min1==min2: shift_amount=0; else branch is a no-op → direct addition.
# ============================================================


def _combine_pdf_same_voltage_axis__mround(x):
    """MATLAB round(): half away from zero, where Python's round() is banker's."""
    x = float(x)
    t = int(x)                      # int() truncates toward zero
    if abs(x - t) == 0.5:           # exact tie: MATLAB goes away from zero
        return t + (1 if x > 0 else -1)
    # Off a tie round() is exact, and unlike floor(x + 0.5) it does not
    # send 0.49999999999999994 to 1: that sum is exactly 1.0 in binary.
    return int(round(x))



def _combine_pdf_same_voltage_axis__require_row(a, name):
    """MATLAB builds the shifted axes with horizontal concatenation, so every
    field has to be a row.  A column makes `[zeros(1,n) pdf2.y]` a dimension
    error, and a row/column *mix* implicit-expands into a matrix instead.
    np.concatenate flattens both away, so Python answered where MATLAB did not.

    COM Octave 4p16p0, pdf1.x/.y columns and pdf2.x/.y rows, equal Min:
      out.y comes back 3x3 = [1 2 1;2 3 2;1 2 1], not the 1x3 [1 3 1].
    With both as columns and a nonzero shift:
      "horizontal dimensions mismatch (1x1 vs 3x1)".
    """
    a = np.asarray(a, dtype=float)
    if a.ndim > 1 and a.shape[0] != 1:
        raise ValueError('combine_pdf_same_voltage_axis: %s must be a row '
                         'vector' % name)
    return a.reshape(-1).copy()


def combine_pdf_same_voltage_axis(pdf1, pdf2):
    if pdf1.BinSize != pdf2.BinSize:
        raise ValueError('bin size must be equal')

    x1 = _combine_pdf_same_voltage_axis__require_row(pdf1.x, 'pdf1.x')
    y1 = _combine_pdf_same_voltage_axis__require_row(pdf1.y, 'pdf1.y')
    x2 = _combine_pdf_same_voltage_axis__require_row(pdf2.x, 'pdf2.x')
    y2 = _combine_pdf_same_voltage_axis__require_row(pdf2.y, 'pdf2.y')

    min1 = x1[0]   # pdf1.x(1) in MATLAB = x1[0] in Python
    min2 = x2[0]
    shift_amount = _combine_pdf_same_voltage_axis__mround(abs(min1 - min2) / pdf1.BinSize)

    if min1 < min2:
        # pdf1 extends further left; prepend first shift_amount pts of x1 to x2/y2
        x2 = np.concatenate([x1[:shift_amount], x2])
        y2 = np.concatenate([np.zeros(shift_amount), y2])
    else:
        # pdf2 extends further left (or equal); prepend first shift_amount pts of x2 to x1/y1
        x1 = np.concatenate([x2[:shift_amount], x1])
        y1 = np.concatenate([np.zeros(shift_amount), y1])

    L1 = len(x1)
    L2 = len(x2)
    Ldiff = abs(L1 - L2)

    if L1 > L2:
        out_x = x1
        y2 = np.concatenate([y2, np.zeros(Ldiff)])
    else:
        out_x = x2
        y1 = np.concatenate([y1, np.zeros(Ldiff)])

    out_pdf = SimpleNamespace()
    out_pdf.x = out_x
    out_pdf.y = y1 + y2
    out_pdf.BinSize = pdf1.BinSize
    return out_pdf



# --- combines4p (MATLAB lines 5327–5370) ---

def combines4p(s11in1, s12in1, s21in1, s22in1, s11in2, s12in2, s21in2, s22in2):
    """Cascade two 2-port S-parameter networks (MATLAB lines 5327-5370)."""
    def _sq(x): return np.asarray(x, dtype=complex).ravel()
    a11, a12 = _sq(s11in1), _sq(s12in1)
    a21, a22 = _sq(s21in1), _sq(s22in1)
    b11, b12 = _sq(s11in2), _sq(s12in2)
    b21, b22 = _sq(s21in2), _sq(s22in2)
    N = 1 - a22 * b11
    s11out = a11 + a12 * a21 * b11 / N
    s12out = a12 * b12 / N
    s21out = b21 * a21 / N
    s22out = b22 + b12 * b21 * a22 / N
    return s11out, s12out, s21out, s22out



