# --- cursor_sample_index (MATLAB lines 5405–5479) ---

def cursor_sample_index(sbr, param, OP, peak_search_range):
    """Find cursor sample index via Muller-Mueller criterion (MATLAB lines 5405-5479).

    All indices are 0-based in Python (MATLAB uses 1-based).

    Parameters
    ----------
    sbr               : pulse response array
    param             : struct with samples_per_ui, ndfe, bmax
    OP                : struct with CDR ('MM' or 'Mod-MM')
    peak_search_range : 0-based index array for peak search window

    Returns
    -------
    cursor_i          : 0-based cursor index (None if no zero crossing)
    no_zero_crossing  : 0 or 1 flag
    sbr_peak_i        : 0-based peak index
    zxi               : 0-based zero-crossing index (scalar array, empty if none)
    """
    sbr = np.asarray(sbr, dtype=float).ravel()
    peak_search_range = np.asarray(peak_search_range, dtype=int).ravel()
    M = int(param.samples_per_ui)

    # Find peak in search window
    sub = sbr[peak_search_range]
    sbr_peak_tmp = int(np.argmax(sub))
    max_of_sbr = float(sub[sbr_peak_tmp])
    sbr_peak_i = sbr_peak_tmp + int(peak_search_range[0])

    no_zero_crossing = 0
    cursor_i = None

    # Find zero crossings in [search_start, sbr_peak_i]
    search_start = max(0, sbr_peak_i - 4 * M)
    segment = sbr[search_start:sbr_peak_i + 1]
    diff_signs = np.diff(np.sign(segment - 0.01 * max_of_sbr))
    local_idx = np.where(diff_signs >= 1)[0]
    zxi_arr = local_idx + search_start  # 0-based global indices

    if len(zxi_arr) == 0:
        no_zero_crossing = 1
        return None, no_zero_crossing, sbr_peak_i, np.array([], dtype=int)

    if len(zxi_arr) > 1:
        zxi_arr = zxi_arr[[-1]]  # keep only last zero crossing

    zxi = int(zxi_arr[0])

    max_dfe1 = 0.0 if param.ndfe == 0 else float(np.asarray(param.bmax).ravel()[0])

    mm_range = np.arange(zxi, zxi + 2 * M + 1, dtype=int)
    cdr = str(OP.CDR).strip()
    if cdr == 'Mod-MM':
        mm_metric = np.abs(sbr[mm_range + M] - max_dfe1 * sbr[mm_range])
    else:
        mm_metric = np.abs(
            sbr[mm_range - M] - np.maximum(sbr[mm_range + M] - max_dfe1 * sbr[mm_range], 0.0)
        )

    mm_cursor_offset = int(np.argmin(mm_metric))
    cursor_i = zxi + mm_cursor_offset  # 0-based

    return cursor_i, no_zero_crossing, sbr_peak_i, zxi_arr



# --- d_cpdf (MATLAB lines 5480–5530) ---

# ============================================================
# MATLAB→Python translation notes for d_cpdf
# MATLAB lines: 5480–5530
# ============================================================
# all(values==0): early-return with scalar y=1, x=0 (special case).
# ~issorted(values): np.any(np.diff(values) < 0) → sort if not ascending.
# values=binsize*round(values/binsize): snap to grid.
# t=(values(1):binsize:values(end)): MATLAB range → np.arange(t_start, t_end+1)*binsize.
# pdf.Min = values(1)/binsize: 1-based first bin index (integer).
# Loop bin assignment:
#   k==1 (MATLAB) → bin=1 → Python k==0, bin_idx=0
#   k==length → last bin → Python k==N-1, bin_idx=len(t)-1
#   else: argmin(|t-v|) 0-based ✓
# pdf.y = pdf.y/sum(pdf.y): normalize to sum=1.
# support = find(pdf.y): 1-based non-zero indices → Python np.where > 0, 0-based.
# pdf.y = pdf.y(support(1):support(end)): trim leading/trailing zeros.
# pdf.Min += support(1)-1 (MATLAB 1-based shift) = support[0] (Python 0-based) ✓
# pdf.x = (pdf.Min:-pdf.Min)*binsize: symmetric axis → np.arange(Min,-Min+1)*binsize.
# ============================================================


def _d_cpdf__mround_arr(x):
    """MATLAB round() on an array: halves go away from zero, where np.round
    takes them to even.

    Only exact ties are corrected. Adding 0.5 and truncating would be wrong:
    0.49999999999999994 + 0.5 is exactly 1.0 in double precision, so that form
    rounds the largest double below a half up to 1 where MATLAB gives 0.
    """
    x = np.asarray(x, dtype=float)
    tie = np.abs(x - np.trunc(x)) == 0.5
    return np.where(tie, np.trunc(x) + np.copysign(1.0, x), np.round(x))



def d_cpdf(binsize, values, probs):
    values = np.asarray(values, dtype=float)
    probs = np.asarray(probs, dtype=float)

    if np.all(values == 0):
        pdf = SimpleNamespace()
        pdf.BinSize = binsize
        pdf.Min = 0
        pdf.y = np.array([1.0])
        pdf.x = np.array([0.0])
        return pdf

    if np.size(probs) < np.size(values):
        # MATLAB reads probs(k) for k = 1..length(values); a short probs is an
        # out-of-bound error, not a shorter answer.  zip() below would stop at
        # the shorter of the two and silently normalise whatever it collected.
        # COM Octave 4p16p0: d_cpdf(1,[-1 0 1],[0.5 0.5]) errors
        # "probs(3): out of bound 2 (dimensions are 1x2)".
        raise IndexError('d_cpdf: probs is shorter than values')

    # ~issorted(values): MATLAB requires every element <= the next, which is
    # false as soon as a NaN is present.  np.diff(values) < 0 is False across a
    # NaN, so that form calls [-1 NaN 1] sorted where MATLAB does not.
    if not np.all(values[:-1] <= values[1:]):     # ~issorted
        si = np.argsort(values, kind='stable')
        values = values[si]
        probs = probs[si]

    values = binsize * _d_cpdf__mround_arr(values / binsize)   # snap to grid

    t_start = int(round(values[0] / binsize))
    t_end = int(round(values[-1] / binsize))
    t = np.arange(t_start, t_end + 1) * binsize    # (values(1):binsize:values(end))

    pdf_min = t_start                               # values(1)/binsize (integer)
    pdf_y = np.zeros(len(t))

    for k, (v, prob) in enumerate(zip(values, probs)):
        if k == 0:
            bin_idx = 0                             # MATLAB k==1 → bin=1
        elif k == len(values) - 1:
            bin_idx = len(t) - 1                    # MATLAB k==length → last bin
        else:
            bin_idx = int(np.argmin(np.abs(t - v)))
        pdf_y[bin_idx] += prob

    pdf_y = pdf_y / np.sum(pdf_y)

    if np.any(pdf_y < 0):
        raise ValueError('PDF must be real and nonnegative')

    # find(pdf.y) selects *nonzero*, and NaN counts as nonzero.  `> 0` drops
    # NaN, so an all-zero or NaN-bearing probs vector (pdf.y = 0/0) left the
    # support empty and raised instead of answering.
    # COM Octave 4p16p0: d_cpdf(1,[-1 0 1],[0.5 NaN 0.5]) returns
    # Min=-1, x=[-1 0 1], y=[NaN NaN NaN]; likewise probs=[0 0 0].
    support = np.where(pdf_y != 0)[0]              # 0-based nonzero indices
    pdf_y = pdf_y[support[0]:support[-1] + 1]
    pdf_min = pdf_min + int(support[0])             # MATLAB: pdf.Min+(support(1)-1)

    pdf = SimpleNamespace()
    pdf.BinSize = binsize
    pdf.Min = pdf_min
    pdf.y = pdf_y
    pdf.x = np.arange(pdf_min, -pdf_min + 1) * binsize   # (Min:-Min)*binsize
    return pdf



# --- dfe_clipper (MATLAB lines 5531–5544) ---

# ============================================================
# MATLAB→Python translation notes for dfe_clipper
# MATLAB lines: 5531–5544
# ============================================================
# 1-based vs 0-based indexing: not applicable (boolean indexing only).
# Column-major vs row-major: MATLAB isrow() distinguishes 1×n from n×1.
#   Python 1-D arrays have no inherent orientation; we treat ndim==1 as
#   "row-like" (threshold stays flat) and ndim==2 with shape[1]==1 as
#   column (threshold reshaped to (-1,1)).
# MATLAB `end` keyword: not used.
# Output shape: same shape as input.
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def dfe_clipper(input_arr, max_threshold, min_threshold):
    """Element-wise clip with per-element bounds.

    Clips input so that:
      input[i] > max_threshold[i]  →  output[i] = max_threshold[i]
      input[i] < min_threshold[i]  →  output[i] = min_threshold[i]
    Threshold orientation is aligned to input (row vs column).
    """
    inp = np.asarray(input_arr, dtype=float)
    hi = np.asarray(max_threshold, dtype=float)
    lo = np.asarray(min_threshold, dtype=float)

    # MATLAB isrow(input): true for 1-D or 2-D with shape[0]==1
    is_row = inp.ndim <= 1 or (inp.ndim == 2 and inp.shape[0] == 1)
    if is_row:
        hi = hi.ravel()   # (:).' in MATLAB — flatten to row-compatible 1-D
        lo = lo.ravel()
    else:
        hi = hi.ravel().reshape(-1, 1)  # (:) in MATLAB — column vector
        lo = lo.ravel().reshape(-1, 1)

    out = inp.copy()
    # Both masks are taken from the ORIGINAL input: MATLAB computes
    # input<min_threshold, not clip_output<min_threshold, so with crossed
    # bounds (min>max) an element can be raised after being lowered.
    # Octave: dfe_clipper([0 1.5 3],[1 1 1],[2 2 2]) -> [2 2 1].
    # NaN compares false both ways and passes through unclipped:
    # dfe_clipper([1 NaN 3],[2 2 2],[0 0 0]) -> [1 NaN 2].
    mask_hi = inp > hi
    mask_lo = inp < lo

    # MATLAB writes max_threshold(input>max_threshold): a logical index into
    # the THRESHOLD array. It errors as soon as a true position falls past the
    # end of that array, so a scalar threshold works only while nothing beyond
    # the first element is clipped. Octave:
    #     dfe_clipper([3 1 1], 2, -9) -> [2 1 1]      (only position 1 true)
    #     dfe_clipper([1 3 1], 2, -9) -> error: max_threshold(2): out of bound 1
    # numpy would instead broadcast the scalar and return a plausible answer
    # for a call MATLAB refuses.
    # Assigning positionally rather than with a boolean mask is what makes
    # that emulation possible: numpy requires a boolean index to match the
    # array's shape exactly, while MATLAB only requires every TRUE position to
    # be in range -- so a threshold that is scalar, or simply longer than the
    # input, is legal there and a shape error here.
    # MATLAB linear indexing is column-major; identical to C order for the
    # vectors every caller passes, but order='F' keeps 2-D honest.
    out_f = out.ravel(order='F')
    for mask, thr, nm in ((mask_hi, hi, 'max_threshold'),
                          (mask_lo, lo, 'min_threshold')):
        where = np.nonzero(np.asarray(mask).ravel(order='F'))[0]
        if where.size == 0:
            continue
        if where.max() >= thr.size:
            raise IndexError(
                'dfe_clipper: %s(%d): out of bound %d -- MATLAB indexes the '
                'threshold array with the input-shaped logical mask, so it '
                'errors here rather than broadcasting.'
                % (nm, where.max() + 1, thr.size))
        out_f[where] = thr.ravel(order='F')[where]
    return out_f.reshape(inp.shape, order='F')



