# Pure display/reporting function.
# MATLAB msgbox → print(msg) (GUI not available in Python).
# MATLAB fprintf(...) → print(f'...') to stdout.
# MATLAB fprintf(2,...) → print(f'...', file=sys.stderr) for FAIL messages.
# MATLAB size(param.z_p_tx_cases) → np.asarray(...).shape
# param.flex set based on mele (2/4/1).
# ERL message uses ERL (two-element array) spread across format args.
# ============================================================



def end_display_control(msg, param, OP, output_args, COM, min_ERL, ERL, VEO_mV, VEC_dB,
                        threshold_DER, DISPLAY_WINDOW):
    ztx = np.asarray(param.z_p_tx_cases)
    if ztx.ndim == 1:
        ncases = len(ztx)
        mele = 1
    else:
        ncases, mele = ztx.shape[0], ztx.shape[1]

    if mele == 2:
        param.flex = 2
    elif mele == 4:
        param.flex = 4
    elif mele == 1:
        param.flex = 1
    else:
        raise ValueError('config file syntax error: unexpected z_p_tx_cases shape')

    if not getattr(param, 'FLAG', None) or not getattr(param.FLAG, 'S2P', False):
        if not OP.TDMODE:
            print(f'SCMR_CH =  {output_args.SCMR_CH:.4g} dB ')

    if DISPLAY_WINDOW and not OP.RX_CALIBRATION:
        msgcolor = 'g'
        if not OP.ERL_ONLY:
            phy = str(getattr(OP, 'PHY', 'C2C'))
            if phy == 'C2M':
                if VEO_mV >= param.Min_VEO and VEO_mV <= param.Max_VEO:
                    msg = f'{msg}: EH = {VEO_mV:.3f} mV (pass)\n'
                else:
                    msg = f'{msg}: EH = {VEO_mV:.3f} mV (FAIL)\n'
                    msgcolor = 'r'
                if VEC_dB <= param.VEC_pass_threshold:
                    msg = f'{msg}: VEC = {VEC_dB:.3f} dB (pass)\n'
                else:
                    msg = f'{msg}: VEC = {VEC_dB:.3f} dB (FAIL)\n'
                    msgcolor = 'r'
            elif phy == 'C2C':
                if COM >= param.pass_threshold:
                    msg = f'{msg}: COM = {COM:.3f} dB (pass)\n'
                else:
                    msg = f'{msg}: COM = {COM:.3f} dB (FAIL)\n'
                    msgcolor = 'r'
                msg = f'{msg}: DER = {threshold_DER:.3e} at COM threshold \n'
            elif phy == 'C2Mcom':
                if VEO_mV >= param.Min_VEO and VEO_mV <= param.Max_VEO:
                    msg = f'{msg}: EH = {VEO_mV:.3f} mV (pass)\n'
                else:
                    msg = f'{msg}: EH = {VEO_mV:.3f} mV (FAIL)\n'
                    msgcolor = 'r'
                if VEC_dB <= param.VEC_pass_threshold:
                    msg = f'{msg}: VEC = {VEC_dB:.3f} dB (pass)\n'
                else:
                    msg = f'{msg}: VEC = {VEC_dB:.3f} dB (FAIL)\n'
                    msgcolor = 'r'
                if COM >= param.pass_threshold:
                    msg = f'{msg}: COM = {COM:.3f} dB (pass)\n'
                else:
                    msg = f'{msg}: COM = {COM:.3f} dB (FAIL)\n'
                    msgcolor = 'r'
                msg = f'{msg}: DER = {threshold_DER:.3e} at COM threshold \n'

        if OP.ERL:
            if ERL is not None and len(np.asarray(ERL)) > 0:
                erl_arr = np.asarray(ERL).ravel()
                if min_ERL >= param.ERL_pass_threshold:
                    msg = (f'{msg}: PASS ... ERL = {min_ERL:.3f} dB '
                           f'({erl_arr[0]:.3f} dB,{erl_arr[1]:.3f} dB) \n')
                else:
                    msg = (f'{msg}: FAIL ... ERL = {min_ERL:.3f} dB '
                           f'({erl_arr[0]:.3f} dB,{erl_arr[1]:.3f} dB) \n')
                    msgcolor = 'r'

        # MATLAB msgbox → print (GUI not available)
        revision = getattr(output_args, 'code_revision', '')
        print(f'[COM r{revision} results] {msg}')
    else:
        if not OP.ERL_ONLY:
            phy = str(getattr(OP, 'PHY', 'C2C'))
            if phy == 'C2C':
                if COM >= param.pass_threshold:
                    print(f'{msg} PASS ... COM = {COM:.3f} dB')
                else:
                    print(f'{msg} FAIL ... COM = {COM:.3f} dB', file=sys.stderr)
                print(f'{msg} DER = {threshold_DER:.3e} at COM threshold ')
            elif phy == 'C2Mcom':
                if VEC_dB <= param.VEC_pass_threshold:
                    print(f'{msg} PASS ... VEC = {VEC_dB:.3f} dB')
                else:
                    print(f'{msg} FAIL ... VEC = {VEC_dB:.3f} dB', file=sys.stderr)
                if VEO_mV >= param.Min_VEO and VEO_mV <= param.Max_VEO:
                    print(f'{msg} PASS ... EH = {VEO_mV:.3f} mV')
                else:
                    print(f'{msg} FAIL ... EH = {VEO_mV:.3f} mV', file=sys.stderr)
                if COM >= param.pass_threshold:
                    print(f'{msg} PASS ... COM = {COM:.3f} dB')
                else:
                    print(f'{msg} FAIL ... COM = {COM:.3f} dB', file=sys.stderr)
                print(f'{msg} DER = {threshold_DER:.3e} at COM threshold ')
            elif phy == 'C2M':
                if VEC_dB <= param.VEC_pass_threshold:
                    print(f'{msg} PASS ... VEC = {VEC_dB:.3f} dB')
                else:
                    print(f'{msg} FAIL ... VEC = {VEC_dB:.3f} dB', file=sys.stderr)
                if VEO_mV >= param.Min_VEO and VEO_mV <= param.Max_VEO:
                    print(f'{msg} PASS ... EH = {VEO_mV:.3f} mV')
                else:
                    print(f'{msg} FAIL ... EH = {VEO_mV:.3f} mV', file=sys.stderr)

        if OP.ERL:
            if ERL is not None and len(np.asarray(ERL)) > 0:
                erl_arr = np.asarray(ERL).ravel()
                if min_ERL >= param.ERL_pass_threshold:
                    print(f'{msg}: PASS ... ERL = {min_ERL:.3f} dB '
                          f'({erl_arr[0]:.3f} dB, {erl_arr[1]:.3f} dB)')
                else:
                    print(f'{msg}: FAIL ... ERL = {min_ERL:.3f} dB '
                          f'({erl_arr[0]:.3f} dB, {erl_arr[1]:.3f} dB)', file=sys.stderr)
                report_modal = str(getattr(OP, 'Report_Modal_ERL', '')).lower()
                if report_modal in ('enable', 'provisional'):
                    print(f'ERL11 CD DC CC = [{output_args.ERL11_CD:.4g} '
                          f'{output_args.ERL11_DC:.4g} {output_args.ERL11_CC:.4g}] dB    '
                          f'ERL22 CD DC CC = [{output_args.ERL22_CD:.4g} '
                          f'{output_args.ERL22_DC:.4g} {output_args.ERL22_CC:.4g}] dB')
    return msg



# --- find_eye_width (MATLAB lines 5723–5785) ---

# ============================================================
# MATLAB→Python translation notes for find_eye_width
# MATLAB lines: 5723–5785
# ============================================================
# eye_contour is (N×2): column 0 = top eye, column 1 = bottom eye.
# MATLAB 1-based indexing: eye_contour(half_UI:-1:1, 1) → Python eye_contour[half_UI-1::-1, 0].
# half_UI appears in both the left slice (reversed) and right slice (forward).
# vref_intersect: linear interpolation between the two samples bracketing the vref crossing.
#   x_in is 1-based within the passed slice.
# ============================================================



def _find_eye_width__vref_intersect(eye_col_1d, x_in_1based, vref):
    # MATLAB reads eye_contour(x_in-1,1), so x_in<=1 asks for subscript 0 and
    # errors. eye_col_1d[x-2] turns that into a NEGATIVE index and quietly
    # reads the LAST row instead, answering off the far end of the eye.
    # COM Octave: vref_intersect([0.1;0.3;0.7;0.9], 1, 0.5) ->
    #   "eye_contour(0,_): subscripts must be either integers 1 to (2^63)-1
    #    or logicals"                 (this copy returned 0.5)
    # Same guard as the canonical vref_intersect; this copy takes the eye
    # column already sliced out, so it indexes one dimension rather than two.
    if x_in_1based != int(x_in_1based) or x_in_1based < 2:
        raise IndexError('eye_contour(%s,_): subscripts must be either '
                         'integers 1 to (2^63)-1 or logicals'
                         % (x_in_1based - 1,))
    x = int(x_in_1based)
    m1 = eye_col_1d[x - 1] - eye_col_1d[x - 2]
    b1 = eye_col_1d[x - 1] - m1 * x
    return (vref - b1) / m1


def find_eye_width(eye_contour, half_UI, samples_per_UI, vref):
    eye_contour = np.asarray(eye_contour)

    # Left eye (top)
    left_top = eye_contour[half_UI - 1::-1, 0]
    idx = np.where(left_top < vref)[0]
    if len(idx) == 0:
        L1 = half_UI
    elif idx[0] == 0:
        L1 = 0
    else:
        vc = int(idx[0]) + 1  # 1-based
        x_in = half_UI - vc + 2
        INT = _find_eye_width__vref_intersect(eye_contour[:half_UI, 0], x_in, vref)
        L1 = half_UI - INT

    # Left eye (bottom)
    left_bot = eye_contour[half_UI - 1::-1, 1]
    idx = np.where(left_bot > vref)[0]
    if len(idx) == 0:
        L0 = half_UI
    elif idx[0] == 0:
        L0 = 0
    else:
        vc = int(idx[0]) + 1
        x_in = half_UI - vc + 2
        INT = _find_eye_width__vref_intersect(eye_contour[:half_UI, 1], x_in, vref)
        L0 = half_UI - INT

    # Right eye (top)
    right_top = eye_contour[half_UI - 1:, 0]
    idx = np.where(right_top < vref)[0]
    if len(idx) == 0:
        R1 = samples_per_UI - half_UI
    elif idx[0] == 0:
        R1 = 0
    else:
        vc = int(idx[0]) + 1
        INT = _find_eye_width__vref_intersect(eye_contour[half_UI - 1:, 0], vc, vref) + half_UI - 1
        R1 = INT - half_UI

    # Right eye (bottom)
    right_bot = eye_contour[half_UI - 1:, 1]
    idx = np.where(right_bot > vref)[0]
    if len(idx) == 0:
        R0 = samples_per_UI - half_UI
    elif idx[0] == 0:
        R0 = 0
    else:
        vc = int(idx[0]) + 1
        INT = _find_eye_width__vref_intersect(eye_contour[half_UI - 1:, 1], vc, vref) + half_UI - 1
        R0 = INT - half_UI

    Left_EW = min(L1, L0)
    Right_EW = min(R1, R0)
    return Left_EW, Right_EW



# --- findbankloc (MATLAB lines 5786–5937) ---

def _findbankloc__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _findbankloc__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _findbankloc__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)


def _findbankloc__mmin(a):
    """MATLAB min(): the mirror of _findbankloc__mmax."""
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _findbankloc__mextreme_complex(a, 0)
    if a.dtype.kind != 'f':
        return np.min(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.min(a)
    return np.nanmin(a)



def findbankloc(hisi, idx_st, idx_en, tap_bk, curval, bmaxg, N_bg):
    """Find optimal DFE bank locations within hisi[idx_st-1 : idx_en].

    Parameters use MATLAB 1-based convention (idx_st, idx_en).
    Returns 0-based indices into hisi (Python convention).

    Algorithm:
      Build ndiff[j] = sum of (h0^2 - h1^2) for tap bank starting at j,
      where h1 = max(0, h0 - bmaxg*curval).  Choose N_bg non-adjacent banks
      greedily by highest ndiff; enforce minimum gap of tap_bk between banks.
    """
    hisi = np.asarray(hisi, dtype=float).ravel()
    len_ = idx_en - idx_st + 1
    h0 = np.abs(hisi[idx_st - 1:idx_en])   # length len_
    h1 = np.maximum(0.0, h0 - bmaxg * curval)
    if curval < 0:
        h1 = np.zeros(len_)

    n_bins = len_ - tap_bk + 1             # number of valid bank start positions
    h0n = np.zeros(n_bins)
    h1n = np.zeros(n_bins)
    for ii in range(tap_bk):
        h0n += h0[ii:ii + n_bins] ** 2
        h1n += h1[ii:ii + n_bins] ** 2
    ndiff = h0n - h1n                       # 0-based indices 0..n_bins-1

    MIN_E = -np.inf
    # idx stores 0-based ndiff positions; -1 = not yet placed
    idx = np.full(tap_bk * N_bg, -1, dtype=int)
    # Shortcut check: are 0..(N_bg-1)*tap_bk the top (N_bg-1)*tap_bk+1 entries?
    ordered_set = np.arange((N_bg - 1) * tap_bk + 1)
    set_next_bank = -1   # -1 = not pending

    for k in range(N_bg):
        val_sort = np.argsort(-ndiff, kind='stable')       # 0-based, descending

        if k == 0:
            ns = len(ordered_set)
            if np.array_equal(np.sort(val_sort[:ns]), ordered_set):
                idx = np.arange(N_bg * tap_bk)
                break

        if set_next_bank >= 0:
            new_bank = np.arange(set_next_bank, set_next_bank + tap_bk)
            idx[tap_bk * k: tap_bk * (k + 1)] = new_bank
            set_next_bank = -1
            ndiff = _findbankloc__mask(ndiff, new_bank, MIN_E)
            b_start = new_bank[0] - tap_bk + 1
            b_end = new_bank[0] - 1
            badV = _findbankloc__make_badV(b_start, b_end)
            if len(badV):
                ndiff[badV] = MIN_E
            continue

        new_bank = np.arange(val_sort[0], val_sort[0] + tap_bk)
        if k == N_bg - 1:
            idx[tap_bk * k: tap_bk * (k + 1)] = new_bank
            break

        placed = idx[:tap_bk * k]           # already-placed 0-based positions
        badV = np.array([], dtype=int)
        do_it_again = True
        first_time = True
        num_loops = 0
        while do_it_again:
            do_it_again = False
            if num_loops > len(ndiff):
                break
            b_start = new_bank[0] - tap_bk + 1
            b_end = new_bank[0] - 1
            badV = _findbankloc__make_badV(b_start, b_end)
            # remove already-placed indices from badV
            if len(badV) and len(placed):
                badV = badV[~np.isin(badV, placed)]
            goodV_idx = new_bank[0] - tap_bk

            if len(badV) > 0:
                if not first_time:
                    val_sort = np.argsort(-ndiff, kind='stable')
                first_time = False
                checkV = np.concatenate([badV, new_bank])
                badV_pos = np.array(
                    [int(np.where(val_sort == v)[0][0]) for v in badV]
                )

                found_goodV = False
                ii_found = len(val_sort) - 1
                for ii_vs in range(len(val_sort)):
                    if val_sort[ii_vs] == goodV_idx:
                        found_goodV = True
                        ii_found = ii_vs
                        break
                    if not np.any(val_sort[ii_vs] == checkV):
                        ii_found = ii_vs
                        break

                if (not found_goodV) and (len(badV_pos) > 0) and (_findbankloc__mmin(badV_pos) < ii_found):
                    do_it_again = True
                    ndiff[new_bank[0]] = MIN_E
                    new_bank = np.arange(val_sort[1], val_sort[1] + tap_bk)
                if found_goodV:
                    set_next_bank = goodV_idx
            num_loops += 1

        ndiff = _findbankloc__mask(ndiff, new_bank, MIN_E)
        idx[tap_bk * k: tap_bk * (k + 1)] = new_bank
        if len(badV):
            ndiff[badV] = MIN_E

    # Convert 0-based ndiff positions → 0-based hisi positions
    return idx + (idx_st - 1)


def _findbankloc__mask(ndiff, positions, value):
    """ndiff[positions] = value, growing ndiff the way MATLAB would.

    ML 6260/6296: `ndiff(new_bank)=min_energy` where new_bank is
    `val_sort(1):val_sort(1)+tap_bk-1`. When the strongest bank start is within
    tap_bk-1 of the end, that range runs past the end of ndiff -- ndiff is
    indexed by bank START position and so is tap_bk-1 shorter than h0. MATLAB
    grows an array on out-of-range assignment; NumPy raises IndexError.

    On ~4.4% of random inputs the strongest start lands in that window, so the
    Python version crashed where MATLAB did not. The grown entries are -Inf, so
    they sort last and are never selected as a bank: the growth is inert, which
    is why the divergence is a crash rather than a wrong answer.

    Returns ndiff, which may be a new, longer array.
    """
    positions = np.asarray(positions, dtype=int).ravel()
    if positions.size == 0:
        return ndiff
    need = int(positions.max()) + 1
    if need > ndiff.size:
        # MATLAB zero-fills any gap; assignments here are contiguous from an
        # in-range start, so no gap arises, but fill for fidelity regardless.
        ndiff = np.concatenate([ndiff, np.zeros(need - ndiff.size)])
    ndiff[positions] = value
    return ndiff


def _findbankloc__make_badV(b_start, b_end):
    """Build array of 0-based indices from b_start to b_end inclusive (handles negatives)."""
    if b_end < 0:
        return np.array([], dtype=int)
    start = max(0, b_start)
    return np.arange(start, b_end + 1, dtype=int)



# --- compute_hard_cap (MATLAB lines 5788–5794) ---

# ============================================================
# MATLAB→Python translation notes for compute_hard_cap
# MATLAB lines: 5788-5794 (com_ieee8023_4p15p0_adaptive_local_search.m)
# NEW in Hansel D'silva's adaptive-local-search branch.
# ============================================================
# Tiny helper: the hard cap on the raw TX-tap L1 distance used by the
# adaptive local search. round() is MATLAB round (half away from zero).
# Returns NaN when capping is disabled, matching the MATLAB return.
# ============================================================



def _compute_hard_cap__mround(x):
    """MATLAB round(): half away from zero."""
    x = float(x)
    # MATLAB round(NaN) is NaN and round(Inf) is Inf; int() raises on both, so
    # a NaN local-search value used to abort here instead of being capped.
    # COM Octave: compute_hard_cap(1, 1.2, NaN, 1) -> 1
    #             compute_hard_cap(1, 1.2, Inf, 1) -> Inf
    if not np.isfinite(x):
        return x
    t = int(x)                      # int() truncates toward zero
    if abs(x - t) == 0.5:           # exact tie: MATLAB goes away from zero
        return t + (1 if x > 0 else -1)
    # Off a tie round() is exact, and unlike floor(x + 0.5) it does not
    # send 0.49999999999999994 to 1: that sum is exactly 1.0 in binary.
    return int(round(x))


def _compute_hard_cap__mmax2(a, b):
    """MATLAB max(a,b): a NaN operand is dropped, not propagated.

    Python's max() compares with > and keeps whichever it saw first, so
    max(NaN, 2) is NaN where MATLAB gives 2.
    COM Octave: compute_hard_cap(1, 1.2, 2, NaN) -> 2   (Python gave nan)
                compute_hard_cap(1, NaN, 2, 3)   -> 3   (Python raised)
                compute_hard_cap(1, NaN, NaN, NaN) -> NaN
    """
    if np.isnan(a):
        return b
    if np.isnan(b):
        return a
    return a if a > b else b


def compute_hard_cap(use_hard_cap, mul, LSV, min_radius):
    """Hard cap for the raw TX L1 distance (MATLAB lines 5788-5794)."""
    # MATLAB `if X` is false for an empty X and true only when every element is
    # non-zero; `if np.array([])` raises in numpy.
    # COM Octave: compute_hard_cap([], 1.2, 2, 1) -> NaN
    if np.size(use_hard_cap) and np.all(use_hard_cap):
        return _compute_hard_cap__mmax2(min_radius, _compute_hard_cap__mround(mul * LSV))
    return float('nan')



# --- floatingDFE (MATLAB lines 5938–5972) ---

def floatingDFE(hisi, N_b, N_bf, N_bg, N_bmax, bmaxg, curval, dfe_delta=0):
    """Find and apply N_bg groups of N_bf floating DFE taps.

    N_b: number of fixed taps (floating taps start after these, 0-based: position N_b).
    N_bmax: maximum tap index (1-based MATLAB convention; internally converted).
    Returns (tap_loc, tap_coef, hisi_modified, b) all using 0-based indices.
    """
    hisi = np.asarray(hisi, dtype=float).copy()
    tap_coef = np.zeros(len(hisi))
    b = np.zeros(len(hisi))

    # MATLAB: findbankloc(hisi, N_b+1, N_bmax, N_bf, curval, bmaxg, N_bg)
    # idx_st=N_b+1 (1-based), idx_en=N_bmax (1-based)
    tap_loc = _findbankloc(hisi, N_b + 1, N_bmax, N_bf, curval, bmaxg, N_bg)

    flt_curval = hisi[tap_loc].copy()
    if dfe_delta != 0:
        flt_curval_q = (
            np.floor(np.abs(flt_curval / curval) / dfe_delta)
            * dfe_delta * np.sign(flt_curval) * curval
        )
    else:
        flt_curval_q = flt_curval

    applied_coef = np.minimum(np.abs(flt_curval_q / curval), bmaxg) * np.sign(flt_curval_q)
    hisi[tap_loc] -= curval * applied_coef
    tap_coef[tap_loc] = applied_coef
    tap_loc = np.sort(tap_loc)
    b[tap_loc] = bmaxg
    return tap_loc, tap_coef, hisi, b



# --- floating_taps_1sttest (MATLAB lines 5973–6089) ---

def _floating_taps_1sttest__hrem(h, index, N_bf, bmaxg):
    """Remove at most bmaxg from N_bf taps starting at 0-based index.

    The index is 0-based here where the canonical hrem takes it 1-based: the
    caller below passes ig1/ig2/ig3 from range(N_b, ...), the 0-based form of
    MATLAB's `ig1 = N_b+1:end1`. Everything else matches the canonical.
    """
    h = np.asarray(h, dtype=float)
    # MATLAB L7941 builds the result with HORIZONTAL concatenation, so h must
    # be a row. A column makes the three pieces 1x1 / Nx1 / Mx1 and MATLAB
    # errors "horizontal dimensions mismatch". Verified against Octave.
    if h.ndim == 2 and h.shape[1] == 1 and h.shape[0] > 1:
        raise ValueError(
            'hrem: h must be a row vector. MATLAB concatenates the three '
            'pieces horizontally, so a %dx1 column errors there with '
            '"horizontal dimensions mismatch".' % h.shape[0])
    h = h.ravel()
    index = int(index)

    # MATLAB indexes h(index:index+N_bf-1) directly, so running past the end
    # errors ("h(7): out of bound 5"). A numpy slice silently returns a SHORTER
    # segment, handing back a result of the wrong length instead.
    if index < 0 or index + int(N_bf) > h.size:
        raise IndexError(
            'hrem: h(%d:%d) is out of bounds for a length-%d h; MATLAB errors '
            'here rather than shortening the result.'
            % (index + 1, index + int(N_bf), h.size))

    mid = (
        h[index:index + N_bf]
        - np.sign(h[index:index + N_bf])
        * np.minimum(bmaxg, np.abs(h[index:index + N_bf]))
    )
    return np.concatenate([h[:index], mid, h[index + N_bf:]])


def floating_taps_1sttest(hisi, N_b, N_bf, N_bg, N_bmax, bmaxg, COOP=0):
    """Find best floating DFE tap locations by exhaustive/sequential search.

    N_b: number of fixed taps (0-based: floating starts at index N_b).
    N_bmax: 1-based MATLAB max tap number; 0-based last position = N_bmax-1.
    COOP: 1 = co-optimise banks; 0 = sequential (default).
    Returns (bmax, floating_tap_locations) using 0-based Python indices.
    """
    hisi = np.asarray(hisi, dtype=float).ravel()
    if N_bg == 0:
        # MATLAB returns on `bmax=0` -- the SCALAR zero, not a vector, and
        # floating_tap_locations is never assigned.  This port always hands
        # back both, which is the two-output call.  COM Octave:
        #   [bmax,locs] = ... N_bg=0 -> "error: element number 2 undefined in
        #                                return list"
        #   bmax        = ... N_bg=0 -> 0   (1x1)
        # The old code returned zeros(len(hisi)) and an empty location list,
        # neither of which the reference ever produces.
        raise ValueError('floating_taps_1sttest: N_bg=0 returns bmax=0 with '
                         'floating_tap_locations unassigned; MATLAB errors on '
                         'a two-output call ("element number 2 undefined")')

    # MATLAB end1 = N_bmax - N_bf (1-based); Python end1_py = N_bmax - N_bf - 1 (0-based inclusive)
    # MATLAB loop: ig1 = N_b+1:end1  (1-based)  → Python: range(N_b, N_bmax - N_bf)
    if N_bg == 1:
        end1_py = N_bmax - N_bf      # exclusive upper bound for range
        end2_py = N_b + 1            # single iteration at N_b
        end3_py = N_b + 1
    elif N_bg == 2:
        end1_py = N_bmax - N_bf
        end2_py = N_bmax - N_bf
        end3_py = N_b + 1
    else:  # N_bg == 3
        end1_py = N_bmax - N_bf
        end2_py = N_bmax - N_bf
        end3_py = N_bmax - N_bf

    # MATLAB seeds best_ig1/2/3 = -1 and leaves best_hcap unset, so a group
    # that never improves on best_sigma is NOT silently placed at N_b: the
    # final bmax(best_ig:..) is an illegal subscript and MATLAB stops.
    # COM Octave, hisi 20 taps, N_b=2 N_bf=3 N_bmax=16, bmaxg=0 (so no
    # iteration can reduce the norm), N_bg=2 sequential:
    #   "error: bmax(-1): subscripts must be either integers 1 to (2^63)-1".
    # The pre-seeded N_b answered with a bank at 2..4 that was never evaluated.
    UNSET = -1
    best_sigma = np.inf
    best_ig1 = best_ig2 = best_ig3 = UNSET
    best_hcap = None

    if COOP:
        for ig1 in range(N_b, end1_py):
            hcap = _floating_taps_1sttest__hrem(hisi, ig1, N_bf, bmaxg)
            for ig2 in range(N_b, end2_py):
                hcap2 = _floating_taps_1sttest__hrem(hcap, ig2, N_bf, bmaxg) if N_bg >= 2 else hcap
                for ig3 in range(N_b, end3_py):
                    hcap3 = _floating_taps_1sttest__hrem(hcap2, ig3, N_bf, bmaxg) if N_bg >= 3 else hcap2
                    sigma = float(np.linalg.norm(hcap3))
                    if sigma < best_sigma:
                        best_sigma = sigma
                        best_ig1, best_ig2, best_ig3 = ig1, ig2, ig3
                        best_hcap = hcap3
    else:
        # Sequential: first find best ig1
        for ig1 in range(N_b, end1_py):
            hcap = _floating_taps_1sttest__hrem(hisi, ig1, N_bf, bmaxg)
            sigma = float(np.linalg.norm(hcap))
            if sigma < best_sigma:
                best_sigma = sigma
                best_ig1 = ig1
                best_hcap = hcap
        # MATLAB reads best_hcap here unconditionally.  When the ig1 loop
        # never ran (N_bmax-N_bf < N_b+1) or every sigma was NaN, nothing
        # assigned it.  COM Octave, N_b=6 N_bf=3 N_bmax=8 and again with a NaN
        # in hisi: "error: 'best_hcap' undefined near line 69".  Python carried
        # on from a copy of hisi and returned a bank it had never scored.
        if best_hcap is None:
            raise ValueError("floating_taps_1sttest: 'best_hcap' undefined -- "
                             'no group improved on the initial sigma')
        hisi = best_hcap
        # Then best ig2
        for ig2 in range(N_b, end2_py):
            hcap = _floating_taps_1sttest__hrem(hisi, ig2, N_bf, bmaxg)
            sigma = float(np.linalg.norm(hcap))
            if sigma < best_sigma:
                best_sigma = sigma
                best_ig2 = ig2
                best_hcap = hcap
        hisi = best_hcap
        # Then best ig3
        for ig3 in range(N_b, end3_py):
            hcap = _floating_taps_1sttest__hrem(hisi, ig3, N_bf, bmaxg)
            sigma = float(np.linalg.norm(hcap))
            if sigma < best_sigma:
                best_sigma = sigma
                best_ig3 = ig3
                best_hcap = hcap

    # bmax(best_ig:...) with an unset best_ig is bmax(-1) in MATLAB, which
    # stops.  A negative Python slice bound would instead index from the END
    # of bmax and write the bank in the wrong place.
    for used, ig in ((1, best_ig1), (2, best_ig2), (3, best_ig3)):
        if used <= N_bg and ig == UNSET:
            raise IndexError(
                'floating_taps_1sttest: bmax(-1): group %d was never selected, '
                'so its location is unset' % used)

    bmax = np.zeros(N_bmax)
    if N_bg == 1:
        bmax[best_ig1:best_ig1 + N_bf] = bmaxg
        locs = np.arange(best_ig1, best_ig1 + N_bf)
    elif N_bg == 2:
        bmax[best_ig1:best_ig1 + N_bf] = bmaxg
        bmax[best_ig2:best_ig2 + N_bf] = bmaxg
        locs = np.concatenate([
            np.arange(best_ig1, best_ig1 + N_bf),
            np.arange(best_ig2, best_ig2 + N_bf),
        ])
    else:  # N_bg == 3
        bmax[best_ig1:best_ig1 + N_bf] = bmaxg
        bmax[best_ig2:best_ig2 + N_bf] = bmaxg
        bmax[best_ig3:best_ig3 + N_bf] = bmaxg
        locs = np.concatenate([
            np.arange(best_ig1, best_ig1 + N_bf),
            np.arange(best_ig2, best_ig2 + N_bf),
            np.arange(best_ig3, best_ig3 + N_bf),
        ])

    return bmax, np.sort(locs).astype(int)



# --- force (MATLAB lines 6090–6253) ---

# ============================================================
# MATLAB→Python translation notes for force
# MATLAB lines: 6090–6253
# ============================================================
# RxFFE tap solver. Inlines FFE helper.
# Inputs: V (pulse response row), param, OP, ix (0-based cursor), C (taps or []), return_V flag
#
# FFE: for each tap i (0-based, 0..len(C)-1):
#   ishift = (i - cmx) * spui
#   V0 += np.roll(V, ishift) * C[i]
#
# MATLAB vsampled: zero-padded to [zeros(num_taps), vsampled_raw, zeros(cpx)]
# In Python: same 0-based indexing.
# VV matrix: num_taps x num_taps
#   VV[:, i] = vsampled[ivs+i : ivs+i-num_taps+1 : -1]  (reverse stride)
# Solver: VV'\FV' → np.linalg.lstsq(VV.T, FV).
# WIENER_HOPF_MMSE path: undefined in the reference MATLAB -> raises NotImplementedError
#   (not a port gap; the reference itself has no such function). Use FFE_OPT_METHOD='MMSE'.
# Floating taps: uses _force__findbankloc (inlined).
# RXFFE_FLOAT_CTL: 'taps' uses Cmod for bank, else uses VV row.
# RXFFE_TAP_CONSTRAINT: 'unity cursor' → normalize by Cmod[cmx].
# ============================================================


def _force__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _force__mmin(a):
    """MATLAB min(): the mirror of _mmax."""
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _force__mextreme_complex(a, 0)
    if a.dtype.kind != 'f':
        return np.min(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.min(a)
    return np.nanmin(a)



def _force__fb_mask(ndiff, positions, value):
    """ndiff[positions] = value, growing ndiff the way MATLAB would.

    ML 6260/6296 assign `ndiff(new_bank)=min_energy` where new_bank can run
    past the end of ndiff: ndiff is indexed by bank START position, so it is
    tap_bk-1 shorter than h0. MATLAB grows on out-of-range assignment; NumPy
    raises IndexError. The grown entries are -Inf, sort last, and are never
    selected, so the growth is inert -- the divergence was a crash, not a wrong
    answer. See com_functions/fn/findbankloc/py_impl.py.
    """
    positions = np.asarray(positions, dtype=int).ravel()
    if positions.size == 0:
        return ndiff
    need = int(positions.max()) + 1
    if need > ndiff.size:
        ndiff = np.concatenate([ndiff, np.zeros(need - ndiff.size)])
    ndiff[positions] = value
    return ndiff


def _force__findbankloc(hisi, idx_st, idx_en, tap_bk, curval, bmaxg, N_bg):
    """Faithful port of MATLAB findbankloc (ML 5918-6069).

    This was previously a "pick the highest-power non-overlapping banks"
    approximation, which is not what MATLAB does. The real routine ranks bank
    start positions by ndiff = h0n - h1n and then runs a badV/goodV
    admissibility loop that can reject the strongest bank and pre-commit the
    next one, so the selected set differs from a plain energy ranking.

    idx_st/idx_en are MATLAB 1-based bounds. Returns MATLAB-convention 1-based
    positions in hisi, which is what the callers here expect (MMSE_FOM selects
    columns as idx + RxFFE_cmx; force places taps at cmx + 1 + idx - 1).
    """
    hisi = np.asarray(hisi, dtype=float).ravel()
    idx_st, idx_en = int(idx_st), int(idx_en)
    tap_bk, N_bg = int(tap_bk), int(N_bg)
    len_ = idx_en - idx_st + 1
    h0 = np.abs(hisi[idx_st - 1:idx_en])
    h1 = np.maximum(0.0, h0 - bmaxg * curval)
    if curval < 0:
        # ML 5934: a negative cursor would invert ndiff and make the WEAKEST isi
        # the most desirable, so h1 is forced flat.
        h1 = np.zeros(len_)

    n_bins = len_ - tap_bk + 1
    h0n = np.zeros(n_bins)
    h1n = np.zeros(n_bins)
    for _ii in range(tap_bk):
        h0n += h0[_ii:_ii + n_bins] ** 2
        h1n += h1[_ii:_ii + n_bins] ** 2
    ndiff = h0n - h1n

    def _bad_range(b_start, b_end):
        """Taps closer than one bank below new_bank[0] (ML 6002-6009)."""
        if b_end < 0:
            return np.array([], dtype=int)
        return np.arange(max(0, b_start), b_end + 1, dtype=int)

    MIN_E = -np.inf
    idx = np.full(tap_bk * N_bg, -1, dtype=int)
    ordered_set = np.arange((N_bg - 1) * tap_bk + 1)
    set_next_bank = -1

    for k in range(N_bg):
        # stable, to match MATLAB's sort(...,'descend'); ndiff ties are common
        # because the isi tail is mostly zeros.
        val_sort = np.argsort(-ndiff, kind='stable')

        if k == 0 and np.array_equal(np.sort(val_sort[:len(ordered_set)]), ordered_set):
            idx = np.arange(N_bg * tap_bk)
            break

        if set_next_bank >= 0:
            new_bank = np.arange(set_next_bank, set_next_bank + tap_bk)
            idx[tap_bk * k:tap_bk * (k + 1)] = new_bank
            set_next_bank = -1
            ndiff = _force__fb_mask(ndiff, new_bank, MIN_E)
            badV = _bad_range(new_bank[0] - tap_bk + 1, new_bank[0] - 1)
            if len(badV):
                ndiff[badV] = MIN_E
            continue

        new_bank = np.arange(val_sort[0], val_sort[0] + tap_bk)
        if k == N_bg - 1:
            idx[tap_bk * k:tap_bk * (k + 1)] = new_bank
            break

        placed = idx[:tap_bk * k]
        badV = np.array([], dtype=int)
        do_it_again, first_time, num_loops = True, True, 0
        while do_it_again:
            do_it_again = False
            if num_loops > len(ndiff):
                break
            badV = _bad_range(new_bank[0] - tap_bk + 1, new_bank[0] - 1)
            if len(badV) and len(placed):
                badV = badV[~np.isin(badV, placed)]
            goodV_idx = new_bank[0] - tap_bk

            if len(badV) > 0:
                if not first_time:
                    val_sort = np.argsort(-ndiff, kind='stable')
                first_time = False
                checkV = np.concatenate([badV, new_bank])
                badV_pos = np.array([int(np.where(val_sort == v)[0][0]) for v in badV])

                found_goodV = False
                ii_found = len(val_sort) - 1
                for ii_vs in range(len(val_sort)):
                    if val_sort[ii_vs] == goodV_idx:
                        found_goodV = True
                        ii_found = ii_vs
                        break
                    if not np.any(val_sort[ii_vs] == checkV):
                        ii_found = ii_vs
                        break

                if (not found_goodV) and len(badV_pos) and _force__mmin(badV_pos) < ii_found:
                    do_it_again = True
                    ndiff[new_bank[0]] = MIN_E
                    new_bank = np.arange(val_sort[1], val_sort[1] + tap_bk)
                if found_goodV:
                    set_next_bank = goodV_idx
            num_loops += 1

        ndiff = _force__fb_mask(ndiff, new_bank, MIN_E)
        idx[tap_bk * k:tap_bk * (k + 1)] = new_bank
        if len(badV):
            ndiff[badV] = MIN_E

    # ML 6069 returns idx+idx_st-1 as 1-based; our idx is 0-based within the
    # window, so +idx_st lands on the same 1-based value.
    return idx + idx_st

def force(V, param, OP, ix=None, C=None, return_V=1, chdata=None, txffe=None, Noise_XC=None):
    """RxFFE tap solver (MATLAB lines 6090-6253).

    V: pulse response (1D array).
    ix: 0-based cursor index (default: argmax of V).
    C: pre-computed taps (if not None, skips optimization).
    return_V: if 0, skip computing Vfiltered (speed-up).

    Returns (Vfiltered, Cmod, idx).
    """
    V = np.asarray(V, dtype=float).ravel()

    if ix is None:
        ix = int(np.argmax(V))

    cmx = int(param.RxFFE_cmx)
    cpx = int(param.RxFFE_cpx)

    if int(getattr(param, 'N_bg', 0)) != 0:
        cpx = int(param.N_bmax)

    num_taps = cmx + cpx + 1
    cstep = float(getattr(param, 'RxFFE_stepz', 0))
    ndfe = int(param.ndfe)
    spui = int(param.samples_per_ui)
    # ML 6568 is `param.current_ffegain=0;` here, and ML 6634 reads it back a
    # few lines down, so inside force the gain is ALWAYS 0 in the reference.
    #
    # MATLAB passes param BY VALUE, so that write never reaches the caller.
    # This used to write the caller's object, zeroing a value the caller had
    # set. COM Octave, on its own force with param.current_ffegain = 7:
    #   caller param.current_ffegain BEFORE the call: 7
    #   caller param.current_ffegain AFTER  the call: 7
    # SiCoPR gave 0. Keeping the write local restores by-value semantics and
    # leaves the reference's own logic untouched, because the only reader is
    # inside this function.
    current_ffegain = 0.0

    idx = np.array([], dtype=int)

    if return_V and C is not None and len(np.asarray(C)) > 0:
        Vfiltered = _FFE(C, cmx, spui, V)
        return Vfiltered, np.asarray(C, dtype=float).ravel(), idx

    # Build vsampled_raw: samples at spui spacing starting at ix.
    #
    # MATLAB's ix is 1-BASED and ours is 0-based, so mod(ix,spui) there is
    # (ix+1) % spui here. Taking the modulus of the 0-based ix instead put the
    # first pre-cursor sample one UI late whenever mod(ix_MATLAB,spui)==1, and
    # dropped V(1) from the sampled vector. COM Octave, spui=4, cmx=2, cpx=3,
    # V = exp(-(t-17)^2/12) + 0.4*exp(-t/6) on t=0:39:
    #   ix=5  -> Cmod(1) = -341.8916096927, the port gave 1.3240864760e-16
    #   ix=9  -> Cmod(1) =   -1.2321309684, the port gave -1.6655157754
    #   ix=13 -> Cmod(1) =   -0.1151234261, the port gave 0.3764832703
    #   ix=17 -> Cmod(6) = -7.9658626843e-08, the port gave 9.0392051417e-05
    # Every ix with mod(ix,spui)~=1 already agreed to 1e-14.
    #
    # Both MATLAB branches end the pre-cursor run at 1-based ix-spui, because
    # mod(ix,spui) + spui*(floor(ix/spui)-1) is ix-spui either way.
    #
    # `ix < length(V)` is on the 1-BASED ix, so the last sample of V takes the
    # else branch in MATLAB and took the if branch here. COM Octave, same V and
    # params, ix = length(V) = 64:
    #   Cmod = [-0.180678956 0.117026343 1 -0.23555319 0.209619484 -0.239829445]
    #   the port gave [0.02850437 -0.19691076 1 -0.091935245 0.131560803 -0.04219104]
    N = len(V)
    ix = int(ix)
    mod_ix = (ix + 1) % spui                       # MATLAB mod(ix, spui)
    first = (spui if mod_ix == 0 else mod_ix) - 1  # 0-based first pre sample
    ix_before_end = (ix + 1) < N                   # MATLAB ix < length(V)
    if ix_before_end:
        pre_idx = np.arange(first, ix - spui + 1, spui)
        post_idx = np.arange(ix, N, spui)
        vsampled_raw = np.concatenate([V[pre_idx], V[post_idx]])
    else:
        vsampled_raw = V[first::spui]

    # Zero-pad: [zeros(num_taps), vsampled_raw, zeros(cpx)]
    vsampled = np.concatenate([np.zeros(num_taps), vsampled_raw, np.zeros(cpx)])

    # Find ivs: index in vsampled matching V[ix]
    if ix_before_end:
        matches = np.where(vsampled == V[ix])[0]
        ivs = int(matches[0]) if len(matches) > 0 else num_taps
    else:
        ivs = int(np.argmax(vsampled))

    # Build VV matrix (num_taps x num_taps).
    # A window that runs off either end of vsampled is a subscript error in
    # MATLAB, not a short column zero-filled to length. Silently padding meant
    # the solve ran on a VV the reference never produces. COM Octave, spui=4,
    # cmx=2, cpx=3, length(V)=64, ix=63:
    #   error: vsampled(26): out of bound 25 (dimensions are 1x25)
    #   force at line 90 column 5
    nvs = len(vsampled)
    VV = np.zeros((num_taps, num_taps))
    for i in range(num_taps):
        start_idx = ivs + i
        end_idx = start_idx - num_taps + 1
        if start_idx >= nvs:
            raise IndexError('vsampled(%d): out of bound %d (dimensions are '
                             '1x%d)' % (start_idx + 1, nvs, nvs))
        if end_idx < 0:
            raise IndexError('vsampled(%d): subscripts must be either integers '
                             '1 to (2^63)-1 or logicals' % (end_idx + 1))
        VV[:, i] = vsampled[start_idx:end_idx - 1 if end_idx > 0 else None:-1]

    if C is None or len(np.asarray(C)) == 0:
        ffe_opt = str(getattr(OP, 'FFE_OPT_METHOD', 'FORCE')).upper()
        if ffe_opt == 'WIENER-HOPF':
            # MATLAB L6188 calls WIENER_HOPF_MMSE(), but that function is NOT defined
            # anywhere in the reference (com_ieee8023_4p14p0.m or any matlab_source.m) —
            # the reference itself errors on this path.  We do not fabricate a solver
            # (would be speculative and, since Wiener-Hopf == MMSE normal equations, a
            # duplicate of the existing 'MMSE' path).  Use FFE_OPT_METHOD='MMSE' instead.
            raise NotImplementedError(
                "force: FFE_OPT_METHOD='WIENER-HOPF' is non-functional in the reference "
                "MATLAB (WIENER_HOPF_MMSE is undefined). Use 'MMSE'.")

        # Build forcing vector FV
        FV = np.zeros(num_taps)
        cursor_gain_dB = current_ffegain      # ML 6634, always 0: see L213
        FV[cmx] = vsampled[ivs] * 10 ** (cursor_gain_dB / 20.0)
        if ndfe != 0 and cpx > 0 and ivs + 1 < len(vsampled):
            bmax_arr = np.asarray(param.bmax, dtype=float).ravel()
            bmax_val = float(bmax_arr[0]) if len(bmax_arr) > 0 else 1.0
            FV[cmx + 1] = min(bmax_val * FV[cmx], abs(vsampled[ivs + 1])) * np.sign(vsampled[ivs + 1])

        VVt = VV.T
        if VV.shape[0] == VV.shape[1]:
            # RULED 2026-09-23 (owner): reproduce MATLAB's CONDITION, but make
            # its occurrence loud instead of silent.
            #
            # The three references disagreed:
            #   MATLAB  VV'\FV'  warns "Matrix is singular to working
            #                    precision" and returns Inf.
            #   Octave  VV'\FV'  returned a minimum-norm least-squares
            #                    solution: [1 2; 2 4] \ [1; 3] -> [0.28 0.56].
            #   here             LinAlgError -> lstsq, i.e. the OCTAVE answer.
            #
            # Octave was repaired in 4c73cba: force's backslash now goes
            # through octave/patches/mldivide_matlab.m, which returns inv(A)*b
            # for rcond(A)==0, so the oracle gives MATLAB's Inf. The oracle can
            # therefore adjudicate this now, and the port was the odd one out.
            #
            # A silent lstsq answer is the one outcome NEITHER reference
            # produces, and it hides a degenerate channel by quietly returning
            # something plausible. MATLAB's Inf poisons the taps and propagates;
            # knowing the case occurred is worth more than either. So: raise.
            #
            # VV is built square (zeros(num_taps,num_taps)), so the else-branch
            # below is dead in both languages and only this path matters.
            try:
                C_solved = np.linalg.solve(VVt, FV)
            except np.linalg.LinAlgError:
                raise ValueError(
                    'force: VV is singular to working precision, so the tap '
                    'solve has no unique answer. MATLAB returns Inf here and '
                    'carries it into the taps; SiCoPR stops instead, so the '
                    'degenerate channel is visible rather than silently '
                    'absorbed. num_taps=%d, cmx=%d.' % (num_taps, cmx))
        else:
            VVVt = VV @ VV.T
            try:
                C_solved = (np.linalg.solve(VVVt, VV) @ FV)
            except np.linalg.LinAlgError:
                C_solved, _, _, _ = np.linalg.lstsq(VV.T, FV, rcond=None)

        Cmod = C_solved[:num_taps]

        # Floating taps.
        # DIVERGENCE, REPORTED NOT FIXED (2026-09-22): MATLAB calls findbankloc
        # unconditionally, this guard skips it when N_bg==0. With N_bg==0 the
        # routine returns an empty idx, so the outputs agree -- unless
        # param.N_bmax exceeds the length of the vector it indexes, where the
        # reference stops and this does not. COM Octave, cmx=2, cpx=3
        # (num_taps=6), N_bg=0, N_bmax=10:
        #   error: hisi(10): out of bound 6 (dimensions are 6x1)
        #   findbankloc at line 12 column 1 / force at line 127 column 14
        # The bound belongs in findbankloc, which is a shared helper, so this
        # is for the owner of com_functions/fn/findbankloc to place.
        N_bg = int(getattr(param, 'N_bg', 0))
        if N_bg != 0:
            N_tail_start = int(getattr(param, 'N_tail_start', cpx))
            N_bmax = int(getattr(param, 'N_bmax', cpx))
            N_bf = int(getattr(param, 'N_bf', 1))
            bmaxg = float(getattr(param, 'bmaxg', 1.0))
            float_ctl = str(getattr(OP, 'RXFFE_FLOAT_CTL', 'isi')).lower()
            if float_ctl == 'taps':
                src = Cmod
            else:
                src = VV[cmx, :] if cmx < VV.shape[0] else Cmod
            idx = _force__findbankloc(src, N_tail_start, N_bmax, N_bf, float(Cmod[cmx]), bmaxg, N_bg)
            idx = np.sort(idx)

        tap_constraint = str(getattr(OP, 'RXFFE_TAP_CONSTRAINT', 'unity cursor')).lower()
        if tap_constraint == 'unity cursor':
            # RULED 2026-09-23 (owner), the same ruling as the singular VV
            # above: Cmod(cmx+1) only collapses when VV is degenerate.
            #
            # ML 6238 is `Cmod=Cmod/Cmod(cmx+1)` with NO guard. The 1e-12 floor
            # that used to stand here diverged twice over. For a cursor tap
            # below 1e-12 but LEGAL it substituted 1.0, leaving the taps
            # unnormalised and differing from MATLAB by the whole scale factor;
            # and for a cursor tap of exactly zero it silently returned
            # unnormalised taps where MATLAB returns Inf or NaN.
            #
            # So divide exactly as MATLAB does, however small the tap, and stop
            # only on the one value MATLAB cannot divide by. Small is not
            # degenerate; zero is.
            cursor_val = float(Cmod[cmx])
            if cursor_val == 0.0:
                raise ValueError(
                    'force: the cursor tap Cmod[%d] is exactly zero, so the '
                    'unity-cursor normalisation has no answer. MATLAB divides '
                    'anyway and carries Inf or NaN into every tap; SiCoPR '
                    'stops instead, so the degenerate case is visible.' % cmx)
            Cmod = Cmod / cursor_val
        else:
            Cmod = C_solved[:num_taps]

        if cstep != 0:
            Cmod = np.floor(np.abs(Cmod / cstep)) * np.sign(Cmod) * cstep

        if len(idx) > 0:
            N_fixed = cmx + int(getattr(param, 'RxFFE_cpx', cpx)) + 1
            C1 = Cmod.copy()
            C1[N_fixed:] = 0.0
            for j, k in enumerate(idx):
                pos = cmx + 1 + int(k) - 1  # idx is 1-based
                if pos < len(C1):
                    C1[pos] = Cmod[pos] if pos < len(Cmod) else 0.0
            Cmod = C1
    else:
        Cmod = np.asarray(C, dtype=float).ravel()

    if return_V:
        Vfiltered = _FFE(Cmod, cmx, spui, V)
    else:
        Vfiltered = np.array([])

    return Vfiltered, Cmod, idx



# --- get_ILN (MATLAB lines 6254–6269) ---

def get_ILN(sdd21, faxis_f2):
    """Fit insertion loss normalisation curve and return ILN residual.

    Returns (ILN, efit) where:
      efit = weighted polynomial fit: a0 + a1*sqrt(f) + a2*f + a3*f^2
      ILN  = 20*log10(|sdd21|) - efit
    """
    sdd21 = np.squeeze(np.asarray(sdd21, dtype=complex)).ravel()
    faxis_f2 = np.asarray(faxis_f2, dtype=float).ravel()

    abs_s = np.abs(sdd21)
    # MATLAB is silent about log10(0) and about the 0*(-Inf) that follows it.
    with np.errstate(divide='ignore', invalid='ignore'):
        db_s = 20.0 * np.log10(abs_s)

        # Weighted basis matrix (n x 4); columns are abs_s * [1, sqrt(f), f, f^2]
        fmbg = np.column_stack([
            abs_s,
            np.sqrt(faxis_f2) * abs_s,
            faxis_f2 * abs_s,
            faxis_f2 ** 2 * abs_s,
        ])
        LGw = abs_s * db_s  # weighted log response (RHS)

        # MATLAB: alpha = ((fmbg'*fmbg)^-1)*fmbg'*LGw, with
        # warning('off','MATLAB:nearlySingularMatrix') immediately above it — i.e.
        # it deliberately takes the raw normal-equations inverse of a matrix it
        # knows is nearly singular, and keeps all four basis terms.
        #
        # This MUST NOT be replaced by np.linalg.lstsq. faxis is in Hz, so the f^2
        # column reaches ~4.5e21 and cond(fmbg'fmbg) overflows to inf; lstsq then
        # truncates small singular values and solves with an effective rank of 2 of
        # 4, silently discarding half the fit basis. That produced fitted-IL errors
        # of 3.6-14.4 dB against MATLAB and a correspondingly wrong FOM_ILD.
        A = fmbg.T @ fmbg
        try:
            Ainv = np.linalg.inv(A)
        except np.linalg.LinAlgError:
            # MATLAB's inv() does not fail on an exactly singular matrix: it
            # warns and returns Inf in every entry, and that Inf (or the NaN
            # that Inf*0 makes of it) flows out through efit and ILN.
            # COM Octave, get_ILN on a single frequency point:
            #   warning: inverse: matrix singular to machine precision, rcond = 0
            #   alpha = [Inf Inf Inf Inf]   efit = Inf   ILN = -Inf
            # and on an all-zero sdd21:
            #   alpha = [NaN NaN NaN NaN]   efit = NaN   ILN = NaN
            # Falling back to lstsq answered both with finite numbers the
            # reference never produces: efit 1.0662767 where MATLAB says Inf,
            # and efit 0 where MATLAB says NaN.
            Ainv = np.full_like(A, np.inf)
        # MATLAB associates left to right: ((fmbg'*fmbg)^-1 * fmbg') * LGw.
        alpha = (Ainv @ fmbg.T) @ LGw
        efit = (
            alpha[0]
            + alpha[1] * np.sqrt(faxis_f2)
            + alpha[2] * faxis_f2
            + alpha[3] * faxis_f2 ** 2
        )
        ILN = db_s - efit
    return ILN, efit



# --- get_ILN_cmp_td (MATLAB lines 6270–6379) ---

# ============================================================
# MATLAB→Python translation notes for get_ILN_cmp_td
# MATLAB lines: 6270–6378
# ============================================================
# Computes complex IL fitting and TD ILN.
# Polynomial fit: fmbg = [ones sdd21, sqrt(f)*sdd21, f*sdd21, f^2*sdd21] (column matrix).
# LGw = (sdd21 * log(abs(sdd21)) + 1j*unwrap(angle(sdd21))) transposed.
# alpha = inv(fmbg'*fmbg) * fmbg'*LGw -- the NORMAL EQUATIONS (ML 6740),
# NOT a least-squares solve: fmbg is nearly singular and the two differ by ~0.9 dB.
# efit_C = sum(alpha_i * basis_i); FIT = exp(efit_C).
# efit = dB(FIT); ILN = dB(sdd21) - efit.
# TD: calls the real s21_to_impulse_DC. An all-zero sdd21 has no answer and the
# reference stops on it; so does this.
# ipeak: 0-based argmax of TD_ILN.REF.PR.
# Loop im=0..M-1: norm, pdf, cdf → FOM_PDF.
# ============================================================


def _get_ILN_cmp_td__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _get_ILN_cmp_td__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _get_ILN_cmp_td__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)


def _get_ILN_cmp_td__mround(x):
    """MATLAB round(): half away from zero, where Python's round() is banker's."""
    x = float(x)
    t = int(x)                      # int() truncates toward zero
    if abs(x - t) == 0.5:           # exact tie: MATLAB goes away from zero
        return t + (1 if x > 0 else -1)
    # Off a tie round() is exact, and unlike floor(x + 0.5) it does not
    # send 0.49999999999999994 to 1: that sum is exactly 1.0 in binary.
    return int(round(x))





# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.


def _get_ILN_cmp_td__s21_to_impulse_DC_zero(freq_array, time_step, OP, param):
    """Zero-input path of s21_to_impulse_DC (eps-valued output)."""
    freq_array = np.asarray(freq_array, dtype=float)
    fmax = 1.0 / time_step / 2.0
    freq_step = float(freq_array[2] - freq_array[1]) if len(freq_array) > 2 else float(freq_array[1] - freq_array[0])
    n_steps = _get_ILN_cmp_td__mround(fmax / freq_step)
    fout = np.arange(0, n_steps + 1) * (fmax / n_steps)
    IL_interp = np.full(len(fout), np.finfo(float).eps, dtype=complex)
    IL_symmetric = np.concatenate([
        [np.real(IL_interp[0])],
        IL_interp[1:-1],
        [np.real(IL_interp[-1])],
        np.conj(IL_interp[1:-1])[::-1]
    ])
    impulse_response = np.real(np.fft.ifft(IL_symmetric))
    L = len(impulse_response)
    t_base = np.arange(L) / (freq_step * L)
    ir_peak = _get_ILN_cmp_td__mmax(np.abs(impulse_response))
    thresh = getattr(OP, 'impulse_response_truncation_threshold', 1e-7)
    last_arr = np.where(np.abs(impulse_response) > ir_peak * thresh)[0]
    ir_last = int(last_arr[-1]) if len(last_arr) > 0 else L - 1
    voltage = impulse_response[:ir_last + 1]
    t_out = t_base[:ir_last + 1]
    return voltage, t_out, 0.0, -np.inf


def _get_ILN_cmp_td__get_pdf_from_sampled_signal(input_vector, L, BinSize):
    iv = np.asarray(input_vector, dtype=float).ravel()
    if len(iv) == 0:
        return _d_cpdf(BinSize, 0, 1)
    if _get_ILN_cmp_td__mmax(np.abs(iv)) > BinSize:
        iv = iv[np.abs(iv) > BinSize]
    else:
        return _d_cpdf(BinSize, 0, 1)
    iv[np.abs(iv) < BinSize] = 0.0
    b = np.sign(iv)
    sort_idx = np.argsort(np.abs(iv), kind='stable')[::-1]
    iv = np.abs(iv[sort_idx]) * b[sort_idx]
    values = 2.0 * np.arange(L) / (L - 1) - 1.0
    prob = np.ones(L) / L
    pdf = _d_cpdf(BinSize, 0, 1)
    empty_pdf = pdf
    for v in iv:
        pdfn = _Init_PDF_Fast(empty_pdf, np.abs(v) * values, prob)
        pdf = _conv_fct(pdf, pdfn)
    return pdf


def get_ILN_cmp_td(sdd21, faxis_f2, OP, param, A_T=None):
    """Complex IL fitting and TD ILN (MATLAB lines 6270-6378).

    sdd21: complex S21 (row or column vector).
    Returns (ILN, efit, TD_ILN).
    ILN and efit are in dB. TD_ILN contains time-domain struct.
    For non-zero sdd21: uses the real s21_to_impulse_DC for the TD section.
    """
    if A_T is None:
        A_T = 1.0

    sdd21 = np.asarray(sdd21, dtype=complex).ravel()
    faxis_f2 = np.asarray(faxis_f2, dtype=float).ravel()

    # Override OP settings for this function (per MATLAB L6279-6280, 6307)
    OP_copy = SimpleNamespace(**vars(OP))
    OP_copy.impulse_response_truncation_threshold = 1e-7
    OP_copy.interp_sparam_mag = 'trend_to_DC'
    OP_copy.interp_sparam_phase = 'interp_to_DC'

    # Polynomial basis for complex log fitting
    f = faxis_f2
    fmbg = np.column_stack([
        sdd21,
        np.sqrt(f) * sdd21,
        f * sdd21,
        f ** 2 * sdd21,
    ])  # shape (N, 4)

    # ML 6738: unwraplog=log(abs(sdd21))+1i*unwrap(angle(sdd21)) -- NO eps
    # floor. The floor changes every value slightly and, at |sdd21| = 0,
    # replaces the reference's -Inf with a finite ~-708.
    with np.errstate(divide='ignore'):
        unwraplog = np.log(np.abs(sdd21)) + 1j * np.unwrap(np.angle(sdd21))
    LGw = (sdd21 * unwraplog).reshape(-1, 1)

    # ML 6740: alpha = ((fmbg'*fmbg)^-1)*fmbg'*LGw -- the NORMAL EQUATIONS with
    # an explicit inverse, not a least-squares solve.
    #
    # They are the same answer only for a well-conditioned system, and this one
    # is not: ML 6737 is `warning('off','MATLAB:nearlySingularMatrix')`, so the
    # reference knows fmbg'*fmbg is nearly singular and proceeds anyway. On a
    # near-singular system np.linalg.lstsq truncates the small singular values
    # and returns the minimum-norm answer, while the explicit inverse amplifies
    # them; the two fits differ by about 0.9 dB across the band.
    #
    # Measured on a smooth real sdd21 = 0.9*exp(-f/40e9), 40 points:
    #   COM Octave ILN[0:3] = 3.33e-14, 5.33e-14, 6.06e-14   (a near-exact fit)
    #   lstsq      ILN[0:3] = -0.905,   -0.807,   -0.713
    # The reference's fit reproduces this channel essentially exactly, which is
    # what ILN is supposed to do; the lstsq fit does not.
    #
    # `fmbg.conj().T` is MATLAB's `'`, the CONJUGATE transpose, which matters
    # because fmbg is complex.
    fmbg_h = fmbg.conj().T
    alpha = np.linalg.inv(fmbg_h @ fmbg) @ (fmbg_h @ LGw)
    alpha = alpha.ravel()

    efit_C = (alpha[0] + alpha[1] * np.sqrt(f) + alpha[2] * f + alpha[3] * f ** 2)
    FIT = np.exp(efit_C)

    # ML 6731: db = @(x) 20*log10(abs(x)) -- NO eps floor. Same defect as
    # plot_modal carried: at |x| = 0 the reference gives -Inf and the
    # epsilon version gives a plausible -313 dB that reads like data.
    # errstate only silences numpy's warning; MATLAB returns -Inf quietly.
    def dB(x):
        with np.errstate(divide='ignore'):
            return 20.0 * np.log10(np.abs(x))
    efit = dB(np.abs(FIT))
    ILN = dB(sdd21) - efit

    print('computing TD_ILN (dB) ...', end='')

    M = int(param.samples_per_ui)
    BinSize = float(getattr(OP, 'BinSize', 1e-4))
    specBER = float(param.specBER)

    # TX/BT/BW filters (MATLAB L6309-6313). H_bt forced use_BT=1; H_bw computed
    # but NOT used in the s21_to_impulse_DC call (matches MATLAB). H_tw = ones.
    H_bt = Bessel_Thomson_Filter(param, f, 1)
    H_bw = Butterworth_Filter(param, f, 1)
    H_t = np.exp(-(np.pi * f / 1e9 * float(OP.transmitter_transition_time) / 1.6832) ** 2)  # Eq 93A-46
    H_tw = np.ones(len(f))

    TD_ILN = SimpleNamespace()

    # REF (from sdd21) — MATLAB L6315-6318: s21_to_impulse_DC(sdd21.*H_bt.*H_t.*H_tw)
    if np.all(sdd21 == 0):
        fir_r, t_r, caus_r, trunc_r = _get_ILN_cmp_td__s21_to_impulse_DC_zero(f, float(param.sample_dt), OP_copy, param)
    else:
        fir_r, t_r, caus_r, trunc_r = s21_to_impulse_DC(
            sdd21 * H_bt * H_t * H_tw, f, float(param.sample_dt), OP_copy, param)

    TD_ILN.REF = SimpleNamespace(FIR=fir_r, t=t_r,
                                  causality_correction_dB=caus_r, truncation_dB=trunc_r)
    TD_ILN.REF.PR = lfilter(np.ones(M), [1.0], fir_r)

    # FIT (from complex fitted response) — MATLAB L6321-6324: s21_to_impulse_DC(FIT.*H_bt.*H_t.*H_tw)
    if np.all(sdd21 == 0):
        fir_f, t_f, caus_f, trunc_f = _get_ILN_cmp_td__s21_to_impulse_DC_zero(f, float(param.sample_dt), OP_copy, param)
    else:
        fir_f, t_f, caus_f, trunc_f = s21_to_impulse_DC(
            FIT * H_bt * H_t * H_tw, f, float(param.sample_dt), OP_copy, param)

    TD_ILN.FIT = SimpleNamespace(FIR=fir_f, t=t_f,
                                  causality_correction_dB=caus_f, truncation_dB=trunc_f)
    TD_ILN.FIT.PR = lfilter(np.ones(M), [1.0], fir_f)

    ipeak = int(np.where(TD_ILN.REF.PR == _get_ILN_cmp_td__mmax(TD_ILN.REF.PR))[0][0])
    range_end = min(len(TD_ILN.REF.PR), len(TD_ILN.FIT.PR))
    irange = slice(ipeak, range_end)

    TD_ILN.ILN = TD_ILN.FIT.PR[irange] - TD_ILN.REF.PR[irange]
    TD_ILN.t = TD_ILN.FIT.t[irange] if len(TD_ILN.FIT.t) > ipeak else TD_ILN.FIT.t
    TD_ILN.FOM = -np.inf
    TD_ILN.FOM_PDF = -np.inf

    rms_fom = -np.inf
    for im in range(M):
        samples = TD_ILN.ILN[im::M]
        TD_ILN.FOM = max(float(TD_ILN.FOM), float(np.linalg.norm(samples)))
        pdf = _get_ILN_cmp_td__get_pdf_from_sampled_signal(samples, int(param.levels), BinSize)
        pdf_y = np.asarray(pdf.y, dtype=float)
        pdf_x = np.asarray(pdf.x, dtype=float)
        rms = float(np.sqrt(np.dot(pdf_y, pdf_x ** 2)) * np.sqrt(2))
        cdf_y = np.cumsum(pdf_y)
        if rms > rms_fom:
            rms_fom = rms
            idx_ber = np.where(cdf_y >= specBER)[0]
            if len(idx_ber) > 0:
                TD_ILN.FOM_PDF = float(-pdf_x[idx_ber[0]])
            TD_ILN.PDF = pdf

    # MATLAB db = @(x) 20*log10(abs(x)); the abs() handles a negative fit_peak
    # (FIT.PR at the REF peak index can be < 0 -> bare log10 gives NaN).
    fit_peak = float(TD_ILN.FIT.PR[ipeak])
    TD_ILN.SNR_ISI_FOM = (float(20.0 * np.log10(abs(fit_peak / TD_ILN.FOM)))
                           if TD_ILN.FOM != 0 else np.inf)
    TD_ILN.SNR_ISI_FOM_PDF = (float(20.0 * np.log10(abs(fit_peak / TD_ILN.FOM_PDF)))
                               if TD_ILN.FOM_PDF != 0 else np.inf)
    print(f'{TD_ILN.SNR_ISI_FOM_PDF:.6g} dB')

    return ILN, efit, TD_ILN



# --- get_PSDs (MATLAB lines 6380–6654) ---

# ============================================================
# MATLAB→Python translation notes for get_PSDs
# MATLAB lines: 6380–6654
# ============================================================
# cursor_i: caller passes 0-based Python index. MATLAB code uses 1-based.
#   Internal conversion: cursor_i_m = cursor_i + 1 where MATLAB 1-based needed.
#   mod(cursor_i_m - 1, M) + 1 → cursor_i % M  (0-based phase)
#   mod(cursor_i_m, M) → (cursor_i + 1) % M
# filter(ones(1,M), 1, x) → lfilter(ones(M), 1, x)
# reshape(v, num_ui, M) MATLAB col-major → v.reshape(num_ui, M, order='F')
# sum(A.') where A is num_ui×M → np.sum(A.T, axis=0) giving shape (num_ui,)
# Single→double-sided: [re(S[0]), S[1:-1], re(S[-1]), conj(S[-2:0:-1])]
# fvec: single-sided, length = num_ui*M//2 + 1
# isfield → hasattr
# Output: result SimpleNamespace with S_rn, S_xn, S_tn, S_jn, S_qn, S_n, etc.
# ============================================================





# ---------------------------------------------------------------------------
# Callee stubs (minimal)
# ---------------------------------------------------------------------------


# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.


# get_PSDs calls get_pdf_from_sampled_signal once per tick per EQ setting, and
# consecutive ticks feed it the SAME sampled vector, so most builds are exact
# repeats. Each build costs ~120 convolutions over a 4096-point vector, so
# memoising them is worthwhile. Keyed on the input bytes, so a hit is
# bit-identical by construction; small LRU because repeats are temporally local
# (within one equalizer setting's tick sweep).
#
# This wrapper is the reason get_PSDs keeps a local name for the function
# rather than calling the canonical directly. It is NOT a duplicate
# translation: it returns exactly what the canonical returns, which is why the
# differential in tests/test_inlined_copies.py reports it as identical. It was
# collapsed onto a bare import on 2026-09-22 and had to be restored -- a copy
# being behaviourally equivalent does not make it redundant.
_PDF_CACHE = _collections.OrderedDict()
_PDF_CACHE_MAX = 64


def _get_PSDs__detach(pdf):
    """Hand out a PDF that shares nothing mutable with the cached entry.

    Copying the namespace alone is not enough: the arrays inside would still be
    shared, so a caller doing `pdf.y *= k` (rather than `pdf.y = pdf.y * k`)
    would corrupt the cache and silently poison every later hit. Copying the
    arrays costs far less than recomputing the PDF, so the speed-up stands.
    """
    out = SimpleNamespace(**vars(pdf))
    for _k, _v in vars(out).items():
        if isinstance(_v, np.ndarray):
            setattr(out, _k, _v.copy())
    return out


def _get_PSDs__get_pdf_from_sampled_signal(input_vector, L, BinSize, FAST_NOISE_CONV=0):
    _arr = np.ascontiguousarray(np.asarray(input_vector, dtype=float))
    _key = (_hashlib.blake2b(_arr.tobytes(), digest_size=16).digest(),
            int(L), float(BinSize), int(FAST_NOISE_CONV))
    _hit = _PDF_CACHE.get(_key)
    if _hit is not None:
        _PDF_CACHE.move_to_end(_key)
        return _get_PSDs__detach(_hit)
    _res = _pdf_uncached(input_vector, L, BinSize, FAST_NOISE_CONV)
    _PDF_CACHE[_key] = _res
    if len(_PDF_CACHE) > _PDF_CACHE_MAX:
        _PDF_CACHE.popitem(last=False)
    return _get_PSDs__detach(_res)


def _get_PSDs__S_RN(fvec, G_DC, G_DC2, param):
    """Stub for S_RN — returns flat receiver noise PSD (V^2/GHz)."""
    eta_0 = param.eta_0  # V^2/GHz
    return eta_0 * np.ones(len(fvec))


def _get_PSDs__S_IN(fvec, H_noise, G_DC, G_DC2, param, OP):
    """Stub for S_IN — returns zeros."""
    return np.zeros(len(fvec))


def _get_PSDs__H_interp(sdd21p, faxis, fvec, fb):
    """Stub for H_interp — interpolates linearly."""
    return np.interp(fvec, faxis, np.abs(sdd21p))


# ---------------------------------------------------------------------------
# Helper: build conjugate-symmetric double-sided vector
# ---------------------------------------------------------------------------

def _get_PSDs__check_h_index(idx, n):
    """Refuse an h() index the reference would refuse, with its own message.

    `idx` is 0-based; the message quotes the 1-based index MATLAB reports.
    """
    idx = np.asarray(idx)
    # Which offending index the reference names: the FIRST non-positive one,
    # but the LARGEST over-bound one.
    #   COM Octave: h=1:10; h([3 -5 -1]) -> "h(-5): ...";  h([-1 -5 3]) ->
    #   "h(-1): ...";  h([3 12 15]) and h([3 15 12]) both -> "h(15): out of
    #   bound 10".
    bad = idx[idx < 0]
    if bad.size:
        raise IndexError(
            'get_PSDs: h(%d): subscripts must be either integers 1 to '
            '(2^63)-1 or logicals - the jitter sampling window starts '
            'before the pulse response' % (int(bad[0]) + 1))
    if idx.size and int(idx.max()) >= n:
        raise IndexError(
            'get_PSDs: h(%d): out of bound %d - the jitter sampling window '
            'runs past the pulse response' % (int(idx.max()) + 1, n))


def _get_PSDs__to_double_sided(S_ss):
    """Convert single-sided spectrum to double-sided (conjugate symmetric).

    Input: S_ss of length N = num_ui*M/2 + 1
    Output: length 2*(N-1) = num_ui*M
    """
    return np.concatenate([
        [np.real(S_ss[0])],
        S_ss[1:-1],
        [np.real(S_ss[-1])],
        np.conj(S_ss[-2:0:-1])
    ])


def _get_PSDs__fold_psd(full_psd, num_ui, M):
    """Fold full double-sided PSD (num_ui*M elements) to decimated num_ui-element PSD.

    Equivalent to MATLAB: sum(reshape(psd, num_ui, M).')
    Then take single-sided and mirror back.
    """
    # MATLAB column-major reshape: each column of length num_ui
    mat = full_psd.reshape(num_ui, M, order='F')  # (num_ui, M)
    # Transpose and sum columns → length num_ui
    S_folded = np.sum(mat.T, axis=0)
    return S_folded


# ---------------------------------------------------------------------------
# Main function
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# Inlined helpers for the B01-D2 'slow' ADC-clip path (MATLAB 4p15p0 6716-6725).
# Faithful copies of the audited canonical get_pdf_from_sampled_signal / conv_fct /
# CDF_inv_ev (and their sub-helpers). No cross-py_impl imports per build protocol.
# ---------------------------------------------------------------------------


# The ADC-clip signal PDF depends only on the sampled pulse response, which is a
# pure function of the equalizer setting and the sampling PHASE (cursor_i % M).
# The itick sweep visits 49 ticks but only M=32 distinct phases, so ~35% of these
# builds are exact repeats. Each build costs ~120 convolutions over a 4096-point
# vector, so memoising them is worthwhile. Keyed on the input bytes, so a hit is
# bit-identical by construction; small LRU because repeats are temporally local
# (within one equalizer setting's tick sweep).


def get_PSDs(result, h, cursor_i, txffe, G_DC, G_DC2, param, chdata, OP,
             _S_RN_fn=None, _S_IN_fn=None, _H_interp_fn=None):
    """Compute power spectral densities for all noise sources.

    MATLAB lines 6380–6654.

    cursor_i: 0-based Python index of the cursor in the equalized pulse response h.
    h: 1D array — equalized pulse response (all channels, CTLE+TxFFE applied).
    result: SimpleNamespace to accumulate PSD fields.
    txffe: TX FFE tap array.
    G_DC, G_DC2: CTLE DC gain parameters.
    param, chdata, OP: standard COM structs.
    Dependency injection via optional *_fn params.
    Returns result (modified in place).
    """
    S_RN_fn = _S_RN_fn if _S_RN_fn is not None else _get_PSDs__S_RN
    S_IN_fn = _S_IN_fn if _S_IN_fn is not None else _get_PSDs__S_IN
    H_interp_fn = _H_interp_fn if _H_interp_fn is not None else _get_PSDs__H_interp

    # MATLAB passes [] for an uninitialised result; assigning a field to [] there
    # auto-creates a struct. Replicate that: None -> new namespace.
    if result is None:
        result = SimpleNamespace()

    # ---- Setup ----
    num_ui = int(param.num_ui_RXFF_noise)
    M = int(param.samples_per_ui)
    L = param.levels
    fb = param.fb
    SNR_TX = param.SNR_TX
    dw = param.RxFFE_cmx
    bmax = np.atleast_1d(np.asarray(param.bmax, dtype=float))
    bmin = np.atleast_1d(np.asarray(param.bmin, dtype=float))
    Nb = int(param.ndfe)
    sigma_X2 = (L**2 - 1) / (3.0 * (L - 1)**2)
    eta_0 = param.eta_0  # V^2/GHz
    T_b = 1.0 / fb
    delta_f = fb / num_ui  # Hz
    # Single-sided frequency vector: num_ui*M/2 + 1 points
    n_fvec = num_ui * M // 2 + 1
    fvec = np.arange(n_fvec) * delta_f
    result.fvec = fvec

    # ---- H_rxffe (eq 178A-28) ----
    if OP.COMPUTE_COM:
        H_rxffe = np.zeros(len(fvec), dtype=complex)
        w_vec = np.atleast_1d(np.asarray(result.w, dtype=complex))
        for nn, w_n in enumerate(w_vec):
            H_rxffe += w_n * np.exp(-1j * 2 * np.pi * fvec * T_b * (nn - dw - 1))
        # MATLAB L6408-6410: take the symbol-rate band (first num_ui/2+1 points)
        # of |H_rxffe|^2 and double-side to num_ui. Do NOT fold/alias — folding
        # sums M copies and inflates the noise enhancement ~Mx (closes the eye).
        H_rxffe_2_of_f = np.abs(H_rxffe) ** 2  # length num_ui*M//2+1
        H_rxffe_2_ss = H_rxffe_2_of_f[:num_ui // 2 + 1]
        H_rxffe_2 = _get_PSDs__to_double_sided(H_rxffe_2_ss)  # length num_ui
    else:
        H_rxffe_2 = 1

    result.H_rxffe_2 = H_rxffe_2

    if OP.WO_TXFFE:
        # ---- S_rn (eq 178A-15): receiver thermal noise ----
        if not OP.COMPUTE_COM:
            S_RN_of_f = S_RN_fn(fvec, G_DC, G_DC2, param)
            rxn_psd = _get_PSDs__to_double_sided(S_RN_of_f) / 1e9  # V^2/GHz → V^2/Hz
            rxn_rms = np.sqrt(np.sum(rxn_psd) * delta_f)
            S_rn_full = _get_PSDs__fold_psd(rxn_psd, num_ui, M)
            S_rn_ss = S_rn_full[:num_ui // 2 + 1]
            result.S_rn = _get_PSDs__to_double_sided(S_rn_ss)
            result.S_rn_rms = np.sqrt(np.sum(result.S_rn) * delta_f)

            # ---- S_in (eq 178A-24): input noise ----
            if OP.PSDRXCAL:
                # MATLAB L7215 keeps the interpolated noise-path VTF on the
                # result struct; the port computed it into a local and dropped
                # it, so result.H_noise never existed.
                result.H_noise = H_interp_fn(chdata[-1].sdd21p, chdata[0].faxis,
                                             fvec, fb)
                S_IN_of_f = S_IN_fn(fvec, result.H_noise, G_DC, G_DC2, param, OP)
                inn_psd = _get_PSDs__to_double_sided(S_IN_of_f)
                inn_rms = np.sqrt(np.sum(inn_psd) * delta_f)
                S_in_full = _get_PSDs__fold_psd(inn_psd, num_ui, M)
                S_in_ss = S_in_full[:num_ui // 2 + 1]
                result.S_in = _get_PSDs__to_double_sided(S_in_ss)
                result.S_in_rms = np.sqrt(np.sum(result.S_in) * delta_f)
            else:
                result.S_in = 0
                result.S_in_rms = 0
        else:
            # Apply H_rxffe to cached PSDs
            result.S_rn = result.S_rn * H_rxffe_2
            result.S_rn_rms = np.sqrt(np.sum(result.S_rn) * delta_f)
            result.S_in = result.S_in * H_rxffe_2
            result.S_in_rms = np.sqrt(np.sum(result.S_in) * delta_f)

    else:
        # ---- S_xn (eq 178A-16): crosstalk PSD ----
        if not OP.COMPUTE_COM:
            result.S_xn = 0.0
            n_channels = len(chdata)
            if OP.PSDRXCAL:
                num_channel_files = n_channels - 1
            else:
                num_channel_files = n_channels

            if num_channel_files != 1:
                hk_list = [None] * n_channels  # 0-indexed placeholder
                # ML: [~, iphase(xchan)] = max(hxn) for xchan=2:num_channel_files
                # on a variable never initialised, so MATLAB grows it to
                # num_channel_files and leaves iphase(1), the THRU, at 0. In
                # the port's 0-based form that is -1. get_pdf never reads the
                # THRU's entry (it samples the thru at the cursor phase).
                # COM Octave, checkpoint 05 of wXtalk_T4_R24: iphase [0 8 8 6].
                iphase = np.full(num_channel_files, -1, dtype=int)
                for xchan in range(1, num_channel_files):  # 0-based: channels 1..num_channel_files-1
                    ch = chdata[xchan]
                    # r4p15p0: dropped the unused pulse_ctle length calc; pad/truncate
                    # the crosstalk pulse response (hk_k) directly to num_ui*M.
                    hk_k = np.asarray(ch.pulse_response_w_CFT_TXFFE_noRxFFE).ravel()
                    # Pad or truncate to num_ui*M
                    if num_ui * M > len(hk_k):
                        hk_k = np.concatenate([hk_k, np.zeros(num_ui * M - len(hk_k))])
                    else:
                        hk_k = hk_k[:num_ui * M]

                    hxn = np.array([np.linalg.norm(hk_k[i::M]) for i in range(M)])
                    iphase[xchan] = int(np.argmax(hxn))  # 0-based phase

                    hrn = hk_k[iphase[xchan]::M]
                    S_xn_chan = sigma_X2 * (np.abs(np.fft.fft(hrn))) ** 2 / fb
                    # ML: hk(xchan).k, .hrn, .S_xn, then result.hk=hk after the
                    # loop, so the result carries all three, not hrn alone.
                    hk_list[xchan] = SimpleNamespace(k=hk_k, hrn=hrn, S_xn=S_xn_chan)
                    result.__dict__.setdefault('hk', [None] * num_channel_files)
                    result.hk[xchan] = hk_list[xchan]
                    result.S_xn = result.S_xn + S_xn_chan

                result.iphase = iphase
                result.S_xn_rms = np.sqrt(np.sum(result.S_xn) * delta_f)
            else:
                result.S_xn = 0.0
                result.hk = []
                result.iphase = 0      # ML: result.iphase=1, 1-based
                result.S_xn_rms = 0.0
        else:
            result.S_xn = result.S_xn * H_rxffe_2
            result.S_xn_rms = np.sqrt(np.sum(result.S_xn) * delta_f)

        # ---- S_tn (eq 178A-17): transmitter noise PSD ----
        if not OP.COMPUTE_COM:
            if not OP.TDMODE:
                htn = lfilter(np.ones(M), 1, chdata[0].ctle_imp_response)
            else:
                if hasattr(chdata[0], 'ctle_pulse_response'):
                    htn = chdata[0].ctle_pulse_response
                else:
                    htn = lfilter(np.ones(M), 1, chdata[0].ctle_imp_response)

            # Align to sample point (0-based cursor_i)
            phase_0 = cursor_i % M  # 0-based phase start
            htn = htn[phase_0:].ravel()
            htn = htn[::M]  # resample every M

            len_htn = len(htn)
            if num_ui > len_htn:
                hext = np.concatenate([htn, np.zeros(num_ui - len_htn)])
            else:
                hext = htn[:num_ui]

            S_tn_w_AM = int(getattr(param, 'S_tn_w_AM', 0))
            result.S_tn = (sigma_X2 ** S_tn_w_AM) * 10 ** (-SNR_TX / 10) * \
                           (np.abs(np.fft.fft(hext))) ** 2 / fb
            result.S_tn_rms = np.sqrt(np.sum(result.S_tn) * delta_f)
        else:
            result.S_tn = result.S_tn * H_rxffe_2
            result.S_tn_rms = np.sqrt(np.sum(result.S_tn) * delta_f)

        # ---- S_jn (eq 93A-28): jitter noise PSD ----
        if not OP.COMPUTE_COM:
            # Sampling offset logic (MATLAB 1-based → 0-based Python)
            cursor_i_m = cursor_i + 1  # 1-based equivalent
            sampling_offset = cursor_i_m % M  # MATLAB: mod(cursor_i, M)
            if sampling_offset <= 1:
                sampling_offset += M
            # MATLAB: cursors_early_sample = h(sampling_offset-1:M:end) (1-based)
            # → 0-based: h[sampling_offset-2::M]
            # MATLAB: cursors_late_sample = h(sampling_offset+1:M:end) (1-based)
            # → 0-based: h[sampling_offset::M]
            if OP.LIMIT_JITTER_CONTRIB_TO_DFE_SPAN:
                # h(cursor_i-1+M*(-1:ndfe)) (1-based) → h[cursor_i + M*(-1:ndfe)] (0-based)
                # fix B01-D1 (MATLAB rev 4p15p0 lines 6676-6677): early/late samples are
                # h(cursor_i-1+M*(-1:ndfe)) / h(cursor_i+1+M*(-1:ndfe)), centered at the cursor.
                idx_early = cursor_i - 1 + M * np.arange(-1, Nb + 1)
                idx_late = cursor_i + 1 + M * np.arange(-1, Nb + 1)
                # No masking: MATLAB indexes h() with the whole vector and
                # refuses an index off either end rather than quietly taking
                # the jitter slope from fewer UI.  Dropping the out-of-range
                # entries left a shorter h_J that still FFTs to a plausible
                # S_jn, which is the worst kind of wrong.
                # COM Octave: cursor_i=4 (1-based), M=4 -> "error: h(-1):
                #   subscripts must be either integers 1 to (2^63)-1 or
                #   logicals"; ndfe=14 with len(h)=64 -> "error: h(69): out of
                #   bound 64 (dimensions are 64x1)".
                _get_PSDs__check_h_index(idx_early, len(h))
                _get_PSDs__check_h_index(idx_late, len(h))
                cursors_early_sample = h[idx_early]
                cursors_late_sample = h[idx_late]
            else:
                cursors_early_sample = h[sampling_offset - 2::M]
                cursors_late_sample = h[sampling_offset::M]

            # Ensure equal length
            n_eq = min(len(cursors_early_sample), len(cursors_late_sample))
            cursors_early_sample = cursors_early_sample[:n_eq]
            cursors_late_sample = cursors_late_sample[:n_eq]

            h_J = (cursors_late_sample - cursors_early_sample) / 2.0 * M
            h_J = h_J.ravel()
            if num_ui > len(h_J):
                h_J = np.concatenate([h_J, np.zeros(num_ui - len(h_J))])
            else:
                h_J = h_J[:num_ui]

            A_DD = float(param.A_DD)
            sigma_RJ = float(param.sigma_RJ)
            result.S_jn = sigma_X2 * (A_DD**2 + sigma_RJ**2) * \
                           (np.abs(np.fft.fft(h_J))) ** 2 / fb
            result.S_jn_rms = np.sqrt(np.sum(result.S_jn) * delta_f)
            result.S_rj_jn = sigma_X2 * (sigma_RJ**2) * \
                              (np.abs(np.fft.fft(h_J))) ** 2 / fb
            result.S_rj_rms = np.sqrt(np.sum(result.S_rj_jn) * delta_f)
        else:
            result.S_jn = result.S_jn * H_rxffe_2
            result.S_jn_rms = np.sqrt(np.sum(result.S_jn) * delta_f)
            result.S_rj_jn = result.S_rj_jn * H_rxffe_2
            result.S_rj_rms = np.sqrt(np.sum(result.S_rj_jn) * delta_f)

        # ---- S_qn: quantization noise ----
        N_qb = int(param.N_qb)
        if N_qb != 0:
            pulse_for_quantization = chdata[0].pulse_response_w_CFT_TXFFE_noRxFFE
            sample_idx_0 = cursor_i % M  # 0-based
            sampled_pr = pulse_for_quantization[sample_idx_0:]
            sampled_pr = sampled_pr.ravel()[::M]
            if num_ui > len(sampled_pr):
                sampled_pr = np.concatenate([sampled_pr, np.zeros(num_ui - len(sampled_pr))])
            else:
                sampled_pr = sampled_pr[:num_ui]

            if str(getattr(param, 'clip_method', 'Fast')).lower() == 'slow':
                # fix B01-D2 (MATLAB rev 4p15p0 lines 6716-6725): adc_clip is the P_qc
                # quantile of the signal+Gaussian-noise PDF, and ctle_signal_sigma is set.
                sig_pdf = _get_PSDs__get_pdf_from_sampled_signal(sampled_pr, int(param.levels), OP.BinSize)
                sigma_noise = np.sqrt(
                    getattr(result, 'S_in_rms', 0)**2 +
                    getattr(result, 'S_rn_rms', 0)**2 +
                    getattr(result, 'S_xn_rms', 0)**2 +
                    getattr(result, 'S_tn_rms', 0)**2 +
                    getattr(result, 'S_rj_rms', 0)**2
                )
                noise_pdf = SimpleNamespace(**vars(sig_pdf))   # copy x-axis/Min/BinSize, replace y
                noise_pdf.y = (1.0 / (np.sqrt(2 * np.pi) * sigma_noise)
                               * np.exp(-sig_pdf.x**2 / (2 * sigma_noise**2)) * OP.BinSize)
                sig_noise_pdf = _conv_fct(sig_pdf, noise_pdf)
                sig_noise_cdf = np.cumsum(sig_noise_pdf.y)
                ctle_signal_sigma = float(np.sqrt(np.sum(sig_noise_pdf.x**2 * sig_noise_pdf.y)))
                adc_clip = float(-_CDF_inv_ev(param.P_qc, sig_noise_pdf, sig_noise_cdf))
                result.ctle_signal_sigma = ctle_signal_sigma
            else:
                adc_clip = float(np.sum(np.abs(sampled_pr)))

            adc_lsb = 2.0 * adc_clip / (2**N_qb - 1)
            sigma_Q = adc_lsb / np.sqrt(12.0)
            result.adc_clip = adc_clip
            result.S_qn = sigma_Q**2 / fb * np.ones(num_ui)
            result.S_qn_rms = np.sqrt(np.sum(result.S_qn) * delta_f)
        else:
            result.S_qn = 0.0
            result.S_qn_rms = 0.0

        # ---- Total S_n ----
        result.S_n = (result.S_rn + result.S_tn + result.S_xn +
                      result.S_jn + result.S_qn + result.S_in)
        result.S_n_rms = np.sqrt(np.sum(result.S_n) * delta_f)

        # ---- S_isi, S_G, Sn_rho (COMPUTE_COM path only) ----
        if OP.COMPUTE_COM:
            # 0-based: samp_idx = phase..len(h) step M
            samp_phase = cursor_i % M
            samp_idx = np.arange(samp_phase, len(h), M)
            cursor_n_arr = np.where(samp_idx == cursor_i)[0]
            if len(cursor_n_arr) == 0:
                # cursor_i not in the sample grid → find nearest
                cursor_n = int(np.searchsorted(samp_idx, cursor_i))
            else:
                cursor_n = int(cursor_n_arr[0])

            hisi = h[samp_idx].copy()
            if num_ui > len(hisi):
                hisi = np.concatenate([hisi, np.zeros(num_ui - len(hisi))])
            else:
                hisi = hisi[:num_ui]
            hisi = hisi.reshape(1, -1).ravel()

            # Apply DFE clipping to ISI taps (eq 178A-29)
            if cursor_n < len(hisi):
                cursor_val = hisi[cursor_n]
                hisi[cursor_n] = 0.0
                for ii in range(cursor_n + 1, cursor_n + Nb + 1):
                    if ii < len(hisi):
                        ib = ii - cursor_n - 1
                        if ib < len(bmax) and hisi[ii] >= bmax[ib] * cursor_val:
                            hisi[ii] -= bmax[ib] * cursor_val
                        elif ib < len(bmin) and hisi[ii] <= bmin[ib] * cursor_val:
                            hisi[ii] -= bmin[ib] * cursor_val
                        else:
                            hisi[ii] = 0.0

            result.S_isi = sigma_X2 * (np.abs(np.fft.fft(hisi))) ** 2 / fb
            result.S_isi_rms = np.sqrt(np.sum(result.S_isi) * delta_f)

            result.S_G = result.S_tn + result.S_rj_jn + result.S_rn + result.S_in
            result.S_G_rms = np.sqrt(np.sum(result.S_G) * delta_f)
            result.Sn_rho = result.S_isi + result.S_n
            result.Sn_rho_rms = np.sqrt(np.sum(result.Sn_rho) * delta_f)

    return result



# --- get_PulseR (MATLAB lines 6655–6685) ---

_EPS = np.finfo(float).eps


def _get_PulseR__colon(step, limit):
    """MATLAB `0:step:limit`.

    np.arange(0, limit + step, step) is one element too long whenever
    limit/step is not an integer, which it is not for the shipped default
    TR_TDR = 8e-3 ns.  COM Octave, fb=106.25e9, samples_per_ui=32,
    TR_TDR=8e-3: numel(0:dt:edge_time*2) is 55, arange gave 56.  Plain
    floor() is not enough either -- it is one short whenever the quotient
    lands a fraction of an eps below an integer, e.g. fb=106.25e9,
    samples_per_ui=32, TR_TDR=0.5325 where the quotient is 3620.9999999999995
    and Octave returns 3622 elements.  The last element is clamped to the
    limit when it would overshoot it, as Octave's range::final_value does.
    """
    n = int(round(limit / step + 1.0))
    if n > 0 and (n - 1) * step > limit + 3.0 * _EPS * abs(limit):
        n -= 1
    out = np.arange(max(n, 0)) * step
    if out.size:
        out[0] = 0.0        # the base, not 0*step, which is NaN for step=Inf
    if out.size > 1 and out[-1] > limit:
        out[-1] = limit
    return out


def _get_PulseR__ones_row(n):
    """MATLAB `ones(1,n)`: n must be an integer value, and n<=0 gives empty."""
    if float(n) != int(n):
        # COM Octave: ones(1,2.5) -> "conversion of 2.5 to int64_t value failed"
        raise ValueError(
            'param.samples_per_ui must be an integer, got %r' % (n,))
    return np.ones(max(int(n), 0))


def _get_PulseR__filter(b, x):
    """MATLAB `filter(b,1,x)`; scipy's lfilter refuses the empty cases."""
    # COM Octave: filter(ones(1,4),1,zeros(1,0)) -> 1x0, and
    #             filter(zeros(1,0),1,x)         -> zeros(size(x)).
    if x.size == 0:
        return np.zeros(0)
    if b.size == 0:
        return np.zeros(x.shape)
    return lfilter(b, [1.0], x)


def get_PulseR(ir, param, cb_step, ZT):
    """Compute TDR pulse response from impulse response (MATLAB lines 6655-6682).

    cb_step=True: drive with a shaped edge; cb_step=False: rectangular UI pulse.
    Returns SimpleNamespace with fields: PDR (TDR response), pulse (filtered IR).
    """
    ir = np.asarray(ir, dtype=float).ravel()
    M = param.samples_per_ui

    if cb_step:
        # TR_TDR=0 makes fedge Inf and the cosine argument 0*Inf = NaN, and
        # samples_per_ui=0 makes dt Inf so tedge collapses to the single base
        # point.  MATLAB carries both through rather than raising, so these
        # divisions must be numpy's and not Python's.
        with np.errstate(divide='ignore', invalid='ignore'):
            dt = np.float64(1.0) / np.float64(param.fb) / np.float64(M)
            edge_time = float(param.TR_TDR) * 1e-9
            fedge = np.float64(1.0) / np.float64(edge_time)
            tedge = _get_PulseR__colon(dt, edge_time * 2)
            edge = 2 * np.cos(2 * np.pi * tedge * fedge / 16 - np.pi / 4) ** 2 - 1
        drive_pulse = np.concatenate([edge, _get_PulseR__ones_row(M)])
        pulse = _get_PulseR__filter(drive_pulse, ir)
    else:
        pulse = _get_PulseR__filter(_get_PulseR__ones_row(M), ir)

    PDR_response = (1 + pulse) / (1 - pulse) * float(ZT) * 2
    return SimpleNamespace(PDR=PDR_response, pulse=pulse)



# --- get_RAW_FIR (MATLAB lines 6686–6693) ---

def get_RAW_FIR(H, f, OP, param):
    """Apply Butterworth H_r then convert to impulse response. MATLAB lines 6686-6692."""
    f = np.asarray(f, dtype=float).ravel()
    H = np.asarray(H, dtype=complex).ravel()
    H_r = 1.0 / np.polyval([1, 2.613126, 3.414214, 2.613126, 1],
                            1j * f / (0.75 * float(param.fb)))
    H_filtered = H * H_r
    FIR, t, _, _ = s21_to_impulse_DC(H_filtered, f, float(param.sample_dt), OP, param)
    return FIR, t



# --- get_RILN_cmp_td (MATLAB lines 6694–6875) ---

# ============================================================
# MATLAB→Python translation notes for get_RILN_cmp_td
# MATLAB lines: 6694–6875
# ============================================================
# Row/col: MATLAB uses row vectors; Python uses 1D arrays (ravel).
# 1000-echo sum: geometric series in FD; looped faithfully.
# fmin_idx: MATLAB 1-based find(f>=fmin,1,'first') → np.searchsorted(f,fmin)
# fmbg least squares: MATLAB's normal equations ((fmbg'*fmbg)^-1)*fmbg'*LGw,
#   reproduced term for term.  np.linalg.lstsq is NOT a substitute: fmbg is
#   conditioned ~1e21 (its columns span sdd21 .. f^2*sdd21) and lstsq's SVD
#   cutoff throws away the very modes that carry the fit (see test_verify).
# filter(ones(1,M),1,x) → lfilter(ones(M),1,x)
# ipeak: MATLAB 1-based argmax → 0-based np.argmax; range ipeak:range_end
#   MATLAB inclusive → Python slice [ipeak:range_end] (exclusive upper OK since
#   MATLAB range_end = min(len,len) and slicing is safe)
# calculate_delay_CausalityEnforcement: MATLAB's `try ... catch end` leaves
#   delay_sec undefined, so the next line raises. Matched, not papered over.
# get_pdf_from_sampled_signal: returns SimpleNamespace with .x and .y
# Bessel_Thomson_Filter / Butterworth_Filter / s21_to_impulse_DC /
#   calculate_delay_CausalityEnforcement / get_pdf_from_sampled_signal /
#   normal_dist are top-level functions of the assembled module and are called
#   by name.  They used to be hand-written stubs here; the stubbed Butterworth
#   response alone (1/sqrt(1+(2f/fb)^8), magnitude only) put REF_noise.PR out
#   by a factor of 2.6 against the reference.  A stub is not a translation.
# ============================================================



# ---------------------------------------------------------------------------
# Main function
# ---------------------------------------------------------------------------

def get_RILN_cmp_td(sdd21, RIL_struct, faxis_f2, OP, param, A_T,
                    _Bessel_Thomson_Filter_fn=None,
                    _Butterworth_Filter_fn=None,
                    _s21_to_impulse_DC_fn=None,
                    _calculate_delay_fn=None,
                    _get_pdf_fn=None,
                    _normal_dist_fn=None):
    """Compute TD reflection and re-reflection noise (RILN) figure of merit.

    MATLAB lines 6694–6875.

    sdd21: complex insertion loss array (1D, length matching faxis_f2)
    RIL_struct: SimpleNamespace with fields RIL, rho_port1, rho_port2, freq
    faxis_f2: frequency axis (Hz, at least up to fb)
    OP: SimpleNamespace with Bessel_Thomson, Butterworth, transmitter_transition_time,
        BinSize, impulse_response_truncation_threshold, etc.
    param: SimpleNamespace with samples_per_ui, sample_dt, fb, fb_BT_cutoff,
           levels, specBER, etc.
    A_T: amplitude threshold (not used in this function body; kept for signature compat)

    Returns RILN_TD_struct SimpleNamespace with fields:
        REF, FIT, RIL, REF_noise — each with FIR, PR, t, causality/truncation dBs
        ILN, t, FOM, FOM_PDF, SNR_ISI_FOM, SNR_ISI_FOM_PDF, PDF
    """
    bt_fn = _Bessel_Thomson_Filter_fn or Bessel_Thomson_Filter
    bw_fn = _Butterworth_Filter_fn or Butterworth_Filter
    s21_fn = _s21_to_impulse_DC_fn or s21_to_impulse_DC
    delay_fn = _calculate_delay_fn or calculate_delay_CausalityEnforcement
    pdf_fn = _get_pdf_fn or get_pdf_from_sampled_signal
    norm_fn = _normal_dist_fn or normal_dist

    M = int(param.samples_per_ui)

    # ---- Flatten inputs to 1D row-like arrays ----
    sdd21 = np.asarray(sdd21, dtype=complex).ravel()
    RIL = np.asarray(RIL_struct.RIL, dtype=complex).ravel()
    rho_port1 = np.asarray(RIL_struct.rho_port1, dtype=complex).ravel()
    rho_port2 = np.asarray(RIL_struct.rho_port2, dtype=complex).ravel()
    RIL_f = np.asarray(RIL_struct.freq, dtype=float).ravel()
    faxis_f2 = np.asarray(faxis_f2, dtype=float).ravel()

    # ---- Override OP fields (matching MATLAB L6836-6838) ----
    # MATLAB passes OP BY VALUE, so these assignments are local to this function.
    # Python passes it by reference: mutating OP here leaked 'trend_to_DC' /
    # 'interp_to_DC' into every S-parameter interpolation performed afterwards,
    # replacing the configured 'linear_trend_to_DC' /
    # 'extrap_cubic_to_dc_linear_to_inf'. That changes the DC/low-frequency
    # extrapolation and hence the impulse and pulse responses — visible as a
    # low steady-state voltage, a high pulse peak, and a large ISI error, while
    # leaving Nyquist-band magnitude metrics (IL, ICN) untouched.
    # get_ILN_cmp_td already uses this OP_copy pattern; match it here.
    OP = SimpleNamespace(**vars(OP))
    OP.interp_sparam_mag = 'trend_to_DC'
    OP.interp_sparam_phase = 'interp_to_DC'
    OP.impulse_response_truncation_threshold = 1e-7

    # ---- Echo sum: port1 and port2 reflection/re-reflection noise ----
    number_of_echos = 1000
    fmin = 1e9
    port2_rn = np.zeros(len(RIL), dtype=complex)
    port1_rn = np.zeros(len(RIL), dtype=complex)
    abs_RIL = np.abs(RIL)
    for m in range(1, number_of_echos + 1):
        port2_rn += (abs_RIL * (RIL ** (2 * m)) *
                     (rho_port1 ** m) * (rho_port2 ** m) *
                     (1 + rho_port1) * (1 + rho_port2))
        port1_rn += (abs_RIL * (RIL ** (2 * m - 1)) *
                     (rho_port1 ** (m - 1)) * (rho_port2 ** m) *
                     (1 + rho_port1) * (1 + rho_port1))

    # ---- Remove data below fmin (bad TD conversion near DC) ----
    fmin_idx = int(np.searchsorted(RIL_f, fmin))
    port2_rn = port2_rn[fmin_idx:]
    port1_rn = port1_rn[fmin_idx:]
    f_rn = RIL_f[fmin_idx:]

    # ---- Log-domain polynomial fit to sdd21 (trend removal for ILN) ----
    f = faxis_f2
    N = len(f)
    sdd21_col = sdd21.reshape(-1, 1)  # N×1
    fmbg = np.column_stack([
        sdd21,
        np.sqrt(f) * sdd21,
        f * sdd21,
        f**2 * sdd21,
    ])  # N×4
    # MATLAB has no floor here: log(0) is -Inf and 0*-Inf is NaN, which then
    # poisons alpha and every output.  An eps floor quietly returns a plausible
    # number instead, so a channel with a null in it would look healthy.
    with np.errstate(divide='ignore', invalid='ignore'):
        unwraplog = np.log(np.abs(sdd21)) + 1j * np.unwrap(np.angle(sdd21))
        LGw = sdd21 * unwraplog  # N, complex
    # MATLAB L6755: alpha = ((fmbg'*fmbg)^-1)*fmbg'*LGw.  `'` is the conjugate
    # transpose and `^-1` is inv().  Spelled out because a least-squares solver
    # is NOT interchangeable with it here: cond(fmbg) ~ 1e21, so lstsq's SVD
    # cutoff discards the sqrt(f) and f modes and returns a different fit.
    fmbgH = fmbg.conj().T
    with np.errstate(divide='ignore', invalid='ignore'):
        alpha = np.linalg.inv(fmbgH @ fmbg) @ (fmbgH @ LGw)
    efit_C = alpha[0] + alpha[1] * np.sqrt(f) + alpha[2] * f + alpha[3] * f**2
    FIT = np.exp(efit_C)

    # ---- TD responses for REF, FIT ----
    H_bw = bw_fn(param, f, 1)
    H_t = np.exp(-(np.pi * f / 1e9 * OP.transmitter_transition_time / 1.6832) ** 2)
    H_tw = np.ones(len(f))  # Tukey window overridden to ones in MATLAB

    RILN_TD_struct = SimpleNamespace()

    RILN_TD_struct.REF = SimpleNamespace()
    (RILN_TD_struct.REF.FIR,
     RILN_TD_struct.REF.t,
     RILN_TD_struct.REF.causality_correction_dB,
     RILN_TD_struct.REF.truncation_dB) = s21_fn(sdd21 * H_bw * H_t * H_tw, f, param.sample_dt, OP, param)
    RILN_TD_struct.REF.PR = lfilter(np.ones(M), 1, RILN_TD_struct.REF.FIR)

    RILN_TD_struct.FIT = SimpleNamespace()
    (RILN_TD_struct.FIT.FIR,
     RILN_TD_struct.FIT.t,
     RILN_TD_struct.FIT.causality_correction_dB,
     RILN_TD_struct.FIT.truncation_dB) = s21_fn(FIT * H_bw * H_t * H_tw, f, param.sample_dt, OP, param)
    RILN_TD_struct.FIT.PR = lfilter(np.ones(M), 1, RILN_TD_struct.FIT.FIR)

    # ---- TD response for RIL ----
    H_bw_r = bw_fn(param, RIL_f, 1)
    H_t_r = np.exp(-(np.pi * RIL_f / 1e9 * OP.transmitter_transition_time / 1.6832) ** 2)
    H_tw_r = np.ones(len(RIL_f))

    RILN_TD_struct.RIL = SimpleNamespace()
    (RILN_TD_struct.RIL.FIR,
     RILN_TD_struct.RIL.t,
     RILN_TD_struct.RIL.causality_correction_dB,
     RILN_TD_struct.RIL.truncation_dB) = s21_fn(RIL * H_bw_r * H_t_r * H_tw_r, RIL_f, param.sample_dt, OP, param)
    RILN_TD_struct.RIL.PR = lfilter(np.ones(M), 1, RILN_TD_struct.RIL.FIR)

    # ---- Channel delay → apply to port2 noise ----
    # MATLAB: `try [delay_sec, delay_idx] = calculate_delay_...; catch end`.
    # The empty catch swallows the failure and leaves delay_sec UNDEFINED, so
    # the very next line dies with "'delay_sec' undefined" — confirmed by
    # running the reference under Octave against a failing delay function.
    # That is an upstream defect (the catch should set a fallback), but it is
    # the reference's behaviour; the port used to substitute a silent zero
    # delay, which is a different answer, not a recovered one.
    try:
        delay_sec, _ = delay_fn(f, sdd21, param, OP)
    except Exception as exc:
        raise NameError(
            "'delay_sec' undefined: calculate_delay_CausalityEnforcement "
            "failed and the reference's empty catch leaves delay_sec unset "
            '(upstream defect, COM 4p16p0 get_RILN_cmp_td)') from exc
    port2_rn = port2_rn * np.exp(-1j * 2 * np.pi * f_rn * delay_sec)

    # ---- TD response for REF_noise (port2 reflection/re-reflection) ----
    H_bw_n = bw_fn(param, f_rn, 1)
    H_t_n = np.exp(-(np.pi * f_rn / 1e9 * OP.transmitter_transition_time / 1.6832) ** 2)
    H_tw_n = np.ones(len(f_rn))

    RILN_TD_struct.REF_noise = SimpleNamespace()
    (RILN_TD_struct.REF_noise.FIR,
     RILN_TD_struct.REF_noise.t,
     RILN_TD_struct.REF_noise.causality_correction_dB,
     RILN_TD_struct.REF_noise.truncation_dB) = s21_fn(port2_rn * H_bw_n * H_t_n * H_tw_n,
                                                       f_rn, param.sample_dt, OP, param)
    RILN_TD_struct.REF_noise.PR = lfilter(np.ones(M), 1, RILN_TD_struct.REF_noise.FIR)

    # ---- Extract ILN from cursor of REF.PR ----
    REF_PR = RILN_TD_struct.REF.PR
    RN_PR = RILN_TD_struct.REF_noise.PR
    ipeak = int(np.argmax(REF_PR))  # 0-based
    range_end = min(len(REF_PR), len(RN_PR))
    RILN_TD_struct.ILN = RN_PR[ipeak:range_end]
    RILN_TD_struct.t = RILN_TD_struct.REF_noise.t[ipeak:range_end]
    RILN_TD_struct.FOM = -np.inf
    RILN_TD_struct.FOM_PDF = -np.inf
    rms_fom = -np.inf

    # ---- FOM: max norm over M sample phases ----
    bin_size = float(getattr(OP, 'BinSize', 1e-3))
    specBER = float(getattr(param, 'specBER', 1e-4))
    ILN = RILN_TD_struct.ILN

    best_pdf = None
    for im in range(M):
        phase_samples = ILN[im::M]
        if len(phase_samples) == 0:
            continue
        RILN_TD_struct.FOM = max(RILN_TD_struct.FOM, float(np.linalg.norm(phase_samples)))
        pdf = pdf_fn(phase_samples, param.levels, bin_size, 0)
        # rms from PDF: sqrt(sum(y * x^2))
        rms = float(np.sqrt(np.sum(pdf.y * pdf.x**2))) * np.sqrt(2)
        if rms > rms_fom:
            rms_fom = rms
            # CDF threshold
            cdf_y = np.cumsum(pdf.y)
            idx_ber = int(np.searchsorted(cdf_y, specBER))
            if idx_ber < len(pdf.x):
                RILN_TD_struct.FOM_PDF = -pdf.x[idx_ber]
            else:
                RILN_TD_struct.FOM_PDF = -np.inf
            best_pdf = pdf

    RILN_TD_struct.PDF = best_pdf

    # ---- SNR metrics ----
    # MATLAB: db = @(x) 20*log10(abs(x)), applied to FIT.PR(ipeak)/FOM.  No eps
    # floor on the denominator: a zero FOM gives +Inf, and the floored form
    # reported a plausible ~6000 dB instead.  FIT.PR(ipeak) is indexed with no
    # guard, exactly as MATLAB does — it raises when FIT.PR was truncated
    # shorter than REF.PR, and that is the reference's behaviour.
    FIT_peak = np.float64(RILN_TD_struct.FIT.PR[ipeak])
    with np.errstate(divide='ignore', invalid='ignore'):
        RILN_TD_struct.SNR_ISI_FOM = 20.0 * np.log10(
            np.abs(FIT_peak / np.float64(RILN_TD_struct.FOM)))
        RILN_TD_struct.SNR_ISI_FOM_PDF = 20.0 * np.log10(
            np.abs(FIT_peak / np.float64(RILN_TD_struct.FOM_PDF)))

    return RILN_TD_struct



# --- get_StepR (MATLAB lines 6876–6903) ---

_EPS = np.finfo(float).eps


def _get_StepR__colon(step, limit):
    """MATLAB `0:step:limit`.

    Two wrong spellings were tried here first, and both are recorded because
    each looked verified:

    `np.arange(0, limit + step, step)` is one element too LONG whenever
    limit/step is not an integer, which it is not at the shipped default
    TR_TDR = 8e-3 ns. COM Octave, fb=53.125e9, samples_per_ui=32: numel 28,
    not 29.

    `int(floor(limit/step)) + 1` is one element too SHORT whenever the
    quotient lands a fraction of an eps below an integer. fb=106.25e9,
    samples_per_ui=32, TR_TDR=0.5325 gives 3620.9999999999995, about 2000 eps
    below 3621, and Octave returns 3622 points. That spelling was accepted on
    a 660-combination sweep that compared only numel, and numel is exactly
    what it gets wrong here; a sweep over element VALUES, 672 combinations,
    caught it.

    The last element is clamped to the limit when accumulation would overshoot
    it, as Octave's range::final_value does. Identical to the helper in
    get_PulseR, which is the same reference line.
    """
    n = int(round(limit / step + 1.0))
    if n > 0 and (n - 1) * step > limit + 3.0 * _EPS * abs(limit):
        n -= 1
    out = np.arange(max(n, 0)) * step
    if out.size:
        out[0] = 0.0        # the base, not 0*step, which is NaN for step=Inf
    if out.size > 1 and out[-1] > limit:
        out[-1] = limit
    return out


def get_StepR(ir, param, cb_step, ZT):
    """Compute TDR step response from impulse response (MATLAB lines 6876-6902).

    cb_step=True: shaped edge drive; cb_step=False: cumulative sum (ideal step).
    Returns SimpleNamespace with fields: ZSR (TDR response in Ω), pulse (step signal).
    """
    # No dtype=float: MATLAB's filter()/cumsum() carry a complex input
    # through, and the cast silently DISCARDED the imaginary part (a
    # ComplexWarning only).  COM Octave, cb_step=0 on a complex ir, returns
    # cumsum of the complex samples; the cast made ZSR wrong by O(1).
    ir = np.asarray(ir).ravel()
    if ir.dtype.kind not in 'fc':
        ir = ir.astype(float)
    M = int(param.samples_per_ui)

    if cb_step:
        dt = 1.0 / float(param.fb) / float(param.samples_per_ui)
        edge_time = float(param.TR_TDR) * 1e-9
        fedge = 1.0 / edge_time
        # MATLAB `tedge=0:dt:edge_time*2`, via the shared spelling. See
        # _get_StepR__colon below for why neither arange-with-limit nor floor is right.
        tedge = _get_StepR__colon(dt, edge_time * 2)
        edge = 2 * np.cos(2 * np.pi * tedge * fedge / 16 - np.pi / 4) ** 2 - 1
        drive_pulse = np.concatenate([edge, np.ones(M)])
        pulse = lfilter(drive_pulse, [1.0], ir)
    else:
        pulse = np.cumsum(ir)

    TDR_response = (1 + pulse) / (1 - pulse) * float(ZT) * 2
    return SimpleNamespace(ZSR=TDR_response, pulse=pulse)



# --- get_TDR (MATLAB lines 6904–7220) ---

# ============================================================
# MATLAB→Python translation notes for get_TDR
# MATLAB lines: 6904–7220
# ============================================================
# Parameter `np` renamed to `nport` (avoids shadowing numpy).
# S.Parameters shape convention: (NumFreq, NumPorts, NumPorts) in Python
#   (transposed from MATLAB's (NumPorts, NumPorts, NumFreq)).
#   Access: S.Parameters[i_freq, row, col]  ← matches MATLAB S.Parameters(row,col,i)+1
# RL_sel: 0-based in Python (MATLAB 1-based → subtract 1 at call site).
#   Internally: other_port = 1 - rl_sel (for 2-port; only ports 0 and 1).
# MATLAB find(t>=x,1,'first') → np.searchsorted(t, x) → 0-based index
# MATLAB filter(ones(1,M),1,x) → lfilter(ones(M),1,x)
# MATLAB 1-based loop `for ki=1:M` → Python `for ki in range(M)` with 0-based slice
# Tukey_Window stub: returns ones (matching MATLAB override in this function)
# TDR_RL formula: direct translation of long algebraic expression
# PTDR phase search: 0-based ki, PTDR.pulse[ki::M]
# iscolumn checks: replaced by .ravel() for all frequency-domain arrays
# ============================================================



# ---------------------------------------------------------------------------
# Callee stubs
# ---------------------------------------------------------------------------

def _get_TDR__Bessel_Thomson_Filter(param, faxis, enable):
    if not enable:
        return np.ones(len(faxis))
    f0 = param.fb_BT_cutoff * param.fb
    s = 1j * np.asarray(faxis) / (f0 + 1e-300)
    b = [105, 105, 45, 10, 1]
    return np.abs(b[0] / np.polyval(b, s))


def _get_TDR__Butterworth_Filter(param, faxis, enable):
    if not enable:
        return np.ones(len(faxis))
    f0 = param.fb / 2.0
    return 1.0 / np.sqrt(1.0 + (np.asarray(faxis) / (f0 + 1e-300)) ** 8)


def _get_TDR__Tukey_Window(faxis, param):
    """Stub: ones (MATLAB overrides to ones in get_TDR)."""
    return np.ones(len(faxis))


def _get_TDR__s21_to_impulse_DC(sdd21, faxis, sample_dt, OP, param):
    N = len(sdd21)
    S = np.zeros(2 * N - 2, dtype=complex)
    S[:N] = sdd21
    S[N:] = np.conj(sdd21[-2:0:-1])
    ir = np.real(np.fft.ifft(S))
    t = np.arange(len(ir)) * sample_dt
    return ir, t, 0.0, 0.0


def _get_TDR__get_StepR(ir, param, cb_step, ZT):
    """Stub: step response via cumsum; ZSR = (1 + cumsum(ir)) * ZT."""
    step = np.cumsum(ir)
    ZSR = (1.0 + step) * ZT
    return SimpleNamespace(ZSR=ZSR, step=step)


def _get_TDR__get_PulseR(ir, param, cb_step, ZT):
    """Stub: pulse response = ir (delta = derivative of step)."""
    M = int(param.samples_per_ui)
    pulse = lfilter(np.ones(M), 1, ir)
    return SimpleNamespace(pulse=pulse, pulse_orig=pulse.copy())


def _get_TDR__get_pdf_from_sampled_signal(samples, levels, bin_size, flag):
    rms = float(np.sqrt(np.mean(np.asarray(samples, dtype=float)**2))) + 1e-30
    n = max(32, int(8 * rms / (bin_size + 1e-30)))
    x = np.linspace(-4 * rms, 4 * rms, n)
    dx = x[1] - x[0] if n > 1 else 1.0
    y = np.exp(-0.5 * (x / rms)**2) / (rms * np.sqrt(2 * np.pi)) * dx
    y = y / (y.sum() + 1e-300)
    return SimpleNamespace(x=x, y=y)


# ---------------------------------------------------------------------------
# TDR_RL: 4-port reflection normalization formula
# ---------------------------------------------------------------------------

def _get_TDR__TDR_RL(Zin, Zout, s11, s12, s21, s22):
    """Re-normalize reflection coefficient from S-parameters (eq from MATLAB)."""
    num = (Zin**2 * s11 + Zin**2 * s22 + Zout**2 * s11 + Zout**2 * s22 +
           Zin**2 - Zout**2 +
           Zin * Zout * s11 * 2.0 - Zin * Zout * s22 * 2.0 +
           Zin**2 * s11 * s22 - Zin**2 * s12 * s21 -
           Zout**2 * s11 * s22 + Zout**2 * s12 * s21)
    den = (Zin * Zout * 2.0 + Zin**2 * s11 + Zin**2 * s22 -
           Zout**2 * s11 - Zout**2 * s22 + Zin**2 + Zout**2 +
           Zin**2 * s11 * s22 - Zin**2 * s12 * s21 +
           Zout**2 * s11 * s22 - Zout**2 * s12 * s21 -
           Zin * Zout * s11 * s22 * 2.0 + Zin * Zout * s12 * s21 * 2.0)
    return num / (den + 1e-300)


# ---------------------------------------------------------------------------
# Main function
# ---------------------------------------------------------------------------

def get_TDR(S, OP, param, ZT, nport,
            _Bessel_Thomson_Filter_fn=None,
            _Butterworth_Filter_fn=None,
            _Tukey_Window_fn=None,
            _s21_to_impulse_DC_fn=None,
            _get_StepR_fn=None,
            _get_PulseR_fn=None,
            _get_pdf_fn=None):
    """Compute TDR (time-domain reflectometry) metrics.

    MATLAB lines 6904–7220.

    S: SimpleNamespace with:
        Frequencies: 1D float array (Hz)
        Parameters: array of shape (Nf, NumPorts, NumPorts) or (NumPorts, NumPorts, Nf)
                    Access convention: S.Parameters[freq_idx, row_0based, col_0based]
        Impedance: reference impedance (Ohms)
        NumPorts: number of ports
    OP: SimpleNamespace — flags: TDR, PTDR, DISPLAY_WINDOW, TDR_Butterworth, BinSize,
        TDR_duration, N (number of UI for maxtime), RL_norm_test, T_k, cb_Guassian, etc.
    param: SimpleNamespace — samples_per_ui, sample_dt, TR_TDR, tfx (1D, indexed by nport),
           FLAG.S2P, RL_sel (0-based), ui, ndfe, N_bx, beta_x, Grr, rho_x,
           levels, specBER, Tukey_Window, fb, fb_BT_cutoff
    ZT: target impedance (Ohms), typically 50 * sqrt(2) for differential
    nport: 0-based port index (MATLAB uses 1-based `np`)

    Dependency injection via optional *_fn params.
    Returns TDR_results SimpleNamespace.
    """
    bt_fn = _Bessel_Thomson_Filter_fn or _get_TDR__Bessel_Thomson_Filter
    bw_fn = _Butterworth_Filter_fn or _get_TDR__Butterworth_Filter
    tw_fn = _Tukey_Window_fn or _get_TDR__Tukey_Window
    s21_fn = _s21_to_impulse_DC_fn or _get_TDR__s21_to_impulse_DC
    step_fn = _get_StepR_fn or _get_TDR__get_StepR
    pulse_fn = _get_PulseR_fn or _get_TDR__get_PulseR
    pdf_fn = _get_pdf_fn or _get_TDR__get_pdf_from_sampled_signal

    TDR_results = SimpleNamespace()

    f = np.asarray(S.Frequencies, dtype=float).ravel()
    TDR_results.f = f
    f9 = f / 1e9

    # ---- RL computation ----
    rl_sel = int(param.RL_sel)  # 0-based
    Zref = float(S.Impedance)
    Nf = len(f)

    RL = np.zeros(Nf, dtype=complex)
    if int(param.FLAG.S2P) == 0:
        # 4-port S-params; S.Parameters shape (Nf, NumPorts, NumPorts)
        # RL_sel=0 → other_port=1; RL_sel=1 → other_port=0
        other_port = 1 - rl_sel
        Params = np.asarray(S.Parameters)
        is_4port = (S.NumPorts > 1)
        for i in range(Nf):
            s11 = complex(Params[i, rl_sel, rl_sel])
            if is_4port:
                s12 = complex(Params[i, rl_sel, other_port])
                s21 = complex(Params[i, other_port, rl_sel])
                s22 = complex(Params[i, other_port, other_port])
            else:
                s12 = 1.0
                s21 = 1.0
                s22 = complex(Params[i, rl_sel, rl_sel])
            RL[i] = _get_TDR__TDR_RL(Zref, 2 * ZT, s11, s12, s21, s22)
    else:
        # 2-port / s2p mode
        rho = (2 * ZT - Zref) / (2 * ZT + Zref)
        Params = np.asarray(S.Parameters)
        interim = np.sqrt(max(0.0, 1 - abs(rho)**2)) * (1 - rho) / (abs(1 - rho) + 1e-300)
        for i in range(Nf):
            s11_i = complex(Params[i, rl_sel, rl_sel])
            # fix B06-D9 (MATLAB rev 4p15p0 lines 7080-7081): MATLAB uses left-division
            # interim \ (s11-rho) = (s11-rho)/interim (interim then cancels), giving
            # RL = (s11-rho)/(1-rho*s11). Python previously used right-division of interim.
            RL[i] = (s11_i - rho) / interim / (1 - rho * s11_i + 1e-300) * interim

    RL = RL.ravel()

    # ---- Duration and delay ----
    TDR_duration = float(getattr(OP, 'TDR_duration', 5))
    if not hasattr(OP, 'DISPLAY_WINDOW'):
        OP.DISPLAY_WINDOW = 1
    TDR_results.delay = 500e-12  # seconds

    tr = float(param.TR_TDR)  # nanoseconds (transition time)
    tfx = float(np.atleast_1d(param.tfx)[nport])

    try:
        N_op = int(OP.N)
        maxtime = N_op * float(param.ui)
    except Exception:
        maxtime = 2e-9

    if int(getattr(OP, 'N', 1)) == 0 and S.NumPorts > 1:
        # Use get_RAW_FIR to estimate maxtime — stubbed: use default
        maxtime = 2e-9

    # ---- Transmitter filter with delay and Gaussian edge ----
    # MATLAB L7040: exp(-(1j)*2*pi*f9*TDR_results.delay/1e-9).  `*` and `/` are
    # equal precedence and left-associative, so the 1e-9 division happens LAST,
    # after the multiply by delay.  Pre-computing delay/1e-9 = 0.5 and
    # multiplying reorders the rounding: at f9=2.5 the reference gives
    # 1.1943401194869635e-15-1j and the pre-divided form 3.0616169978683831e-16-1j.
    # That is ~4e-15 relative on tx_filter and it propagates into the impulse.
    H_t = (np.exp(-2 * (np.pi * f9 * tr / 1.6832)**2) *
           np.exp(-1j * 2 * np.pi * f9 * TDR_results.delay / 1e-9) *
           np.exp(-1j * 2 * np.pi * f9 * tr * 3))

    Use_gaussian = bool(getattr(OP, 'cb_Guassian', True))
    if Use_gaussian:
        RLf = RL.ravel() * H_t.ravel()
    else:
        RLf = RL.ravel() * np.exp(-1j * 2 * np.pi * f9 * TDR_results.delay / 1e-9)

    # ---- Receiver filters (BT disabled, BW optional, Tukey optional) ----
    OP.TDR_Bessel_Thomson = 0
    H_bt = bt_fn(param, f, 0)  # disabled

    if hasattr(OP, 'TDR_Butterworth'):
        H_bw = bw_fn(param, f, OP.TDR_Butterworth)
    else:
        H_bw = np.ones(len(f))

    if float(getattr(param, 'Tukey_Window', 0)) != 0:
        H_tw = tw_fn(f, param)
    else:
        H_tw = np.ones(len(f))

    # Ensure row-like 1D
    H_bt = H_bt.ravel()
    H_bw = H_bw.ravel()
    H_tw = H_tw.ravel()
    RLf = RLf.ravel()

    TDR_results.Rx_filter = H_bt * H_bw * H_tw
    RLf = RLf * TDR_results.Rx_filter
    TDR_results.tx_filter = H_t

    # 4p16p0 L7460-7474: bail out on a channel with essentially no reflection.
    # "some test fixtures have almost zero CM and will cause TD conversion to
    # fail" -- 4p15p0 ran the conversion regardless. Returns a degenerate result
    # with ERL = inf (infinitely good return loss) and ERLRMS = -300 dB.
    if (str(getattr(param, 'matlab_version', '4p15p0')) == '4p16p0'
            and float(np.mean(np.abs(RL))) < 1e-6):
        dt = float(param.sample_dt)
        M = int(param.samples_per_ui)
        TDR_results.delay = 0
        TDR_results.tdr = np.ones(1000)
        # MATLAB 0:dt:999*dt is inclusive of both ends -> exactly 1000 samples.
        TDR_results.t = np.arange(1000) * dt
        TDR_results.x = 0
        TDR_results.y = 0
        TDR_results.avgZport = 0
        TDR_results.RL = np.zeros(1000)
        TDR_results.ptdr_RL = np.zeros(1000)
        # 0:dt*M:999*dt -- step dt*M, last value <= 999*dt, so floor(999/M)+1
        # samples (32 when M = 32), NOT 1000.
        TDR_results.WC_ptdr_samples_t = np.arange(0, 999 * dt + 1e-18, dt * M)
        TDR_results.WC_ptdr_samples = np.zeros(len(TDR_results.WC_ptdr_samples_t))
        TDR_results.ERL = np.inf
        TDR_results.ERLRMS = -300
        return TDR_results

    # ---- Impulse response ----
    IR, t, causality_dB, truncation_dB = s21_fn(RLf, f, param.sample_dt, OP, param)

    # ---- Time windowing ----
    t = t - TDR_results.delay
    # MATLAB L7098-7101:  tend = find(t>=maxtime+tfx,1);  IR = IR(1:tend)
    # The MATLAB 1-based index IS the Python exclusive bound, so the sample AT
    # the threshold is KEPT.  Slicing with the 0-based index instead dropped it,
    # making every windowed array (tdr, t, ptdr_RL, WC_ptdr_samples) one sample
    # short and shifting avgZport and ERLRMS with it.
    tend_arr = np.where(t >= maxtime + tfx)[0]
    tend = int(tend_arr[0]) + 1 if len(tend_arr) > 0 else len(t)
    IR = IR[:tend]
    t = t[:tend]

    tstart_arr = np.where(t >= tr * 1e-9)[0]
    tstart = int(tstart_arr[0]) if len(tstart_arr) > 0 else 0
    # MATLAB `tstart >= tend` compares two 1-based indices; tstart is 0-based here
    # and tend is the exclusive bound (== the MATLAB 1-based tend after the cut).
    if tstart + 1 >= tend:
        tend = len(t)
        tstart = 0

    cb_step = int(getattr(OP, 'cb_step', 0))
    ch_step = step_fn(IR[tstart:tend], param, cb_step, ZT)
    TDR_results.tdr = ch_step.ZSR
    TDR_results.t = t[tstart:tend]

    PTDR = pulse_fn(IR[tstart:tend], param, cb_step, ZT)
    PTDR.pulse_orig = PTDR.pulse.copy()

    # ---- Average impedance (OP.TDR or OP.PTDR path) ----
    if getattr(OP, 'TDR', False) or getattr(OP, 'PTDR', False):
        try:
            # MATLAB (L7184-7187):
            #   tfstart = find(t >= 3*tr*1e-9, 1);        % index into the FULL t
            #   x = TDR_results.t(tfstart:end);           % applied to the WINDOWED arrays
            # The index is derived from the full, delay-shifted time vector but used to
            # slice t(tstart:tend), so the weighted average effectively begins tstart
            # samples later than 3*tr. Searching the windowed vector instead (as Python
            # did) starts at a different point and biases avgZport -> Z11est/Z22est by a
            # constant ~1.4% independent of package case. Reproduce MATLAB exactly.
            #
            # No clamp: when tfstart runs past the windowed vector MATLAB's slice is
            # EMPTY, x(1) then errors and the catch sets avgZport = 0. Clamping to the
            # last sample instead returned that one sample's impedance.
            tfstart_arr = np.where(t >= 3 * tr * 1e-9)[0]
            # find(...) empty -> MATLAB `t([]:end)` is also empty, same path.
            tfstart = (int(tfstart_arr[0]) if len(tfstart_arr) > 0
                       else len(TDR_results.t))
            T_k = float(getattr(OP, 'T_k', 1e-9))
            x = TDR_results.t[tfstart:]
            y = TDR_results.tdr[tfstart:]
            # MATLAB L7185-7186 assigns x/y BEFORE the average, and with the tdr and t
            # vectors SWAPPED relative to the local x/y it just built.
            TDR_results.x = np.asarray(TDR_results.tdr).ravel()
            TDR_results.y = np.asarray(TDR_results.t).ravel()
            w = np.exp(-(x - x[0]) / (T_k + 1e-300))
            TDR_results.avgZport = float(np.mean(y * w) / (np.mean(w) + 1e-300))
        except Exception:
            TDR_results.avgZport = 0.0
        TDR_results.RL = RL

    # ---- PTDR: ERL computation ----
    if getattr(OP, 'PTDR', False):
        L = int(param.levels)
        BinSize = float(getattr(OP, 'BinSize', 1e-3))
        N_bx = int(getattr(param, 'N_bx', int(param.ndfe)))
        beta_x = float(getattr(param, 'beta_x', 0.0))
        Grr_mode = int(getattr(param, 'Grr', 1))
        rho_x = float(getattr(param, 'rho_x', 0.0))
        specBER = float(getattr(param, 'specBER', 1e-4))
        ui = float(param.ui)
        M = int(param.samples_per_ui)
        t_ptdr = TDR_results.t

        # Find ntx (start of gate, accounting for Gaussian delay)
        ntx_arr = np.where(t_ptdr >= tfx + 3 * tr * 1e-9)[0]
        ntx = int(ntx_arr[0]) if len(ntx_arr) > 0 else 0

        # Find ndfex (end of DFE gate)
        ndfex_arr = np.where(t_ptdr > (N_bx + 1) * ui + tfx + 3 * tr * 1e-9)[0]
        ndfex = int(ndfex_arr[0]) if len(ndfex_arr) > 0 else len(t_ptdr)
        tk = ui * (N_bx + 1) + tfx + 3 * tr * 1e-9

        # Build fctrx gain array.
        # MATLAB (L7230-7243):
        #   switch param.Grr
        #     case 0: fctrx(1:length(PTDR.pulse_orig)) = (1+rho_x)*rho_x;
        #     case 1: fctrx(1:length(PTDR.pulse_orig)) = 1;
        #     case 2: fctrx(1:length(PTDR.pulse_orig)) = 1;
        #   end
        #   fctrx(1:ntx) = 0;              % only the LEAD-IN is zeroed
        #   for ii = ntx:ndfex ...         % INCLUSIVE of ndfex
        #
        # fctrx is pre-filled across the WHOLE array, so beyond the DFE gate
        # (ii > ndfex) it retains that fill value — it is NOT zero. Allocating
        # np.zeros here discarded all reflection energy past the gate, which
        # understates the reflection and overstates ERL (23.1 vs 16.2 dB).
        fill = (1.0 + rho_x) * rho_x if Grr_mode == 0 else 1.0
        fctrx = np.full(len(PTDR.pulse), fill, dtype=float)
        fctrx[:ntx] = 0.0
        for ii in range(ntx, min(ndfex + 1, len(fctrx))):
            x_ii = (t_ptdr[ii] - tfx - 3 * tr * 1e-9) / (ui + 1e-300)
            if N_bx > 0 and beta_x != 0:
                Gloss_ii = 10.0 ** (beta_x * (t_ptdr[ii] - tk) / 20)
            else:
                Gloss_ii = 1.0
            if Grr_mode in (0, 1):
                Grr_ii = ((1 + rho_x) * rho_x *
                          np.exp(-((x_ii - N_bx - 1)**2) / ((1 + N_bx)**2 + 1e-300)))
            else:  # mode 2
                Grr_ii = rho_x
            fctrx[ii] = Gloss_ii * Grr_ii

        PTDR.pulse = PTDR.pulse * fctrx
        FAST_NOISE_CONV = 0

        RL_norm_test = bool(getattr(OP, 'RL_norm_test', False))
        RL_equiv = -np.inf
        best_ki = 0
        best_erl = -np.inf
        best_pdf = None

        for ki in range(M):
            tps = PTDR.pulse[ki::M]
            if len(tps) == 0:
                continue
            if RL_norm_test:
                rl_fom = float(np.linalg.norm(tps))
            else:
                testpdf = pdf_fn(tps, L, BinSize * 10, FAST_NOISE_CONV)
                cdf_test = np.cumsum(testpdf.y)
                idx_ber = int(np.searchsorted(cdf_test, specBER))
                if idx_ber < len(testpdf.x):
                    rl_test = -testpdf.x[idx_ber]
                else:
                    rl_test = 0.0
                rl_fom = rl_test

            if rl_fom > RL_equiv:
                RL_equiv = rl_fom
                best_ki = ki
            # UPSTREAM DEFECT B06-D10 (com_ieee8023_4p14p0/4p15p0/4p16p0, and the
            # adaptive-local-search build, all identical): the reference's
            #     if ~OP.RL_norm_test
            #         best_erl=rl_test; best_pdf=testpdf; best_cdf=cdf_test;
            #     end
            # sits OUTSIDE the `rl_fom > RL_equiv` guard, so ERL is reported for
            # the LAST phase while WC_ptdr_samples still come from best_ki.
            # Reproduced deliberately: COM Octave on a case whose worst phase is
            # not the last gives ERL = 35.391021572434525 dB (last phase,
            # rl_test = 0.017) where picking best_ki gives 32.39577516576788 dB
            # (rl_test = 0.024). Not reached with the default ERL_FOM = 1, which
            # takes the post-loop recompute below.
            if not RL_norm_test:
                best_erl = rl_test
                best_pdf = testpdf

        if RL_norm_test:
            tps = PTDR.pulse[best_ki::M]
            testpdf = pdf_fn(tps, L, BinSize * 10, FAST_NOISE_CONV)
            cdf_test = np.cumsum(testpdf.y)
            idx_ber = int(np.searchsorted(cdf_test, specBER))
            if idx_ber < len(testpdf.x):
                best_erl = -testpdf.x[idx_ber]
            else:
                best_erl = 0.0

        # MATLAB `rms = @(x) norm(x)/sqrt(length(x))`, evaluated BEFORE the ki loop.
        ERLRMS = float(np.linalg.norm(PTDR.pulse) / np.sqrt(len(PTDR.pulse)))
        TDR_results.ptdr_RL = PTDR.pulse
        TDR_results.WC_ptdr_samples_t = t_ptdr[best_ki::M]
        TDR_results.WC_ptdr_samples = PTDR.pulse[best_ki::M]
        # MATLAB `db = @(x) 20*log10(abs(x))` — NO epsilon floor. At best_erl = 0
        # (the degenerate single-bin pdf) the reference reports ERL = +Inf; the
        # +1e-300 floor reported a plausible-looking 6000 dB instead.
        with np.errstate(divide='ignore'):
            TDR_results.ERL = -20.0 * np.log10(abs(best_erl))
            TDR_results.ERLRMS = -20.0 * np.log10(abs(ERLRMS))

    return TDR_results



