def _get_pdf__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _get_pdf__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _get_pdf__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)





# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.



def _get_pdf__mround(x):
    """MATLAB round(): half away from zero, where Python's round() is banker's.

    Not a theoretical concern here. `nui = round(len(residual_response)/M)` is a
    ratio of two INTEGERS, so it lands exactly on .5 whenever the response length
    is an odd multiple of M/2 -- a discrete quantity that really does hit the tie,
    not a continuous one where ties are measure-zero. When it does, MATLAB rounds
    up and Python rounds down to even, the vs matrix loses a row, and one ISI
    sample is dropped from the PDF: sgm_isi comes out LOW.

    Found on 4 of 208 reference case-instances (T1_R23 and T4_R10, both crosstalk
    conditions), where exactly one of ~98,000 round() calls in a run sits on the
    tie. docs/AUDIT_FINDINGS.md listed this site and dismissed it as "measure-zero
    for continuous data", which is true of continuous inputs and false of this one.
    """
    x = float(x)
    t = int(x)                      # int() truncates toward zero
    if abs(x - t) == 0.5:           # exact tie: MATLAB goes away from zero
        return t + (1 if x > 0 else -1)
    # Off a tie round() is exact, and unlike floor(x + 0.5) it does not
    # send 0.49999999999999994 to 1: that sum is exactly 1.0 in binary.
    return int(round(x))

def _get_pdf__get_pdf_from_sampled_signal(input_vector, L, BinSize):
    iv = np.asarray(input_vector, dtype=float).ravel()
    if len(iv) == 0:
        return _d_cpdf(BinSize, 0, 1)
    if _get_pdf__mmax(np.abs(iv)) > BinSize:
        iv = iv[np.abs(iv) > BinSize]
    else:
        return _d_cpdf(BinSize, 0, 1)
    iv[np.abs(iv) < BinSize] = 0.0
    b = np.sign(iv)
    # NOTE: MATLAB sort(x,'descend') is STABLE and this reverses each tied run
    # (COM Octave: sort(abs([0.2 -0.2 0.5 0.2 -0.5 0.1]),'descend') indexes
    # [3 5 1 2 4 6]; this gives [5 3 4 2 1 6]).  Left as is because the loop
    # below uses only abs(v), so a tied run is a run of identical factors and
    # the PDF is bit-identical either way -- verified over 4 tie-rich vectors.
    # The canonical get_pdf_from_sampled_signal has the same line.
    sort_idx = np.argsort(np.abs(iv), kind='stable')[::-1]
    iv = np.abs(iv[sort_idx]) * b[sort_idx]
    values = 2.0 * np.arange(L) / (L - 1) - 1.0
    prob = np.ones(L) / L
    pdf = _d_cpdf(BinSize, 0, 1)
    empty_pdf = pdf
    for v in iv:
        pdfn = _Init_PDF_Fast(empty_pdf, np.abs(v) * values, prob)
        pdf = _conv_fct(pdf, pdfn)
    return pdf


def get_pdf(chdata, delta_y, t_s, param, OP, ixphase=None):
    """Compute ISI PDF from equalised pulse response (MATLAB lines 7377-7472).

    t_s: 0-based Python cursor index.
    ixphase: pre-determined phase column (0-based), used for MMSE+RxFFE path.
    Returns pdf SimpleNamespace.
    """
    SBR = np.asarray(chdata.eq_pulse_response, dtype=float).ravel()
    ch_type = chdata.type
    M = int(param.samples_per_ui)
    residual_response = SBR.copy()

    if ch_type == 'THRU':
        ndfe = int(param.N_bmax) if param.Floating_DFE else int(param.ndfe)
        # No clipping: MATLAB refuses a postcursor past the end of the pulse
        # response rather than quietly using fewer taps, and numpy's fancy
        # indexing raises the same way.
        # COM Octave: SBR 1x60, t_s=41, ndfe=3 -> "error: SBR(65): out of
        #   bound 60 (dimensions are 1x60)".  The port silently used 2 taps.
        idx = t_s + M * np.arange(ndfe + 1)
        ideal_cancelled_cursors = SBR[idx]

        if param.dfe_delta != 0:
            cursor_val = residual_response[t_s]
            dq = abs(ideal_cancelled_cursors / (cursor_val * param.dfe_delta))
            ideal_cancelled_cursors_q = (np.floor(dq) * cursor_val * param.dfe_delta
                                         * np.sign(ideal_cancelled_cursors))
        else:
            ideal_cancelled_cursors_q = ideal_cancelled_cursors

        cursor = SBR[t_s]
        if param.Floating_DFE:
            bmax_v = cursor * np.concatenate([[1.0], np.asarray(param.use_bmax, dtype=float).ravel()])
            bmin_v = cursor * np.concatenate([[1.0], np.asarray(param.use_bmin, dtype=float).ravel()])
        else:
            bmax_v = cursor * np.concatenate([[1.0], np.asarray(param.bmax, dtype=float).ravel()])
            bmin_v = cursor * np.concatenate([[1.0], np.asarray(param.bmin, dtype=float).ravel()])

        n_iq = len(ideal_cancelled_cursors_q)
        effective_cancelled_cursors = _dfe_clipper(
            ideal_cancelled_cursors_q,
            bmax_v[:n_iq],
            bmin_v[:n_iq]
        )

        effective_cancellation_samples = np.repeat(effective_cancelled_cursors, M)

        start_cancel = t_s - M // 2
        end_cancel = t_s + (1 + ndfe) * M - M // 2  # exclusive end for Python slice
        # No trimming: MATLAB indexes residual_response(start_cancel:end_cancel)
        # and refuses either end of that range when it leaves the array, where a
        # python slice would silently shorten and cancel the wrong samples.
        # COM Octave: t_s=3 -> "error: residual_response(-1): subscripts must be
        #   either integers 1 to (2^63)-1 or logicals";
        #   rr=1x10; rr(5:12)=rr(5:12)-ones(1,8) -> "error: rr(12): out of
        #   bound 10 (dimensions are 1x10)".
        if start_cancel < 0:
            raise IndexError(
                'get_pdf: residual_response(%d) - the DFE cancellation window '
                'starts before the pulse response' % (start_cancel + 1))
        if end_cancel > len(residual_response):
            raise IndexError(
                'get_pdf: residual_response(%d): out of bound %d - the DFE '
                'cancellation window runs past the pulse response'
                % (end_cancel, len(residual_response)))
        residual_response[start_cancel:end_cancel] -= effective_cancellation_samples

    nui = _get_pdf__mround(len(residual_response) / M)

    # Build vs matrix: (nui-2) × M; MATLAB vs(i,:) = residual_response(M*(1:nui-2)+i) 1-based
    # Python (0-based): vs[:,i] = residual_response[M*np.arange(1, nui-1) + i]  (i=0..M-1)
    vs = np.zeros((nui - 2, M))
    for i in range(M):
        row_indices = M * np.arange(1, nui - 1) + i  # 0-based
        valid = row_indices[row_indices < len(residual_response)]
        vs[:len(valid), i] = residual_response[valid]

    # Determine phases.  MATLAB strcmp(OP.FFE_OPT_METHOD,'MMSE') is CASE
    # SENSITIVE (strcmpi is the insensitive one), so 'mmse' takes the phase-loop
    # path, not the MMSE one.
    # COM Octave: OP.FFE_OPT_METHOD='mmse', OP.RxFFE=1, type='NEXT' returns a
    #   407-bin pdf (the max-sigma phase); .upper() gave the 295-bin ixphase pdf.
    use_mmse = (str(OP.FFE_OPT_METHOD) == 'MMSE' and OP.RxFFE)
    if use_mmse:
        if ch_type == 'THRU':
            # MATLAB L7451-7452: THRU uses the CURSOR phase mod(t_s,M), NOT ixphase
            # (ixphase is only set for crosstalk channels; the THRU entry stays at its
            # init value 1, which is off-cursor and inflates the ISI PDF).
            t_s_matlab = t_s + 1  # 0-based -> 1-based
            phase_matlab = t_s_matlab % M
            ph_col = (M - 1) if phase_matlab == 0 else (phase_matlab - 1)
            pdf = _get_pdf__get_pdf_from_sampled_signal(vs[:, ph_col], int(param.levels), delta_y)
        else:
            # crosstalk: use the pre-determined ixphase (0-based column)
            ph_col = ixphase if ixphase is not None else 0
            pdf = _get_pdf__get_pdf_from_sampled_signal(vs[:, ph_col], int(param.levels), delta_y)
        return pdf

    # Non-MMSE: loop over phases, pick max sigma
    if ch_type == 'THRU':
        t_s_matlab = t_s + 1  # convert to 1-based
        phase_matlab = t_s_matlab % M
        if phase_matlab == 0:
            phases = [M - 1]  # MATLAB index M → 0-based M-1
        else:
            phases = [phase_matlab - 1]  # MATLAB phase_matlab (1-based col) → 0-based
    else:
        phases = list(range(M))

    mxV = np.zeros(M)
    pdf_samples = {}
    for k in phases:
        p = _get_pdf__get_pdf_from_sampled_signal(vs[:, k], int(param.levels), delta_y)
        pdf_samples[k] = p
        mxV[k] = float(np.sqrt(np.sum(p.x ** 2 * p.y)))

    # MATLAB sizes mxV from `phases`, which for THRU is a SCALAR, then writes
    # mxV(k) at the 1-based phase.  That write auto-grows mxV and leaves zeros
    # in 1..k-1, so when the phase's sigma is 0 max() picks index 1 -- a phase
    # pdf_samples never got, i.e. an unset struct whose every field is [].
    # COM Octave: THRU, t_s=40, M=8 (phase 8) with no residual at that phase
    #   returns numel(pdf.x)==0, numel(pdf.y)==0, pdf.BinSize==[].
    #   The port returned the delta pdf instead.
    if ch_type == 'THRU':
        k1 = phases[0] + 1                       # MATLAB's 1-based phase
        if k1 > 1 and mxV[phases[0]] == 0.0:
            return SimpleNamespace(BinSize=np.array([]), Min=np.array([]),
                                   y=np.array([]), x=np.array([]))
        return pdf_samples[phases[0]]

    best_k = phases[int(np.argmax([mxV[k] for k in phases]))]
    return pdf_samples[best_k]



# --- get_pdf_from_sampled_signal (MATLAB lines 7473–7519) ---

def _get_pdf_from_sampled_signal__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _get_pdf_from_sampled_signal__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _get_pdf_from_sampled_signal__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)





# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.


def get_pdf_from_sampled_signal(input_vector, L, BinSize, FAST_NOISE_CONV=0):
    """Create ISI PDF from sampled signal via successive delta convolutions (MATLAB lines 7473-7518).

    input_vector: ISI sample values
    L: number of PAM levels
    BinSize: PDF grid spacing
    FAST_NOISE_CONV: when set, the small (|tap|<0.001) residual taps are approximated as a
        single Gaussian (normal_dist) and convolved in once, instead of one delta-set
        convolution per tap.  It ends in a call to conv_fct_TEST, which is UNDEFINED in
        the reference, so the reference cannot complete this branch -- see below.
        Every call site in the reference hard-codes FAST_NOISE_CONV=0.
    """
    input_vector = np.asarray(input_vector, dtype=float).ravel()

    # MATLAB max([]) is [], and `if []` is false, so an empty input falls
    # straight through to the delta pdf.  COM Octave:
    # get_pdf_from_sampled_signal([],4,1e-3) -> pdf.Min 0, one bin, y=1.
    # np.max raised "zero-size array to reduction operation maximum".
    if input_vector.size and _get_pdf_from_sampled_signal__mmax(np.abs(input_vector)) > BinSize:
        input_vector = input_vector[np.abs(input_vector) > BinSize]
    else:
        return _d_cpdf(BinSize, 0, 1)

    input_vector[np.abs(input_vector) < BinSize] = 0.0
    b = np.sign(input_vector)
    sort_idx = np.argsort(np.abs(input_vector), kind='stable')[::-1]  # descending by |value|
    input_vector = np.abs(input_vector[sort_idx]) * b[sort_idx]

    # ---- FAST_NOISE_CONV: split off small residual taps as one Gaussian (MATLAB L7498-7502) ----
    res_pdf = None
    if FAST_NOISE_CONV:
        small = np.where(np.abs(input_vector) < 0.001)[0]
        if len(small) > 0:
            first_small = int(small[0])  # MATLAB find(...,1), 0-based here
            sig_res = float(np.linalg.norm(input_vector[first_small + 1:]))
            res_pdf = _normal_dist(sig_res, 5, BinSize)
            input_vector = input_vector[:first_small + 1]
        # (MATLAB has no such guard: with no small tap, find(...) is empty and
        # the two slices come out empty too.  Unobservable, because the branch
        # cannot return -- see the raise below.)

    # Equation 93A-39: values uniformly spaced in [-1, 1]
    values = 2.0 * np.arange(L) / (L - 1) - 1.0
    prob = np.ones(L) / L

    pdf = _d_cpdf(BinSize, 0, 1)
    empty_pdf = pdf
    for v in input_vector:
        pdfn = _Init_PDF_Fast(empty_pdf, np.abs(v) * values, prob)
        pdf = _conv_fct(pdf, pdfn)

    if FAST_NOISE_CONV:
        # MATLAB L7515-7517 calls conv_fct_TEST, which is defined NOWHERE in
        # the reference, so this branch always stops here.  COM Octave,
        # get_pdf_from_sampled_signal([0.03 0.02], 4, 1e-3, 1):
        #   "error: 'conv_fct_TEST' undefined near line 45".
        # Substituting conv_fct (the commented-out L7516) produced a pdf the
        # reference cannot produce, and so cannot be checked against.  The
        # early return above still runs first, exactly as in MATLAB: with
        # every tap below BinSize, or none at all, FAST_NOISE_CONV=1 returns
        # the delta pdf without error.
        raise NameError(
            "get_pdf_from_sampled_signal: 'conv_fct_TEST' undefined -- "
            'FAST_NOISE_CONV is not implemented in the COM reference')

    return pdf



# --- get_pdf_full (MATLAB lines 7520–7663) ---

# ============================================================
# MATLAB→Python translation notes for get_pdf_full
# MATLAB lines: 7520–7663
# ============================================================
# Same as get_pdf but first upsamples pulse response to param.samples_for_C2M.
# old_time = [0..N-1]/samples_per_ui; shifted so t_s is at 0.
# new_time: built so that time=0 is always present; step=1/samp_UI.
# SBR = interp1(old_time, pulse_orig, new_time) (np.interp).
# t_s = argmin(abs(new_time)) after resampling (0-based).
# THRU path: bmax_vec/bmin_vec scaled by residual_response[t_s] (cursor amplitude).
# Floating_DFE: use N_bmax postcursors; otherwise ndfe.
# kron(effective_cancelled_cursors, ones(samp_UI)) → np.repeat.
# effective_cancellation_samples = np.repeat(..., samp_UI) for each postcursor.
# start_cancel = t_s - half_UI + 1 + samp_UI (0-based: t_s - half_UI + samp_UI).
# uiv_start = start_cancel - samp_UI (0-based).
# residual_response[uiv_start:uiv_end+1] = 0.
# vs: reshape residual_response[samp_UI:samp_UI*(nui-1)] → (nui-2, samp_UI).
# phases (MATLAB 1-based): mod(t_s+1, samp_UI); if 0→samp_UI → in Python: (t_s+1)%samp_UI if 0→samp_UI.
# Actually in Python t_s is 0-based. MATLAB t_s (1-based). MATLAB phases = mod(t_s,samp_UI); if 0→samp_UI.
# Python: t_s_matlab = t_s+1; phases_matlab = t_s_matlab % samp_UI; if 0→samp_UI. Then 0-based: phases_matlab-1.
# shift_amount = half_UI - phases (MATLAB); circshift with that amount.
# h_j_full: (L, samp_UI) matrix where L = vs_raw.shape[0].
# ============================================================






# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.



def _get_pdf_full__mround(x):
    """MATLAB round(): half away from zero, where Python's round() is banker's.

    Not a theoretical concern here. `nui = round(len(residual_response)/M)` is a
    ratio of two INTEGERS, so it lands exactly on .5 whenever the response length
    is an odd multiple of M/2 -- a discrete quantity that really does hit the tie,
    not a continuous one where ties are measure-zero. When it does, MATLAB rounds
    up and Python rounds down to even, the vs matrix loses a row, and one ISI
    sample is dropped from the PDF: sgm_isi comes out LOW.

    Found on 4 of 208 reference case-instances (T1_R23 and T4_R10, both crosstalk
    conditions), where exactly one of ~98,000 round() calls in a run sits on the
    tie. docs/AUDIT_FINDINGS.md listed this site and dismissed it as "measure-zero
    for continuous data", which is true of continuous inputs and false of this one.
    """
    x = float(x)
    t = int(x)                      # int() truncates toward zero
    if abs(x - t) == 0.5:           # exact tie: MATLAB goes away from zero
        return t + (1 if x > 0 else -1)
    # Off a tie round() is exact, and unlike floor(x + 0.5) it does not
    # send 0.49999999999999994 to 1: that sum is exactly 1.0 in binary.
    return int(round(x))

_EPS = np.finfo(float).eps


def _get_pdf_full__colon(step, limit):
    """MATLAB `0:step:limit`, for a positive step.

    Verbatim from get_StepR/get_PulseR, where it was verified against COM
    Octave. A colon stops at or BEFORE the limit: `arange(0, limit+step, step)`
    is one element too long when limit/step is not an integer, and
    `floor(limit/step)+1` is one too short when the quotient lands a fraction
    of an eps below an integer.
    """
    n = int(round(limit / step + 1.0))
    if n > 0 and (n - 1) * step > limit + 3.0 * _EPS * abs(limit):
        n -= 1
    out = np.arange(max(n, 0)) * step
    if out.size:
        out[0] = 0.0
    if out.size > 1 and out[-1] > limit:
        out[-1] = limit
    return out


def _get_pdf_full__get_center_of_UI(samp_UI):
    M = int(samp_UI)
    return M // 2 + 1  # 1-based MATLAB half_UI


def _get_pdf_full__get_pdf_from_sampled_signal(input_vector, L, BinSize):
    iv = np.asarray(input_vector, dtype=float).ravel()
    if len(iv) == 0:
        return _d_cpdf(BinSize, 0.0, 1.0)
    mask = np.abs(iv) > BinSize
    if not np.any(mask):
        return _d_cpdf(BinSize, 0.0, 1.0)
    iv = iv[mask]
    iv[np.abs(iv) < BinSize] = 0.0
    b = np.sign(iv)
    sort_idx = np.argsort(np.abs(iv), kind='stable')[::-1]
    iv = np.abs(iv[sort_idx]) * b[sort_idx]
    values = 2.0 * np.arange(L) / (L - 1) - 1.0
    prob = np.ones(L) / L
    empty_pdf = _d_cpdf(BinSize, 0.0, 1.0)
    pdf = empty_pdf
    for v in iv:
        pdfn = _Init_PDF_Fast(empty_pdf, np.abs(v) * values, prob)
        pdf = _conv_fct(pdf, pdfn)
    return pdf


def get_pdf_full(chdata, delta_y, t_s, param, OP, pdf_range=None):
    """Upsampled-pulse PDF computation (MATLAB lines 7520-7663).

    Resamples chdata.eq_pulse_response to param.samples_for_C2M then calls
    get_pdf_from_sampled_signal on each phase.

    Returns (pdf_list, h_j_full, A_s_vec).
    pdf_list: list of SimpleNamespace per sample position (0-based indexed by samp_UI position).
    """
    t_s_orig = int(t_s)
    pulse_type = str(chdata.type)
    pulse_orig = np.asarray(chdata.eq_pulse_response, dtype=float).ravel()
    M_orig = int(param.samples_per_ui)
    samp_UI = int(param.samples_for_C2M)

    # Time axes (0-based)
    old_time = np.arange(len(pulse_orig)) / M_orig
    original_sample_time = old_time[t_s_orig]
    old_time = old_time - original_sample_time

    # New time axis forcing 0 in axis. ML 7990-7992:
    #     new_timea=[0:-1/samp_UI:min(old_time)];
    #     new_timeb=[0:1/samp_UI:max(old_time)];
    #     new_time =[fliplr(new_timea) new_timeb(2:end)];
    #
    # D12. The port used arange(..., floor(x*samp_UI) + 2), which is one point
    # LONGER than the colon on each side, and that extra point lies OUTSIDE
    # [min(old_time), max(old_time)]: a MATLAB colon stops at or before its
    # limit and never steps past it. Two extra samples shift the cursor
    # t_s = argmin(|new_time|) by one, which moves the sampling phase and the
    # centring circshift, and the port disagreed with the MATLAB-faithful
    # oracle in 1 of 32 phase columns.
    #
    # _get_pdf_full__colon is the helper verified against COM Octave for get_StepR and
    # get_PulseR, which are the same reference construct. It takes a POSITIVE
    # step, and the two colons here are symmetric about zero, so the negative
    # side is built on the magnitude and negated.
    new_timea = -_get_pdf_full__colon(1.0 / samp_UI, abs(min(old_time)))[::-1]
    new_timeb = _get_pdf_full__colon(1.0 / samp_UI, max(old_time))
    new_time = np.concatenate([new_timea, new_timeb[1:]])

    SBR = np.interp(new_time, old_time, pulse_orig)

    # New cursor: argmin(abs(new_time))
    t_s = int(np.argmin(np.abs(new_time)))

    residual_response = SBR.copy()

    half_UI = _get_pdf_full__get_center_of_UI(samp_UI)  # 1-based MATLAB

    A_s_vec = None

    if pulse_type == 'THRU':
        if not getattr(param, 'Floating_DFE', False):
            ndfe = int(param.ndfe)
            post_indices = t_s + samp_UI * np.arange(1, ndfe + 1)
            bmax_vec = residual_response[t_s] * np.asarray(param.bmax, dtype=float).ravel()[:ndfe]
            bmin_vec = residual_response[t_s] * np.asarray(param.bmin, dtype=float).ravel()[:ndfe]
        else:
            ndfe = int(param.N_bmax)
            post_indices = t_s + samp_UI * np.arange(1, ndfe + 1)
            bmax_vec = residual_response[t_s] * np.asarray(param.use_bmax, dtype=float).ravel()[:ndfe]
            bmin_vec = residual_response[t_s] * np.asarray(param.use_bmin, dtype=float).ravel()[:ndfe]

        # Clip to valid range
        valid_mask = (post_indices >= 0) & (post_indices < len(SBR))
        post_indices = post_indices[valid_mask].astype(int)
        bmax_vec = bmax_vec[:len(post_indices)]
        bmin_vec = bmin_vec[:len(post_indices)]

        ideal_cancelled_cursors = SBR[post_indices]

        dfe_delta = float(getattr(param, 'dfe_delta', 0))
        if dfe_delta != 0:
            cursor_amp = residual_response[t_s]
            ideal_cancelled_cursors_q = (
                np.floor(np.abs(ideal_cancelled_cursors / (cursor_amp * dfe_delta)))
                * cursor_amp * dfe_delta * np.sign(ideal_cancelled_cursors)
            )
        else:
            ideal_cancelled_cursors_q = ideal_cancelled_cursors

        effective_cancelled_cursors = _dfe_clipper(ideal_cancelled_cursors_q, bmax_vec, bmin_vec)
        effective_cancellation_samples = np.repeat(effective_cancelled_cursors, samp_UI)

        # MATLAB L8035: start_cancel = t_s - half_UI + 1 + samp_UI, with t_s
        # and half_UI both 1-based. Here t_s is the 0-based argmin of the
        # resampled time axis and half_UI is still MATLAB's 1-based centre,
        # so substituting t_s_ml = t_s + 1 and taking one off for 0-based
        # leaves exactly this expression. Subtracting a further 1 -- as this
        # did until 2026-09-22 -- put the cancellation window and A_s_vec one
        # sample early.
        start_cancel = t_s - half_UI + 1 + samp_UI
        n_cancel = len(post_indices) * samp_UI
        end_cancel = start_cancel + n_cancel  # exclusive

        if end_cancel <= len(residual_response):
            residual_response[start_cancel:end_cancel] -= effective_cancellation_samples[:n_cancel]

        uiv_start = start_cancel - samp_UI
        uiv_end = uiv_start + samp_UI  # exclusive
        uiv_end = min(uiv_end, len(residual_response))
        R_LM = float(param.R_LM)
        L_lvl = int(param.levels)
        A_s_vec = R_LM * SBR[uiv_start:uiv_end] / (L_lvl - 1)
        residual_response[uiv_start:uiv_end] = 0.0

    nui = _get_pdf_full__mround(len(residual_response) / samp_UI)
    block_start = samp_UI  # 1-based → 0-based: samp_UI (same as MATLAB index samp_UI+1 → 0-based samp_UI)
    block_end = samp_UI * (nui - 1)

    if block_end > len(residual_response) or block_start >= block_end:
        block_end = len(residual_response)
        n_rows = (block_end - block_start) // samp_UI
        block_end = block_start + n_rows * samp_UI
    n_rows = (block_end - block_start) // samp_UI

    vs = residual_response[block_start:block_end].reshape(n_rows, samp_UI)
    vs_raw = SBR[block_start:block_end].reshape(n_rows, samp_UI)

    L_r = vs_raw.shape[0]

    # Phases (1-based MATLAB convention)
    if pulse_type == 'THRU':
        t_s_matlab = t_s + 1
        phase_matlab = t_s_matlab % samp_UI
        if phase_matlab == 0:
            phase_matlab = samp_UI
        phases = [phase_matlab]  # 1-based, single phase
    else:
        phases = list(range(1, samp_UI + 1))

    # pdf_range: 1-based MATLAB indexing
    if pdf_range is None or len(pdf_range) == 0:
        pdf_range_set = set(range(1, samp_UI + 1))
    else:
        pdf_range_arr = np.asarray(pdf_range, dtype=int).ravel()
        pdf_range_set = set(range(int(min(pdf_range_arr)), int(max(pdf_range_arr)) + 1))

    shift_amount = half_UI - phases[0]  # only used for single phase (THRU)

    # circshift of vs by shift_amount along columns (axis=1)
    vs_shift = np.roll(vs, shift_amount, axis=1)

    h_j_full = np.zeros((L_r, samp_UI))
    pdf_list = [None] * samp_UI  # 0-based

    for k_matlab in range(1, samp_UI + 1):
        if k_matlab not in pdf_range_set:
            continue
        k0 = k_matlab - 1  # 0-based
        samples = vs_shift[:, k0]
        pdf_list[k0] = _get_pdf_full__get_pdf_from_sampled_signal(samples, int(param.levels), float(delta_y))

        # Compute h_j_full column
        hk_matlab = k_matlab - shift_amount  # 1-based
        if hk_matlab < 1:
            hk_matlab += samp_UI
        elif hk_matlab > samp_UI:
            hk_matlab -= samp_UI
        hk0 = hk_matlab - 1  # 0-based

        if hk_matlab == 1:
            # early UI is last column (index samp_UI-1=0-based)
            h_j_full[:L_r - 1, k0] = (vs_raw[1:, hk0 + 1] - vs_raw[:L_r - 1, samp_UI - 1]) / 2 * samp_UI
        elif hk_matlab == samp_UI:
            # late UI is first column (0-based: 0)
            h_j_full[:L_r - 1, k0] = (vs_raw[1:, 0] - vs_raw[:L_r - 1, hk0 - 1]) / 2 * samp_UI
        else:
            h_j_full[:L_r, k0] = (vs_raw[:, hk0 + 1] - vs_raw[:, hk0 - 1]) / 2 * samp_UI

    return pdf_list, h_j_full, A_s_vec



# --- get_s4p_files (MATLAB lines 7664–7795) ---

# ============================================================
# MATLAB→Python translation notes for get_s4p_files
# MATLAB lines: 7664–7795
# ============================================================
# Nearly identical to get_TD_files but:
#   - FEXT and NEXT channels use param.fb * param.f_v (NOT f_f / f_n)
#   - Optional PSDRXCAL noise channel appended at end if OP.PSDRXCAL
#   - GUI path (empty file_list): raises NotImplementedError
# ============================================================



def get_s4p_files(param, OP, num_fext, num_next, file_list):
    """Parse S4P file names into chdata structure (MATLAB lines 7664-7795).

    Returns (chdata, param).
    """
    if not file_list or len(file_list) == 0:
        raise NotImplementedError('get_s4p_files: GUI file selection not supported; provide file_list')

    chdata = []
    runtag = str(getattr(OP, 'RUNTAG', ''))

    def _parse(fpath_raw):
        # MATLAB stores fullfile(filepath, [basename fileext]), and fullfile
        # rewrites every separator to filesep.  COM Octave on Windows,
        # 'a/b\c/ch0.s4p' -> chdata(1).filename 'a\b\c\ch0.s4p', where this
        # kept the mixture the caller passed.
        fpath = str(fpath_raw).replace('\\', os.sep).replace('/', os.sep)
        filepath = os.path.dirname(fpath)
        base_ext = os.path.basename(fpath)
        basename, fileext = os.path.splitext(base_ext)
        dirname = os.path.basename(filepath) if filepath else ''
        return filepath, base_ext, basename, fileext, dirname

    def _fullfile(filepath, base_ext):
        return os.path.join(filepath, base_ext) if base_ext else filepath

    # THRU (index 0 in Python).  The thru has no lastfilepath fallback.
    filepath, base_ext, basename, fileext, dirname = _parse(file_list[0])
    ch = SimpleNamespace()
    ch.filename = _fullfile(filepath, base_ext)
    ch.ext = fileext
    ch.base = f'{runtag} {dirname}--{basename}'
    ch.type = 'THRU'
    ch.ftr = float(param.fb) * float(param.f_v)
    chdata.append(ch)
    param.base = ch.base
    nxi = 1

    def _aggressor(fi, kind, what):
        """One FEXT/NEXT/NOISE entry, carrying the directory forward.

        MATLAB keeps `filepath` alive across the loops and, for every channel
        after the thru, does `if isempty(filepath), filepath=lastfilepath; end`
        -- so a bare file name is opened from the PREVIOUS channel's
        directory, and that inheritance propagates down the list.  COM Octave,
        file_list {'d1/ch0.s4p','ch1.s4p','ch2.s4p'} with one FEXT and one
        NEXT: chdata(2).filename 'd1\\ch1.s4p' and chdata(3).filename
        'd1\\ch2.s4p', base 'run1 d1--ch1' and 'run1 d1--ch2'.  Parsing each
        entry independently opened 'ch1.s4p' from the working directory.
        """
        nonlocal filepath
        if fi >= len(file_list):
            raise ValueError(f'Not enough {what} files')
        fp, be, bn, ext, dn = _parse(file_list[fi])
        if not fp:
            fp = filepath                       # lastfilepath
            dn = os.path.basename(fp) if fp else ''
        filepath = fp
        ch_i = SimpleNamespace()
        ch_i.filename = _fullfile(fp, be)
        ch_i.ext = ext
        ch_i.base = f'{runtag} {dn}--{bn}'
        ch_i.ftr = float(param.fb) * float(param.f_v)
        ch_i.type = kind
        chdata.append(ch_i)

    for i in range(int(num_fext)):
        _aggressor(nxi + i, 'FEXT', 'FEXT')
    nxi += int(num_fext)

    for i in range(int(num_next)):
        _aggressor(nxi + i, 'NEXT', 'NEXT')
    nxi += int(num_next)

    # Optional noise channel for PSDRXCAL
    if getattr(OP, 'PSDRXCAL', False):
        _aggressor(nxi, 'NOISE', 'noise channel')

    return chdata, param



# --- get_sigma_eta_ACCM_noise (MATLAB lines 7796–7819) ---

def get_sigma_eta_ACCM_noise(chdata, param, H_sy, H_r, H_ctf):
    """Compute combined sigma_N from thermal and AC CM noise (Eq. 93A-35).

    chdata is a list/array of channel structs. H_sy, H_r, H_ctf are 1-D complex arrays.
    eta_0 is V^2/GHz; diff(faxis) is divided by 1e9 to match units.
    """
    H_sy = np.asarray(H_sy, dtype=complex).ravel()
    H_r = np.asarray(H_r, dtype=complex).ravel()
    H_ctf = np.asarray(H_ctf, dtype=complex).ravel()
    faxis = np.asarray(chdata[0].faxis, dtype=float).ravel()
    df = np.diff(faxis)

    # eta_0 is V^2/GHz, so the Hz steps are divided by 1e9 -- but AFTER the
    # product, as `.* diff(...)/1e9` does in MATLAB. Pre-dividing df is the
    # same algebra and not the same rounding.
    sigma_N1 = np.sqrt(
        float(param.eta_0)
        * np.sum(np.abs(H_sy[1:] * H_r[1:] * H_ctf[1:]) ** 2 * df / 1e9)
    )

    if np.sum(np.asarray(param.AC_CM_RMS)) != 0:
        sigma_ACCM = 0.0
        f_int = faxis[faxis <= float(param.ACCM_MAX_Freq)]
        nf = len(f_int)
        for i in range(len(chdata)):
            H_dc = np.abs(np.squeeze(np.asarray(chdata[i].sdc21, dtype=complex)))
            sigma_ACCM_acc = np.sqrt(
                2 * float(param.AC_CM_RMS_TX) ** 2
                * np.sum(
                    np.abs(H_sy[1:nf] * H_r[1:nf] * H_ctf[1:nf] * H_dc[1:nf]) ** 2
                    * np.diff(f_int)
                )
                / float(f_int[-1])
            )
            sigma_ACCM = float(np.linalg.norm([sigma_ACCM_acc, sigma_ACCM]))
        sigma_N = float(np.linalg.norm([sigma_N1, sigma_ACCM]))
    else:
        sigma_N = sigma_N1

    return sigma_N



# --- get_sigma_noise (MATLAB lines 7820–7843) ---

def get_sigma_noise(H_ctf, param, chdata, sigma_bn):
    """Compute sigma_NE and sigma_HP for RX calibration noise.

    chdata is a list/array of channel structs; chdata[1] (MATLAB chdata(2)) is used.
    All index arithmetic matches MATLAB find(...,1,'first') 1-based → Python argmax 0-based.
    """
    H_ctf = np.asarray(H_ctf, dtype=complex)
    faxis = np.asarray(chdata[1].faxis, dtype=float).ravel()
    H_r = 1.0 / np.polyval(
        [1, 2.613126, 3.414214, 2.613126, 1],
        1j * faxis / (float(param.f_r) * float(param.fb))
    )
    # MATLAB: idxfbby2 = find(faxis >= fb/2, 1)  [1-based]
    # Python: 0-based argmax → slice [:idxfbby2+1] matches MATLAB (1:idxfbby2)
    hit = faxis >= float(param.fb) / 2
    if not hit.any():
        # find() is empty, so MATLAB averages over H_np(1:[]) — an empty
        # slice — and mean([]) is NaN.  np.argmax answers 0 on an all-False
        # mask, which averaged over the *first* bin instead and returned a
        # finite number.
        # COM Octave 4p16p0: faxis = linspace(0,fb/4,51), fb=100e9 gives
        # sigma_NE = NaN and sigma_HP = NaN; Python returned 0 and 0.
        return float('nan'), float('nan')
    idx0 = int(np.argmax(hit))
    idxfbby2 = idx0 + 1  # exclusive upper bound for slices below

    if len(chdata) >= 2:
        Hnoise_channel = np.asarray(chdata[1].sdd21, dtype=complex).ravel()
    else:
        Hnoise_channel = np.ones(len(faxis), dtype=complex)

    f = faxis
    f_hp = float(param.f_hp)
    if f_hp != 0:
        H_hp = (-1j * f / f_hp) / (1 + 1j * f / f_hp)
    else:
        H_hp = np.ones(len(f), dtype=complex)

    H_np = Hnoise_channel * H_ctf * H_r * H_hp
    # MATLAB squares first and takes the modulus after: abs(H(1:n).^2).
    # |z^2| and |z|^2 agree mathematically but not bit-for-bit — 18 of the 26
    # in-band elements differ in the probe pinned in test_verify.py, where the
    # reference order makes the f_hp=0 result match COM Octave 4p16p0 exactly.
    sigma_NE = float(sigma_bn) * np.sqrt(np.mean(np.abs(H_np[:idxfbby2] ** 2)))
    sigma_HP = float(sigma_bn) * np.mean(np.abs(H_hp[:idxfbby2] ** 2))
    return sigma_NE, sigma_HP



# --- get_xtlk_noise (MATLAB lines 7844–7938) ---

# ============================================================
# MATLAB→Python translation notes for get_xtlk_noise
# MATLAB lines: 7844–7938
# ============================================================
# index_f2: first index where faxis > fb → 0-based Python.
# temp_angle = M*dt*pi*f; at f(1)==0 → set temp_angle[0]=1e-20 to avoid /0.
# PWF_tx: 1D row vector length = len(f).
# When max(upsampled_txffe) > 0: build PWF_tx via TXFFE weights × exp(-j2π(ii-icur)f/fb).
#   ii: 1-based in MATLAB → Python 0-based (icur: argmax → 0-based).
#   phase_memory[:,ii]: MATLAB 1-based column ii → Python column ii-1 (0-based).
#   But note: MATLAB ii=1..N, Python ii=0..N-1, so MATLAB ii → Python column index ii-1.
#   However: the exponent uses (ii-icur) and Python ii runs 0..N-1 while MATLAB runs 1..N,
#   so MATLAB (ii-icur) = Python (ii - icur) since both shift the same way.
# PWF_rx: same pattern with C coefficients; MATLAB ii=-RxFFE_cmx..RxFFE_cpx (1-based column in C).
#   C(ii+RxFFE_cmx+1): MATLAB 1-based → Python C[ii+RxFFE_cmx] (0-based).
#   phase_memory col: MATLAB (ii+RxFFE_cmx+1+len(upsampled_txffe)) → Python same-1 = 0-based.
# For each chdata[ii] (ii=1..end in MATLAB → ii=1..N-1 in Python, 0-based loop over ii=1..):
#   FEXT: MDFEXT power sum; NEXT: MDNEXT power sum.
# nargout==1 NEXT: sigma_XT = MDNEXT_ICN * sqrt(...).
# nargout==1 FEXT: sigma_XT = MDFEXT_ICN * sqrt(...).
# nargout==3: sigma_XT = norm([MDNEXT_ICN, MDFEXT_ICN]) * sqrt(...).
# Python API: nargout parameter (1 or 3) and type ('NEXT' or 'FEXT').
# ============================================================


def _get_xtlk_noise__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _get_xtlk_noise__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _get_xtlk_noise__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)


def _get_xtlk_noise__mmin(a):
    """MATLAB min(): the mirror of _get_xtlk_noise__mmax."""
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _get_xtlk_noise__mextreme_complex(a, 0)
    if a.dtype.kind != 'f':
        return np.min(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.min(a)
    return np.nanmin(a)



def get_xtlk_noise(upsampled_txffe, xtlk_type, param, chdata, phase_memory=None, C=None):
    """Compute crosstalk noise (MATLAB lines 7844-7938).

    Returns (sigma_XT,) for nargout=1, or (sigma_XT, sigma_FEXT, sigma_NEXT) for nargout=3.
    xtlk_type: 'NEXT', 'FEXT', or 'both' (both → 3-output mode).
    """
    upsampled_txffe = np.asarray(upsampled_txffe, dtype=float).ravel()
    f = np.asarray(chdata[0].faxis, dtype=float).ravel()

    # index_f2: MATLAB's find(f>fb,1,'first') is 1-based and the sums below
    # slice 1:index_f2 INCLUSIVELY, so the 1-based number is exactly the
    # exclusive Python end. Using the 0-based index instead dropped the top
    # bin of every ICN sum. COM Octave, faxis = fb + (0:19)*1e9 (so the very
    # first point is at fb and the crossing is the second):
    #     sigma_XT 4.9666884883754367e-05   the port answered 2.85e-19,
    # having summed one bin where the reference sums two, and the dropped bin
    # is the one that carries the energy.
    mask = f > param.fb
    index_f2 = int(np.argmax(mask)) + 1 if np.any(mask) else len(f)

    M = int(param.samples_per_ui)
    dt = float(param.sample_dt)

    temp_angle = M * dt * np.pi * f
    if f[0] == 0.0:
        temp_angle[0] = 1e-20

    # Build PWF_tx
    # pre_calc exists only if the TX branch below runs: MATLAB assigns it
    # inside `if max(upsampled_txffe) > 0` and the RX branch reads it anyway.
    pre_calc = None
    PWF_tx = np.ones(len(f), dtype=complex)
    if _get_xtlk_noise__mmax(upsampled_txffe) > 0:
        PWF_tx = np.zeros(len(f), dtype=complex)
        icur = int(np.argmax(upsampled_txffe))  # 0-based
        pre_calc = phase_memory is not None and len(phase_memory) > 0
        for ii in range(len(upsampled_txffe)):
            if upsampled_txffe[ii] == 0:
                continue
            if ii == icur:
                PWF_tx = PWF_tx + upsampled_txffe[ii]
            else:
                if pre_calc:
                    term = upsampled_txffe[ii] * phase_memory[:, ii]
                else:
                    term = upsampled_txffe[ii] * np.exp(-1j * 2 * np.pi * (ii - icur) * f / param.fb)
                PWF_tx = PWF_tx + term.ravel()

    # Build PWF_rx
    PWF_rx = np.ones(len(f), dtype=complex)
    if C is not None:
        C_arr = np.asarray(C, dtype=float).ravel()
        PWF_rx = np.zeros(len(f), dtype=complex)
        cmx = int(param.RxFFE_cmx)
        cpx = int(param.RxFFE_cpx)
        n_txffe = len(upsampled_txffe)
        for ii in range(-cmx, cpx + 1):
            c_idx = ii + cmx  # 0-based index into C
            # No length guard: MATLAB indexes C(ii+cmx+1) and stops if there
            # is no such element. COM Octave, C = [0.05 -0.2]:
            #     error: C(3): out of bound 2 (dimensions are 2x1)
            # and with C = []: error: C(1): out of bound 0. Skipping the
            # missing taps instead answered with a silently truncated RX FFE
            # (0.0025285640126039653 against an error, and 0 for an empty C).
            if C_arr[c_idx] == 0:
                continue
            if ii + 1 == 0:
                PWF_rx = PWF_rx + C_arr[c_idx]
            else:
                if pre_calc is None:
                    # COM Octave, all-zero upsampled_txffe with C supplied:
                    #     error: 'pre_calc' undefined near line 55, column 16
                    raise NameError(
                        "get_xtlk_noise: 'pre_calc' is undefined. MATLAB sets "
                        'it only when max(upsampled_txffe) > 0, so this call '
                        'errors in the reference.')
                if pre_calc:
                    pm_col = ii + cmx + n_txffe  # 0-based
                    term = C_arr[c_idx] * phase_memory[:, pm_col]
                else:
                    term = C_arr[c_idx] * np.exp(-1j * 2 * np.pi * (ii + 1) * f / param.fb)
                PWF_rx = PWF_rx + term.ravel()

    SINC = np.sin(temp_angle) / temp_angle  # sinc-like
    PWF_data = SINC ** 2

    MDFEXT = np.zeros(len(f))
    MDNEXT = np.zeros(len(f))
    MDFEXT_ICN = 0.0
    MDNEXT_ICN = 0.0

    for i in range(1, len(chdata)):
        ch = chdata[i]
        PWF_next_wt = np.abs(PWF_data * PWF_rx)            # no TX weighting for NEXT
        PWF_fext_wt = np.abs(PWF_data * PWF_rx * PWF_tx)   # TX weighting for FEXT
        sdd21ctf = np.asarray(ch.sdd21ctf, dtype=complex).ravel()
        delta_f = float(ch.delta_f)
        A = float(ch.A)
        f2 = float(param.f2)

        if ch.type == 'FEXT':
            MDFEXT = np.sqrt(np.abs(sdd21ctf) ** 2 + MDFEXT ** 2)  # power sum over channels
            MDFEXT_ICN = float(np.sqrt(
                2 * delta_f / f2 * np.sum(A ** 2 * PWF_fext_wt[:index_f2] * MDFEXT[:index_f2] ** 2)))
        elif ch.type == 'NEXT':
            MDNEXT = np.sqrt(np.abs(sdd21ctf) ** 2 + MDNEXT ** 2)  # power sum over channels
            MDNEXT_ICN = float(np.sqrt(
                2 * delta_f / f2 * np.sum(A ** 2 * PWF_next_wt[:index_f2] * MDNEXT[:index_f2] ** 2)))
        else:
            raise ValueError(
                f'get_xtlk_noise: unexpected channel type "{ch.type}"')

    scale = float(np.sqrt((param.levels ** 2 - 1) / (3 * (param.levels - 1) ** 2)))

    if xtlk_type.upper() == 'NEXT':
        return MDNEXT_ICN * scale
    elif xtlk_type.upper() == 'FEXT':
        return MDFEXT_ICN * scale
    else:
        sigma_XT = float(np.linalg.norm([MDNEXT_ICN, MDFEXT_ICN])) * scale
        sigma_NEXT = MDNEXT_ICN * scale
        sigma_FEXT = MDFEXT_ICN * scale
        return sigma_XT, sigma_FEXT, sigma_NEXT



# --- hrem (MATLAB lines 7939–7949) ---

# ============================================================
# MATLAB→Python translation notes for hrem
# MATLAB lines: 7939–7941
# ============================================================
# 1-based vs 0-based indexing: `index` is 1-based in MATLAB.
#   Python 0-based start = index - 1.
#   MATLAB h(1:index-1)         → Python h[0:index-1]
#   MATLAB h(index:index+N_bf-1)→ Python h[index-1:index-1+N_bf]
#   MATLAB h(index+N_bf:end)    → Python h[index-1+N_bf:]
# Operation on middle segment: x - sign(x)*min(bmaxg, |x|)
#   = soft-thresholding toward zero with threshold bmaxg.
#   If |x| <= bmaxg  → result is 0.
#   If |x| >  bmaxg  → magnitude reduced by bmaxg, sign preserved.
# Output shape: 1-D array, same length as h.
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def hrem(h, index, N_bf, bmaxg):
    """Remove up to bmaxg from N_bf tap values starting at 1-based index.

    Elements outside [index, index+N_bf-1] are unchanged.
    Middle segment: x → x - sign(x)*min(bmaxg, |x|)  (shrink toward zero).
    """
    h = np.asarray(h, dtype=float)
    # MATLAB L7941 builds the result with HORIZONTAL concatenation, so h must
    # be a row. A column makes the three pieces 1x1 / Nx1 / Mx1 and MATLAB
    # errors "horizontal dimensions mismatch". Verified against Octave.
    if h.ndim == 2 and h.shape[1] == 1 and h.shape[0] > 1:
        raise ValueError(
            'hrem: h must be a row vector. MATLAB concatenates the three '
            'pieces horizontally, so a %dx1 column errors there with '
            '"horizontal dimensions mismatch".' % h.shape[0])
    h = h.ravel()
    i = int(index) - 1                        # convert 1-based → 0-based

    # MATLAB indexes h(index:index+N_bf-1) directly, so running past the end
    # errors ("h(7): out of bound 5"). A numpy slice silently returns a SHORTER
    # segment, handing back a result of the wrong length instead.
    if i < 0 or i + int(N_bf) > h.size:
        raise IndexError(
            'hrem: h(%d:%d) is out of bounds for a length-%d h; MATLAB errors '
            'here rather than shortening the result.'
            % (int(index), int(index) + int(N_bf) - 1, h.size))

    seg = h[i:i + N_bf]
    shrunk = seg - np.sign(seg) * np.minimum(bmaxg, np.abs(seg))  # MATLAB line 7941

    out = np.concatenate([h[:i], shrunk, h[i + N_bf:]])
    return out



# --- interp_Sparam (MATLAB lines 7950–8165) ---

# ============================================================
# MATLAB→Python translation notes for interp_Sparam
# MATLAB lines: 7950–8165
# ============================================================
# Interpolates S-parameters Sin(fin) → Sout(fout).
# Steps:
#   1. Compute H_mag = abs(Sin); H_ph = unwrap(angle(Sin))
#   2. Anti-causal check: mean(diff(H_ph)) > 0 → warn/error
#   3. Magnitude interpolation based on opt_interp_Sparam_mag:
#      'linear_trend_to_DC': linear DC extrapolation + linear magnitude
#      'linear_trend_to_DC_log_trend_to_inf': same + log HF extrapolation
#      'trend_to_DC': log DC extrapolation (polyfit on log10 of mag)
#      'extrap_to_DC_or_zero': log interp, AC-coupled if |S(f1)| < -20 dB
#      'extrap_to_DC': log interp + hold HF constant
#      'old': linear interp
#   4. Phase interpolation based on opt_interp_Sparam_phase:
#      'old': shift phase so H_ph_i[0]=0
#      'zero_DC': set H_ph_i[0]=0
#      'interp_to_DC': add (0,0) to fin/fin and interpolate
#      'trend_and_shift_to_DC': correct LF group delay trend, shift to DC=0
#      'interp_and_shift_to_DC': same but no LF correction
#      'extrap_cubic_to_dc_linear_to_inf': pchip for LF, linear for HF
#   5. If ZERO_PAD: apply Tukey window + zero-pad above fin[-1]
#
# Returns Sout = H_mag_i * exp(1j*H_ph_i)
# ============================================================



def _interp_Sparam__interp_extrap(fout, fin, y):
    """interp1(fin, y, fout, 'linear', 'extrap') — linear interp that EXTRAPOLATES
    on the end-segment slope instead of clamping (np.interp clamps)."""
    fout = np.asarray(fout, dtype=float)
    fin = np.asarray(fin, dtype=float)
    y = np.asarray(y, dtype=float)
    out = np.interp(fout, fin, y)
    if len(fin) >= 2:
        lo = fout < fin[0]
        if np.any(lo):
            out[lo] = y[0] + (y[1] - y[0]) / (fin[1] - fin[0]) * (fout[lo] - fin[0])
        hi = fout > fin[-1]
        if np.any(hi):
            out[hi] = y[-1] + (y[-1] - y[-2]) / (fin[-1] - fin[-2]) * (fout[hi] - fin[-1])
    return out


def interp_Sparam(Sin, fin, fout, opt_interp_Sparam_mag, opt_interp_Sparam_phase, OP, param):
    """Interpolate S-parameters from fin to fout (MATLAB lines 7950-8165).

    Sin: complex 1D array, length = len(fin)
    fin: input frequency axis
    fout: output frequency axis
    opt_interp_Sparam_mag: magnitude interpolation method
    opt_interp_Sparam_phase: phase interpolation method
    OP: options namespace
    param: parameter namespace

    Returns Sout: complex 1D array, length = len(fout)
    """
    Sin = np.asarray(Sin, dtype=complex).ravel()
    fin = np.asarray(fin, dtype=float).ravel()
    fout = np.asarray(fout, dtype=float).ravel()

    eps = np.finfo(float).tiny        # tiny/realmin: log-domain guards below
    eps_mag = np.finfo(float).eps     # fix B02-D4 (MATLAB rev 4p15p0 line 8091): machine eps for |S| floor / HF threshold
    H_mag = np.abs(Sin)
    H_mag[H_mag < eps_mag] = eps_mag
    H_ph = np.unwrap(np.angle(Sin))

    # Anti-causal check
    if len(H_ph) > 1 and np.mean(np.diff(H_ph)) > 0:
        if getattr(OP, 'DEBUG', False):
            import warnings
            warnings.warn('Anti-causal response found. Finer frequency step is required for this channel')
        else:
            raise ValueError('Anti-causal response found. Finer frequency step is required for this channel')

    # ---- Magnitude interpolation ----
    mag_method = str(opt_interp_Sparam_mag)

    if mag_method in ('linear_trend_to_DC', 'linear_trend_to_DC_log_trend_to_inf'):
        fin_x = fin.copy()
        H_mag_x = H_mag.copy()
        if fin[0] > 0:
            n_pts = min(10, len(fin))
            p = np.polyfit(fin[:n_pts], H_mag[:n_pts], 1)
            dc_val = float(np.polyval(p, 0))
            fin_x = np.concatenate([[0.0], fin_x])
            H_mag_x = np.concatenate([[dc_val], H_mag_x])

        # UPSTREAM DEFECT (ML 8494 in the 'linear_trend_to_DC_log_trend_to_inf'
        # branch): hf_logtrend_val is assigned ONLY inside
        # `if hf_trend_val>H_mag(end)` or `elseif hf_trend_val<eps`. For a
        # normal HF trend, between eps and H_mag(end), neither runs and the
        # line that reads it references an undefined variable.
        #
        # COM Octave, on the 10 MHz to 40 GHz channel these tests use:
        #   error: 'hf_logtrend_val' undefined
        #       interp_Sparam at line 55 column 13
        # MATLAB raises the same "Undefined function or variable". So the
        # option is unusable on an ordinary channel in the reference itself.
        #
        # This used to be pre-initialised to H_mag[-1], which answered where
        # the reference stops. Copying the reference's bug is the ruling;
        # knowing it occurred is the point, so it raises with the reason named.
        hf_logtrend_val = None
        if fin[-1] < fout[-1]:
            # MATLAB: mid_freq_ind = round(length(fin)/2), used as a 1-BASED index
            # into fin. Python needs the 0-based equivalent, and MATLAB's round is
            # half-away-from-zero. For even len(fin) (48004 points in the 802.3dj
            # channels) floor division starts the HF trend fit one point late.
            _n = len(fin)
            mid = max(0, int(np.floor(_n / 2.0 + 0.5)) - 1)
            with np.errstate(all='ignore'):
                p2 = np.polyfit(fin[mid:], H_mag[mid:], 1)
            hf_val = float(np.polyval(p2, fout[-1]))
            if hf_val > H_mag[-1]:
                hf_val = H_mag[-1]
                hf_logtrend_val = H_mag[-1]
            elif hf_val < eps_mag:                  # fix B02-D4 (MATLAB line 8125): machine eps
                hf_val = eps_mag
                hf_logtrend_val = np.finfo(float).tiny
            fin_x = np.concatenate([fin_x, [fout[-1]]])
            H_mag_x = np.concatenate([H_mag_x, [hf_val]])

        H_mag_i = _interp_Sparam__interp_extrap(fout, fin_x, H_mag_x)

        if mag_method == 'linear_trend_to_DC_log_trend_to_inf' and fin[-1] < fout[-1]:
            if hf_logtrend_val is None:
                raise ValueError(
                    "interp_Sparam: opt_interp_Sparam_mag="
                    "'linear_trend_to_DC_log_trend_to_inf' cannot run on this "
                    'channel. The reference assigns hf_logtrend_val only when '
                    'the HF trend exceeds H_mag(end) or falls below eps; this '
                    'trend is between the two, so the reference reaches an '
                    'undefined variable. COM Octave: '
                    "\"error: 'hf_logtrend_val' undefined, interp_Sparam at "
                    'line 55\". Reported upstream; not a port failure.')
            logmag_x = np.concatenate([np.log(H_mag_x[:-1]), [np.log(max(hf_logtrend_val, eps))]])
            H_logmag_i = np.exp(_interp_Sparam__interp_extrap(fout, fin_x, logmag_x))
            idx = np.searchsorted(fout, fin[-1], side='right')
            H_mag_i[idx:] = H_logmag_i[idx:]

    elif mag_method == 'trend_to_DC':
        fin_x = fin.copy()
        H_mag_x = H_mag.copy()
        if fin[0] > 0:
            n_pts = min(10, len(fin))
            with np.errstate(divide='ignore', invalid='ignore'):
                p = np.polyfit(fin[:n_pts], np.log10(H_mag[:n_pts]), 1)
            dc_val = 10.0 ** float(np.polyval(p, 0))
            fin_x = np.concatenate([[0.0], fin_x])
            H_mag_x = np.concatenate([[dc_val], H_mag_x])
        if fin[-1] < fout[-1]:
            mid = max(0, len(fin) // 2)
            with np.errstate(divide='ignore', invalid='ignore'):
                p2 = np.polyfit(fin[mid:], np.log10(H_mag[mid:]), 1)
            hf_val = 10.0 ** float(np.polyval(p2, fout[-1]))
            if hf_val > H_mag[-1]:
                hf_val = H_mag[-1]
            fin_x = np.concatenate([fin_x, [fout[-1]]])
            H_mag_x = np.concatenate([H_mag_x, [hf_val]])
        with np.errstate(divide='ignore', invalid='ignore'):
            H_mag_i = 10.0 ** _interp_Sparam__interp_extrap(fout, fin_x, np.log10(H_mag_x))

    elif mag_method == 'extrap_to_DC_or_zero':
        # ML 88: 20*log10(H_mag(1)) with NO eps floor. errstate only
        # silences numpy; MATLAB compares against -Inf quietly.
        with np.errstate(divide='ignore'):
            _ac_coupled = fin[0] > 0 and 20 * np.log10(H_mag[0]) < -20
        if _ac_coupled:
            fin_x2 = np.concatenate([[0.0], fin])
            H_log_x = np.concatenate([[-100.0], np.log10(H_mag)])
            mask = fout <= fin[-1]
            H_mag_i = np.zeros(len(fout))
            H_mag_i[mask] = 10.0 ** _interp_Sparam__interp_extrap(fout[mask], fin_x2, H_log_x)
        else:
            mask = fout <= fin[-1]
            H_mag_i = np.zeros(len(fout))
            with np.errstate(divide='ignore', invalid='ignore'):
                H_mag_i[mask] = 10.0 ** _interp_Sparam__interp_extrap(fout[mask], fin, np.log10(H_mag))
        H_mag_i[fout > fin[-1]] = H_mag[-1]

    elif mag_method == 'extrap_to_DC':
        mask = fout <= fin[-1]
        H_mag_i = np.zeros(len(fout))
        with np.errstate(divide='ignore', invalid='ignore'):
            H_mag_i[mask] = 10.0 ** _interp_Sparam__interp_extrap(fout[mask], fin, np.log10(H_mag))
        H_mag_i[fout > fin[-1]] = H_mag[-1]

    elif mag_method == 'old':
        H_mag_i = _interp_Sparam__interp_extrap(fout, fin, H_mag)

    else:
        raise ValueError(f'interp_Sparam: invalid opt_interp_Sparam_mag = {mag_method!r}')

    # ---- Phase interpolation ----
    # fix B02-D5 (MATLAB rev 4p15p0 line 8185): interp1(fin,H_ph,fout,'linear','extrap')
    # extends the end-segment slope beyond [fin[0], fin[-1]] instead of clamping.
    H_ph_i = np.interp(fout, fin, H_ph)
    if len(fin) >= 2:
        lo = fout < fin[0]
        H_ph_i[lo] = H_ph[0] + (H_ph[1] - H_ph[0]) / (fin[1] - fin[0]) * (fout[lo] - fin[0])
        hi = fout > fin[-1]
        H_ph_i[hi] = H_ph[-1] + (H_ph[-1] - H_ph[-2]) / (fin[-1] - fin[-2]) * (fout[hi] - fin[-1])
    ph_method = str(opt_interp_Sparam_phase)

    if ph_method == 'old':
        H_ph_i = H_ph_i - H_ph_i[0]

    elif ph_method == 'zero_DC':
        H_ph_i[0] = 0.0

    elif ph_method == 'interp_to_DC':
        if fin[0] != 0:
            fin_ext = np.concatenate([[0.0], fin])
            ph_ext = np.concatenate([[0.0], H_ph])
            H_ph_i = _interp_Sparam__interp_extrap(fout, fin_ext, ph_ext)

    elif ph_method == 'interp_and_shift_to_DC':
        if fin[0] != 0:
            dc_trend = H_ph[0] - (H_ph[1] - H_ph[0]) / (fin[1] - fin[0]) * fin[0] if len(fin) > 1 else 0.0
            fin_ext = np.concatenate([[0.0], fin])
            ph_ext = np.concatenate([[0.0], H_ph - dc_trend])
            H_ph_i = _interp_Sparam__interp_extrap(fout, fin_ext, ph_ext)

    elif ph_method == 'trend_and_shift_to_DC':
        group_delay = -np.diff(H_ph) / np.diff(fin)
        n_lf = min(50, len(group_delay))
        lf_gd = group_delay[:n_lf]
        m = np.median(lf_gd)
        sigma = np.std(lf_gd, ddof=1)     # MATLAB/Octave std normalises by N-1; numpy defaults to N
        mask = np.abs(lf_gd - m) < sigma
        lf_trend = np.mean(lf_gd[mask]) if np.any(mask) else m

        H_ph_corr = H_ph.copy()
        for k in range(min(9, len(fin) - 1), -1, -1):
            H_ph_corr[k] = H_ph_corr[k + 1] + lf_trend * (fin[k + 1] - fin[k])

        if fin[0] != 0:
            dc_trend = H_ph_corr[0] + lf_trend * (fin[0] - 0)
            fin_x = np.concatenate([[0.0], fin])
            ph_x = np.concatenate([[0.0], H_ph_corr - dc_trend])
        else:
            fin_x = fin.copy()
            ph_x = H_ph_corr.copy()

        if fout[-1] > fin[-1]:
            all_gd = -np.diff(ph_x) / np.diff(fin_x)
            hf_phase_trend = ph_x[-1] - np.median(all_gd) * (fout[-1] - fin_x[-1])
            fin_x = np.concatenate([fin_x, [fout[-1]]])
            ph_x = np.concatenate([ph_x, [hf_phase_trend]])

        H_ph_i = _interp_Sparam__interp_extrap(fout, fin_x, ph_x)

    elif ph_method == 'extrap_cubic_to_dc_linear_to_inf':
        if fin[0] != 0:
            group_delay = -np.diff(H_ph) / np.diff(fin)
            n_lf = min(50, len(group_delay))
            lf_gd = group_delay[:n_lf]
            m = np.median(lf_gd)
            sigma = np.std(lf_gd, ddof=1)     # MATLAB/Octave std normalises by N-1; numpy defaults to N
            mask = np.abs(lf_gd - m) < sigma
            lf_trend = np.mean(lf_gd[mask]) if np.any(mask) else m

            H_ph_corr = H_ph.copy()
            for k in range(min(9, len(fin) - 1), -1, -1):
                H_ph_corr[k] = H_ph_corr[k + 1] + lf_trend * (fin[k + 1] - fin[k])

            # Linear extrapolation
            if fout[-1] > fin[-1]:
                # MATLAB: group_delay(end-50:end) -> 51 samples, not 50
                n_hf = min(51, len(group_delay))
                hf_gd = group_delay[-n_hf:]
                m_hf = np.median(hf_gd)
                sigma_hf = np.std(hf_gd, ddof=1)     # MATLAB/Octave std normalises by N-1; numpy defaults to N
                mask_hf = np.abs(hf_gd - m_hf) < sigma_hf
                hf_trend_val = -np.mean(hf_gd[mask_hf]) if np.any(mask_hf) else -m_hf

                hf_ext_idx = np.where(fout > fin[-1])[0]
                if len(hf_ext_idx) > 0:
                    last_idx = hf_ext_idx[0] - 1
                    H_ph_linear_hf = (H_ph_corr[-1] +
                                      (fout[hf_ext_idx] - fin[-1]) * hf_trend_val)

            # MATLAB uses interp1(...,'linear','extrap') here; np.interp would clamp
            # below fin[0], freezing the phase across the whole DC region and shifting
            # the impulse response in time.
            H_ph_cubic = _interp_Sparam__interp_extrap(fout, fin, H_ph_corr)
            H_ph_lin = _interp_Sparam__interp_extrap(fout, fin, H_ph_corr)
            if fout[-1] > fin[-1] and len(hf_ext_idx) > 0:
                # MATLAB anchors the HF trend at fout(last_data_sample) using the
                # interpolated phase there, not at fin[-1]/H_ph_corr[-1].
                last_idx = int(hf_ext_idx[0]) - 1
                H_ph_lin[hf_ext_idx] = (H_ph_lin[last_idx] +
                                        (fout[hf_ext_idx] - fout[last_idx]) * hf_trend_val)

            diff = np.abs(H_ph_cubic - H_ph_lin)
            indx = int(np.argmin(diff))
            H_ph_i = H_ph_cubic.copy()
            H_ph_i[indx:] = H_ph_lin[indx:]
            H_ph_i = H_ph_lin  # MATLAB uses linear in final version
        # else H_ph_i stays as computed above

    else:
        raise ValueError(f'interp_Sparam: invalid opt_interp_Sparam_phase = {ph_method!r}')

    H_i = H_mag_i * np.exp(1j * H_ph_i)

    # ---- Zero padding ----
    if getattr(OP, 'ZERO_PAD', False):
        zero_pad_tukey = float(getattr(param, 'zero_pad_tukey_window_in_fb', 0))
        fb = float(getattr(param, 'fb', 1.0))
        tukey_limit = fin[-1] + zero_pad_tukey * fb
        zp_freq = fin[-1]

        if zero_pad_tukey == 0:
            H_tw = np.ones(len(fout))
        else:
            if zero_pad_tukey > 0:
                H_tw = _Tukey_Window(fout, param, fin[-1], tukey_limit)
                zp_freq = tukey_limit
            else:
                H_tw = _Tukey_Window(fout, param, tukey_limit, fin[-1])

        H_i = H_tw * H_i
        H_i[fout > zp_freq] = np.finfo(float).tiny

    return H_i



# --- make_full_pkg (MATLAB lines 8166–8358) ---

# ============================================================
# MATLAB→Python translation notes for make_full_pkg
# MATLAB lines: 8166–8358
# ============================================================
# Builds 2-port S-param model for TX or RX package.
# Inlines: synth_tline (11292), make_pkg (8359), combines4p (5327).
#
# Layout (per block):
#   Cpad → [Lcomp] → [Cbump] → Tline → Cball
#
# num_blocks determined by mele (columns of z_p_next_cases):
#   mele=1 → 1 block; mele=4 → 4 blocks
#   If C_diepad is 2D matrix: num_blocks = mele + len(Cd_Tx)-1
#
# Mode 'dc'/'cd': Z0/=2, Cpad*=2, Cball*=2, Zpkg*=2, Lcomp/=2, Cbump*=2
#
# PKG_NAME: if set, swaps pkg_gamma0_a1_a2 and pkg_tau from named struct.
# ============================================================



def _make_full_pkg__lin(arr, k, name):
    """MATLAB `A(k)`: linear indexing is COLUMN-major, and out of range errors.

    COM Octave, make_full_pkg('RX', ...) with mele=1 and the shipped 2x4
    param.pkg_Z_c = [87.5 92.5 90 95; 88 93 91 96] (the workbook stores
    package_Z_c as cases-by-[Tx Rx] and transposes it, so it is 2-by-mele):
    pkg_Z_c(2) is element (2,1) = 88, not the row-major (1,2) = 92.5 that
    numpy's .ravel()[1] returns.  s21 at 1 GHz was
    0.78218388281501161-0.57074890734687478j from the reference against
    0.78497930629192492-0.57106813157164604j from the port.
    COM Octave, C_bump=[1.5e-13] for 'RX': "error: C_bump(2): out of bound 1
    (dimensions are 1x1)" — the reference refuses, it does not fall back.
    """
    a = np.asarray(arr, dtype=float).ravel(order='F')
    if k >= a.size:
        raise IndexError('make_full_pkg: %s(%d): out of bound %d'
                         % (name, k + 1, a.size))
    return float(a[k])


def _make_full_pkg__row(arr, i, name):
    """MATLAB `A(i,:)`: a whole row, and a row that is not there errors.

    COM Octave, make_full_pkg('RX', ...) with mele=4 and a 1-D pkg_Z_c:
    "error: param(2,_): out of bound 1 (dimensions are 1x4)".
    """
    a = np.atleast_2d(np.asarray(arr, dtype=float))
    if i >= a.shape[0]:
        raise IndexError('make_full_pkg: %s(%d,:): out of bound %d'
                         % (name, i + 1, a.shape[0]))
    return a[i, :]


def _make_full_pkg__make_pkg(f, pkg_len, cpad, cball, pkg_z, pkg_param, lcomp=0.0, cbump=0.0):
    """Inlined make_pkg (MATLAB lines 8359-8405)."""
    f = np.asarray(f, dtype=float)
    # MATLAB `f(f<eps)=eps` is eps(1) = 2.220446049250313e-16, not the
    # smallest positive double. np.finfo(float).tiny is 292 orders out,
    # and it is the DC point that gets it, which then goes into
    # synth_tline's sqrt and log. Matches com_functions/fn/make_pkg.
    eps_val = np.finfo(float).eps
    f = np.where(f < eps_val, eps_val, f)
    zref = float(pkg_param.Z0)
    tau = float(pkg_param.pkg_tau)
    gamma_coeff = np.asarray(pkg_param.pkg_gamma0_a1_a2, dtype=float).ravel()

    # Cpad shunt: Eq 93A-8
    jw_cpad_z = 1j * 2 * np.pi * f * float(cpad) * zref
    s11pad = -jw_cpad_z / (2.0 + jw_cpad_z)
    s21pad = 2.0 / (2.0 + jw_cpad_z)
    s12pad = s21pad.copy()
    s22pad = s11pad.copy()

    # Optional Lcomp series
    if float(lcomp) > 0.0:
        jw_lcomp_z = 1j * 2 * np.pi * f * float(lcomp) / zref
        s11comp = jw_lcomp_z / (2.0 + jw_lcomp_z)
        s21comp = 2.0 / (2.0 + jw_lcomp_z)
        s11pad, s12pad, s21pad, s22pad = _combines4p(
            s11pad, s12pad, s21pad, s22pad,
            s11comp, s21comp, s21comp, s11comp)

    # Optional Cbump shunt
    if float(cbump) > 0.0:
        jw_cbump_z = 1j * 2 * np.pi * f * float(cbump) * zref
        s11bump = -jw_cbump_z / (2.0 + jw_cbump_z)
        s21bump = 2.0 / (2.0 + jw_cbump_z)
        s11pad, s12pad, s21pad, s22pad = _combines4p(
            s11pad, s12pad, s21pad, s22pad,
            s11bump, s21bump, s21bump, s11bump)

    # Transmission line: Eqs 93A-9 to 93A-14
    S11, S12, S21, S22 = _synth_tline(f, float(pkg_z), zref, gamma_coeff, tau, float(pkg_len))
    s11out1, s12out1, s21out1, s22out1 = _combines4p(
        s11pad, s12pad, s21pad, s22pad,
        S11, S12, S21, S22)

    # Cball shunt: Eq 93A-8
    jw_cball_z = 1j * 2 * np.pi * f * float(cball) * zref
    s11ball = -jw_cball_z / (2.0 + jw_cball_z)
    s21ball = 2.0 / (2.0 + jw_cball_z)
    s11out, s12out, s21out, s22out = _combines4p(
        s11out1, s12out1, s21out1, s22out1,
        s11ball, s21ball, s21ball, s11ball)

    return s11out, s12out, s21out, s22out


def make_full_pkg(type_, faxis, param, channel_type, mode='dd', include_die=1):
    """Build TX or RX package S-params (MATLAB lines 8166-8358).

    type_: 'TX' or 'RX'
    faxis: frequency array (Hz)
    param: parameter namespace
    channel_type: 'THRU', 'FEXT', 'NEXT', or 'NOISE'
    mode: 'dd' (default), 'dc', or 'cd'
    include_die: if 0, zero out Cpad/Lcomp/Cbump

    Returns (s11out, s12out, s21out, s22out), each shape (nfreq,).
    """
    faxis = np.asarray(faxis, dtype=float)

    # Make a local copy of param so modifications don't persist
    pkg_param = copy.copy(param)

    # PKG_NAME swap: if named packages defined, swap gamma/tau for TX vs RX
    pkg_name_list = getattr(param, 'PKG_NAME', None)
    if pkg_name_list is not None and len(pkg_name_list) > 0:
        swap_fields = ['pkg_gamma0_a1_a2', 'pkg_tau']
        type_upper = str(type_).upper()
        if type_upper == 'TX':
            pkg_name = pkg_name_list[0]
        elif type_upper == 'RX':
            pkg_name = pkg_name_list[1]
        else:
            raise ValueError(f'make_full_pkg: type must be TX or RX, got {type_}')
        # param.PKG is a SimpleNamespace keyed by package name (see read_ParamConfigFile)
        pkg_struct = param.PKG[pkg_name] if isinstance(param.PKG, dict) else getattr(param.PKG, pkg_name)
        for field in swap_fields:
            setattr(pkg_param, field, getattr(pkg_struct, field))

    C_diepad = np.asarray(param.C_diepad, dtype=float)
    C_pkg_board = np.asarray(param.C_pkg_board, dtype=float)
    L_comp = np.asarray(param.L_comp, dtype=float)
    C_bump = np.asarray(param.C_bump, dtype=float)

    if not include_die:
        C_diepad = C_diepad * 0
        L_comp = L_comp * 0
        C_bump = C_bump * 0

    z_p = np.atleast_2d(np.asarray(param.z_p_next_cases))
    ncases, mele = z_p.shape

    # Determine vector vs matrix C_diepad/L_comp
    is_vector_cd = (C_diepad.ndim == 1) or (C_diepad.ndim == 2 and min(C_diepad.shape) == 1)

    if is_vector_cd:
        # MATLAB C_diepad(1)/(2), L_comp(1)/(2): a 1-element parameter is
        # "error: C_diepad(2): out of bound 1", not a silent zero.
        Cd_Tx = _make_full_pkg__lin(C_diepad, 0, 'C_diepad')
        Cd_Rx = _make_full_pkg__lin(C_diepad, 1, 'C_diepad')
        Lcomp_Tx = _make_full_pkg__lin(L_comp, 0, 'L_comp')
        Lcomp_Rx = _make_full_pkg__lin(L_comp, 1, 'L_comp')
        num_blocks = mele
        extra_LC = 0
    else:
        # 2D matrix: row 0 = TX, row 1 = RX
        Cd_Tx = _make_full_pkg__row(C_diepad, 0, 'C_diepad')
        Cd_Rx = _make_full_pkg__row(C_diepad, 1, 'C_diepad')
        Lcomp_Tx = _make_full_pkg__row(L_comp, 0, 'L_comp')
        Lcomp_Rx = _make_full_pkg__row(L_comp, 1, 'L_comp')
        extra_LC = len(Cd_Tx) - 1
        num_blocks = mele + extra_LC

    insert_zeros = np.zeros(extra_LC)

    # MATLAB `switch type / case 'TX'` is case-SENSITIVE, unlike the strcmpi
    # above.  COM Octave, make_full_pkg('Tx', ...): the switch matches nothing,
    # Cball is never assigned and it fails with "error: 'Cball' undefined".
    type_str = str(type_)
    if type_str == 'TX':
        if mele == 1:
            # MATLAB L8389-8390: Cpad=Cd_Tx; Lcomp=L_comp_Tx -- the WHOLE row
            # when C_diepad/L_comp are given as a 2xN matrix of die LC
            # sections. Taking only the first entry dropped every section
            # after it, which is the same truncation already fixed in the
            # mele==4 branch below. Unreachable on the shipped workbooks,
            # which set mele=4 (z_p_next_cases is 4x4) and zero die values.
            Cpad = np.atleast_1d(np.asarray(Cd_Tx, dtype=float)).ravel()
            Lcomp = np.atleast_1d(np.asarray(Lcomp_Tx, dtype=float)).ravel()
            Cbump = np.array([_make_full_pkg__lin(C_bump, 0, 'C_bump')])
            Cball = np.array([_make_full_pkg__lin(C_pkg_board, 0, 'C_pkg_board')])
            Zpkg = np.array([_make_full_pkg__lin(param.pkg_Z_c, 0, 'pkg_Z_c')])
        elif mele == 4:
            # MATLAB: Cpad=[Cd_Tx 0 0 0]; Lcomp=[L_comp_Tx 0 0 0]  (L8390-8391).
            # Cd_Tx/L_comp_Tx are ROW VECTORS when C_d/L_comp are given as a
            # 2xN matrix (N die LC sections per side), so MATLAB's horizontal
            # concatenation yields len(Cd_Tx)+3 entries — matching
            # num_blocks = mele + extra_LC. Taking only Cd_Tx[0] dropped every
            # die section after the first and produced a 4-entry array, losing
            # the die LC delay (~15 ps here) and reshaping the pulse.
            Cpad = np.concatenate([np.atleast_1d(np.asarray(Cd_Tx, dtype=float)).ravel(),
                                   np.zeros(3)])
            Lcomp = np.concatenate([np.atleast_1d(np.asarray(Lcomp_Tx, dtype=float)).ravel(),
                                    np.zeros(3)])
            Cbump = np.array([_make_full_pkg__lin(C_bump, 0, 'C_bump'), 0.0, 0.0, 0.0])
            Cball = np.array([0.0, 0.0, _make_full_pkg__lin(param.C_v, 0, 'C_v'),
                              _make_full_pkg__lin(C_pkg_board, 0, 'C_pkg_board')])
            Zpkg = _make_full_pkg__row(param.pkg_Z_c, 0, 'pkg_Z_c')
        else:
            raise ValueError(f'make_full_pkg: unsupported mele={mele}')

        ch_upper = str(channel_type).upper()
        if ch_upper == 'THRU':
            Len = np.asarray(param.Pkg_len_TX, dtype=float).ravel()
        elif ch_upper == 'NEXT':
            Len = np.asarray(param.Pkg_len_NEXT, dtype=float).ravel()
        elif ch_upper == 'FEXT':
            Len = np.asarray(param.Pkg_len_FEXT, dtype=float).ravel()
        elif ch_upper == 'NOISE':
            raise ValueError('make_full_pkg: TX pkg should not be used for NOISE channels')
        else:
            # MATLAB's channel_type switch has no otherwise, so Len is never
            # assigned.  COM Octave, channel_type='BOGUS': "error: 'Len'
            # undefined near line 145" — it does not fall back to Pkg_len_TX.
            raise ValueError(
                f'make_full_pkg: unsupported channel_type={channel_type}')

    elif type_str == 'RX':
        if mele == 1:
            # MATLAB L8416-8417: the whole row, as for TX above.
            Cpad = np.atleast_1d(np.asarray(Cd_Rx, dtype=float)).ravel()
            Lcomp = np.atleast_1d(np.asarray(Lcomp_Rx, dtype=float)).ravel()
            Cbump = np.array([_make_full_pkg__lin(C_bump, 1, 'C_bump')])
            Cball = np.array([_make_full_pkg__lin(C_pkg_board, 1, 'C_pkg_board')])
            Zpkg = np.array([_make_full_pkg__lin(param.pkg_Z_c, 1, 'pkg_Z_c')])
        elif mele == 4:
            # MATLAB: Cpad=[Cd_Rx 0 0 0]; Lcomp=[L_comp_Rx 0 0 0]  (L8390-8391).
            # Cd_Rx/L_comp_Rx are ROW VECTORS when C_d/L_comp are given as a
            # 2xN matrix (N die LC sections per side), so MATLAB's horizontal
            # concatenation yields len(Cd_Rx)+3 entries — matching
            # num_blocks = mele + extra_LC. Taking only Cd_Rx[0] dropped every
            # die section after the first and produced a 4-entry array, losing
            # the die LC delay (~15 ps here) and reshaping the pulse.
            Cpad = np.concatenate([np.atleast_1d(np.asarray(Cd_Rx, dtype=float)).ravel(),
                                   np.zeros(3)])
            Lcomp = np.concatenate([np.atleast_1d(np.asarray(Lcomp_Rx, dtype=float)).ravel(),
                                    np.zeros(3)])
            Cbump = np.array([_make_full_pkg__lin(C_bump, 1, 'C_bump'), 0.0, 0.0, 0.0])
            Cball = np.array([0.0, 0.0, _make_full_pkg__lin(param.C_v, 1, 'C_v'),
                              _make_full_pkg__lin(C_pkg_board, 1, 'C_pkg_board')])
            Zpkg = _make_full_pkg__row(param.pkg_Z_c, 1, 'pkg_Z_c')
        else:
            raise ValueError(f'make_full_pkg: unsupported mele={mele}')

        # MATLAB's RX switch covers THRU/NEXT/FEXT/NOISE, all of them
        # Pkg_len_RX, and has no otherwise.  COM Octave, channel_type='BOGUS'
        # on 'RX': "error: 'Len' undefined near line 145".
        if str(channel_type).upper() not in ('THRU', 'NEXT', 'FEXT', 'NOISE'):
            raise ValueError(
                f'make_full_pkg: unsupported channel_type={channel_type}')
        Len = np.asarray(param.Pkg_len_RX, dtype=float).ravel()
    else:
        raise ValueError(f'make_full_pkg: type must be TX or RX, got {type_}')

    # Prepend insert_zeros
    Cball = np.concatenate([insert_zeros, Cball.ravel()])
    Cbump = np.concatenate([insert_zeros, Cbump.ravel()])
    Len = np.concatenate([insert_zeros, Len.ravel()])
    Zpkg = np.concatenate([insert_zeros, Zpkg.ravel()])

    # Mode 'dc' or 'cd': scale parameters for common-mode
    if mode.lower() in ('dc', 'cd'):
        pkg_param.Z0 = float(param.Z0) / 2.0
        Cpad = Cpad * 2.0
        Cball = Cball * 2.0
        Zpkg = Zpkg * 2.0
        Lcomp = Lcomp / 2.0
        Cbump = Cbump * 2.0

    # Build and cascade blocks
    n_blocks = int(num_blocks)

    def _el(arr, j, name):
        # MATLAB indexes Len(j), Cpad(j), ... straight; a vector shorter than
        # num_blocks is an error, not an implicit zero.  COM Octave, mele=4
        # with a scalar param.Pkg_len_TX: "error: Len(2): out of bound 1
        # (dimensions are 1x1)".
        arr = np.asarray(arr, dtype=float).ravel()
        if j >= len(arr):
            raise IndexError('make_full_pkg: %s(%d): out of bound %d'
                             % (name, j + 1, len(arr)))
        return float(arr[j])

    if n_blocks == 1:
        s11out, s12out, s21out, s22out = _make_full_pkg__make_pkg(
            faxis, _el(Len, 0, 'Len'), _el(Cpad, 0, 'Cpad'),
            _el(Cball, 0, 'Cball'), _el(Zpkg, 0, 'Zpkg'),
            pkg_param, _el(Lcomp, 0, 'Lcomp'), _el(Cbump, 0, 'Cbump'))
    else:
        for j in range(n_blocks):
            sp11, sp12, sp21, sp22 = _make_full_pkg__make_pkg(
                faxis, _el(Len, j, 'Len'), _el(Cpad, j, 'Cpad'),
                _el(Cball, j, 'Cball'), _el(Zpkg, j, 'Zpkg'),
                pkg_param, _el(Lcomp, j, 'Lcomp'), _el(Cbump, j, 'Cbump'))
            if j == 0:
                s11out, s12out, s21out, s22out = sp11, sp12, sp21, sp22
            else:
                s11out, s12out, s21out, s22out = _combines4p(
                    s11out, s12out, s21out, s22out,
                    sp11, sp12, sp21, sp22)

    return s11out, s12out, s21out, s22out



# --- make_pkg (MATLAB lines 8359–8405) ---

def make_pkg(f, pkg_len, cpad, cball, pkg_z, param, *varargin):
    """Build package S-parameters: pad capacitor + transmission line + ball capacitor (MATLAB lines 8359-8405).

    Optional varargin[0] = lcomp (compensating inductor), varargin[1] = cbump (bump capacitor).
    Returns (s11, s12, s21, s22) as 1-D complex arrays.
    """
    f = np.asarray(f, dtype=float).ravel()
    f = np.where(f < np.finfo(float).eps, np.finfo(float).eps, f)  # f(f<eps)=eps

    tau = float(param.pkg_tau)
    gc = param.pkg_gamma0_a1_a2
    Lenscale = float(pkg_len)
    zref = float(param.Z0)

    # Pad capacitor (Eq. 93A-8)
    denom_pad = 2 + 1j * 2 * np.pi * f * float(cpad) * zref
    s11pad = -1j * 2 * np.pi * f * float(cpad) * zref / denom_pad
    s21pad = 2.0 / denom_pad
    s12pad = s21pad.copy()
    s22pad = s11pad.copy()

    # Optional compensating inductor
    if len(varargin) > 0:
        lcomp = float(varargin[0])
        if lcomp > 0:
            denom_c = 2 + 1j * 2 * np.pi * f * lcomp / zref
            s11comp = (1j * 2 * np.pi * f * lcomp / zref) / denom_c
            s21comp = 2.0 / denom_c
            s11pad, s12pad, s21pad, s22pad = _combines4p(
                s11pad, s12pad, s21pad, s22pad, s11comp, s21comp, s21comp, s11comp)

    # Optional bump capacitor
    if len(varargin) > 1:
        cbump = float(varargin[1])
        if cbump > 0:
            denom_b = 2 + 1j * 2 * np.pi * f * cbump * zref
            s11bump = -1j * 2 * np.pi * f * cbump * zref / denom_b
            s21bump = 2.0 / denom_b
            s11pad, s12pad, s21pad, s22pad = _combines4p(
                s11pad, s12pad, s21pad, s22pad, s11bump, s21bump, s21bump, s11bump)

    # Transmission line segment
    S11, S12, S21, S22 = _synth_tline(f, float(pkg_z), zref, gc, tau, Lenscale)
    s11out1, s12out1, s21out1, s22out1 = _combines4p(
        s11pad, s12pad, s21pad, s22pad, S11, S21, S21, S11)

    # Ball capacitor (Eq. 93A-8)
    denom_ball = 2 + 1j * 2 * np.pi * f * float(cball) * zref
    s11ball = -1j * 2 * np.pi * f * float(cball) * zref / denom_ball
    s21ball = 2.0 / denom_ball

    s11out, s12out, s21out, s22out = _combines4p(
        s11out1, s12out1, s21out1, s22out1, s11ball, s21ball, s21ball, s11ball)

    return s11out, s12out, s21out, s22out



# --- missingParameter (MATLAB lines 8406–8409) ---

# ============================================================
# MATLAB→Python translation notes for missingParameter
# MATLAB lines: 8406–8409
# ============================================================
# 1-based vs 0-based indexing: not applicable.
# Column-major vs row-major: not applicable.
# MATLAB error(): raises an exception with an identifier and message.
#   Python equivalent: raise ValueError with the same message text.
# Output shape: no return value — function always raises.
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def missingParameter(parameterName):
    """Raise ValueError for a missing or incorrect mandatory parameter.

    Mirrors MATLAB error('error:badParameterInformation', ...).
    """
    raise ValueError(
        f"The data for mandatory parameter {parameterName} is missing or incorrect"
    )



# --- normal_dist (MATLAB lines 8410–8416) ---

# ============================================================
# MATLAB→Python translation notes for normal_dist
# MATLAB lines: 8410–8416
# ============================================================
# 1-based vs 0-based indexing: not applicable (range arithmetic only).
# Column-major vs row-major: MATLAB (pdf.Min:-pdf.Min) produces a row
#   vector; np.arange produces a 1-D array — equivalent for our purposes.
# MATLAB `end` keyword: not used.
# Output shape: pdf.x and pdf.y are 1-D arrays of length 2*|pdf.Min|+1.
# eps: MATLAB `eps` == np.finfo(float).eps (machine epsilon, ~2.22e-16).
# round() difference: MATLAB rounds 0.5 away from zero; Python rounds to
#   even. Inputs to round() here are 2*nsigma*sigma/binsize — in practice
#   these are integers or clearly non-half values, so the difference is moot.
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================

def _normal_dist__mround(x):
    """MATLAB round(): half away from zero, where Python's round() is banker's."""
    x = float(x)
    t = int(x)                      # int() truncates toward zero
    if abs(x - t) == 0.5:           # exact tie: MATLAB goes away from zero
        return t + (1 if x > 0 else -1)
    # Off a tie round() is exact, and unlike floor(x + 0.5) it does not
    # send 0.49999999999999994 to 1: that sum is exactly 1.0 in binary.
    return int(round(x))



def normal_dist(sigma, nsigma, binsize):
    """Return a normalised Gaussian PDF struct.

    Fields:
      pdf.BinSize  — bin width (= binsize)
      pdf.Min      — negative integer; x-axis starts at pdf.Min*binsize
      pdf.x        — voltage axis, shape (2*|pdf.Min|+1,)
      pdf.y        — normalised Gaussian weights, sum == 1
    """
    pdf = SimpleNamespace()
    pdf.BinSize = binsize
    # pdf.Min is the (negative) index of the leftmost bin
    pdf.Min = -_normal_dist__mround(2 * nsigma * sigma / binsize)  # MATLAB line 8412

    # MATLAB: (pdf.Min:-pdf.Min) is range [pdf.Min, ..., -pdf.Min] step 1
    # np.arange upper bound is exclusive, so +1 is needed
    pdf.x = np.arange(pdf.Min, -pdf.Min + 1) * binsize  # MATLAB line 8413

    eps = np.finfo(float).eps
    pdf.y = np.exp(-pdf.x ** 2 / (2 * sigma ** 2 + eps))  # MATLAB line 8414
    pdf.y = pdf.y / np.sum(pdf.y)                          # MATLAB line 8415
    return pdf



# --- optimize_fom (MATLAB lines 8417–8793) ---

"""
optimize_fom: EQ search loop — finds best CTLE/TXFFE/DFE/RxFFE settings for FOM.
MATLAB lines 8417–8793.
"""




def _optimize_fom__mround(x):
    """MATLAB round(): half away from zero, where Python's round() is banker's.

    Needed at the triple-transit-time site below because
    `2*sbr_peak_i / samples_per_ui` is a ratio of two INTEGERS, so it lands on
    .5 exactly whenever 2*sbr_peak_i is an odd multiple of samples_per_ui/2 --
    not the measure-zero case the conversion audit dismissed. Ledger #16 is the
    same shape (`nui = round(len/M)`) and was a live defect on 4 of 208 cases.
    Guarded by tests/test_integer_ratio_rounding.py.
    """
    import math
    x = float(x)
    t = int(x)                      # int() truncates toward zero
    if abs(x - t) == 0.5:           # exact tie: MATLAB goes away from zero
        return t + (1 if x > 0 else -1)
    # Off a tie round() is exact, and unlike floor(x + 0.5) it does not
    # send 0.49999999999999994 to 1: that sum is exactly 1.0 in binary.
    return int(round(x))


# ── Optional EQ-search trajectory logging (off by default; no effect on COM) ──
# Set SWEEP_LOG_CSV to a path to capture one row per TX-FFE candidate considered
# (for any method: full grid / legacy local search / adaptive). Rows are buffered
# in memory and flushed to CSV when optimize_fom returns. This is the data source
# for the sweep-vs-adaptive comparison visualisation.
SWEEP_LOG_CSV = None
SWEEP_METHOD_LABEL = ''
_SWEEP_ROWS = []
_SWEEP_HEADER = ['method', 'gffe_index', 'ctle_index', 'lp_index', 'txffe_index',
                 'tx_taps', 'candidate_FOM', 'best_FOM', 'evaluated', 'eval_count',
                 'skip_reason']


def _optimize_fom__sweep_record(row):
    if SWEEP_LOG_CSV is not None:
        _SWEEP_ROWS.append(row)


def _optimize_fom__sweep_flush():
    if SWEEP_LOG_CSV is None:
        return

    def _cell(v):
        if isinstance(v, str):
            return '"' + v + '"'
        if isinstance(v, float):
            return 'nan' if v != v else f'{v:.6g}'
        return str(v)

    with open(SWEEP_LOG_CSV, 'w', newline='') as f:
        f.write(','.join(_SWEEP_HEADER) + '\n')
        for r in _SWEEP_ROWS:
            f.write(','.join(_cell(v) for v in r) + '\n')
    _SWEEP_ROWS.clear()


def optimize_fom(OP, param, chdata, sigma_bn, do_C2M,
                 _OptFom_Initialize_Loop_Struct_fn=None,
                 _OptFom_Build_TXFFE_fn=None,
                 _OptFom_Calculate_Settings_fn=None,
                 _FD_CTLE_fn=None,
                 _OptFom_Compute_CTLE_fn=None,
                 _OptFom_Calc_Noise_XC_fn=None,
                 _get_sigma_eta_ACCM_noise_fn=None,
                 _get_sigma_noise_fn=None,
                 _OptFom_Compute_TXFFE_fn=None,
                 _OptFom_Find_Sample_Point_fn=None,
                 _OptFom_Setup_Sampler_Sweep_fn=None,
                 _OptFom_Itick_BoxSearch_fn=None,
                 _OptFom_Itick_LocalSearch_fn=None,
                 _OptFom_Compute_RxFFE_fn=None,
                 _OptFom_Compute_DFE_fn=None,
                 _OptFom_Calc_Noise_fn=None,
                 _OptFom_Calc_FOM_fn=None,
                 _OptFom_Local_Search_fn=None,
                 _OptFom_Adaptive_Local_Search_fn=None,
                 _get_PSDs_fn=None,
                 _OptFom_Set_Best_Itick_fn=None,
                 _OptFom_Update_Best_Setttings_fn=None,
                 _OptFom_Update_Best_Settings_EQ_Failed_fn=None,
                 _OptFom_Update_BEST_Post_Optimize_fn=None,
                 _OptFom_Create_Output_fn=None):

    result = SimpleNamespace()

    # ── Initialize loop struct ─────────────────────────────────────────────
    THIS = _OptFom_Initialize_Loop_Struct_fn()

    # ── Initialize parameters ──────────────────────────────────────────────
    f = np.asarray(chdata[0].faxis).ravel()

    # Normalize ts_sample_adj_range: single value → [0, value]
    tsar = np.asarray(param.ts_sample_adj_range, dtype=float).ravel()
    if len(tsar) == 1:
        tsar = np.array([0.0, tsar[0]])
    param.ts_sample_adj_range = tsar
    full_sample_range = np.arange(int(tsar[0]), int(tsar[1]) + 1)

    param.ndfe_passed = int(param.ndfe)
    if getattr(param, 'Floating_DFE', False):
        param.ndfe = int(param.N_bmax)

    if getattr(OP, 'RxFFE', False) and getattr(OP, 'FFE_OPT_METHOD', '') == 'MMSE':
        OP.RxFFE_with_MMSE = 1
    else:
        OP.RxFFE_with_MMSE = 0

    OP.itick_box_size = 5

    Gffe_values = np.asarray(param.cursor_gain).ravel()
    if not getattr(OP, 'RxFFE', False):
        Gffe_values = np.array([0.0])

    if getattr(param, 'CTLE_type', '') in ('CL93', 'CL120e'):
        param.g_DC_HP_values = np.array([0.0])

    lf_indx = len(np.asarray(param.g_DC_HP_values).ravel())

    BEST = SimpleNamespace(FOM=float('-inf'), cursor_i=None)
    sbr = np.array([])

    # ── T_O ───────────────────────────────────────────────────────────────
    if do_C2M:
        loop_count = [1, 2]
        T_O = int(max(0, np.floor((float(param.T_O) / 1000.0) * int(param.samples_per_ui))))
    else:
        loop_count = [1]
        T_O = 0

    if getattr(OP, 'Optimize_loop_speed_up', 0) == 1:
        OP.BinSize = 1e-4
        OP.impulse_response_truncation_threshold = 1e-3

    # ── Used to speed up FFE ───────────────────────────────────────────────
    pulse_struc = [SimpleNamespace(pulse_ctle_circshift=None)]
    ctle_response_updated = 1

    # ── Build TXFFE values ─────────────────────────────────────────────────
    txffe_matrix, cur, txffe_sweep_indices, FULL_tx_index_vector, txffe_cursor_vector = \
        _OptFom_Build_TXFFE_fn(param)
    num_txffe_runs = txffe_matrix.shape[0]
    param.cursor_index = cur

    # ── Loop-independent settings ──────────────────────────────────────────
    SETTINGS = _OptFom_Calculate_Settings_fn(txffe_matrix, chdata, param, OP)
    if not hasattr(SETTINGS, 'delta_sbr') or SETTINGS.delta_sbr is None:
        SETTINGS.delta_sbr = None

    # FOM history for the adaptive local search (Hansel branch); harmless otherwise
    FOM_history = []
    iter_count = 0

    # Sweep-trajectory logging counters (only used when SWEEP_LOG_CSV is set)
    n_eval = 0
    if SWEEP_LOG_CSV is not None:
        _SWEEP_ROWS.clear()

    # ── EQ search dimensions ───────────────────────────────────────────────
    n_gffe = len(Gffe_values)
    n_ctle = len(np.asarray(param.ctle_gdc_values).ravel())
    n_samp = len(full_sample_range)
    FOM_TRACKER = np.zeros((n_gffe, n_ctle, lf_indx, num_txffe_runs, n_samp))

    pxi = 0
    runs = n_ctle * lf_indx * n_gffe * num_txffe_runs

    print(f'  optimize_fom: {n_gffe} gffe × {n_ctle} CTLE × {lf_indx} g_DC_HP × '
          f'{num_txffe_runs} TXFFE × {n_samp} itick = {runs * n_samp} evals', flush=True)

    # ── EQ Loop ────────────────────────────────────────────────────────────
    for i in loop_count:
        if do_C2M:
            print(f'  C2M pass {i}/{len(loop_count)}', flush=True)
        for Gffe_index, gffe_val in enumerate(Gffe_values):
            param.current_ffegain = gffe_val
            ctle_gdc_values = np.asarray(param.ctle_gdc_values).ravel()
            for ctle_index, g_dc in enumerate(ctle_gdc_values):
                print(f'    CTLE {ctle_index + 1}/{len(ctle_gdc_values)}  '
                      f'g_dc={g_dc:.2f}  best_FOM={BEST.FOM:.2f} dB', flush=True)
                THIS.ctle_index = ctle_index + 1  # 1-based to match MATLAB
                THIS.g_dc = float(g_dc)
                CTLE_fp1 = float(np.asarray(param.CTLE_fp1).ravel()[ctle_index])
                CTLE_fp2 = float(np.asarray(param.CTLE_fp2).ravel()[ctle_index])
                CTLE_fz = float(np.asarray(param.CTLE_fz).ravel()[ctle_index])
                ctle_gain = _FD_CTLE_fn(f, CTLE_fz, CTLE_fp1, CTLE_fp2, THIS.g_dc)
                ctle_gain_xc = _FD_CTLE_fn(
                    np.asarray(SETTINGS.f_xc).ravel(), CTLE_fz, CTLE_fp1, CTLE_fp2, THIS.g_dc)

                g_DC_HP_values = np.asarray(param.g_DC_HP_values).ravel()
                for g_LP_index, g_lp in enumerate(g_DC_HP_values):
                    THIS.g_DC_low = float(g_lp)
                    THIS.g_LP_index = g_LP_index + 1  # 1-based

                    qual_arr = np.atleast_2d(np.asarray(SETTINGS.qual, dtype=float))
                    g_row = min(g_LP_index, qual_arr.shape[0] - 1)
                    c_col = min(ctle_index, qual_arr.shape[1] - 1)
                    if float(qual_arr[g_row, c_col]) == 0.0:
                        pxi += num_txffe_runs
                        continue

                    if getattr(OP, 'INCLUDE_CTLE', 0) == 1:
                        ctle_response_updated = 1

                    chdata, THIS.H_ctf, H_low_xc, H_ctf2 = _OptFom_Compute_CTLE_fn(
                        chdata, ctle_gain, THIS, SETTINGS.f_xc, param, OP)

                    Noise_XC = _OptFom_Calc_Noise_XC_fn(H_low_xc, ctle_gain_xc, SETTINGS, param, OP)

                    THIS.sigma_N = _get_sigma_eta_ACCM_noise_fn(
                        chdata, param, SETTINGS.H_sy, SETTINGS.H_r, THIS.H_ctf)

                    if getattr(OP, 'RX_CALIBRATION', False):
                        # MATLAB: THIS.sigma_ne = get_sigma_noise(...) takes only the 1st
                        # output (sigma_NE); Python returns (sigma_NE, sigma_HP).
                        THIS.sigma_ne = _get_sigma_noise_fn(H_ctf2, param, chdata, sigma_bn)[0]
                    else:
                        THIS.sigma_ne = 0.0

                    gdc_min = float(getattr(param, 'GDC_MIN', 0))
                    if gdc_min != 0 and THIS.g_dc + THIS.g_DC_low > gdc_min:
                        pxi += num_txffe_runs
                        continue

                    THIS.PSD_results = None
                    if OP.RxFFE_with_MMSE:
                        OP.WO_TXFFE = 1
                        THIS.PSD_results = _get_PSDs_fn(
                            THIS.PSD_results, [], [], [], THIS.g_dc, THIS.g_DC_low,
                            param, chdata, OP)

                    # ── TXFFE Loop ─────────────────────────────────────────
                    _txffe_report_interval = max(1, num_txffe_runs // 10)
                    for TK in range(num_txffe_runs):
                        pxi += 1
                        if num_txffe_runs > 1 and TK % _txffe_report_interval == 0:
                            print(f'      TXFFE {TK + 1}/{num_txffe_runs}  '
                                  f'best={BEST.FOM:.2f} dB', flush=True)
                        txffe_cur = float(np.asarray(txffe_cursor_vector[TK]).ravel()[0])
                        if txffe_cur < float(getattr(param, 'tx_ffe_c0_min', -np.inf)):
                            continue

                        THIS.tx_index_vector = FULL_tx_index_vector[TK, :]

                        if getattr(param, 'LOCAL_SEARCH', 0) > 0 and not np.isinf(BEST.FOM):
                            iter_count += 1
                            # NonZeroLSMethod: 1 -> Hansel adaptive search, else legacy
                            if (getattr(param, 'NonZeroLSMethod', 0) == 1
                                    and _OptFom_Adaptive_Local_Search_fn is not None):
                                # 4p16p0 L9017 passes Overwrite_Min_Radius as the
                                # second positional argument; here it is a keyword
                                # so the 4p15p0 call shape is unchanged.
                                skip_it = _OptFom_Adaptive_Local_Search_fn(
                                    param.LOCAL_SEARCH, BEST, THIS, FOM_history,
                                    iter_count, num_txffe_runs,
                                    Overwrite_Min_Radius=getattr(
                                        param, 'Overwrite_Min_Radius', None),
                                    matlab_version=getattr(
                                        param, 'matlab_version', '4p15p0'))
                            else:
                                skip_it = _OptFom_Local_Search_fn(
                                    param.LOCAL_SEARCH, BEST, THIS, txffe_sweep_indices)
                            if skip_it:
                                if SWEEP_LOG_CSV is not None:
                                    _optimize_fom__sweep_record([SWEEP_METHOD_LABEL, Gffe_index, ctle_index,
                                                   g_LP_index, TK,
                                                   np.array2string(np.asarray(THIS.tx_index_vector).ravel()),
                                                   float('nan'), float(BEST.FOM), 0, n_eval, 'search_skip'])
                                continue

                        cand_fom = float('-inf')  # best FOM over this candidate's itick sweep
                        THIS.txffe = txffe_matrix[TK, :]
                        sbr, chdata, pulse_struc = _OptFom_Compute_TXFFE_fn(
                            chdata, pulse_struc, THIS.txffe, ctle_response_updated, param, OP)
                        sbr_from_txffe = sbr.copy()
                        if ctle_response_updated:
                            ctle_response_updated = 0

                        raw_cursor_i, no_zero_crossing, sbr_peak_i = _OptFom_Find_Sample_Point_fn(
                            sbr, param, OP, SETTINGS.Peak_Search_Range)
                        if no_zero_crossing:
                            continue

                        triple_transit_time = _optimize_fom__mround(int(sbr_peak_i) * 2 / int(param.samples_per_ui)) + 20
                        if SETTINGS.min_number_of_UI_in_response < triple_transit_time:
                            SETTINGS.min_number_of_UI_in_response = triple_transit_time

                        # ── ITICK loop ─────────────────────────────────────
                        loop_range_it, BEST, middle_search, box_search, cluster, box_mid = \
                            _OptFom_Setup_Sampler_Sweep_fn(full_sample_range, BEST, OP)

                        for itickn in loop_range_it:
                            if box_search:
                                THIS.itick, BEST, skip_it = _OptFom_Itick_BoxSearch_fn(
                                    itickn, cluster, BEST, box_mid, OP.itick_box_size)
                                if skip_it:
                                    continue
                            else:
                                THIS.itick = full_sample_range[itickn]

                            THIS.cursor_i = int(raw_cursor_i) + int(THIS.itick)
                            sbr = sbr_from_txffe.copy()

                            if getattr(param, 'LOCAL_SEARCH', 0) > 0:
                                skip_it = _OptFom_Itick_LocalSearch_fn(
                                    THIS.itick, middle_search, BEST, param.LOCAL_SEARCH)
                                if skip_it:
                                    continue

                            if getattr(OP, 'RxFFE', False):
                                sbr, THIS, skip_it = _OptFom_Compute_RxFFE_fn(
                                    sbr, THIS, Noise_XC, chdata, param, OP)
                                if skip_it:
                                    continue

                            # Cursor amplitude.
                            # AUDIT FINDING B16-D20: cursor_sample_index and
                            # OptFom_Find_Sample_Point return 0-BASED indices (the
                            # convention get_PSDs, get_pdf and OptFom_Compute_DFE use),
                            # so no -1 belongs here; MATLAB L8788-8801 reads
                            # sbr(cursor_i) with no offset.
                            #
                            # History: removing the -1 was tried on 2026-08-13 while the
                            # package die-network bug was still present and made COM
                            # agreement WORSE, so it was reverted. Once the die LC
                            # sections were fixed (make_full_pkg/read_s4p_files/s21_pkg
                            # kept only 1 of 3 sections) the two errors were shown to have
                            # been compensating, and D20 is now applied.
                            cursor = float(sbr[THIS.cursor_i])
                            THIS.A_p = float(sbr[int(sbr_peak_i)])
                            THIS.A_s = float(param.R_LM) * cursor / (int(param.levels) - 1)

                            if SETTINGS.delta_sbr is None:
                                SETTINGS.delta_sbr = sbr.copy()
                            sbr = sbr.ravel()

                            # Far cursors and precursors (eq 93A-27)
                            far_start = THIS.cursor_i - T_O + int(param.samples_per_ui) * (int(param.ndfe) + 1)
                            far_start = max(far_start, 0)
                            THIS.far_cursors = sbr[far_start::int(param.samples_per_ui)]

                            pre_start = THIS.cursor_i - int(param.samples_per_ui)
                            if pre_start >= 0:
                                pre_rev = sbr[pre_start::-int(param.samples_per_ui)]
                                THIS.precursors = pre_rev[::-1]
                            else:
                                THIS.precursors = np.array([])

                            # Early FOM bound check (skip if no chance of beating best)
                            if not OP.RxFFE_with_MMSE:
                                combined = np.concatenate([THIS.precursors, THIS.far_cursors])
                                sigma_ISI_ignoreDFE = float(param.sigma_X) * np.linalg.norm(combined)
                                if sigma_ISI_ignoreDFE > 0 and 20 * np.log10(
                                        abs(THIS.A_s) / sigma_ISI_ignoreDFE) < BEST.FOM:
                                    continue

                            # Extend sbr if too short
                            sbr_required_length = THIS.cursor_i + int(param.samples_per_ui) * (int(param.ndfe) + 1)
                            if len(sbr) < sbr_required_length:
                                sbr = np.append(sbr, np.zeros(sbr_required_length - len(sbr)))

                            # Solve DFE
                            THIS, param = _OptFom_Compute_DFE_fn(sbr, THIS, param, do_C2M, T_O)

                            # Calculate all noise
                            THIS, abort_status = _OptFom_Calc_Noise_fn(
                                THIS, BEST.FOM, sbr, SETTINGS, chdata, param, OP)
                            if abort_status == 1:
                                continue
                            elif abort_status == 2:
                                break

                            # Find FOM
                            if not OP.RxFFE_with_MMSE:
                                THIS.FOM, skip_loop = _OptFom_Calc_FOM_fn(
                                    chdata, do_C2M, THIS, param, OP, sbr)
                                if skip_loop:
                                    continue

                            # Update FOM history for the adaptive local search,
                            # capped at the itick sampler-sweep length (loop_range)
                            if getattr(param, 'LOCAL_SEARCH', 0) > 0:
                                FOM_history.append(float(THIS.FOM))
                                max_history_length = len(loop_range_it)
                                if len(FOM_history) > max_history_length:
                                    FOM_history = FOM_history[-max_history_length:]

                            # Track FOM
                            itick_matches = np.where(full_sample_range == int(THIS.itick))[0]
                            if len(itick_matches) > 0:
                                itick_idx = itick_matches[0]
                                FOM_TRACKER[Gffe_index, ctle_index, g_LP_index, TK, itick_idx] = THIS.FOM
                            if SWEEP_LOG_CSV is not None:
                                cand_fom = max(cand_fom, float(THIS.FOM))

                            # Update best settings
                            BEST = _OptFom_Set_Best_Itick_fn(THIS, BEST)
                            if THIS.FOM > BEST.FOM:
                                BEST = _OptFom_Update_Best_Setttings_fn(BEST, THIS, sbr, chdata, param, OP)
                                print(f'      ** new best FOM = {BEST.FOM:.3f} dB '
                                      f'(CTLE {ctle_index + 1}, TXFFE {TK + 1}, itick={THIS.itick})',
                                      flush=True)

                        # End of this candidate's itick sweep — record it as evaluated
                        if SWEEP_LOG_CSV is not None:
                            n_eval += 1
                            _optimize_fom__sweep_record([SWEEP_METHOD_LABEL, Gffe_index, ctle_index,
                                           g_LP_index, TK,
                                           np.array2string(np.asarray(THIS.tx_index_vector).ravel()),
                                           float(cand_fom), float(BEST.FOM), 1, n_eval, ''])

        if do_C2M:
            if BEST.FOM == float('-inf'):
                param.Min_VEO_Test = 0
            else:
                break

    # ── Check EQ failure ──────────────────────────────────────────────────
    cursor_i_empty = (BEST.cursor_i is None or
                      (hasattr(BEST.cursor_i, '__len__') and len(np.asarray(BEST.cursor_i).ravel()) == 0))
    if cursor_i_empty:
        result.eq_failed = True
        BEST = _OptFom_Update_Best_Settings_EQ_Failed_fn(BEST, THIS, sbr, chdata, param, OP)
        if do_C2M:
            _optimize_fom__sweep_flush()
            return result
    else:
        result.eq_failed = False

    # ── Post-optimize ─────────────────────────────────────────────────────
    f_post = np.arange(1e8, 100e9 + 1e8, 1e8)
    length_sbr = len(np.asarray(BEST.sbr).ravel())
    t_out = np.arange(length_sbr) * float(param.ui) / float(param.samples_per_ui)

    BEST = _OptFom_Update_BEST_Post_Optimize_fn(BEST, f_post, param, OP)

    # ── Create output ─────────────────────────────────────────────────────
    result = _OptFom_Create_Output_fn(result, BEST, t_out, chdata, param, OP)
    result.FOM_TRACKER = FOM_TRACKER  # full FOM landscape, for the convergence plot
    # The itick values indexing FOM_TRACKER's last axis. FOM_TRACKER was already
    # exported but the axis it is measured against was not, so a FOM-versus-
    # sampling-phase plot could not be drawn from it. Carrying the axis costs a
    # reference to an array the search already built and changes no result.
    result.sample_range = np.asarray(full_sample_range)
    # EQ sweep dimensions (for the engineering-export run summary; no effect on COM)
    result.sweep_dims = SimpleNamespace(
        n_gffe=int(n_gffe), n_ctle=int(n_ctle), n_g_DC_HP=int(lf_indx),
        n_txffe=int(num_txffe_runs), n_itick=int(n_samp),
        total_evals=int(runs * n_samp),
        local_search=int(getattr(param, 'LOCAL_SEARCH', 0)))

    _optimize_fom__sweep_flush()  # write the per-candidate trajectory CSV when logging is enabled
    return result



# --- parameter_size_adjustment (MATLAB lines 8794–8845) ---

# ============================================================
# MATLAB→Python translation notes for parameter_size_adjustment
# MATLAB lines: 8794–8845
# ============================================================
# Expands scalar parameters to arrays of the required length.
# z_p_tx_cases is a 2-D array; ncases = number of rows.
# pkg_sel_vec length = max(OP.pkg_len_select).
# Uses np.ones_like to match the shape/dtype of reference arrays.
# ============================================================


def _parameter_size_adjustment__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _parameter_size_adjustment__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _parameter_size_adjustment__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)


def _parameter_size_adjustment__mmin(a):
    """MATLAB min(): the mirror of _parameter_size_adjustment__mmax."""
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _parameter_size_adjustment__mextreme_complex(a, 0)
    if a.dtype.kind != 'f':
        return np.min(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.min(a)
    return np.nanmin(a)



def parameter_size_adjustment(param, OP):
    make_length2 = ['C_pkg_board', 'C_diepad', 'L_comp', 'C_bump', 'tfx',
                    'C_v', 'C_0', 'C_1', 'pkg_Z_c', 'brd_Z_c', 'R_diepad']
    make_length_WCPORTZ = ['a_thru', 'a_fext', 'a_next', 'SNDR']
    make_length_GDC = ['CTLE_fp1', 'CTLE_fp2', 'CTLE_fz', 'f_HP_Z', 'f_HP_P']
    make_length_DCHP = ['f_HP']
    make_length_ncases = ['AC_CM_RMS']

    # MATLAB [ncases, mele] = size(param.z_p_tx_cases).  Everything in MATLAB is
    # at least 2-D, so a row vector is 1xN and counts as ONE case; a 1-D numpy
    # array of length N gave N.  COM Octave, z_p_tx_cases=[1 2 3]:
    # numel(param.AC_CM_RMS) == 1 after the call, where Python expanded it to 3.
    ztx = np.asarray(param.z_p_tx_cases)
    ncases = ztx.shape[0] if ztx.ndim >= 2 else 1

    pkg_sel = np.asarray(OP.pkg_len_select)
    if OP.WC_PORTZ:
        PORTZ_mult = np.ones(2, dtype=float)
    else:
        PORTZ_mult = np.ones(int(_parameter_size_adjustment__mmax(pkg_sel)), dtype=float)

    # A missing field is a divergence that is deliberately left open: MATLAB
    # `numel(param.(name))` errors ("structure has no member 'tfx'", confirmed
    # under COM Octave) where these loops skip.  Making Python raise would break
    # every run today, because read_ParamConfigFile never sets param.C_0 /
    # param.C_1 (MATLAB com_ieee8023_4p16p0.m L10379-10380) -- the skip is what
    # hides that gap.  Close it there first, then turn these into errors.
    for field in make_length2:
        raw = getattr(param, field, None)
        if raw is None:
            continue
        val = np.asarray(raw)
        if val.size == 1:
            setattr(param, field, float(val.ravel()[0]) * np.ones(2))

    for field in make_length_ncases:
        raw = getattr(param, field, None)
        if raw is None:
            continue
        val = np.asarray(raw)
        if val.size == 1:
            setattr(param, field, float(val.ravel()[0]) * np.ones(ncases))

    for field in make_length_GDC:
        raw = getattr(param, field, None)
        if raw is None:
            continue
        val = np.asarray(raw)
        if val.size == 1:
            ref = np.asarray(param.ctle_gdc_values)
            setattr(param, field, float(val.ravel()[0]) * np.ones_like(ref, dtype=float))

    for field in make_length_DCHP:
        raw = getattr(param, field, None)
        if raw is None:
            continue
        val = np.asarray(raw)
        if val.size == 1:
            ref = np.asarray(param.g_DC_HP_values)
            setattr(param, field, float(val.ravel()[0]) * np.ones_like(ref, dtype=float))

    for field in make_length_WCPORTZ:
        raw = getattr(param, field, None)
        if raw is None:
            continue
        val = np.asarray(raw)
        if val.size == 1:
            setattr(param, field, float(val.ravel()[0]) * PORTZ_mult)

    return param



# --- pdf2sgm (MATLAB lines 8846–8852) ---

# ============================================================
# MATLAB→Python translation notes for pdf2sgm
# MATLAB lines: 8846–8848
# ============================================================
# 1-based vs 0-based indexing: not applicable.
# Element-wise ops: .* and .^2 map directly to * and **2 on NumPy arrays.
# Output shape: scalar float.
# Formula: weighted mean then weighted standard deviation of the PDF.
#   avg = E[x]     = sum(x * y)
#   sgm = std(x)   = sqrt(sum((x - avg)^2 * y))
#   (This is the RMS voltage spread, i.e., std dev of the PDF.)
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def pdf2sgm(pdf):
    """Return the standard deviation (sigma) of a PDF struct.

    Computes:
      avg = sum(pdf.x * pdf.y)          weighted mean
      sgm = sqrt(sum((pdf.x-avg)^2 * pdf.y))  weighted std dev
    """
    x = np.asarray(pdf.x, dtype=float)
    y = np.asarray(pdf.y, dtype=float)
    avg = np.sum(x * y)                       # MATLAB line 8847
    sgm = np.sqrt(np.sum((x - avg) ** 2 * y)) # MATLAB line 8848
    return float(sgm)



# --- pdf_to_cdf (MATLAB lines 8853–8864) ---

# ============================================================
# MATLAB→Python translation notes for pdf_to_cdf
# MATLAB lines: 8853–8864
# ============================================================
# 1-based vs 0-based indexing: not applicable.
# cumsum direction: MATLAB cumsum on a row vector is element-wise left-to-
#   right — same as np.cumsum on a 1-D array.
# fliplr: MATLAB fliplr reverses a row vector; np.flip does the same for
#   1-D arrays.  (fliplr on a 2-D matrix reverses columns; that case does
#   not arise here because pdf.y is always 1-D.)
# min([yB(:) yT(:)], [], 2): MATLAB stacks two column vectors into n×2,
#   then takes the minimum across each row.  Equivalent to np.minimum(yB, yT).
# Output shape: cdf.y is 1-D (MATLAB produces a column vector, which we
#   store as a flat NumPy array consistent with our pdf convention).
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def pdf_to_cdf(pdf):
    """Transform a PDF struct to a combined top/bottom CDF struct.

    Returns a SimpleNamespace with fields:
      cdf.yB  — left-to-right cumulative sum (bottom eye)
      cdf.yT  — right-to-left cumulative sum (top eye)
      cdf.y   — element-wise minimum of yB and yT
      cdf.x   — x-axis copied from pdf.x
    """
    cdf = SimpleNamespace()
    y = np.asarray(pdf.y, dtype=float).ravel()  # ensure 1-D

    cdf.yB = np.cumsum(y)                              # MATLAB line 8861
    cdf.yT = np.flip(np.cumsum(np.flip(y)))            # MATLAB line 8862
    cdf.y  = np.minimum(cdf.yB, cdf.yT)               # MATLAB line 8863
    cdf.x  = pdf.x                                     # MATLAB line 8864
    return cdf



# --- plot_bathtub_curves (MATLAB lines 8865–8913) ---

# ============================================================
# MATLAB→Python translation notes for plot_bathtub_curves
# MATLAB lines: 8865–8913
# ============================================================
# Inline helpers: conv_fct (5371-5388), d_cpdf (MATLAB d_cpdf).
# cursors: two-point PDF at ±max_signal with equal probability 1/2.
# MATLAB semilogy → axes.semilogy in Python.
# vbt_r: MATLAB fliplr(0.5 - cumsum(fliplr(...))) → np.flipud for 1-D arrays.
# The if 0 ... end debug block is omitted.
# ============================================================





# PDF convolutions are extremely skewed in size: ~79% of the arithmetic sits in
# ~1% of the calls (both operands long), while most calls have a kernel of a few
# bins. Direct convolution wins for tiny kernels and loses badly for long ones
# (measured 2.7x slower at 600, 19x at 9000, >1000x at 20000+), so dispatch on
# size. The FFT path agrees with the direct path to ~1e-15 relative.


def plot_bathtub_curves(hax, max_signal, sci_pdf, cci_pdf, isi_and_xtalk_pdf,
                        noise_pdf, jitt_pdf, combined_interference_and_noise_pdf, bin_size):
    cursors = _d_cpdf(bin_size, max_signal * np.array([-1.0, 1.0]), np.array([0.5, 0.5]))
    signal_and_isi_pdf = _conv_fct(cursors, sci_pdf)
    signal_and_xtalk_pdf = _conv_fct(cursors, cci_pdf)
    signal_and_channel_noise_pdf = _conv_fct(cursors, isi_and_xtalk_pdf)
    signal_and_system_noise_pdf = _conv_fct(cursors, noise_pdf)
    signal_and_system_jitt_pdf = _conv_fct(cursors, jitt_pdf)

    cursors_l = copy.copy(cursors)
    cursors_l.y = cursors_l.y.copy()
    cursors_l.y[cursors_l.x > 0] = 0

    cursors_r = copy.copy(cursors)
    cursors_r.y = cursors_r.y.copy()
    cursors_r.y[cursors_r.x < 0] = 0

    signal_and_total_noise_pdf_l = _conv_fct(cursors_l, combined_interference_and_noise_pdf)
    signal_and_total_noise_pdf_r = _conv_fct(cursors_r, combined_interference_and_noise_pdf)

    hax.semilogy(signal_and_isi_pdf.x, np.abs(np.cumsum(signal_and_isi_pdf.y) - 0.5),
                 'r', label='ISI')
    hax.semilogy(signal_and_xtalk_pdf.x, np.abs(np.cumsum(signal_and_xtalk_pdf.y) - 0.5),
                 'b', label='Xtalk')
    hax.semilogy(signal_and_channel_noise_pdf.x, np.abs(np.cumsum(signal_and_channel_noise_pdf.y) - 0.5),
                 'c', label='ISI+Xtalk')
    hax.semilogy(signal_and_system_noise_pdf.x, np.abs(np.cumsum(signal_and_system_noise_pdf.y) - 0.5),
                 'm', label='Jitter, SNR_TX,RL_M, eta_0 noise')
    hax.semilogy(signal_and_system_jitt_pdf.x, np.abs(np.cumsum(signal_and_system_jitt_pdf.y) - 0.5),
                 'g', label='Jitter noise')

    vbt_l = np.abs(0.5 - np.cumsum(signal_and_total_noise_pdf_l.y))
    vbt_r = np.flipud(0.5 - np.cumsum(np.flipud(signal_and_total_noise_pdf_r.y)))
    hax.semilogy(signal_and_total_noise_pdf_l.x, vbt_l, 'k', label='total noise PDF left')
    hax.semilogy(signal_and_total_noise_pdf_r.x, vbt_r, 'k', label='total noise PDF right')

    hax.plot(max_signal * np.array([-1.0, -1.0, 1.0, 1.0]),
             [0.5, 1e-20, 1e-20, 0.5], '--ok')
    hax.set_ylabel('Probability')
    hax.set_xlabel('volts')
    hax.legend()



# --- plot_modal (MATLAB lines 8914–9010) ---

# ============================================================
# MATLAB→Python translation notes for plot_modal
# MATLAB lines: 8914–9010
# ============================================================
# Computes CM_MASK_REPORT struct (modal mask pass/fail) when OP.CM_MASK_REPORT.
# All MATLAB figure/plot calls skipped (OP.DISPLAY_WINDOW=False).
# Sfield: '_orig' if not OP.SHOW_BRD, else '_raw'.
# RLcc_mask, RLcc178, RLdc_mask: lambda functions of f/1e9.
# chdata[0].faxis is frequency axis (Hz).
# dB(x) = 20*log10(abs(x)).
# Return value: return_struct (SimpleNamespace) or None if not CM_MASK_REPORT.
# ============================================================


def _plot_modal__mextreme_complex(a, take):
    """MATLAB orders complex values by magnitude, then by angle; numpy orders
    them lexicographically by real part, so max([3+4i, 5]) is 3+4i in MATLAB
    and 5 in numpy. take is -1 for max, 0 for min."""
    f = np.asarray(a).ravel()
    good = ~np.isnan(np.abs(f))
    if not good.any():
        return f[0]
    g = f[good]
    return g[np.lexsort((np.angle(g), np.abs(g)))[take]]


def _plot_modal__mmax(a):
    """MATLAB max(): a NaN is skipped unless every element is NaN, and complex
    values are ordered by magnitude then angle.

    np.max propagates a NaN, so one bad sample swallows the result where MATLAB
    ignores it. np.nanmax matches MATLAB but warns on an all-NaN input, where
    MATLAB quietly returns NaN. The isnan test also keeps the ordinary no-NaN
    case on np.max's faster path.
    """
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _plot_modal__mextreme_complex(a, -1)
    if a.dtype.kind != 'f':
        return np.max(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.max(a)
    return np.nanmax(a)


def _plot_modal__mmin(a):
    """MATLAB min(): the mirror of _plot_modal__mmax."""
    a = np.asarray(a)
    if a.dtype.kind == 'c':
        return _plot_modal__mextreme_complex(a, 0)
    if a.dtype.kind != 'f':
        return np.min(a)
    nan = np.isnan(a)
    if not nan.any() or nan.all():
        return np.min(a)
    return np.nanmin(a)



def _plot_modal__RLcc_mask(f_ghz):
    f = np.asarray(f_ghz, dtype=float)
    return (
        -2.0 * ((5 >= f) & (f < 4))
        - (2 + 2 / 40 * (f - 4)) * ((4 <= f) & (f < 44))
        - (4 + 2 / 16 * (44 - f)) * ((44 <= f) & (f < 60))
        - 2.0 * ((60 <= f) & (f <= 67))
        - 2.0 * (f > 67)
    )


def _plot_modal__RLcc178(f_ghz):
    f = np.asarray(f_ghz, dtype=float)
    return -np.ones(len(f)) * 3.25


def _plot_modal__RLdc_mask(f_ghz):
    f = np.asarray(f_ghz, dtype=float)
    return (
        (-23 + 22 * f / 106.25) * ((f >= 0.05) & (f < 53.125))
        - 12.0 * ((f >= 53.125) & (f <= 67))
        - 12.0 * (f > 67)
    )


def _plot_modal__dB(x):
    """MATLAB: dB=@(x) 20*log10(squeeze(abs(x))).  There is no epsilon floor.

    The port added np.finfo(float).eps inside the log, which shifted every
    margin by 20/ln(10)*eps/|S| dB and replaced MATLAB's -Inf at |S|=0 with
    -313 dB.  Found by running the reference process_sxp (which calls
    plot_modal) under Octave: see test_verify.py in process_sxp, where the
    epsilon put Rlcc_179mm(1) at 24.020599913279586 against the reference's
    24.020599913279625.  errstate only silences numpy's divide warning at
    |S|=0; MATLAB returns -Inf there without complaint.
    """
    with np.errstate(divide='ignore'):
        return 20.0 * np.log10(np.squeeze(np.abs(np.asarray(x, dtype=complex))))


def plot_modal(param, OP, chdata):
    """Modal mask computation and (skipped) plotting (MATLAB lines 8914-9010).

    Returns SimpleNamespace with Rlcc/Rldc margin fields when OP.CM_MASK_REPORT,
    otherwise returns None.
    """
    if isinstance(chdata, list):
        ch0 = chdata[0]
    else:
        ch0 = chdata

    Sfield = '_raw' if getattr(OP, 'SHOW_BRD', False) else '_orig'
    f = np.asarray(ch0.faxis, dtype=float)
    f_ghz = f / 1e9

    if getattr(OP, 'CM_MASK_REPORT', False):
        rs = SimpleNamespace()

        scc11 = np.asarray(getattr(ch0, 'scc11' + Sfield, np.zeros(len(f))), dtype=complex)
        scd22 = np.asarray(getattr(ch0, 'scd22' + Sfield, np.zeros(len(f))), dtype=complex)
        sdc22 = np.asarray(getattr(ch0, 'sdc22' + Sfield, np.zeros(len(f))), dtype=complex)

        rs.Rlcc_179mm = _plot_modal__RLcc_mask(f_ghz) - _plot_modal__dB(scc11)
        rs.Rlcc_179mm_fail = bool(_plot_modal__mmin(rs.Rlcc_179mm) < 0)
        rs.Rlcc_178mm = _plot_modal__RLcc178(f_ghz) - _plot_modal__dB(scc11)
        rs.Rlcc_178mm_fail = bool(_plot_modal__mmin(rs.Rlcc_178mm) < 0)
        rs.Rlcd_179mm = _plot_modal__RLdc_mask(f_ghz) - _plot_modal__dB(scd22)
        rs.Rlcd_179mm_fail = bool(_plot_modal__mmin(rs.Rlcd_179mm) < 0)
        rs.Rldc_179mm = _plot_modal__RLdc_mask(f_ghz) - _plot_modal__dB(sdc22)
        rs.Rldc_179mm_fail = bool(_plot_modal__mmin(rs.Rldc_179mm) < 0)
        return rs

    return None



# --- plot_pie_com (MATLAB lines 9011–9092) ---

# ============================================================
# MATLAB→Python translation notes for plot_pie_com
# MATLAB lines: 9011–9091
# ============================================================
# No return value in MATLAB (void function).
# All matplotlib bar/plot calls skipped (no DISPLAY_WINDOW).
# Computes COM_per_noise breakdown and prints it.
# iex.*: find first abs(cumsum(y)) >= BER (0-based in Python: argmax of cumsum >= BER).
# maxn[0]=sci, maxn[1]=noise, maxn[2]=cci.
# COM_per_noise = COM * (maxn^2 / sum(maxn^2)).
# pfctr/mfctr: exp(+/-0.09054*delta_dB).
# Returns None (void).
# ============================================================



def plot_pie_com(hax, max_signal, sci_pdf, cci_pdf, isi_and_xtalk_pdf, noise_pdf,
                 combined_interference_and_noise_pdf, bin_size, param):
    """COM breakdown computation and (skipped) pie/bar plot (MATLAB lines 9011-9091).

    Prints COM breakdown percentages. No return value.
    """
    BER = float(param.specBER)
    delta_dB = float(param.delta_IL)

    def _find_iex(pdf):
        cs = np.cumsum(np.asarray(pdf.y, dtype=float))
        idx = np.where(np.abs(cs) >= BER)[0]
        return int(idx[0]) if len(idx) > 0 else len(cs) - 1

    iex_combined = _find_iex(combined_interference_and_noise_pdf)
    iex_noise = _find_iex(noise_pdf)
    iex_cci = _find_iex(cci_pdf)
    iex_sci = _find_iex(sci_pdf)

    x_combined = np.asarray(combined_interference_and_noise_pdf.x, dtype=float)
    x_noise = np.asarray(noise_pdf.x, dtype=float)
    x_cci = np.asarray(cci_pdf.x, dtype=float)
    x_sci = np.asarray(sci_pdf.x, dtype=float)

    maxn = np.array([
        abs(x_sci[iex_sci]),
        abs(x_noise[iex_noise]),
        abs(x_cci[iex_cci]),
    ], dtype=float)
    maxn_tot = abs(x_combined[iex_combined])

    COM = 20.0 * np.log10(float(max_signal) / maxn_tot) if maxn_tot > 0 else -np.inf

    if COM < 0:
        return

    sum_maxn2 = float(np.dot(maxn, maxn))
    COM_per_noise = COM * (maxn ** 2 / sum_maxn2) if sum_maxn2 > 0 else np.zeros(3)

    COM_ISI = f'{100 * COM_per_noise[0] / np.sum(COM_per_noise):.2g}%' if np.sum(COM_per_noise) > 0 else '0%'
    COM_SYS = f'{100 * COM_per_noise[1] / np.sum(COM_per_noise):.2g}%' if np.sum(COM_per_noise) > 0 else '0%'
    COM_xtalk = f'{100 * COM_per_noise[2] / np.sum(COM_per_noise):.2g}%' if np.sum(COM_per_noise) > 0 else '0%'

    pfctr = float(np.exp(-0.09054 * delta_dB))
    mfctr = float(np.exp(0.09054 * delta_dB))

    plus_maxn = np.array([maxn[0] * pfctr, maxn[1], maxn[2] * pfctr])
    minus_maxn = np.array([maxn[0] * mfctr, maxn[1], maxn[2] * mfctr])

    plus_maxn_tot = float(np.linalg.norm(plus_maxn))
    minus_maxn_tot = float(np.linalg.norm(minus_maxn))

    COMp = 20.0 * np.log10(float(max_signal) * pfctr / maxn_tot) if maxn_tot > 0 else -np.inf
    COMm = 20.0 * np.log10(float(max_signal) * mfctr / maxn_tot) if maxn_tot > 0 else -np.inf

    print(f'ISI: {COM_ISI}, System noise: {COM_SYS}, Crosstalk: {COM_xtalk}')



# --- process_sxp (MATLAB lines 9093–9389) ---

# ============================================================
# MATLAB→Python translation notes for process_sxp
# MATLAB lines: 9093–9389
# ============================================================
# Indexing: MATLAB 1-based → 0-based Python.
#   i=1..num_files → i=0..num_files-1
#   ipsl=1..len(port_sel) → ipsl=0..len(port_sel)-1
#   izt=1..len(param.Z_t) → izt=0..len(param.Z_t)-1
#   First-channel guard: MATLAB i==1 → Python i==0
#
# S.Parameters storage: MATLAB S.Parameters(row,col,freq) [1-based NumPorts×NumPorts×Nf]
#   → Python shape (Nf, NumPorts, NumPorts), access S.Parameters[freq_idx, row, col]
#
# Sfield: '_orig' (default, no board) or '_raw' (when OP.SHOW_BRD=True)
#
# MATLAB struct arrays TDR_results(izt,ipsl) → Python list-of-lists tdr_results[izt][ipsl]
# MATLAB chdata(i).TDR11(izt) → Python chdata[i].TDR11 list indexed by izt (0-based)
#
# OP.Report_Modal_ERL: MATLAB strcmpi(x,'enable') || strcmpi(x,'provisional')
#   → x.lower() in ('enable', 'provisional')
#
# All display/plot code (DISPLAY_WINDOW, DEBUG) is omitted — no output.
#
# get_RAW_FIR stub: returns zeros (OP.AUTO_TFX logic uses it only optionally)
# plot_modal stub: returns empty dict (no modal return struct)
# add_pkg_with_die stub: returns S unchanged and TX_RL=0
# get_TDR is the primary callee — must be stubbed here, no import from get_TDR/py_impl
# ============================================================



