    H_i = H_mag_i * np.exp(1j * H_ph_i)

    if getattr(OP, 'ZERO_PAD', False):
        zpf = float(getattr(param, 'zero_pad_tukey_window_in_fb', 0))
        fb = float(getattr(param, 'fb', 1.0))
