# ============================================================
# MATLAB→Python translation notes for varargin_extractor
# MATLAB lines: 11326–11334
# ============================================================
# varargin: MATLAB cell array of variable args → Python *args tuple.
# isempty(varargin): True when called with no args → len(args)==0.
# out_var=[]: MATLAB empty array → Python None (or [] — None preferred
#   as it clearly signals "no value" to callers).
# varg_out={}: empty cell → empty list [].
# varg_out(1)=[]: delete first element of cell array → args[1:].
# Output: (first_arg_or_None, remaining_args_list).
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def varargin_extractor(*args):
    """Extract the first element from a variable-argument list.

    Returns (out_var, varg_out):
      out_var  — first argument, or None if args is empty
      varg_out — remaining arguments as a list (empty list if ≤1 arg)
    """
    if len(args) == 0:                    # MATLAB isempty(varargin)
        return None, []
    return args[0], list(args[1:])



# --- vma (MATLAB lines 11337–11365) ---

def _vma__strfind_int(arr, pattern):
    """Find all 0-based positions where pattern occurs in arr."""
    arr = np.asarray(arr)
    n, m = len(arr), len(pattern)
    return np.array([i for i in range(n - m + 1) if np.array_equal(arr[i:i + m], pattern)],
                    dtype=int)


def vma(PR, M):
    """Compute Vertical Margin with Alignment (VMA) for PAM4 (MATLAB lines 11337-11365).

    PR: pulse response (1-D array), M: samples per UI.
    Returns SimpleNamespace with P_3, P_0, VMA fields.
    """
    PR = np.asarray(PR, dtype=float).ravel()
    M = int(M)

    seq, syms, _ = _PRBS13Q()
    symbols = seq

    imaxPR = int(np.argmax(PR))  # 0-based

    # Positions of 7 consecutive 3s in syms (0-based)
    pos_3x7 = _vma__strfind_int(syms, [3, 3, 3, 3, 3, 3, 3])
    # MATLAB: indx_S3x7_start = M*(pos-1) + imaxPR (1-based) → Python 0-based: M*pos + imaxPR
    indx_S3x7_start = M * pos_3x7 + imaxPR
    indx_S3x7_end = M * (pos_3x7 + 6) + imaxPR  # MATLAB: M*(pos+5)+imaxPR (1-based)

    # Positions of 6 consecutive 0s in syms (0-based)
    pos_0x6 = _vma__strfind_int(syms, [0, 0, 0, 0, 0, 0])
    # MATLAB: M*pos - 1 + imaxPR (1-based) → Python 0-based: M*(pos_0+1) + imaxPR_0 - 1
    indx_S0x6_start = M * (pos_0x6 + 1) + imaxPR - 1
    indx_S0x6_end = M * (pos_0x6 + 5) + imaxPR  # MATLAB: M*(pos+4)+imaxPR (1-based)

    # Upsample symbols by M: kron(symbols, [1, 0, 0, ..., 0])
    unit_pulse = np.zeros(M)
    unit_pulse[0] = 1
    shifting_vector = np.kron(symbols, unit_pulse)

    # Superposition response: filter(PR, 1, shifting_vector) — PR is the FIR kernel
    Bit_stream_response = lfilter(PR, [1.0], shifting_vector)

    # Center indices for 3s and 0s patterns (take first match)
    icent3 = int(np.floor((indx_S3x7_end - indx_S3x7_start) / 2 + indx_S3x7_start)[0])
    icent0 = int(np.floor((indx_S0x6_end - indx_S0x6_start) / 2 + indx_S0x6_start)[0])

    # MATLAB indexes Bit_stream_response((icent-M):(icent+M)) directly, so a
    # window that runs off either end is an error there, not a shorter mean.
    # COM Octave, M=1 with a 9000-sample PR peaking at sample 8901:
    #   "error: Bit_stream_response(11732): out of bound 4095".
    # A numpy slice clips instead, and an empty slice made P_3 and P_0 NaN
    # with no sign that the measurement had left the bit stream.
    n_bsr = len(Bit_stream_response)
    for icent in (icent3, icent0):
        if icent - M < 0 or icent + M >= n_bsr:
            raise IndexError(
                'vma: measurement window Bit_stream_response(%d..%d) lies '
                'outside the %d-sample bit stream'
                % (icent - M + 1, icent + M + 1, n_bsr))

    P_3 = float(np.mean(Bit_stream_response[icent3 - M:icent3 + M + 1]))
    P_0 = float(np.mean(Bit_stream_response[icent0 - M:icent0 + M + 1]))
    VMA = P_3 - P_0

    return SimpleNamespace(P_3=P_3, P_0=P_0, VMA=VMA)



# --- vref_intersect (MATLAB lines 11366–11383) ---

# ============================================================
# MATLAB→Python translation notes for vref_intersect
# MATLAB lines: 11366–11378
# ============================================================
# 1-based vs 0-based indexing: x_in is a 1-based MATLAB row index.
#   MATLAB eye_contour(x_in,   1) → Python eye_contour[x_in-1, 0]
#   MATLAB eye_contour(x_in-1, 1) → Python eye_contour[x_in-2, 0]
#   x_in is also used as a real coordinate in b1 = y - m1*x_in, so it
#   stays as-is in the arithmetic (1-based convention preserved throughout).
#   The returned line_intersection is therefore also in 1-based index space.
# Column indexing: eye_contour(:,1) in MATLAB = eye_contour[:,0] in Python.
# Output shape: scalar float (fractional index, 1-based).
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def vref_intersect(eye_contour, x_in, vref):
    """Find x where the eye contour linearly crosses vref.

    Uses the line through (x_in-1, y_prev) and (x_in, y_curr) to find
    the fractional 1-based index where y == vref.

    Parameters
    ----------
    eye_contour : 2-D array, first column holds y-values
    x_in        : 1-based integer index of the upper bracket point
    vref        : target voltage level
    """
    ec = np.asarray(eye_contour, dtype=float)

    # MATLAB reads eye_contour(x_in-1,1), so x_in<=1 asks for subscript 0 and
    # errors. Python's ec[x_in-2, 0] turns that into a negative index and
    # quietly reads the LAST row instead, answering off the far end of the eye.
    # COM Octave: vref_intersect([0.1;0.3;0.7;0.9], 1, 0.5) ->
    #   "eye_contour(0,_): subscripts must be either integers 1 to (2^63)-1
    #    or logicals"                 (Python returned 0.5)
    # A fractional x_in is refused the same way; int(x_in) used to truncate it.
    # COM Octave: x_in=2.5 -> "eye_contour(2.5,_): subscripts must be ..."
    #   (Python returned 3.0)
    if x_in != int(x_in) or x_in < 2:
        raise IndexError('eye_contour(%s,_): subscripts must be either '
                         'integers 1 to (2^63)-1 or logicals' % (x_in - 1,))
    x_in = int(x_in)

    y_curr = ec[x_in - 1, 0]          # MATLAB eye_contour(x_in, 1)
    y_prev = ec[x_in - 2, 0]          # MATLAB eye_contour(x_in-1, 1)

    m1 = y_curr - y_prev               # slope in index-space (step = 1)
    b1 = y_curr - m1 * x_in           # y-intercept of the contour line
    # m2 = 0, b2 = vref  →  intersection = (b2 - b1) / (m1 - m2)
    line_intersection = (vref - b1) / m1   # MATLAB line 11378
    return float(line_intersection)



# --- writecsv_transposed (MATLAB lines 11384–11407) ---

def _writecsv_transposed__g(v, prec):
    """%.*g with MATLAB's spelling of the non-finite values."""
    if math.isnan(v):
        return 'NaN'
    if math.isinf(v):
        return 'Inf' if v > 0 else '-Inf'
    return '%.*g' % (prec, v)


def _writecsv_transposed__complex_num2str(z):
    """MATLAB num2str for one complex value: both parts under the precision
    the pair selects, joined by the sign of the imaginary part."""
    re, im = float(z.real), float(z.imag)
    parts = [v for v in (re, im) if not (math.isnan(v) or math.isinf(v))]
    biggest = max((abs(v) for v in parts), default=0.0)
    dgt = 0 if biggest == 0 else int(math.floor(math.log10(biggest)))
    if all(v == math.trunc(v) for v in parts):
        prec = min(dgt + 1, 16)
    else:
        prec = max(min(dgt + 5, 16), 5)
    return '%s%s%si' % (_writecsv_transposed__g(re, prec), '-' if im < 0 else '+',
                        _writecsv_transposed__g(abs(im), prec))


def _writecsv_transposed__num2str(x):
    """MATLAB num2str for a real numeric value or array.

    Scalars: five significant digits for a non-integer, the exact digits for
    an integer. Arrays: every element right-aligned in a fixed field, the
    whole result then trimmed. The widths below reproduce COM Octave:
        [1 2 3]      -> '1  2  3'        [100 2]     -> '100    2'
        [1.5 2.5]    -> '1.5         2.5'
        [pi 1/3]     -> '3.1416     0.33333'
        [1e-13 1]    -> '1e-13           1'
        linspace(0,1,5) ->
            '0        0.25         0.5        0.75           1'
        []           -> ''               [1 2;3 4]   -> '1  2' / '3  4'
    NOT VERIFIED against MATLAB: MATLAB's num2str widens the field by one for
    an array containing a negative, and Octave does not. Every pinned test
    uses non-negative arrays, where the two rules agree, and scalars, which
    were checked directly.
    """
    a = np.asarray(x)
    if a.size == 0:
        return ''
    if a.dtype.kind == 'c':
        # Complex scalars are checked: COM Octave num2str gives 1+2i -> '1+2i',
        # pi+1i -> '3.1416+1i', 1/3+1i/7 -> '0.33333+0.14286i'. The field
        # widths num2str uses for a complex ARRAY were not checked, so those
        # are simply joined.
        return '  '.join(_writecsv_transposed__complex_num2str(v) for v in a.ravel())
    a = a.astype(float)
    flat = a.ravel()
    finite = flat[np.isfinite(flat)]
    biggest = float(np.max(np.abs(finite))) if finite.size else 0.0
    dgt = 0 if biggest == 0 else int(math.floor(math.log10(biggest)))
    if finite.size == flat.size and np.all(finite == np.trunc(finite)):
        prec = min(dgt + 1, 16)
        width = prec + 2
    else:
        prec = max(min(dgt + 5, 16), 5)
        width = prec + 7

    rows = a.reshape(1, -1) if a.ndim < 2 else a
    text = [''.join('%*s' % (width, _writecsv_transposed__g(float(v), prec)) for v in row)
            for row in rows]
    lead = min(len(r) - len(r.lstrip(' ')) for r in text)
    trail = min(len(r) - len(r.rstrip(' ')) for r in text)
    # strtrim on a char matrix drops the blank columns every row shares.
    # A matrix input therefore leaves several rows; MATLAB puts that
    # multi-row char array in one cell, and what writecell does with it could
    # not be checked here, so the rows are simply joined.
    return '\n'.join(r[lead:len(r) - trail] for r in text)


def _writecsv_transposed__is_logical(v):
    return isinstance(v, (bool, np.bool_)) or (
        isinstance(v, np.ndarray) and v.dtype == bool)


def _writecsv_transposed__is_numeric(v):
    if isinstance(v, (int, float, complex, np.number)):
        return True
    if isinstance(v, np.ndarray):
        return v.dtype.kind in 'iufc'
    # A list or tuple of numbers is how a MATLAB numeric row vector arrives
    # when the caller did not build an ndarray; a list of anything else is a
    # cell array, which MATLAB reports as '[unsupported]'.
    return (isinstance(v, (list, tuple)) and len(v) > 0
            and all(isinstance(e, (int, float, complex, np.number))
                    and not isinstance(e, bool) for e in v))


def _writecsv_transposed__val_to_str(v):
    # MATLAB's order: ischar, isnumeric, islogical, isstruct, isempty, else.
    # islogical is lifted above isnumeric here only because a Python bool IS
    # an int; in MATLAB the two predicates are disjoint.
    if isinstance(v, str):
        return v
    if _writecsv_transposed__is_logical(v):
        # ML 11399 is `string(val)`, which is "true"/"false", not "True".
        # A logical ARRAY gives a string array, and what writecell writes for
        # that could not be checked without MATLAB.
        flat = np.asarray(v).ravel()
        return ' '.join('true' if bool(b) else 'false' for b in flat)
    if _writecsv_transposed__is_numeric(v):
        return _writecsv_transposed__num2str(v)
    if hasattr(v, '__dict__') or isinstance(v, dict):
        return '[struct]'
    if v is None:
        return ''
    try:
        if len(v) == 0:
            return ''
    except TypeError:
        pass
    return '[unsupported]'


def writecsv_transposed(output_args, filename):
    """Write struct fields as two-column CSV (Field, Value) (MATLAB lines 11384-11407)."""
    d = output_args if isinstance(output_args, dict) else vars(output_args)
    with open(filename, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['Field', 'Value'])
        for field, value in d.items():
            writer.writerow([field, _writecsv_transposed__val_to_str(value)])



# --- xls_parameter (MATLAB lines 11408–11493) ---

_SENTINEL = object()


def xls_parameter(param_sheet, param_name, eval_if_string=False, default_value=_SENTINEL):
    """Case-insensitive lookup in 2D param_sheet (MATLAB lines 11408-11493).

    param_sheet: list-of-lists.
    Returns p (the value in the cell one column to the right of the match).
    Raises KeyError if not found and no default_value was provided.
    Raises ValueError if multiple matches found.
    The SAVE_KEYWORD_FILE block is dead code (always false) and is omitted.
    """
    name_lower = param_name.lower()
    matches = [
        (r, c)
        for r, row in enumerate(param_sheet)
        for c, cell in enumerate(row)
        if isinstance(cell, str) and cell.lower() == name_lower
    ]

    if len(matches) == 0:
        if default_value is _SENTINEL:
            raise KeyError(
                f'Mandatory parameter "{param_name}" is missing or incorrect'
            )
        # MATLAB assigns `p = default_value` and then falls through to the
        # `ischar(p) && eval_if_string` line below, so a *default* that is a
        # string is evaluated too. COM Octave:
        #     xls_parameter(sheet, 'ZZ', true, '1+1')             -> 2
        #     xls_parameter(sheet, 'ZZ', true, '[92 92 ; 70 70]') -> 2x2 matrix
        #     xls_parameter(sheet, 'ZZ', 0,    '1+1')             -> '1+1'
        # Returning here instead handed back the unevaluated string. That is
        # reachable: line 10403 of the reference reads
        #     param.pkg_Z_c = xls_parameter(parameter, 'package_Z_c', true,
        #                                   '[92 92 ; 70 70; 80 80; 100 100]').'
        # so a config without package_Z_c transposed a string.
        p = default_value
    elif len(matches) > 1:
        raise ValueError(
            f'{len(matches)} occurrences of "{param_name}" found. Please recheck spreadsheet'
        )
    else:
        r, c = matches[0]
        p = param_sheet[r][c + 1]

    # NOTE: this is Python's eval, and MATLAB's reads MATLAB. Anything in the
    # array syntax a COM workbook actually uses — '[92 92 ; 70 70]', '[-0.34:.02:0]'
    # — raises SyntaxError here where the reference returns a matrix. The
    # engine's own config reader does not use this function; it calls an
    # inlined variant that routes strings through a MATLAB-syntax evaluator
    # (see xls_parameter_txffe._matlab_eval). Sharing that evaluator needs a
    # home outside a single fn directory, so it is left for the caller of this
    # pass to place.
    if isinstance(p, str) and eval_if_string:
        p = eval(p)  # noqa: S307 — matches MATLAB eval() for parameter loading
    return p



# --- xls_parameter_txffe (MATLAB lines 11494–11515) ---

_NUMBER = re.compile(r'[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?')
_TOKEN = re.compile(r'^%s(?::%s){0,2}$' % (_NUMBER.pattern, _NUMBER.pattern))
# Octave's colon operator counts intervals with a tolerant floor; 3*eps is the
# tolerance it uses.  Without it '[-0.2:0.05:0.05]' comes out one point short,
# because (0.05+0.2)/0.05 is 4.999999999999999 in binary.
_COLON_TOL = 3.0 * np.finfo(float).eps


def _xls_parameter_txffe__colon(token):
    """MATLAB a:b or a:s:b.  COM Octave: '[ -0.34:.02:0]' -> 18 points ending
    at exactly 0; '[ 0.14:.02:0]' -> empty; '[0.14:-.02:0]' -> 8 points."""
    parts = token.split(':')
    if len(parts) == 2:
        start, step, stop = float(parts[0]), 1.0, float(parts[1])
    else:
        start, step, stop = (float(p) for p in parts)
    n = int(math.floor((stop - start) / step + _COLON_TOL)) + 1
    return start + np.arange(max(n, 0)) * step


def _xls_parameter_txffe__matlab_matrix(body):
    """The inside of a MATLAB '[...]': rows on ';', elements on commas and
    whitespace, each element a number or a colon range.  Raises ValueError on
    anything else, so the caller can fall through to Python's eval."""
    rows = []
    for row in body.split(';'):
        vals = []
        for token in row.replace(',', ' ').split():
            if not _TOKEN.match(token):
                raise ValueError(token)
            vals.extend(_xls_parameter_txffe__colon(token) if ':' in token else [float(token)])
        rows.append(vals)
    if len(rows) == 1:
        return np.array(rows[0], dtype=float)
    return np.array(rows, dtype=float)


def _xls_parameter_txffe__matlab_eval(s):
    """MATLAB eval() of a spreadsheet value string.

    Python's eval cannot read MATLAB's array syntax at all, and every TxFFE
    range in a COM config is written in it: the value cell for c(-1) in
    examples/akinwale_CR_22dB_VendorX is the string '[ -0.34:.02:0]', on which
    eval() raises SyntaxError.  COM Octave, same string through
    xls_parameter_txffe, returns the 18 points -0.34 .. 0 in steps of 0.02.
    Also pinned: '[1 0 0]' -> [1 0 0], '[1, 2, 3]' -> [1 2 3],
    '[1 2 3; 4 5 6]' -> 2x3, '[]' -> empty, '0.4' -> 0.4, '2*3' -> 6,
    'not code' -> "syntax error" (so junk must still raise).
    """
    t = s.strip()
    if t.startswith('[') and t.endswith(']'):
        return _xls_parameter_txffe__matlab_matrix(t[1:-1])
    try:
        return float(t)
    except ValueError:
        pass
    if _TOKEN.match(t):
        return _xls_parameter_txffe__colon(t)
    return eval(t)  # noqa: S307 — matches MATLAB eval() for parameter loading


def xls_parameter_txffe(param_sheet, param_name):
    """Case-insensitive search in 2D param_sheet; return (value, found) (MATLAB lines 11494-11515).

    param_sheet is a list-of-lists (rows × cols).
    Returns (p, 1) on match, (0, 0) if not found.
    Raises ValueError if multiple matches found.
    """
    name_lower = param_name.lower()
    matches = [
        (r, c)
        for r, row in enumerate(param_sheet)
        for c, cell in enumerate(row)
        if isinstance(cell, str) and cell.lower() == name_lower
    ]
    if len(matches) == 0:
        return 0, 0
    if len(matches) > 1:
        raise ValueError(
            f'{len(matches)} occurrences of "{param_name}" found. Please recheck spreadsheet'
        )
    r, c = matches[0]
    p = param_sheet[r][c + 1]
    if isinstance(p, str):
        p = _xls_parameter_txffe__matlab_eval(p)
    return p, 1



